import type { OverflowSnapshot } from './types';

export const DATA_OVERFLOWING = 'data-overflowing';
export const DATA_OVERFLOW_GROUP = 'data-overflow-group';

/**
 * An empty, frozen overflow snapshot used as the default before anything has been measured.
 * @internal
 */
export const EMPTY_SNAPSHOT: OverflowSnapshot = Object.freeze({
  itemVisibility: {},
  groupVisibility: {},
  invisibleItemCount: 0,
});

/**
 * Helper function that creates a resize observer in the element's own window global
 * @param elementToObserve - Uses the element's window global to create the resize observer
 * @param callback
 * @returns function to cleanup the resize observer
 */
export function observeResize(elementToObserve: HTMLElement, callback: ResizeObserverCallback): () => void {
  const GlobalResizeObserver = elementToObserve.ownerDocument.defaultView?.ResizeObserver;

  if (!GlobalResizeObserver) {
    if (process.env.NODE_ENV !== 'production') {
      // eslint-disable-next-line no-console
      console.error('@fluentui/priority-overflow', 'ResizeObserver does not exist on container window');
    }
    return () => null;
  }

  let resizeObserver: InstanceType<typeof GlobalResizeObserver> | undefined = new GlobalResizeObserver(callback);
  resizeObserver.observe(elementToObserve);

  return () => {
    resizeObserver?.disconnect();
    resizeObserver = undefined;
  };
}

/**
 * Microtask debouncer
 * https://developer.mozilla.org/en-US/docs/Web/API/HTML_DOM_API/Microtask_guide
 * @param fn - Function to debounce
 * @returns debounced function
 */
export function debounce(fn: () => void): () => void {
  let pending: boolean;

  // React testing platforms will often output errors when state updates happen outside `act`
  // Since there is nothing obvious to wait for we just avoid debouncing in unit test environments
  if (process.env.NODE_ENV === 'test') {
    return fn;
  }

  return () => {
    if (!pending) {
      pending = true;
      queueMicrotask(() => {
        // Need to set pending to `false` before the debounced function is run.
        // React can actually interrupt the function while it's running!
        pending = false;
        fn();
      });
    }
  };
}

import { DATA_OVERFLOWING, DATA_OVERFLOW_GROUP, EMPTY_SNAPSHOT } from './consts';
import { observeResize } from './createResizeObserver';
import { debounce } from './debounce';
import type { PriorityQueue } from './priorityQueue';
import { createPriorityQueue } from './priorityQueue';
import type {
  OverflowGroupState,
  OverflowItemEntry,
  OverflowManager,
  OverflowOptions,
  OverflowDividerEntry,
  OverflowSnapshot,
} from './types';

const DEFAULT_OPTIONS: Required<OverflowOptions> = {
  overflowAxis: 'horizontal',
  overflowDirection: 'end',
  padding: 10,
  minimumVisible: 0,
  hasHiddenItems: false,
  onUpdateItemVisibility: () => {
    /* noop */
  },
  onUpdateOverflow: () => {
    /* noop */
  },
};

/**
 * Creates an overflow manager instance for a single container.
 *
 * @internal
 * @param initialOptions - Initial observe options. Missing values are filled with defaults.
 * @returns overflow manager instance
 */
export function createOverflowManager(initialOptions: Partial<OverflowOptions> = {}): OverflowManager {
  // calls to `offsetWidth or offsetHeight` can happen multiple times in an update
  // Use a cache to avoid causing too many recalcs and avoid scripting time to meausure sizes
  const sizeCache = new Map<HTMLElement, number>();
  let container: HTMLElement | undefined;
  let overflowMenu: HTMLElement | undefined;
  // Set as true when resize observer is observing
  let observing = false;
  // If true, next update will dispatch to onUpdateOverflow even if queue top states don't change
  // Initially true to force dispatch on first mount
  let forceDispatch = true;
  const options: Required<OverflowOptions> = { ...DEFAULT_OPTIONS, ...initialOptions };
  const overflowItems: Record<string, OverflowItemEntry> = {};
  const overflowDividers: Record<string, OverflowDividerEntry> = {};
  const listeners = new Set<() => void>();
  let disposeResizeObserver: () => void = () => {
    /* noop */
  };

  let snapshot: OverflowSnapshot = EMPTY_SNAPSHOT;
  const takeSnapshot = (nextSnapshot: OverflowSnapshot) => {
    snapshot = nextSnapshot;
    listeners.forEach(listener => listener());
  };

  const getNextItem = (queueToDequeue: PriorityQueue<string>, queueToEnqueue: PriorityQueue<string>) => {
    const nextItem = queueToDequeue.dequeue();
    queueToEnqueue.enqueue(nextItem);
    return overflowItems[nextItem];
  };

  const groupManager = createGroupManager();

  function compareItems(lt: string | null, rt: string | null): number {
    if (!lt || !rt) {
      return 0;
    }

    const lte = overflowItems[lt];
    const rte = overflowItems[rt];

    // TODO this should not happen but there have been reports of one of these items being undefined
    // Try to find a consistent repro for this
    if (!lte || !rte) {
      return lte ? 1 : -1;
    }

    // Pinned items have "infinite" priority - they should never be hidden
    if (lte.pinned !== rte.pinned) {
      return lte.pinned ? 1 : -1;
    }

    if (lte.priority !== rte.priority) {
      return lte.priority > rte.priority ? 1 : -1;
    }

    // Node.DOCUMENT_POSITION_FOLLOWING = 4, Node.DOCUMENT_POSITION_PRECEDING = 2
    const positionStatusBit = options.overflowDirection === 'end' ? 4 : 2;

    // eslint-disable-next-line no-bitwise
    return lte.element.compareDocumentPosition(rte.element) & positionStatusBit ? 1 : -1;
  }

  function getElementAxisSize(
    horizontal: 'clientWidth' | 'offsetWidth',
    vertical: 'clientHeight' | 'offsetHeight',
    el: HTMLElement,
  ): number {
    if (!sizeCache.has(el)) {
      sizeCache.set(el, options.overflowAxis === 'horizontal' ? el[horizontal] : el[vertical]);
    }

    return sizeCache.get(el)!;
  }

  const getOffsetSize = getElementAxisSize.bind(null, 'offsetWidth', 'offsetHeight');
  const getClientSize = getElementAxisSize.bind(null, 'clientWidth', 'clientHeight');

  const invisibleItemQueue = createPriorityQueue<string>((a, b) => -1 * compareItems(a, b));

  const visibleItemQueue = createPriorityQueue<string>(compareItems);

  function occupiedSize(): number {
    let totalItemSize = 0;
    for (const id of visibleItemQueue) {
      totalItemSize += getOffsetSize(overflowItems[id].element);
    }

    const totalDividerSize = Object.entries(groupManager.groupVisibility()).reduce(
      (acc, [id, state]) =>
        acc + (state !== 'hidden' && overflowDividers[id] ? getOffsetSize(overflowDividers[id].element) : 0),
      0,
    );

    const overflowMenuSize =
      (invisibleItemQueue.size() > 0 || options.hasHiddenItems) && overflowMenu ? getOffsetSize(overflowMenu) : 0;

    return totalItemSize + totalDividerSize + overflowMenuSize;
  }

  const showItem = () => {
    const item = getNextItem(invisibleItemQueue, visibleItemQueue);
    options.onUpdateItemVisibility({ item, visible: true });

    if (item.groupId) {
      groupManager.showItem(item.id, item.groupId);

      if (groupManager.isSingleItemVisible(item.id, item.groupId)) {
        overflowDividers[item.groupId]?.element.removeAttribute(DATA_OVERFLOWING);
      }
    }
  };

  const hideItem = () => {
    const item = getNextItem(visibleItemQueue, invisibleItemQueue);
    options.onUpdateItemVisibility({ item, visible: false });

    if (item.groupId) {
      if (groupManager.isSingleItemVisible(item.id, item.groupId)) {
        overflowDividers[item.groupId]?.element.setAttribute(DATA_OVERFLOWING, '');
      }

      groupManager.hideItem(item.id, item.groupId);
    }
  };

  const dispatchOverflowUpdate = () => {
    const groupVisibility = groupManager.groupVisibility();

    // Build the legacy ordered-entry arrays and the snapshot's id -> visible map in a single pass
    // over each queue.
    const itemVisibility: Record<string, boolean> = {};
    const visibleItems: OverflowItemEntry[] = [];
    const invisibleItems: OverflowItemEntry[] = [];

    for (const itemId of visibleItemQueue) {
      itemVisibility[itemId] = true;
      visibleItems.push(overflowItems[itemId]);
    }
    for (const itemId of invisibleItemQueue) {
      itemVisibility[itemId] = false;
      invisibleItems.push(overflowItems[itemId]);
    }

    // Set the snapshot first so `getSnapshot()` is current for both subscribers and any
    // `onUpdateOverflow` consumer that reads it.
    takeSnapshot({
      itemVisibility,
      groupVisibility,
      invisibleItemCount: invisibleItems.length,
    });

    // Legacy event payload: ordered item entries for `onUpdateOverflow` consumers.
    options.onUpdateOverflow({ visibleItems, invisibleItems, groupVisibility });
  };

  const getSnapshot: OverflowManager['getSnapshot'] = () => snapshot;

  const processOverflowItems = (): boolean => {
    if (!container) {
      return false;
    }
    sizeCache.clear();

    const availableSize = getClientSize(container) - options.padding;

    // Snapshot of the visible/invisible state to compare for updates
    const visibleTop = visibleItemQueue.peek();
    const invisibleTop = invisibleItemQueue.peek();

    while (compareItems(invisibleItemQueue.peek(), visibleItemQueue.peek()) > 0) {
      hideItem(); // hide elements whose priority become smaller than the highest priority of the hidden one
    }

    // Run the show/hide step twice - the first step might not be correct if
    // it was triggered by a new item being added - new items are always visible by default.
    for (let i = 0; i < 2; i++) {
      // Add items until available width is filled - can result in overflow
      while (
        (occupiedSize() < availableSize && invisibleItemQueue.size() > 0) ||
        invisibleItemQueue.size() === 1 // attempt to show the last invisible item hoping it's size does not exceed overflow menu size
      ) {
        showItem();
      }

      // Remove items until there's no more overflow
      while (occupiedSize() > availableSize && visibleItemQueue.size() > options.minimumVisible) {
        const nextItemId = visibleItemQueue.peek();

        // Never hide pinned items - they should always remain visible
        if (nextItemId && overflowItems[nextItemId]?.pinned) {
          break;
        }

        hideItem();
      }
    }

    // only update when the state of visible/invisible items has changed
    return visibleItemQueue.peek() !== visibleTop || invisibleItemQueue.peek() !== invisibleTop;
  };

  const forceUpdate: OverflowManager['forceUpdate'] = () => {
    if (processOverflowItems() || forceDispatch) {
      forceDispatch = false;
      dispatchOverflowUpdate();
    }
  };

  const update: OverflowManager['update'] = debounce(forceUpdate);

  const setOptions: OverflowManager['setOptions'] = nextOptions => {
    if (options === nextOptions) {
      return;
    }

    const shouldTriggerUpdate =
      (nextOptions.overflowAxis && options.overflowAxis !== nextOptions.overflowAxis) ||
      (nextOptions.overflowDirection && options.overflowDirection !== nextOptions.overflowDirection) ||
      (nextOptions.padding && options.padding !== nextOptions.padding) ||
      (nextOptions.minimumVisible && options.minimumVisible !== nextOptions.minimumVisible) ||
      (nextOptions.hasHiddenItems && options.hasHiddenItems !== nextOptions.hasHiddenItems);

    Object.assign(options, nextOptions);

    if (shouldTriggerUpdate) {
      forceDispatch = true;
      update();
    }
  };

  const observe: OverflowManager['observe'] = (observedContainer, observeOptions) => {
    const { forceUpdate: shouldForceUpdate, ...userOptions } = observeOptions ?? {};
    Object.assign(options, userOptions);

    Object.values(overflowItems).forEach(item => {
      if (!visibleItemQueue.contains(item.id) && !invisibleItemQueue.contains(item.id)) {
        visibleItemQueue.enqueue(item.id);
      }
    });

    container = observedContainer;
    observing = true;
    disposeResizeObserver = observeResize(container, entries => {
      if (!entries[0] || !container) {
        return;
      }
      update();
    });

    if (shouldForceUpdate && getClientSize(observedContainer) > 0) {
      forceUpdate();
    }
  };

  const disconnect: OverflowManager['disconnect'] = () => {
    disposeResizeObserver();
    disposeResizeObserver = () => {
      /* noop */
    };

    // reset flags
    container = undefined;
    observing = false;
    forceDispatch = true;

    // clear all entries
    Object.keys(overflowItems).forEach(itemId => removeItem(itemId));
    Object.keys(overflowDividers).forEach(dividerId => removeDivider(dividerId));
    removeOverflowMenu();
    sizeCache.clear();

    // Reset the snapshot during teardown, but do not broadcast a final update.
    // Consumers unsubscribe as part of unmount, and a disconnect-time notification can race
    // those cleanups and dispatch into already-unmounting React listeners.
    snapshot = EMPTY_SNAPSHOT;
  };

  const addItem: OverflowManager['addItem'] = items => {
    if (overflowItems[items.id]) {
      return;
    }

    overflowItems[items.id] = items;

    // some options can affect priority which are only set on `observe`
    if (observing) {
      // Updates to elements might not change the queue tops
      // i.e. new element is enqueued but the top of the queue stays the same
      // force a dispatch on the next batched update
      forceDispatch = true;
      visibleItemQueue.enqueue(items.id);
      update();
    }

    if (items.groupId) {
      groupManager.addItem(items.id, items.groupId);
      items.element.setAttribute(DATA_OVERFLOW_GROUP, items.groupId);
    }
  };

  const addOverflowMenu: OverflowManager['addOverflowMenu'] = el => {
    if (overflowMenu === el) {
      return;
    }

    overflowMenu = el;

    if (observing) {
      forceDispatch = true;
      if (invisibleItemQueue.size() > 0) {
        forceUpdate();
      } else {
        update();
      }
    }
  };

  const addDivider: OverflowManager['addDivider'] = divider => {
    if (!divider.groupId || overflowDividers[divider.groupId]) {
      return;
    }

    divider.element.setAttribute(DATA_OVERFLOW_GROUP, divider.groupId);
    overflowDividers[divider.groupId] = divider;
  };

  const removeOverflowMenu: OverflowManager['removeOverflowMenu'] = () => {
    if (!overflowMenu) {
      return;
    }

    const hasInvisibleItems = invisibleItemQueue.size() > 0;
    overflowMenu = undefined;

    if (observing && hasInvisibleItems) {
      forceDispatch = true;
      update();
    }
  };

  const removeDivider: OverflowManager['removeDivider'] = groupId => {
    if (!overflowDividers[groupId]) {
      return;
    }
    const divider = overflowDividers[groupId];
    if (divider.groupId) {
      delete overflowDividers[groupId];
      divider.element.removeAttribute(DATA_OVERFLOW_GROUP);
    }
  };

  const removeItem: OverflowManager['removeItem'] = itemId => {
    if (!overflowItems[itemId]) {
      return;
    }

    if (observing) {
      // We might be removing an item in an overflow which would not affect the tops,
      // but we need to update anyway to update the overflow menu state
      forceDispatch = true;
    }

    const item = overflowItems[itemId];
    visibleItemQueue.remove(itemId);
    invisibleItemQueue.remove(itemId);

    if (item.groupId) {
      groupManager.removeItem(item.id, item.groupId);
      item.element.removeAttribute(DATA_OVERFLOW_GROUP);
    }

    sizeCache.delete(item.element);
    delete overflowItems[itemId];
    if (observing) {
      update();
    }
  };

  const subscribe: OverflowManager['subscribe'] = listener => {
    listeners.add(listener);

    return () => {
      listeners.delete(listener);
    };
  };

  return {
    addItem,
    disconnect,
    forceUpdate,
    observe,
    removeItem,
    update,
    addOverflowMenu,
    removeOverflowMenu,
    addDivider,
    removeDivider,
    setOptions,
    getSnapshot,
    subscribe,
  };
}

const createGroupManager = () => {
  const groupVisibility: Record<string, OverflowGroupState> = {};
  const groups: Record<string, { visibleItemIds: Set<string>; invisibleItemIds: Set<string> }> = {};
  function updateGroupVisibility(groupId: string) {
    const group = groups[groupId];
    if (group.invisibleItemIds.size && group.visibleItemIds.size) {
      groupVisibility[groupId] = 'overflow';
    } else if (group.visibleItemIds.size === 0) {
      groupVisibility[groupId] = 'hidden';
    } else {
      groupVisibility[groupId] = 'visible';
    }
  }
  function isGroupVisible(groupId: string) {
    return groupVisibility[groupId] === 'visible' || groupVisibility[groupId] === 'overflow';
  }
  return {
    groupVisibility: () => groupVisibility,
    isSingleItemVisible(itemId: string, groupId: string) {
      return (
        isGroupVisible(groupId) &&
        groups[groupId].visibleItemIds.has(itemId) &&
        groups[groupId].visibleItemIds.size === 1
      );
    },
    addItem(itemId: string, groupId: string) {
      groups[groupId] ??= {
        visibleItemIds: new Set<string>(),
        invisibleItemIds: new Set<string>(),
      };

      groups[groupId].visibleItemIds.add(itemId);
      updateGroupVisibility(groupId);
    },
    removeItem(itemId: string, groupId: string) {
      groups[groupId].invisibleItemIds.delete(itemId);
      groups[groupId].visibleItemIds.delete(itemId);
      updateGroupVisibility(groupId);
    },
    showItem(itemId: string, groupId: string) {
      groups[groupId].invisibleItemIds.delete(itemId);
      groups[groupId].visibleItemIds.add(itemId);
      updateGroupVisibility(groupId);
    },
    hideItem(itemId: string, groupId: string) {
      groups[groupId].invisibleItemIds.add(itemId);
      groups[groupId].visibleItemIds.delete(itemId);
      updateGroupVisibility(groupId);
    },
  };
};

export type PriorityQueueCompareFn<T> = (a: T, b: T) => number;

export interface PriorityQueue<T> extends Iterable<T> {
  clear: () => void;
  contains: (item: T) => boolean;
  dequeue: () => T;
  enqueue: (item: T) => void;
  peek: () => T | null;
  remove: (item: T) => void;
  size: () => number;
}

/**
 * @param compare - comparison function for items
 * @returns Priority queue implemented with a min heap
 */
export function createPriorityQueue<T>(compare: PriorityQueueCompareFn<T>): PriorityQueue<T> {
  const arr: T[] = [];
  let size = 0;

  const left = (i: number) => {
    return 2 * i + 1;
  };

  const right = (i: number) => {
    return 2 * i + 2;
  };

  const parent = (i: number) => {
    return Math.floor((i - 1) / 2);
  };

  const swap = (a: number, b: number) => {
    const tmp = arr[a];
    arr[a] = arr[b];
    arr[b] = tmp;
  };

  const heapify = (i: number) => {
    let smallest = i;
    const l = left(i);
    const r = right(i);

    if (l < size && compare(arr[l], arr[smallest]) < 0) {
      smallest = l;
    }

    if (r < size && compare(arr[r], arr[smallest]) < 0) {
      smallest = r;
    }

    if (smallest !== i) {
      swap(smallest, i);
      heapify(smallest);
    }
  };

  const dequeue = () => {
    if (size === 0) {
      throw new Error('Priority queue empty');
    }

    const res = arr[0];
    arr[0] = arr[--size];
    heapify(0);

    return res;
  };

  const peek = () => {
    if (size === 0) {
      return null;
    }

    return arr[0];
  };

  const enqueue = (item: T) => {
    arr[size++] = item;
    let i = size - 1;
    let p = parent(i);
    while (i > 0 && compare(arr[p], arr[i]) > 0) {
      swap(p, i);
      i = p;
      p = parent(i);
    }
  };

  const contains = (item: T) => {
    const index = arr.indexOf(item);
    return index >= 0 && index < size;
  };

  const remove = (item: T) => {
    const i = arr.indexOf(item);

    if (i === -1 || i >= size) {
      return;
    }

    arr[i] = arr[--size];
    heapify(i);
  };

  const clear = () => {
    size = 0;
  };

  return {
    clear,
    contains,
    dequeue,
    enqueue,
    peek,
    remove,
    size: () => size,
    // Iterates items in heap order, without allocating an intermediate array. Bounded by `size`:
    // `arr` keeps stale entries past `size` (dequeue/remove/clear shrink `size`, not `arr`), so the
    // array's own iterator would yield removed items.
    *[Symbol.iterator]() {
      for (let index = 0; index < size; index++) {
        yield arr[index];
      }
    },
  };
}

/**
 * Direction where items are removed when overflow occurs.
 */
export type OverflowDirection = 'start' | 'end';

/**
 * Axis used to measure overflow.
 */
export type OverflowAxis = 'horizontal' | 'vertical';

/**
 * Visibility state for an overflow group.
 */
export type OverflowGroupState = 'visible' | 'hidden' | 'overflow';

/**
 * Tracked item in the overflow manager.
 */
export interface OverflowItemEntry {
  /**
   * HTML element that disappears when the item overflows.
   */
  element: HTMLElement;
  /**
   * Lower-priority items become invisible first when the container overflows.
   * @default 0
   */
  priority: number;
  /**
   * Stable item id used to track visibility and emit updates.
   */
  id: string;

  /**
   * Optional group id used to coordinate divider and grouped visibility states.
   */
  groupId?: string;

  /**
   * If true, the item will never overflow and will always be visible.
   * Pinned items are excluded from the overflow count.
   * @default false
   */
  pinned?: boolean;
}

/**
 * Tracked divider in the overflow manager.
 */
export interface OverflowDividerEntry {
  /**
   * HTML element that disappears when its group overflows.
   */
  element: HTMLElement;

  /**
   * Id of the group controlled by this divider.
   */
  groupId: string;
}

/**
 * Signature similar to standard event listeners, typed for overflow updates.
 */
export type OnUpdateOverflow = (data: OverflowEventPayload) => void;

/**
 * Callback invoked when a single item's visibility changes.
 */
export type OnUpdateItemVisibility = (data: OnUpdateItemVisibilityPayload) => void;

/**
 * Payload of the custom DOM event for overflow updates
 */
export interface OverflowEventPayload {
  /**
   * Items currently visible in the container.
   */
  visibleItems: OverflowItemEntry[];

  /**
   * Items currently moved to overflow.
   */
  invisibleItems: OverflowItemEntry[];

  /**
   * Current visibility state by group id.
   */
  groupVisibility: Record<string, OverflowGroupState>;
}

/**
 * Indexed, immutable overflow state returned by `OverflowManager.getSnapshot`.
 *
 * Unlike {@link OverflowEventPayload}, this is shaped for O(1) consumer lookups (item/group
 * visibility by id, item count) rather than ordered item entries.
 */
export interface OverflowSnapshot {
  /**
   * Visibility of each registered item, keyed by item id.
   */
  itemVisibility: Record<string, boolean>;

  /**
   * Current visibility state by group id.
   */
  groupVisibility: Record<string, OverflowGroupState>;

  /**
   * Number of items currently moved to overflow (invisible).
   */
  invisibleItemCount: number;
}

/**
 * Payload for item-level visibility updates.
 */
export interface OnUpdateItemVisibilityPayload {
  /**
   * Item whose visibility changed.
   */
  item: OverflowItemEntry;

  /**
   * Whether the item is now visible.
   */
  visible: boolean;
}

/**
 * Options used to initialize or reconfigure overflow observation.
 */
export interface OverflowOptions {
  /**
   * Padding in pixels reserved at the end of the container before overflow occurs.
   * Useful for accounting for extra elements (for example an overflow menu button)
   * or margins between items that are difficult to measure in JavaScript.
   * @default 10
   */
  padding?: number;
  /**
   * Direction where items are removed when overflow occurs.
   * @default end
   */
  overflowDirection?: OverflowDirection;

  /**
   * Overflow axis used for size measurement.
   * @default horizontal
   */
  overflowAxis?: OverflowAxis;

  /**
   * Minimum number of items that must remain visible.
   */
  minimumVisible?: number;

  /**
   * Callback invoked when an individual item's visibility changes.
   */
  onUpdateItemVisibility: OnUpdateItemVisibility;

  /**
   * Callback invoked after overflow state is recomputed.
   */
  onUpdateOverflow: OnUpdateOverflow;

  /**
   * When true, reserve space as if the overflow menu were visible even with no overflowing items.
   * @default false
   */
  hasHiddenItems?: boolean;
}

export interface ObserveOptions extends Partial<OverflowOptions> {
  /**
   * forces update when observation begins, ensuring initial overflow state is correct. This is useful when the container starts with items that should be overflowed, or when the container resizes immediately after mounting.
   * @default false
   */
  forceUpdate?: boolean;
}

/**
 * Internal manager contract used to observe and compute priority overflow.
 *
 * @internal
 */
export interface OverflowManager {
  /**
   * Starts observing the container and managing the overflow state
   */
  observe: (container: HTMLElement, options?: ObserveOptions) => void;
  /**
   * Stops observing the container
   */
  disconnect: () => void;
  /**
   * Updates engine options without restarting observation.
   */
  setOptions: (options: Partial<OverflowOptions>) => void;
  /**
   * Add overflow items
   */
  addItem: (items: OverflowItemEntry) => void;
  /**
   * Remove overflow item
   */
  removeItem: (itemId: string) => void;
  /**
   * Manually update the overflow, updates are batched and async
   */
  update: () => void;
  /**
   * Manually update the overflow sync
   */
  forceUpdate: () => void;

  /**
   * Adds an element that opens an overflow menu. This is used to calculate
   * available space and check if additional items need to overflow
   */
  addOverflowMenu: (element: HTMLElement) => void;

  /**
   * Add overflow divider
   */
  addDivider: (divider: OverflowDividerEntry) => void;

  /**
   * Remove overflow divider
   */
  removeDivider: (groupId: string) => void;

  /**
   * Unsets the overflow menu element
   */
  removeOverflowMenu: () => void;

  /**
   * Returns the current overflow snapshot.
   */
  getSnapshot: () => OverflowSnapshot;

  /**
   * Subscribes to snapshot changes.
   */
  subscribe: (listener: () => void) => () => void;
}

