export const useAccordionBase_unstable = <Value = AccordionItemValue>(
  props: AccordionBaseProps<Value>,
  ref: React.Ref<HTMLElement>,
): AccordionBaseState<Value> => {
  const {
    openItems: controlledOpenItems,
    defaultOpenItems,
    multiple = false,
    collapsible = false,
    onToggle,
    ...rest
