    active: noop,
    blur: noop,
    find: noop,
    first: noop,
    focus: noop,
    focusLastActive: noop,
    scrollActiveIntoView: noop,
    last: noop,
    next: noop,
    prev: noop,
    showAttributes: noop,
    hideAttributes: noop,
    showFocusVisibleAttributes: noop,
    hideFocusVisibleAttributes: noop,
  },
};

const ActiveDescendantContext = React.createContext<ActiveDescendantContextValue | undefined>(undefined);

export const ActiveDescendantContextProvider = ActiveDescendantContext.Provider;
export const useActiveDescendantContext = (): ActiveDescendantContextValue =>
  React.useContext(ActiveDescendantContext) ?? activeDescendantContextDefaultValue;
export const useHasParentActiveDescendantContext = (): boolean => !!React.useContext(ActiveDescendantContext);

/**
 * Applied to the element that is active descendant
 */
export const ACTIVEDESCENDANT_ATTRIBUTE = 'data-activedescendant';

/**
 * Applied to the active descendant when the user is navigating with keyboard
 */
export const ACTIVEDESCENDANT_FOCUSVISIBLE_ATTRIBUTE = 'data-activedescendant-focusvisible';

export type { ActiveDescendantContextValue } from './ActiveDescendantContext';
export {
  ActiveDescendantContextProvider,
  useActiveDescendantContext,
  useHasParentActiveDescendantContext,
} from './ActiveDescendantContext';
