} from './types';

export const scrollIntoView = (target: HTMLElement | null | undefined): void => {
  if (!target) {
    return;
  }

  const scrollParent = findScrollableParent(target.parentElement as HTMLElement);
  if (!scrollParent) {
    return;
  }

  const { offsetHeight } = target;
  const offsetTop = getTotalOffsetTop(target, scrollParent);

  const { scrollMarginTop, scrollMarginBottom } = getScrollMargins(target);

  const { offsetHeight: parentOffsetHeight, scrollTop } = scrollParent;

  const isAbove = offsetTop - scrollMarginTop < scrollTop;
  const isBelow = offsetTop + offsetHeight + scrollMarginBottom > scrollTop + parentOffsetHeight;

  const buffer = 2;

  if (isAbove) {
    scrollParent.scrollTo(0, offsetTop - scrollMarginTop - buffer);
  } else if (isBelow) {
    scrollParent.scrollTo(0, offsetTop + offsetHeight + scrollMarginBottom - parentOffsetHeight + buffer);
  }
};

const findScrollableParent = (element: HTMLElement | null): HTMLElement | null => {
  if (!element) {
    return null;
  }

  if (element.scrollHeight > element.offsetHeight) {
    return element;
  }

  return findScrollableParent(element.parentElement);
};

const getTotalOffsetTop = (element: HTMLElement, scrollParent: HTMLElement): number => {
  if (!element || element === scrollParent) {
    return 0;
  }

  if (element.contains(scrollParent)) {
    // subtract the scroll parent's offset top from the running total if the offsetParent is above it
    return scrollParent.offsetTop * -1;
  }

  return element.offsetTop + getTotalOffsetTop(element.offsetParent as HTMLElement, scrollParent);
};

const getScrollMargins = (element: HTMLElement) => {
  const win = element.ownerDocument?.defaultView;
  if (!win) {
    return {
      scrollMarginTop: 0,
      scrollMarginBottom: 0,
    };
  }

  const computedStyles = win.getComputedStyle(element);
  const scrollMarginTop =
    getIntValueOfComputedStyle(computedStyles.scrollMarginTop) ??
    getIntValueOfComputedStyle(computedStyles.scrollMarginBlockStart);
  const scrollMarginBottom =
    getIntValueOfComputedStyle(computedStyles.scrollMarginBottom) ??
    getIntValueOfComputedStyle(computedStyles.scrollMarginBlockEnd);
  return {
    scrollMarginTop,
    scrollMarginBottom,
  };
};

const getIntValueOfComputedStyle = (computedStyle: string) => {
  return computedStyle ? parseInt(computedStyle, 10) : 0;
};

import type * as React from 'react';

export interface ActiveDescendantImperativeRef {
  first: (options?: IteratorOptions) => string | undefined;
  last: (options?: IteratorOptions) => string | undefined;
  next: (options?: IteratorOptions) => string | undefined;
  prev: (options?: IteratorOptions) => string | undefined;
  find: (predicate: (id: string) => boolean, options?: IteratorOptions & FindOptions) => string | undefined;
  blur: () => void;
  active: () => string | undefined;
  focus: (id: string) => void;
  /**
   * @deprecated This function is not used internally anymore and will be removed in the future
   */
  focusLastActive: () => void;
  /**
   * Scrolls the active option into view, if it still exists
   */
  scrollActiveIntoView: () => void;
  hideAttributes: () => void;
  showAttributes: () => void;
  hideFocusVisibleAttributes: () => void;
  showFocusVisibleAttributes: () => void;
}

export interface ActiveDescendantOptions {
  /**
   * @param el - HTML element to test
   * @returns whether the element can be an active descendant
   */
  matchOption: (el: HTMLElement) => boolean;
  /**
   * Forward imperative refs when exposing functionality from a React component
   */
  imperativeRef?: React.RefObject<ActiveDescendantImperativeRef | null>;
}

export interface FindOptions {
  /**
   * Starts the search from a specific id
   */
  startFrom?: string;
}

export interface UseActiveDescendantReturn<
  TActiveParentElement extends HTMLElement = HTMLElement,
  TListboxElement extends HTMLElement = HTMLElement,
> {
  /**
   * Attach this to the element that contains all active descendants
   */
  listboxRef: React.Ref<TListboxElement>;
  /**
   * Attach this to the element that has an active descendant
   */
  activeParentRef: React.Ref<TActiveParentElement>;
  /**
   * Imperative functions to manage active descendants within the listboxRef
   */
  controller: ActiveDescendantImperativeRef;
}

export interface IteratorOptions {
  /**
   * When passive, the active descendant is changed
   * @default false
   */
  passive?: boolean;
}

import * as React from 'react';
import { mount } from '@fluentui/scripts-cypress';
import { makeStyles } from '@griffel/react';
import { ACTIVEDESCENDANT_FOCUSVISIBLE_ATTRIBUTE } from './constants';
import { useActiveDescendant } from './useActiveDescendant';

describe('onActiveOptionChange', () => {
  it('Should fire change event on active item change', () => {
    const Example = () => {
      const { listboxRef, activeParentRef, controller } = useActiveDescendant<HTMLButtonElement, HTMLDivElement>({
        matchOption: el => el.getAttribute('role') === 'option',
      });

      const containerRef = React.useRef<HTMLDivElement>(null);

      const [lastActive, setLastActive] = React.useState('');

      const onActiveDescendantChange = React.useCallback(
        (event: CustomEventInit<{ id: string }>) => {
          setLastActive(event?.detail?.id || 'no event');
        },
        [setLastActive],
      );

      React.useEffect(() => {
        const element = containerRef.current;
        element?.addEventListener('activedescendantchange', onActiveDescendantChange);
        return () => {
          element?.removeEventListener('activedescendantchange', onActiveDescendantChange);
        };
      }, [containerRef, onActiveDescendantChange]);

      return (
        <>
          <div data-test-id="last-active">{lastActive}</div>
          <div ref={containerRef}>
            <button
              onKeyDown={e => {
                switch (e.key) {
                  case 'Enter':
                    controller.first();
                    break;
                  case 'ArrowDown':
                    controller.next();
                    break;
                }
              }}
              ref={activeParentRef}
            >
              active parent
            </button>
            <div ref={listboxRef}>
              <div role="option" id="option-1">
                Option 1
              </div>
              <div role="option" id="option-2">
                Option 2
              </div>
            </div>
          </div>
        </>
      );
    };

    const example = mount(<Example />);

    example.get('button').focus().type('{enter}');
    example.get('[data-test-id="last-active"]').should('have.text', 'option-1');

    example.get('button').focus().type('{downArrow}');
    example.get('[data-test-id="last-active"]').should('have.text', 'option-2');
  });
});

describe('useOnKeyboardNavigationChange', () => {
  it('Should add focus visible attribute on active option', () => {
    // Used for browser test test
    // eslint-disable-next-line @griffel/styles-file
    const useStyles = makeStyles({
