  });
});

'use client';

import * as React from 'react';
import { useEventCallback, useMergedRefs } from '@fluentui/react-utilities';
import { useOnKeyboardNavigationChange } from '@fluentui/react-tabster';
import { useOptionWalker } from './useOptionWalker';
import type { ActiveDescendantImperativeRef, ActiveDescendantOptions, UseActiveDescendantReturn } from './types';
import { ACTIVEDESCENDANT_ATTRIBUTE, ACTIVEDESCENDANT_FOCUSVISIBLE_ATTRIBUTE } from './constants';
import { scrollIntoView } from './scrollIntoView';

interface ActiveDescendantChangeEventDetail {
  id: string;
  previousId: string | null;
}

export type ActiveDescendantChangeEvent = CustomEvent<ActiveDescendantChangeEventDetail>;

export const createActiveDescendantChangeEvent = (
  detail: ActiveDescendantChangeEventDetail,
): ActiveDescendantChangeEvent =>
  new CustomEvent<ActiveDescendantChangeEventDetail>('activedescendantchange', {
    bubbles: true,
    cancelable: false,
    composed: true,
    detail,
  });

export function useActiveDescendant<TActiveParentElement extends HTMLElement, TListboxElement extends HTMLElement>(
  options: ActiveDescendantOptions,
): UseActiveDescendantReturn<TActiveParentElement, TListboxElement> {
  const { imperativeRef, matchOption: matchOptionUnstable } = options;
  const focusVisibleRef = React.useRef(false);
  const shouldShowFocusVisibleAttrRef = React.useRef(true);
  const activeIdRef = React.useRef<string | null>(null);
  const lastActiveIdRef = React.useRef<string | null>(null);
  const activeParentRef = React.useRef<TActiveParentElement>(null);
  const attributeVisibilityRef = React.useRef(true);

  const removeAttribute = React.useCallback(() => {
    activeParentRef.current?.removeAttribute('aria-activedescendant');
  }, []);

  const setAttribute = React.useCallback((id?: string) => {
    if (id) {
      activeIdRef.current = id;
    }
    if (attributeVisibilityRef.current && activeIdRef.current) {
      activeParentRef.current?.setAttribute('aria-activedescendant', activeIdRef.current);
    }
  }, []);

  useOnKeyboardNavigationChange(isNavigatingWithKeyboard => {
    focusVisibleRef.current = isNavigatingWithKeyboard;

    // eslint-disable-next-line react-hooks/immutability, react-hooks/preserve-manual-memoization
    const active = getActiveDescendant();
    if (!active) {
      return;
    }

    if (isNavigatingWithKeyboard && shouldShowFocusVisibleAttrRef.current) {
      active.setAttribute(ACTIVEDESCENDANT_FOCUSVISIBLE_ATTRIBUTE, '');
    } else {
      active.removeAttribute(ACTIVEDESCENDANT_FOCUSVISIBLE_ATTRIBUTE);
    }
  });

  const matchOption = useEventCallback(matchOptionUnstable);
  const listboxRef = React.useRef<TListboxElement>(null);
  const { optionWalker, listboxCallbackRef } = useOptionWalker<TListboxElement>({ matchOption });

  // eslint-disable-next-line react-hooks/preserve-manual-memoization
  const getActiveDescendant = React.useCallback(() => {
    return listboxRef.current?.querySelector<HTMLElement>(`#${activeIdRef.current}`);
  }, [listboxRef]);

  const setShouldShowFocusVisibleAttribute = React.useCallback(
    (shouldShow: boolean) => {
      shouldShowFocusVisibleAttrRef.current = shouldShow;

      const active = getActiveDescendant();
      if (!active) {
        return;
      }

      if (shouldShow && focusVisibleRef.current) {
        active.setAttribute(ACTIVEDESCENDANT_FOCUSVISIBLE_ATTRIBUTE, '');
      } else {
        active.removeAttribute(ACTIVEDESCENDANT_FOCUSVISIBLE_ATTRIBUTE);
      }
    },
    [getActiveDescendant],
  );

  const blurActiveDescendant = React.useCallback(() => {
    const active = getActiveDescendant();
    if (active) {
      active.removeAttribute(ACTIVEDESCENDANT_ATTRIBUTE);
      active.removeAttribute(ACTIVEDESCENDANT_FOCUSVISIBLE_ATTRIBUTE);
    }

    removeAttribute();
    lastActiveIdRef.current = activeIdRef.current;
    activeIdRef.current = null;
    return active?.id ?? null;
  }, [getActiveDescendant, removeAttribute]);

  const focusActiveDescendant = React.useCallback(
    (nextActive: HTMLElement | null) => {
      if (!nextActive) {
        return;
      }

      const previousActiveId = blurActiveDescendant();

      scrollIntoView(nextActive);
      setAttribute(nextActive.id);
      nextActive.setAttribute(ACTIVEDESCENDANT_ATTRIBUTE, '');

      if (focusVisibleRef.current && shouldShowFocusVisibleAttrRef.current) {
        nextActive.setAttribute(ACTIVEDESCENDANT_FOCUSVISIBLE_ATTRIBUTE, '');
      }

      const event = createActiveDescendantChangeEvent({ id: nextActive.id, previousId: previousActiveId });
      nextActive.dispatchEvent(event);
    },
    [blurActiveDescendant, setAttribute],
  );

  const controller: ActiveDescendantImperativeRef = React.useMemo(
    () => ({
      first: ({ passive } = {}) => {
        const first = optionWalker.first();
        if (!passive) {
          focusActiveDescendant(first);
        }

        return first?.id;
      },
      last: ({ passive } = {}) => {
        const last = optionWalker.last();
        if (!passive) {
          focusActiveDescendant(last);
        }

        return last?.id;
      },
      next: ({ passive } = {}) => {
        const active = getActiveDescendant();
        if (!active) {
          return;
        }

        optionWalker.setCurrent(active);
        const next = optionWalker.next();
        if (!passive) {
          focusActiveDescendant(next);
        }

        return next?.id;
      },
      prev: ({ passive } = {}) => {
        const active = getActiveDescendant();
        if (!active) {
          return;
        }

        optionWalker.setCurrent(active);
        const next = optionWalker.prev();

        if (!passive) {
          focusActiveDescendant(next);
        }

        return next?.id;
      },
      blur: () => {
        blurActiveDescendant();
      },
      active: () => {
        return getActiveDescendant()?.id;
      },
      focus: (id: string) => {
        if (!listboxRef.current) {
          return;
        }

        const target = listboxRef.current.querySelector<HTMLElement>(`#${id}`);
        if (target) {
          focusActiveDescendant(target);
        }
      },
      focusLastActive: () => {
        if (!listboxRef.current || !lastActiveIdRef.current) {
          return;
        }

        const target = listboxRef.current.querySelector<HTMLElement>(`#${lastActiveIdRef.current}`);
        if (target) {
          focusActiveDescendant(target);
          return true;
        }
      },
      find(predicate, { passive, startFrom } = {}) {
        const target = optionWalker.find(predicate, startFrom);
        if (!passive) {
          focusActiveDescendant(target);
        }

        return target?.id;
      },
      scrollActiveIntoView: () => {
        if (!listboxRef.current) {
          return;
        }

        const active = getActiveDescendant();
        if (!active) {
          return;
        }

        scrollIntoView(active);
      },
      showAttributes() {
        attributeVisibilityRef.current = true;
        setAttribute();
      },
      hideAttributes() {
        attributeVisibilityRef.current = false;
        removeAttribute();
      },
      showFocusVisibleAttributes() {
        setShouldShowFocusVisibleAttribute(true);
      },
      hideFocusVisibleAttributes() {
        setShouldShowFocusVisibleAttribute(false);
      },
    }),
    [
      optionWalker,
      listboxRef,
      setAttribute,
      removeAttribute,
      focusActiveDescendant,
      blurActiveDescendant,
      getActiveDescendant,
      setShouldShowFocusVisibleAttribute,
    ],
  );

  React.useImperativeHandle(imperativeRef, () => controller);

  return { listboxRef: useMergedRefs(listboxRef, listboxCallbackRef), activeParentRef, controller };
}

'use client';

import * as React from 'react';
import { useFluent_unstable as useFluent } from '@fluentui/react-shared-contexts';
import { isHTMLElement } from '@fluentui/react-utilities';

interface UseOptionWalkerOptions {
  matchOption: (el: HTMLElement) => boolean;
}

export function useOptionWalker<TListboxElement extends HTMLElement>(
  options: UseOptionWalkerOptions,
): {
  optionWalker: {
    first: () => HTMLElement | null;
    last: () => HTMLElement | null;
    next: () => HTMLElement | null;
    prev: () => HTMLElement | null;
    find: (predicate: (id: string) => boolean, startFrom?: string) => HTMLElement | null;
    setCurrent: (el: HTMLElement) => void;
  };
  listboxCallbackRef: (el: TListboxElement) => void;
} {
  const { matchOption } = options;
  const { targetDocument } = useFluent();
  const treeWalkerRef = React.useRef<TreeWalker | null>(null);
  const listboxRef = React.useRef<TListboxElement | null>(null);

  const optionFilter = React.useCallback(
    (node: Node) => {
      if (isHTMLElement(node) && matchOption(node)) {
        return NodeFilter.FILTER_ACCEPT;
      }

      return NodeFilter.FILTER_SKIP;
    },
    [matchOption],
  );

  const setListbox = React.useCallback(
    (el: TListboxElement) => {
      if (el && targetDocument) {
        listboxRef.current = el;
        treeWalkerRef.current = targetDocument.createTreeWalker(el, NodeFilter.SHOW_ELEMENT, optionFilter);
      } else {
        listboxRef.current = null;
        treeWalkerRef.current = null;
      }
    },
    [targetDocument, optionFilter],
  );

  const optionWalker = React.useMemo(
    () => ({
      first: () => {
        if (!treeWalkerRef.current || !listboxRef.current) {
          return null;
        }

        treeWalkerRef.current.currentNode = listboxRef.current;
        return treeWalkerRef.current.firstChild() as HTMLElement | null;
      },
      last: () => {
        if (!treeWalkerRef.current || !listboxRef.current) {
          return null;
        }

        treeWalkerRef.current.currentNode = listboxRef.current;
        return treeWalkerRef.current.lastChild() as HTMLElement | null;
      },
      next: () => {
        if (!treeWalkerRef.current) {
          return null;
        }

        return treeWalkerRef.current.nextNode() as HTMLElement | null;
      },
      prev: () => {
        if (!treeWalkerRef.current) {
          return null;
        }

        return treeWalkerRef.current.previousNode() as HTMLElement | null;
      },
      find: (predicate: (id: string) => boolean, startFrom?: string) => {
        if (!treeWalkerRef.current || !listboxRef.current) {
          return null;
        }

        const start = startFrom ? targetDocument?.getElementById(startFrom) : null;
        treeWalkerRef.current.currentNode = start ?? listboxRef.current;
        let cur: HTMLElement | null = treeWalkerRef.current.currentNode as HTMLElement;
        while (cur && !predicate(cur.id)) {
          cur = treeWalkerRef.current.nextNode() as HTMLElement | null;
        }

        return cur;
      },
      setCurrent: (el: HTMLElement) => {
        if (!treeWalkerRef.current) {
          return;
        }

        treeWalkerRef.current.currentNode = el;
      },
    }),
    [targetDocument],
  );

  return {
    optionWalker,
    listboxCallbackRef: setListbox,
  };
}

export { useARIAButtonProps } from './useARIAButtonProps';
// eslint-disable-next-line @typescript-eslint/no-deprecated
export { useARIAButtonShorthand } from './useARIAButtonShorthand';
export type {
  ARIAButtonAlteredProps,
  ARIAButtonElement,
  ARIAButtonElementIntersection,
  ARIAButtonProps,
  ARIAButtonResultProps,
  ARIAButtonSlotProps,
  ARIAButtonType,
} from './types';

import type {
  DistributiveOmit,
  ExtractSlotProps,
  Slot,
  UnionToIntersection,
  JSXIntrinsicElement,
} from '@fluentui/react-utilities';
import type * as React from 'react';

export type ARIAButtonType = 'button' | 'a' | 'div';

export type ARIAButtonElement<AlternateAs extends 'a' | 'div' = 'a' | 'div'> =
  | HTMLButtonElement
  | (AlternateAs extends 'a' ? HTMLAnchorElement : never)
  | (AlternateAs extends 'div' ? HTMLDivElement : never);

/**
 * @internal
 */
export type ARIAButtonElementIntersection<AlternateAs extends 'a' | 'div' = 'a' | 'div'> = UnionToIntersection<
  ARIAButtonElement<AlternateAs>
>;

/**
 * Props expected by `useARIAButtonProps` hooks
 */
export type ARIAButtonProps<Type extends ARIAButtonType = ARIAButtonType> = DistributiveOmit<
  // eslint-disable-next-line @typescript-eslint/no-deprecated
  React.PropsWithRef<JSXIntrinsicElement<Type>>,
  'children'
> & {
  disabled?: boolean;
  /**
   * When set, allows the button to be focusable even when it has been disabled.
   * This is used in scenarios where it is important to keep a consistent tab order
   * for screen reader and keyboard users. The primary example of this
   * pattern is when the disabled button is in a menu or a commandbar and is seldom used for standalone buttons.
   *
   * @default false
   */
  disabledFocusable?: boolean;
};

export type ARIAButtonSlotProps<AlternateAs extends 'a' | 'div' = 'a' | 'div'> = ExtractSlotProps<
  Slot<'button', AlternateAs>
> &
  Pick<ARIAButtonProps<ARIAButtonType>, 'disabled' | 'disabledFocusable'>;

/**
 * Props that will be modified internally by `useARIAButtonProps` by each case.
 * This typing is to ensure a well specified return value for `useARIAbButtonProps`
 */
export type ARIAButtonAlteredProps<Type extends ARIAButtonType> =
  | (Type extends 'button'
      ? Pick<
          JSXIntrinsicElement<'button'>,
          'onClick' | 'onKeyDown' | 'onKeyUp' | 'disabled' | 'aria-disabled' | 'tabIndex'
        >
      : never)
  | (Type extends 'a'
      ? Pick<
          JSXIntrinsicElement<'a'>,
          'onClick' | 'onKeyDown' | 'onKeyUp' | 'aria-disabled' | 'tabIndex' | 'role' | 'href'
        >
      : never)
  | (Type extends 'div'
      ? Pick<JSXIntrinsicElement<'div'>, 'onClick' | 'onKeyDown' | 'onKeyUp' | 'aria-disabled' | 'tabIndex' | 'role'>
      : never);

/**
 * Merge of props provided by the user and props provided internally.
 */
export type ARIAButtonResultProps<Type extends ARIAButtonType, Props> = Props &
  UnionToIntersection<ARIAButtonAlteredProps<Type>>;

'use client';

import { Enter, Space } from '@fluentui/keyboard-keys';
import { useEventCallback } from '@fluentui/react-utilities';
import type * as React from 'react';
import type { ARIAButtonElementIntersection, ARIAButtonProps, ARIAButtonResultProps, ARIAButtonType } from './types';

/**
 * Button keyboard handling, role, disabled and tabIndex implementation that ensures ARIA spec
 * for multiple scenarios of non native button elements. Ensuring 1st rule of ARIA for cases
 * where no attribute addition is required.
 *
 * @internal
 * @param type - the proper scenario to be interpreted by the hook.
 *  1. `button` - Minimal interference from the hook, as semantic button already supports most of the states
 *  2. `a` or `div` - Proper keyboard/mouse handling plus other support to ensure ARIA behavior
 * @param props - the props to be passed down the line to the desired element.
 * This hook will encapsulate proper properties, such as `onClick`, `onKeyDown`, `onKeyUp`, etc,.
 *
 * @example
 * ```tsx
 * const buttonProps = useARIAButtonProps('a', {
 *   href: './some-route'
 *   onClick: () => console.log('this should run both on click and Space and Enter')
 * })
 *
 * // ...
 *
 * return (
 *  <a {...buttonProps}>This anchor will behave as a proper button</a>
 * )
 * ```
 */
export function useARIAButtonProps<Type extends ARIAButtonType, Props extends ARIAButtonProps<Type>>(
  type?: Type,
  props?: Props,
): ARIAButtonResultProps<Type, Props> {
  const {
    disabled,
    disabledFocusable = false,
    ['aria-disabled']: ariaDisabled,
    onClick,
    onKeyDown,
    onKeyUp,
    ...rest
  } = props ?? {};

  const normalizedARIADisabled = typeof ariaDisabled === 'string' ? ariaDisabled === 'true' : ariaDisabled;

  const isDisabled = disabled || disabledFocusable || normalizedARIADisabled;

  const handleClick = useEventCallback((ev: React.MouseEvent<ARIAButtonElementIntersection>) => {
    if (isDisabled) {
      ev.preventDefault();
      ev.stopPropagation();
    } else {
      onClick?.(ev);
    }
  });

  const handleKeyDown = useEventCallback((ev: React.KeyboardEvent<ARIAButtonElementIntersection>) => {
    onKeyDown?.(ev);

    if (ev.isDefaultPrevented()) {
      return;
    }

    const key = ev.key;

    if (isDisabled && (key === Enter || key === Space)) {
      ev.preventDefault();
      ev.stopPropagation();
      return;
    }

    if (key === Space) {
      ev.preventDefault();
      return;
    }

    // If enter is pressed, activate the button
    else if (key === Enter) {
      ev.preventDefault();
      ev.currentTarget.click();
    }
  });

  const handleKeyUp = useEventCallback((ev: React.KeyboardEvent<ARIAButtonElementIntersection>) => {
    onKeyUp?.(ev);

    if (ev.isDefaultPrevented()) {
      return;
    }

    const key = ev.key;

    if (isDisabled && (key === Enter || key === Space)) {
      ev.preventDefault();
      ev.stopPropagation();
      return;
    }

    if (key === Space) {
      ev.preventDefault();
      ev.currentTarget.click();
    }
  });

  // If a <button> tag is to be rendered we just need to set disabled and aria-disabled correctly
  if (type === 'button' || type === undefined) {
    return {
      ...rest,
      disabled: disabled && !disabledFocusable,
      'aria-disabled': disabledFocusable ? true : normalizedARIADisabled,
      // onclick should still use internal handler to ensure prevention if disabled
      // if disabledFocusable then there's no requirement for handlers as those events should not be propagated
      onClick: disabledFocusable ? undefined : handleClick,
      onKeyUp: disabledFocusable ? undefined : onKeyUp,
      onKeyDown: disabledFocusable ? undefined : onKeyDown,
    } as ARIAButtonResultProps<Type, Props>;
  }

  // If an <a> or <div> tag is to be rendered we have to remove disabled and type,
  // and set aria-disabled, role and tabIndex.
  else {
    // the role needs to be explicitly set if the href is undefined
    const isLink = !!(rest as ARIAButtonResultProps<'a', Props>).href;
    let roleOverride = isLink ? undefined : 'button';
    if (!roleOverride && isDisabled) {
      // need to set role=link explicitly for disabled links
      roleOverride = 'link';
    }

    const resultProps = {
      role: roleOverride,
      tabIndex: disabledFocusable || (!isLink && !disabled) ? 0 : undefined,
      ...rest,
      // If it's not a <button> than listeners are required even with disabledFocusable
      // Since you cannot assure the default behavior of the element
      // E.g: <a> will redirect on click
      onClick: handleClick,
      onKeyUp: handleKeyUp,
      onKeyDown: handleKeyDown,
      'aria-disabled': isDisabled,
    } as ARIAButtonResultProps<Type, Props>;

    if (type === 'a' && isDisabled) {
      (resultProps as ARIAButtonResultProps<'a', Props>).href = undefined;
    }

    return resultProps;
  }
}

