import type { ForwardRefComponent } from '@fluentui/react-utilities';
import type { CalendarDayGridCellProps } from './CalendarDayGridCell.types';

/**
 * A single day in the grid. Days repeat per week, so the cell resolves its own `dayCell` shorthand
 * from the grid context rather than being resolved once by the grid.
 */
export const CalendarDayGridCell: ForwardRefComponent<CalendarDayGridCellProps> = React.forwardRef((props, ref) => {
  const state = useCalendarDayGridCell_unstable(props, ref);

  useCalendarDayGridCellStyles_unstable(state);

  return renderCalendarDayGridCell_unstable(state);
});

CalendarDayGridCell.displayName = 'CalendarDayGridCell';

import type { ComponentProps, ComponentState, Slot } from '@fluentui/react-utilities';
import type { DayInfo } from '../../hooks/useWeeks';

/**
 * Defines the CalendarDayGridCellSlots contract.
 */
export type CalendarDayGridCellSlots = {
  /**
   * The `role="gridcell"` element for a single day. Resolved from the grid's `dayCell` shorthand,
   * so a consumer can take the cell over entirely.
   */
  root: NonNullable<Slot<'td'>>;

  /**
   * The button rendered inside the cell, which carries the day's accessible name.
   */
  button: NonNullable<Slot<'button'>>;

  /**
   * The formatted day number.
   */
  dayLabel: NonNullable<Slot<'span'>>;

  /**
   * The dot shown under marked days. Only rendered while the day is marked.
   */
  marker?: Slot<'div'>;
};

/**
 * Defines the CalendarDayGridCellProps contract.
 */
export type CalendarDayGridCellProps = ComponentProps<Partial<CalendarDayGridCellSlots>> & {
  day: DayInfo;

  dayIndex: number;

  weekIndex: number;

  /**
   * Set on the transition rows, which exist only to be animated out.
   */
  ariaHidden?: boolean;
};

/**
 * Defines the CalendarDayGridCellState contract.
 */
export type CalendarDayGridCellState = ComponentState<CalendarDayGridCellSlots> & {
  day: DayInfo;

  lightenDaysOutsideNavigatedMonth: boolean;
};

export { CalendarDayGridCell } from './CalendarDayGridCell';
export { useCalendarDayGridCell_unstable } from './useCalendarDayGridCell';
export { renderCalendarDayGridCell_unstable } from './renderCalendarDayGridCell';
export {
  calendarDayGridCellClassNames,
  useCalendarDayGridCellStyles_unstable,
} from './useCalendarDayGridCellStyles.styles';
export type {
  CalendarDayGridCellProps,
  CalendarDayGridCellSlots,
  CalendarDayGridCellState,
} from './CalendarDayGridCell.types';

/** @jsxRuntime automatic */
/** @jsxImportSource @fluentui/react-jsx-runtime */
import { assertSlots } from '@fluentui/react-utilities';
import type { JSXElement } from '@fluentui/react-utilities';
import type { CalendarDayGridCellSlots, CalendarDayGridCellState } from './CalendarDayGridCell.types';

/**
 * Render the final JSX of CalendarDayGridCell.
 */
export const renderCalendarDayGridCell_unstable = (state: CalendarDayGridCellState): JSXElement => {
  assertSlots<CalendarDayGridCellSlots>(state);

  return (
    <state.root>
      <state.button>
        <state.dayLabel />
        {state.marker && <state.marker />}
      </state.button>
    </state.root>
  );
};

