    grid,
    header,
    navigation,
    nextYearButton,
    onHeaderSelect: onUserHeaderSelect,
    onNavigateDate = noop,
    onSelectDate,
    previousYearButton,
    heading,
    yearPicker,
    yearPickerHidden = false,
