      if (onSelectDate) {
        const availableDates = getDateRange(date, 'month', firstDayOfWeek).filter(
          rangeDate => !isRestrictedDate(rangeDate, { minDate, maxDate, restrictedDates }),
        );
        if (!availableDates.length) {
          return;
