    yearPickerProps = {
      navigatedYear: navigatedDate.getFullYear(),
      selectedYear: selectedDate === null ? null : selectedDate?.getFullYear(),
      onHeaderSelect: onYearPickerHeaderSelect,
      onSelectYear,
    };
  }

  return {
    isYearPickerVisible,
    monthRows,
    navigatedMonthRef,
    navigatedYear: navigatedDate.getFullYear(),
    yearPickerRef,
    yearString,
    components: {
      root: 'div',
      header: 'div',
      heading: 'button',
      navigation: 'div',
      previousYearButton: 'button',
      nextYearButton: 'button',
      grid: 'div',
      yearPicker: 'div',
    },
    root: slot.always(getIntrinsicElementProps('div', props), { elementType: 'div' }),
    header: slot.always(header, { elementType: 'div' }),
