import { motionTokens, createMotionComponent } from '@fluentui/react-motion';
import { Slide, fadeAtom, slideAtom } from '@fluentui/react-motion-components-preview';
import { tokens } from '@fluentui/react-theme';
import * as React from 'react';
import { getReactElementRef, useMergedRefs } from '@fluentui/react-utilities';
import type { MotionComponentProps } from '@fluentui/react-motion';
import type { AnimationDirection } from './constants';
import type { JSXElement } from '@fluentui/react-utilities';

// Distance the rows travel as they slide in/out. Shared so the enter and exit motions stay in sync.
const SLIDE_DISTANCE = tokens.spacingHorizontalXL;

/*
 * Clones the single child with a ref that merges the forwarded ref and the child's own ref. Lets the
 * `DirectionalSlideIn`/`DirectionalSlideOut` wrappers render no DOM of their own while still exposing a
 * ref to the actual child element (e.g. the `<tr>`), keeping them transparent for table semantics.
 */
function useChildWithMergedRef(children: JSXElement, ref: React.Ref<HTMLElement>) {
  const child = React.Children.only(children) as React.ReactElement<{ ref?: React.Ref<HTMLElement> }>;
  const mergedRef = useMergedRefs(ref, getReactElementRef(child));
  return React.cloneElement(child, { ref: mergedRef });
}

/**
 * Params the calendars pass to their row motion slots. All rows in a grid share the same values,
 * so they are baked into the slot's `defaultProps` rather than passed per row.
 */
export type DirectionalSlideParams = {
  /**
   * The direction in which the row should slide.
   */
  animationDirection: AnimationDirection;
  /**
   * Whether the row should animate in the reverse direction.
   */
  animateBackwards?: boolean;
  /**
   * When this value changes, the animation replays from the start on the same DOM element without
   * remounting the subtree, so focus and DOM identity survive keyboard navigation.
   */
  replayKey: string | number;
};

/**
 * Params for the transition-row exit motion, which additionally needs to know which edge of the
 * grid it sits on. `edge` is supplied by the row, not by the picker.
 */
export type DirectionalSlideOutParams = DirectionalSlideParams & {
  edge?: 'first' | 'last';
};

export type DirectionalSlideInProps = MotionComponentProps & {
  duration?: number;
  easing?: string;
  animationDirection?: AnimationDirection;
  animateBackwards?: boolean;
};

/*
 * `forwardRef` per the repo rule banning `React.FC`. This wrapper renders no DOM of its own,
 * so the forwarded ref is cloned onto the child below — callers get a ref to the actual
 * `<tr>`/`<div role="row">`, keeping `DirectionalSlideIn` transparent.
 */
export const DirectionalSlideIn = React.forwardRef<HTMLElement, DirectionalSlideInProps>((props, ref) => {
  const {
    // Using durationSlower (400ms) as the closest token to the original 367ms
    duration = motionTokens.durationSlower,
    easing = motionTokens.curveDecelerateMax,
    animationDirection = 'vertical',
    animateBackwards = false,
    replayKey,
    children,
    ...motionProps
  } = props;

  let outX = '0px';
  let outY = '0px';
  const distance = animateBackwards ? `calc(-1 * ${SLIDE_DISTANCE})` : SLIDE_DISTANCE;
  if (animationDirection === 'horizontal') {
    outX = distance;
  } else {
    outY = distance;
  }

  // `Slide.In`'s `useChildElement` will further merge its motion ref on top.
  const childWithRef = useChildWithMergedRef(children, ref);

  /*
   * `Slide.In` bakes `outY` into its atoms at mount and `replayKey` only replays them, so a
   * direction flip needs a remount. Same-direction navigations keep the key and reuse the DOM.
   */
  const directionKey = animateBackwards ? 'back' : 'fwd';

  return (
    <Slide.In
      key={directionKey}
      duration={duration}
      easing={easing}
      outX={outX}
      outY={outY}
      replayKey={replayKey}
      {...motionProps}
    >
      {childWithRef}
    </Slide.In>
  );
});

DirectionalSlideIn.displayName = 'DirectionalSlideIn';

/*
 * One-way "out" motion for the day grid's transition (filler) rows. It fades and slides the row
 * out in the navigation direction (the top row slides up, the bottom row slides down). The row is
 * `position: absolute` and `opacity: 0` at rest, so the motion's forwards fill leaves it back at its
 * hidden resting state once it finishes. Composed from Fluent's `fadeAtom` + `slideAtom` so it stays
 * consistent with the rest of the motion system; there is no size animation, because the row is
 * overlaid out of flow and hidden via opacity (not by collapsing its box).
 */
const TransitionRowSlideOut = createMotionComponent(({ outY }: { outY: string }) => {
  const duration = motionTokens.durationSlower;
  const easing = motionTokens.curveDecelerateMax;
  return [fadeAtom({ direction: 'exit', duration, easing }), slideAtom({ direction: 'exit', duration, easing, outY })];
});

export type DirectionalSlideOutProps = MotionComponentProps & {
  /**
   * Which transition row this wraps: the first (top) or last (bottom) filler row.
   */
  edge?: 'first' | 'last';
  /**
   * The direction in which the row should slide.
   */
  animationDirection?: AnimationDirection;
  /**
   * Whether the row should animate in the reverse direction.
   */
  animateBackwards?: boolean;
};

/*
 * `forwardRef` per the repo rule banning `React.FC`. Like `DirectionalSlideIn`, this wrapper renders
 * no DOM of its own — the forwarded ref is cloned onto the child so callers get a ref to the actual
 * `<tr>`, keeping the wrapper transparent for table semantics.
 */
export const DirectionalSlideOut = React.forwardRef<HTMLElement, DirectionalSlideOutProps>((props, ref) => {
  const {
    edge = 'first',
    animationDirection = 'vertical',
    animateBackwards,
    replayKey,
    children,
    ...motionProps
  } = props;

  const childWithRef = useChildWithMergedRef(children, ref);

  /*
   * The legacy animation only ran for vertical navigation, and only on the row matching the
   * navigation direction: the top (first) row slides up & out when navigating forward, the bottom
   * (last) row slides down & out when navigating backward. `animateBackwards === undefined` means no
   * navigation has happened yet, so nothing animates on initial mount (the row stays hidden at rest).
   */
  const isVertical = animationDirection !== 'horizontal';
  const shouldAnimate =
    isVertical && animateBackwards !== undefined && (edge === 'first' ? !animateBackwards : animateBackwards);

  if (!shouldAnimate) {
    return childWithRef;
  }

  // First (top) row slides up and out; last (bottom) row slides down and out.
  const outY = edge === 'first' ? `calc(-1 * ${SLIDE_DISTANCE})` : SLIDE_DISTANCE;

  return (
    <TransitionRowSlideOut outY={outY} replayKey={replayKey} {...motionProps}>
      {childWithRef}
    </TransitionRowSlideOut>
  );
});

DirectionalSlideOut.displayName = 'DirectionalSlideOut';

/**
 * Renders a boolean as a presence data attribute: `''` when true, `undefined` when false so the
 * attribute is omitted entirely.
 */
export function stringifyDataAttribute(value: boolean | undefined): '' | undefined {
  return value ? '' : undefined;
}

import { addDays, compareDatePart } from '../dateMath';
import type { AvailableDateOptions, RestrictedDatesOptions } from './dateGrid.types';

/**
 * Checks if a date is after the maximum allowed date based on the given restrictions.
 */
const isAfterMaxDate = (date: Date, options: RestrictedDatesOptions): boolean => {
  const { maxDate } = options;
  return maxDate ? compareDatePart(date, maxDate) >= 1 : false;
};

/**
 * Checks if a date is before the minimum allowed date based on the given restrictions.
 */
const isBeforeMinDate = (date: Date, options: RestrictedDatesOptions): boolean => {
  const { minDate } = options;
  return minDate ? compareDatePart(minDate, date) >= 1 : false;
};

/**
 * Checks if `date` falls into the restricted `options`
 * @param date - date to check
 * @param options - restriction options (min date, max date and list of restricted dates)
 */
export const isRestrictedDate = (date: Date, options: RestrictedDatesOptions): boolean => {
  const { restrictedDates, minDate, maxDate } = options;
  if (!restrictedDates && !minDate && !maxDate) {
    return false;
  }
  const inRestrictedDates = restrictedDates && restrictedDates.some((rd: Date) => compareDatePart(rd, date) === 0);
  return inRestrictedDates || isBeforeMinDate(date, options) || isAfterMaxDate(date, options);
};

/**
 * Returns closest available date given the restriction `options`, or undefined otherwise
 * @param options - list of search options
 * @throws RangeError if the direction is not 1 or -1, or search dates cannot be represented.
 */
export const findAvailableDate = (options: AvailableDateOptions): Date | undefined => {
  const { targetDate, initialDate, direction, ...restrictionOptions } = options;
  if (direction !== 1 && direction !== -1) {
    throw new RangeError('direction must be 1 or -1.');
  }
  if (!Number.isFinite(targetDate.getTime()) || !Number.isFinite(initialDate.getTime())) {
    throw new RangeError('targetDate and initialDate must be valid.');
  }

  let availableDate = targetDate;
  let daysOffset = 0;
  // if the target date is available, return it immediately
  if (!isRestrictedDate(targetDate, restrictionOptions)) {
    return targetDate;
  }

  while (
    compareDatePart(initialDate, availableDate) !== 0 &&
    isRestrictedDate(availableDate, restrictionOptions) &&
    !isAfterMaxDate(availableDate, restrictionOptions) &&
    !isBeforeMinDate(availableDate, restrictionOptions)
  ) {
    // A skipped local date may normalize back to the previous candidate.
    daysOffset += direction;
    availableDate = addDays(targetDate, daysOffset);
    if (!Number.isFinite(availableDate.getTime())) {
      throw new RangeError('Cannot search for an out-of-range date.');
    }
  }

  if (compareDatePart(initialDate, availableDate) !== 0 && !isRestrictedDate(availableDate, restrictionOptions)) {
    return availableDate;
  }

  return undefined;
};

/**
 * Generates a list of dates, bounded by min and max dates
 * @param dateRange - input date range
 * @param minDate - min date to limit the range
 * @param maxDate - max date to limit the range
 */
export const getBoundedDateRange = (dateRange: Date[], minDate?: Date, maxDate?: Date): Date[] => {
  let boundedDateRange = [...dateRange];
  if (minDate) {
    boundedDateRange = boundedDateRange.filter(date => compareDatePart(date, minDate) >= 0);
  }
  if (maxDate) {
    boundedDateRange = boundedDateRange.filter(date => compareDatePart(date, maxDate) <= 0);
  }
  return boundedDateRange;
};

import type { DayOfWeek, DateRangeType, FirstWeekOfYear } from '../constants';

export interface Day {
  /**
   * Local year, zero-based month, and day joined with hyphens (`year-month-day`)
   */
  key: string;
  /**
   * `Date.getDate()` value of current date
   */
  date: string;
  /**
   * `Date` object of current date
   */
  originalDate: Date | null;
  /**
   * Whether this cell represents a civil date that does not exist in the local timezone.
   */
  isPlaceholder: boolean;
  /**
   * Whether the current date is in the same month as the navigated date
   */
  isInMonth: boolean;
  /**
   * Is current date is "today" date
   */
  isToday: boolean;
  /**
   * Whether the current date is selected in a range
   */
  isSelected: boolean;
  /**
   * Whether the current date is selected without a range
   */
  isSingleSelected: boolean;
  /**
   * Is current date within restriction boundaries
   */
  isInBounds: boolean;
  /**
   * Is current date marked
   */
  isMarked: boolean;
}

export interface AvailableDateOptions extends RestrictedDatesOptions {
  /**
   * Date from which we start the search
   */
  initialDate: Date;
  /**
   * Ideal available date
   */
  targetDate: Date;
  /**
   * Direction of search (`1` - search in future / `-1` search in past)
   */
  direction: 1 | -1;
}

export interface RestrictedDatesOptions {
  /**
   * If set the Calendar will not allow navigation to or selection of a date earlier than this value.
   */
  minDate?: Date;

  /**
   * If set the Calendar will not allow navigation to or selection of a date later than this value.
   */
  maxDate?: Date;

  /**
   * If set the Calendar will not allow selection of dates in this array.
   */
  restrictedDates?: Date[];
}

export interface DayGridOptions extends RestrictedDatesOptions {
  /**
   * The first day of the week for your locale.
   */
  firstDayOfWeek: DayOfWeek;

  /**
   * Defines when the first week of the year should start.
   */
  firstWeekOfYear: FirstWeekOfYear;

  /**
   * The date range type indicating how  many days should be selected as the user
   * selects days
   */
  dateRangeType: DateRangeType;

  /**
   * The number of days to select while `dateRangeType` is `day`. Used in order to have multi-day
   * views.
   */
  daysToSelectInDayView?: number;

  /**
   * Value of today. If unspecified, current time in client machine will be used.
   */
  today?: Date;

  /**
   * Whether the calendar should show the week number before each week row
   */
  showWeekNumbers?: boolean;

  /**
   * The days that are selectable when `dateRangeType` is `workWeek`.
   * If `dateRangeType` is not `workWeek` this property does nothing.
   */
  workWeekDays?: DayOfWeek[];

  /**
   * Which days in the generated grid should be marked.
   */
  markedDays?: Date[];

  /**
   * The currently selected date
   */
  selectedDate?: Date | null;

  /**
   * The currently navigated date
   */
  navigatedDate: Date;

  /**
   * How many weeks to show by default. If not provided, will show enough weeks to display the current
   * month, between 4 and 6 depending
   */
  weeksToShow?: number;
}

import { areDatesEqual, createDate, getDateRange, getStartDateOfWeek, isDateInRange } from '../dateMath';
import { DAYS_IN_WEEK, DEFAULT_WORK_WEEK_DAYS } from '../constants';
import type { DayOfWeek } from '../constants';
import type { Day, DayGridOptions } from './dateGrid.types';
import { getBoundedDateRange, isRestrictedDate } from './dateAvailability';
import { getDateRangeTypeToUse } from './workWeek';

/**
 * Generates a grid of days, given the `options`.
 * Returns one additional week at the beginning from the previous range
 * and one at the end from the future range
 * @param options - parameters to specify date related restrictions for the resulting grid
 * @throws RangeError if the week count is invalid or grid dates cannot be represented.
 */
export const getDayGrid = (options: DayGridOptions): Day[][] => {
  const {
    selectedDate,
    dateRangeType,
    firstDayOfWeek,
    today,
    minDate,
    maxDate,
    weeksToShow,
    workWeekDays,
    daysToSelectInDayView,
    restrictedDates,
    markedDays,
  } = options;

  if (
    weeksToShow !== undefined &&
    (!Number.isFinite(weeksToShow) || !Number.isInteger(weeksToShow) || weeksToShow <= 0)
  ) {
    throw new RangeError('weeksToShow must be a positive finite integer.');
  }

  const restrictedDateOptions = { minDate, maxDate, restrictedDates };
  const effectiveWorkWeekDays: DayOfWeek[] = workWeekDays ?? [...DEFAULT_WORK_WEEK_DAYS];

  const todaysDate = today || new Date();

  const navigatedDate = options.navigatedDate ? options.navigatedDate : todaysDate;

  if (!Number.isFinite(navigatedDate.getTime())) {
    throw new RangeError('navigatedDate must be valid.');
  }

  let date;
  if (weeksToShow && weeksToShow <= 4) {
    // if showing less than a full month, just use date == navigatedDate
    date = createDate(navigatedDate.getFullYear(), navigatedDate.getMonth(), navigatedDate.getDate());
  } else {
    date = createDate(navigatedDate.getFullYear(), navigatedDate.getMonth(), 1);
  }
  const weeks: Day[][] = [];

  date = getStartDateOfWeek(date, firstDayOfWeek);

  // add the transition week as last week of previous range
  date = createDate(date.getFullYear(), date.getMonth(), date.getDate() - DAYS_IN_WEEK);
  let civilDate = {
    year: date.getFullYear(),
    month: date.getMonth(),
    day: date.getDate(),
  };

  // a flag to indicate whether all days of the week are outside the month
  let isAllDaysOfWeekOutOfMonth = false;
  let hasReachedNavigatedMonth = false;

  // in work week view if the days aren't contiguous we use week view instead
  const selectedDateRangeType = getDateRangeTypeToUse(dateRangeType, effectiveWorkWeekDays, firstDayOfWeek);

  let selectedDates: Date[] = [];

  if (selectedDate) {
    selectedDates = getDateRange(
      selectedDate,
      selectedDateRangeType,
      firstDayOfWeek,
      effectiveWorkWeekDays,
      daysToSelectInDayView,
    );
    selectedDates = getBoundedDateRange(selectedDates, minDate, maxDate);
  }

  let shouldGetWeeks = true;

  for (let weekIndex = 0; shouldGetWeeks; weekIndex++) {
    const week: Day[] = [];

    isAllDaysOfWeekOutOfMonth = true;

    for (let dayIndex = 0; dayIndex < DAYS_IN_WEEK; dayIndex++) {
      const { year: civilYear, month: civilMonth, day: civilDay } = civilDate;
      if (!Number.isFinite(civilYear) || !Number.isFinite(civilMonth) || !Number.isFinite(civilDay)) {
        throw new RangeError('Cannot generate a grid containing an out-of-range date.');
      }
      const originalDate = createDate(civilYear, civilMonth, civilDay);
      const isPlaceholder =
        originalDate.getFullYear() !== civilYear ||
        originalDate.getMonth() !== civilMonth ||
        originalDate.getDate() !== civilDay;
      if (!isPlaceholder && !Number.isFinite(originalDate.getTime())) {
        throw new RangeError('Cannot generate a grid containing an out-of-range date.');
      }
      const dayInfo: Day = {
        key: `${civilYear}-${civilMonth}-${civilDay}`,
        date: civilDay.toString(),
        originalDate: isPlaceholder ? null : originalDate,
        isPlaceholder,
        isInMonth: civilYear === navigatedDate.getFullYear() && civilMonth === navigatedDate.getMonth(),
        isToday: !isPlaceholder && areDatesEqual(todaysDate, originalDate),
        isSelected: !isPlaceholder && isDateInRange(originalDate, selectedDates),
        isSingleSelected:
          !isPlaceholder && !!selectedDate && selectedDates.length === 1 && areDatesEqual(originalDate, selectedDate),
        isInBounds: !isPlaceholder && !isRestrictedDate(originalDate, restrictedDateOptions),
        isMarked:
          (!isPlaceholder && markedDays?.some((markedDay: Date) => areDatesEqual(originalDate, markedDay))) || false,
      };

      week.push(dayInfo);

      if (dayInfo.isInMonth) {
        isAllDaysOfWeekOutOfMonth = false;
        hasReachedNavigatedMonth = true;
      }

      const nextCivilDate = new Date(0);
      nextCivilDate.setUTCFullYear(civilYear, civilMonth, civilDay + 1);
      civilDate = {
        year: nextCivilDate.getUTCFullYear(),
        month: nextCivilDate.getUTCMonth(),
        day: nextCivilDate.getUTCDate(),
      };
      date = createDate(civilDate.year, civilDate.month, civilDate.day);
    }

    // A fixed week count includes both transition rows; a skipped weekday may add leading rows in month view.
    shouldGetWeeks = weeksToShow
      ? weekIndex < weeksToShow + 1
      : !isAllDaysOfWeekOutOfMonth || !hasReachedNavigatedMonth;

    // we don't check shouldGetWeeks before pushing because we want to add one extra week for transition state
    weeks.push(week);
  }

  return weeks;
};

export type { AvailableDateOptions, Day, DayGridOptions, RestrictedDatesOptions } from './dateGrid.types';
export { findAvailableDate, getBoundedDateRange, isRestrictedDate } from './dateAvailability';
export { getDayGrid } from './getDayGrid';

import { getDayFromIndex, getDayIndex } from '../dateUtils';
import type { DateRangeType, DayOfWeek } from '../constants';

/**
 * Checks if the given set of days forms a contiguous sequence within a week.
 */
const isContiguous = (days: DayOfWeek[], isSingleWeek: boolean, firstDayOfWeek: DayOfWeek): boolean => {
  const daySet = new Set(days);
  let amountOfNoNeighbors = 0;
  for (const day of daySet) {
    const nextDay = getDayFromIndex(getDayIndex(day) + 1);
    if (!(daySet.has(nextDay) && (!isSingleWeek || firstDayOfWeek !== nextDay))) {
      amountOfNoNeighbors++;
    }
  }

  /*
   *  In case the full week is provided, then each day has a neighbor
   * , otherwise the last day does not have a neighbor.
   */
  return amountOfNoNeighbors < 2;
};

/**
 * Return corrected date range type, given `dateRangeType` and list of working days.
 * For non-contiguous working days and working week range type, returns general week range type.
 * For other cases returns input date range type.
 * @param dateRangeType - input type of range
 * @param workWeekDays - list of working days in a week
 */
export const getDateRangeTypeToUse = (
  dateRangeType: DateRangeType,
  workWeekDays: DayOfWeek[] | undefined,
  firstDayOfWeek: DayOfWeek,
): DateRangeType => {
  if (workWeekDays && dateRangeType === 'workWeek') {
    if (!isContiguous(workWeekDays, true, firstDayOfWeek) || new Set(workWeekDays).size === 0) {
      return 'week';
    }
  }

  return dateRangeType;
};

import { DAYS_IN_WEEK, DEFAULT_WORK_WEEK_DAYS } from './constants';
import { getDayIndex, getMonthIndex } from './dateUtils';
import type { DateRangeType, DayOfWeek, FirstWeekOfYear } from './constants';

/**
 * Creates a new Date object with the specified year, month, and day, with the time set to midnight.
 */
export function createDate(year: number, month: number, day: number): Date {
  const date = new Date(0);
  date.setHours(0, 0, 0, 0);
  date.setFullYear(year, month, day);
  return date;
}

/**
 * Returns a date offset from the given date by the specified number of days.
 * @param date - The origin date
 * @param days - The number of days to offset. 'days' can be negative.
 * @returns A new Date object offset from the origin date by the given number of days
 */
export function addDays(date: Date, days: number): Date {
  const result = new Date(date.getTime());
  result.setDate(result.getDate() + days);
  return result;
}

/**
 * Returns a date offset from the given date by the specified number of weeks.
 * @param date - The origin date
 * @param weeks - The number of weeks to offset. 'weeks' can be negative.
 * @returns A new Date object offset from the origin date by the given number of weeks
 */
export function addWeeks(date: Date, weeks: number): Date {
  return addDays(date, weeks * DAYS_IN_WEEK);
}

/**
 * Returns a date offset from the given date by the specified number of months.
 * The method tries to preserve the day-of-month; however, if the new month does not have enough days
 * to contain the original day-of-month, we'll use the last day of the new month.
 * @param date - The origin date
 * @param months - The number of months to offset. 'months' can be negative.
 * @returns A new Date object offset from the origin date by the given number of months
 */
export function addMonths(date: Date, months: number): Date {
  let result = new Date(date.getTime());
  const targetMonth = result.getMonth() + months;
  result.setMonth(targetMonth);

  const normalizedTargetMonth = ((targetMonth % 12) + 12) % 12;
  if (result.getMonth() !== normalizedTargetMonth) {
    result = addDays(result, -result.getDate());
  }

  return result;
}

/**
 * Returns a date offset from the given date by the specified number of years.
 * The method tries to preserve the day-of-month; however, if the new month does not have enough days
 * to contain the original day-of-month, we'll use the last day of the new month.
 * @param date - The origin date
 * @param years - The number of years to offset. 'years' can be negative.
 * @returns A new Date object offset from the origin date by the given number of years
 */
export function addYears(date: Date, years: number): Date {
  let result = new Date(date.getTime());
  result.setFullYear(date.getFullYear() + years);

  if (result.getMonth() !== date.getMonth()) {
    result = addDays(result, -result.getDate());
  }

  return result;
}

/**
 * Returns a date that is the first day of the month of the provided date.
 * @param date - The origin date
 * @returns A new Date object with the day set to the first day of the month.
 */
export function getMonthStart(date: Date): Date {
  return createDate(date.getFullYear(), date.getMonth(), 1);
}

/**
 * Returns a date that is the last day of the month of the provided date.
 * @param date - The origin date
 * @returns A new Date object with the day set to the last day of the month.
 */
export function getMonthEnd(date: Date): Date {
  return addDays(createDate(date.getFullYear(), date.getMonth() + 1, 1), -1);
}

/**
 * Returns a date that is the first day of the year of the provided date.
 * @param date - The origin date
 * @returns A new Date object with the day set to the first day of the year.
 */
export function getYearStart(date: Date): Date {
  return createDate(date.getFullYear(), 0, 1);
}

/**
 * Returns a date that is the last day of the year of the provided date.
 * @param date - The origin date
 * @returns A new Date object with the day set to the last day of the year.
 */
export function getYearEnd(date: Date): Date {
  return addDays(createDate(date.getFullYear() + 1, 0, 1), -1);
}

/**
 * Returns a date that is a copy of the given date, aside from the month changing to the given month.
 * The method tries to preserve the day-of-month; however, if the new month does not have enough days
 * to contain the original day-of-month, we'll use the last day of the new month.
 * @param date - The origin date
 * @param month - The 0-based index of the month to set on the date.
 * @returns A new Date object with the given month set.
 */
export function setMonth(date: Date, month: number): Date {
  return addMonths(date, month - date.getMonth());
}

/**
 * Compares two dates, and returns true if the two dates (not accounting for time-of-day) are equal.
 * @returns True if the two dates represent the same date (regardless of time-of-day), false otherwise.
 */
export function areDatesEqual(date1: Date, date2: Date): boolean {
  if (!date1 && !date2) {
    return true;
  } else if (!date1 || !date2) {
    return false;
  } else {
    return compareDatePart(date1, date2) === 0;
  }
}

/**
 * Compare the date parts of two dates
 * @param date1 - The first date to compare
 * @param date2 - The second date to compare
 * @returns A negative value if date1 is earlier than date2, 0 if the dates are equal, or a positive value
 * if date1 is later than date2.
 */
export function compareDatePart(date1: Date, date2: Date): number {
  return (
    date1.getFullYear() - date2.getFullYear() ||
    date1.getMonth() - date2.getMonth() ||
    date1.getDate() - date2.getDate()
  );
}

/**
 * Gets the date range array including the specified date. The date range array is calculated as the list
 * of dates accounting for the specified first day of the week and date range type.
 * @param date - The input date
 * @param dateRangeType - The desired date range type, i.e., day, week, month, etc.
 * @param firstDayOfWeek - The first day of the week.
 * @param workWeekDays - The allowed days in work week. Defaults to Monday through Friday.
 * @param daysToSelectInDayView - The number of days to include when using dateRangeType === 'day'
 * for multiday view. Defaults to 1
 * @returns An array of dates representing the date range containing the specified date.
 */
export function getDateRange(
  date: Date,
  dateRangeType: DateRangeType,
  firstDayOfWeek: DayOfWeek,
  workWeekDays?: DayOfWeek[],
  daysToSelectInDayView: number = 1,
): Date[] {
  if (!Number.isFinite(date.valueOf())) {
    throw new RangeError('date must be valid');
  }

  if (!Number.isFinite(daysToSelectInDayView) || !Number.isInteger(daysToSelectInDayView)) {
    throw new RangeError('daysToSelectInDayView must be a finite integer');
  }

  if (dateRangeType === 'day' && daysToSelectInDayView === 0) {
    return [];
  }

  const datesArray: Date[] = [];
  let startDate: Date;
  let endDate = null;
  let maximumRangeLength: number;

  if (!workWeekDays) {
    workWeekDays = [...DEFAULT_WORK_WEEK_DAYS];
  }

  const workWeekDayIndices = workWeekDays.map(getDayIndex);

  switch (dateRangeType) {
    case 'day':
      // Create a date range for the specified date

      [startDate, endDate] = [date, addDays(date, daysToSelectInDayView)];
      maximumRangeLength = Math.abs(daysToSelectInDayView);

      // If the start date is after the end date, swap them
      if (compareDatePart(startDate, endDate) > 0) {
        /*
         * For reverse dates we need to add one day to both dates
         * to ensure correct start date
         */
        [startDate, endDate] = [addDays(endDate, 1), addDays(startDate, 1)];
      }

      break;

    case 'week':
    case 'workWeek':
      startDate = getStartDateOfWeek(date, firstDayOfWeek);
      endDate = addDays(startDate, DAYS_IN_WEEK);
      if (compareDatePart(date, endDate) >= 0) {
        startDate = addDays(startDate, DAYS_IN_WEEK);
        endDate = addDays(endDate, DAYS_IN_WEEK);
      }
      maximumRangeLength = DAYS_IN_WEEK;
      break;

    case 'month':
      startDate = createDate(date.getFullYear(), date.getMonth(), 1);
      endDate = addMonths(startDate, 1);
      maximumRangeLength = 31;
      break;

    default:
      throw new Error('Unexpected object: ' + dateRangeType);
  }

  if (!Number.isFinite(endDate.getTime())) {
    throw new RangeError('Date range end is outside the representable date range');
  }

  // Populate the dates array with a range-specific bound so a faulty adapter cannot hang rendering.
  let nextDate = startDate;
  for (let index = 0; index < maximumRangeLength && compareDatePart(nextDate, endDate) !== 0; index++) {
    if (dateRangeType !== 'workWeek') {
      // push all days not in work week view
      datesArray.push(nextDate);
    } else if (workWeekDayIndices.indexOf(nextDate.getDay()) !== -1) {
      datesArray.push(nextDate);
    }
    nextDate = addDays(nextDate, 1);
  }

  if (compareDatePart(nextDate, endDate) !== 0) {
    throw new Error('Date range iteration did not reach the end of the requested range');
  }

  return datesArray;
}

/**
 * Checks whether the specified date is in the given date range.
 * @param date - The origin date
 * @param dateRange - An array of dates to do the lookup on
 * @returns True if the date matches one of the dates in the specified array, false otherwise.
 */
export function isDateInRange(date: Date, dateRange: Date[]): boolean {
  for (const dateInRange of dateRange) {
    if (compareDatePart(date, dateInRange) === 0) {
      return true;
    }
  }
  return false;
}

/**
 * Returns the week number in a year for a date.
 *
 * @param weeksInMonth - The number of weeks to include; must be a non-negative finite integer.
 * @param navigatedDate - A date to find the week number for.
 * @param firstDayOfWeek - The named day that starts each week.
 * @param firstWeekOfYear - The convention that determines which week is the first week of the year.
 * @returns The week number array for the current month.
 */
export function getWeekNumbersInMonth(
  weeksInMonth: number,
  firstDayOfWeek: DayOfWeek,
  firstWeekOfYear: FirstWeekOfYear,
  navigatedDate: Date,
): number[] {
  if (!Number.isFinite(weeksInMonth) || !Number.isInteger(weeksInMonth) || weeksInMonth < 0) {
    throw new RangeError('weeksInMonth must be a non-negative finite integer.');
  }
  if (!Number.isFinite(navigatedDate.getTime())) {
    throw new RangeError('navigatedDate must be valid.');
  }

  const selectedYear = navigatedDate.getFullYear();
  const selectedMonth = navigatedDate.getMonth();
  const firstDayOfWeekIndex = getDayIndex(firstDayOfWeek);
  const dayOfMonth = 1;
  const firstDayOfMonth = createDate(selectedYear, selectedMonth, dayOfMonth);
  const endOfFirstWeek =
    dayOfMonth +
    (firstDayOfWeekIndex + DAYS_IN_WEEK - 1) -
    adjustWeekDay(firstDayOfWeekIndex, firstDayOfMonth.getDay());
  let endOfWeekRange = createDate(selectedYear, selectedMonth, endOfFirstWeek);

  const weeksArray = [];
  for (let i = 0; i < weeksInMonth; i++) {
    // Get week number for end of week
    weeksArray.push(getWeekNumber(endOfWeekRange, firstDayOfWeek, firstWeekOfYear));
    endOfWeekRange = addDays(endOfWeekRange, DAYS_IN_WEEK);
  }
  return weeksArray;
}

/**
 * Returns the week number for a date.
 *
 * @param date - A date to find the week number for.
 * @param firstDayOfWeek - The named day that starts each week.
 * @param firstWeekOfYear - The convention that determines which week is the first week of the year.
 * @returns The week's number in the year.
 */
export function getWeekNumber(date: Date, firstDayOfWeek: DayOfWeek, firstWeekOfYear: FirstWeekOfYear): number {
  // First four-day week of the year - minimum days count
  const fourDayWeek = 4;

  switch (firstWeekOfYear) {
    case 'firstFullWeek':
      return getWeekOfYearFullDays(date, firstDayOfWeek, DAYS_IN_WEEK);

    case 'firstFourDayWeek':
      return getWeekOfYearFullDays(date, firstDayOfWeek, fourDayWeek);

    default:
      return getFirstDayWeekOfYear(date, firstDayOfWeek);
  }
}

/**
 * Gets the date for the first day of the week based on the given date assuming
 * the specified first day of the week.
 * @param date - The date to find the beginning of the week date for.
 * @returns A new date object representing the first day of the week containing the input date.
 */
export function getStartDateOfWeek(date: Date, firstDayOfWeek: DayOfWeek): Date {
  const year = date.getFullYear();
  const month = date.getMonth();
  const day = date.getDate();
  const firstDayOfWeekIndex = getDayIndex(firstDayOfWeek);

  for (let daysBack = 0; daysBack < 2 * DAYS_IN_WEEK; daysBack++) {
    const candidate = createDate(year, month, day - daysBack);
    if (!Number.isFinite(candidate.getTime())) {
      throw new RangeError('Cannot align an invalid or out-of-range date.');
    }
    if (candidate.getDay() === firstDayOfWeekIndex) {
      return candidate;
    }
  }

  throw new RangeError('Could not find a representable week start within two weeks.');
}

/**
 * Helper function for `getWeekNumber`.
 * Returns week number for a date.
 * @param date - current selected date.
 * @param firstDayOfWeek - The first day of week (0-6, Sunday = 0)
 * @param numberOfFullDays - week settings.
 * @returns The week's number in the year.
 */
function getWeekOfYearFullDays(date: Date, firstDayOfWeek: DayOfWeek, numberOfFullDays: number): number {
  const firstDayOfWeekIndex = getDayIndex(firstDayOfWeek);
  const dayOfYear = getDayOfYear(date) - 1;
  let num = date.getDay() - (dayOfYear % DAYS_IN_WEEK);

  const lastDayOfPrevYear = createDate(date.getFullYear() - 1, getMonthIndex('december'), 31);
  const daysInYear = getDayOfYear(lastDayOfPrevYear) - 1;

  let num2 = (firstDayOfWeekIndex - num + 2 * DAYS_IN_WEEK) % DAYS_IN_WEEK;
  if (num2 !== 0 && num2 >= numberOfFullDays) {
    num2 -= DAYS_IN_WEEK;
  }

  let num3 = dayOfYear - num2;
  if (num3 < 0) {
    num -= daysInYear % DAYS_IN_WEEK;
    num2 = (firstDayOfWeekIndex - num + 2 * DAYS_IN_WEEK) % DAYS_IN_WEEK;
    if (num2 !== 0 && num2 + 1 >= numberOfFullDays) {
      num2 -= DAYS_IN_WEEK;
    }

    num3 = daysInYear - num2;
  }

  const nextYearFirstWeekStart = getStartDateOfWeek(createDate(date.getFullYear() + 1, 0, 1), firstDayOfWeek);
  const nextYearFirstWeekDays = Array.from({ length: DAYS_IN_WEEK }, (_, index) =>
    addDays(nextYearFirstWeekStart, index),
  ).filter(nextYearDate => nextYearDate.getFullYear() === date.getFullYear() + 1).length;
  if (nextYearFirstWeekDays >= numberOfFullDays && compareDatePart(date, nextYearFirstWeekStart) >= 0) {
    return 1;
  }

  return Math.floor(num3 / DAYS_IN_WEEK + 1);
}

/**
 * Helper function for `getWeekNumber`.
 * Returns week number for a date.
 * @param date - current selected date.
 * @param firstDayOfWeek - The first day of week (0-6, Sunday = 0)
 * @returns The week's number in the year.
 */
function getFirstDayWeekOfYear(date: Date, firstDayOfWeek: DayOfWeek): number {
  const num = getDayOfYear(date) - 1;
  const num2 = date.getDay() - (num % DAYS_IN_WEEK);
  const num3 = (num2 - getDayIndex(firstDayOfWeek) + 2 * DAYS_IN_WEEK) % DAYS_IN_WEEK;

  return Math.floor((num + num3) / DAYS_IN_WEEK + 1);
}

/**
 * Helper function for `getWeekNumber`.
 * Returns adjusted week day number when `firstDayOfWeek` is other than Sunday.
 * For Week Day Number comparison checks
 * @param firstDayOfWeekIndex - The first day of week (0-6, Sunday = 0)
 * @param dateWeekDay - shifts number forward to 1 week in case passed as true
 * @returns The day of week adjusted to `firstDayOfWeek`; e.g. when `firstDayOfWeek` is Monday (1),
 * Sunday becomes 7.
 */
function adjustWeekDay(firstDayOfWeekIndex: number, dateWeekDay: number): number {
  return firstDayOfWeekIndex !== 0 && dateWeekDay < firstDayOfWeekIndex ? dateWeekDay + DAYS_IN_WEEK : dateWeekDay;
}

/**
 * Returns the day number for a date in a year:
 * the number of days since January 1st in the particular year.
 * @param date - A date to find the day number for.
 * @returns The day's number in the year.
 */
function getDayOfYear(date: Date): number {
  const month = date.getMonth();
  const year = date.getFullYear();
  let daysUntilDate = 0;

  for (let i = 0; i < month; i++) {
    daysUntilDate += daysInMonth(i + 1, year);
  }

  daysUntilDate += date.getDate();

  return daysUntilDate;
}

/**
 * Returns the number of days in the month
 * @param month - The month number to target (months 1-12).
 * @param year - The year to target.
 * @returns The number of days in the month.
 */
function daysInMonth(month: number, year: number): number {
  return createDate(year, month, 0).getDate();
}

import { DAYS_IN_WEEK, daysOfWeek, monthsOfYear } from './constants';
import type { DayOfWeek, MonthOfYear } from './constants';

/**
 * Converts a day of the week to the index used by `Date.prototype.getDay()`.
 */
export function getDayIndex(day: DayOfWeek): number {
  return daysOfWeek.indexOf(day);
}

/**
 * Converts an index used by `Date.prototype.getDay()` to a day of the week, wrapping out-of-range values.
 */
export function getDayFromIndex(index: number): DayOfWeek {
  if (!Number.isFinite(index) || !Number.isInteger(index)) {
    throw new RangeError('index must be a finite integer.');
  }

  return daysOfWeek[((index % DAYS_IN_WEEK) + DAYS_IN_WEEK) % DAYS_IN_WEEK];
}

/**
 * Converts a month to the index used by `Date.prototype.getMonth()`.
 */
export function getMonthIndex(month: MonthOfYear): number {
  return monthsOfYear.indexOf(month);
}

type FocusTarget = HTMLElement | { focus: () => void };
type FocusWindow = Pick<Window, 'requestAnimationFrame'>;

const targetsToFocusOnNextRepaint = new WeakMap<FocusWindow, FocusTarget>();

/**
 * Sets focus to an element asynchronously. The focus will be set at the next browser repaint,
 * meaning it won't cause any extra recalculations. If more than one focusAsync is called during one frame,
 * only the latest called focusAsync element will actually be focused
 * @param element - The element to focus
 */
export function focusAsync(element: FocusTarget | undefined | null, win: FocusWindow | undefined | null): void {
  if (element && win) {
    // An element was already queued to be focused, so replace that one with the new element
    if (targetsToFocusOnNextRepaint.has(win)) {
      targetsToFocusOnNextRepaint.set(win, element);
      return;
    }

    targetsToFocusOnNextRepaint.set(win, element);

    // element.focus() is a no-op if the element is no longer in the DOM, meaning this is always safe
    win.requestAnimationFrame(() => {
      const target = targetsToFocusOnNextRepaint.get(win);
      targetsToFocusOnNextRepaint.delete(win);
      target?.focus();
    });
  }
}

