/**
 * Render the final JSX of Card.
 */
export const renderCard_unstable = (state: CardBaseState, cardContextValue: CardContextValue): JSXElement => {
  assertSlots<CardSlots>(state);

  return (
    <state.root>
      <CardProvider value={cardContextValue}>
        {state.checkbox ? <state.checkbox /> : null}
        {state.floatingAction ? <state.floatingAction /> : null}
        {state.root.children}
      </CardProvider>
    </state.root>
