    color,
    requestChange,
  };
};

export const useColorPicker_unstable = (props: ColorPickerProps, ref: React.Ref<HTMLDivElement>): ColorPickerState => {
  const { shape, ...baseProps } = props;

  return {
    ...useColorPickerBase_unstable(baseProps, ref),
    shape,
  };
};

