export type UseListboxSlotState = Pick<ComboboxBaseState, 'multiselect'>;

type UseListboxSlotOptions = {
  state: UseListboxSlotState;
  triggerRef:
    | React.RefObject<HTMLInputElement | null>
    | React.RefObject<HTMLButtonElement | null>
    | React.RefObject<HTMLButtonElement | HTMLInputElement | null>;
  defaultProps?: Partial<ListboxProps>;
};

/**
 * @internal
 * @returns  listbox slot with desired behaviour and props
 */
export function useListboxSlot(
  listboxSlotFromProp: Slot<typeof Listbox> | undefined,
  ref: React.Ref<HTMLDivElement>,
  options: UseListboxSlotOptions,
): SlotComponentType<ExtractSlotProps<Slot<typeof Listbox>>> | undefined {
  const {
    state: { multiselect },
    triggerRef,
    defaultProps,
  } = options;

  const listboxId = useId(
    'fluent-listbox',
    isResolvedShorthand(listboxSlotFromProp) ? listboxSlotFromProp.id : undefined,
  );

  const listboxSlot = slot.optional(listboxSlotFromProp, {
    renderByDefault: true,
    elementType: Listbox,
    defaultProps: {
      id: listboxId,
      multiselect,
      tabIndex: undefined,
      ...defaultProps,
    },
  });

  const fieldControlProps = useFieldControlProps_unstable({ id: listboxId } as FieldControlProps, {
    supportsLabelFor: true,
  });

  // Use the field's label to provide an accessible name for the listbox if it doesn't already have one
  if (
    listboxSlot &&
    !listboxSlot['aria-label'] &&
    !listboxSlot['aria-labelledby'] &&
    fieldControlProps['aria-labelledby']
  ) {
    listboxSlot['aria-labelledby'] = fieldControlProps['aria-labelledby'];
  }

  /**
   * Clicking on the listbox should never blur the trigger
   * in a combobox
   */
  const onMouseDown = useEventCallback(
    mergeCallbacks((event: React.MouseEvent<HTMLDivElement>) => {
      event.preventDefault();
    }, listboxSlot?.onMouseDown),
  );

  const onClick = useEventCallback(
    // eslint-disable-next-line react-hooks/refs
    mergeCallbacks((event: React.MouseEvent<HTMLDivElement>) => {
      event.preventDefault();
      triggerRef.current?.focus();
    }, listboxSlot?.onClick),
  );

  const listboxRef = useMergedRefs(listboxSlot?.ref, ref);
  if (listboxSlot) {
    listboxSlot.ref = listboxRef;
    listboxSlot.onMouseDown = onMouseDown;
    listboxSlot.onClick = onClick;
  }

  return listboxSlot;
}

'use client';

import * as React from 'react';
import type { OptionCollectionState, OptionValue } from './OptionCollection.types';

/**
 * A hook for managing a collection of child Options
 */
export const useOptionCollection = (): OptionCollectionState => {
  const optionsById = React.useRef(new Map<string, OptionValue>());

  const collectionAPI = React.useMemo(() => {
    const getCount = () => optionsById.current.size;

    // index searches are no longer used
    const getOptionAtIndex = () => undefined;
    const getIndexOfId = () => -1;

    const getOptionById = (id: string) => {
      return optionsById.current.get(id);
    };
    const getOptionsMatchingText = (matcher: (text: string) => boolean) => {
      return Array.from(optionsById.current.values()).filter(({ text }) => matcher(text));
    };

    const getOptionsMatchingValue = (matcher: (value: string) => boolean) => {
      const matches: OptionValue[] = [];
      for (const option of optionsById.current.values()) {
        if (matcher(option.value)) {
          matches.push(option);
        }
      }

      return matches;
    };

    return {
      getCount,
      getOptionAtIndex,
      getIndexOfId,
      getOptionById,
      getOptionsMatchingText,
      getOptionsMatchingValue,
    };
  }, []);

  const registerOption = React.useCallback((option: OptionValue) => {
    optionsById.current.set(option.id, option);

    return () => optionsById.current.delete(option.id);
  }, []);

  return {
    ...collectionAPI,
    // eslint-disable-next-line react-hooks/refs
    options: Array.from(optionsById.current.values()),
    registerOption,
  };
};

'use client';

import * as React from 'react';
import { useControllableState } from '@fluentui/react-utilities';
import type { OptionValue } from './OptionCollection.types';
import type { SelectionEvents, SelectionProps, SelectionState } from './Selection.types';

export const useSelection = (props: SelectionProps): SelectionState => {
  const { defaultSelectedOptions, multiselect, onOptionSelect } = props;

  const [selectedOptions, setSelectedOptions] = useControllableState({
    state: props.selectedOptions,
    defaultState: defaultSelectedOptions,
    initialState: [],
  });

  const selectOption = React.useCallback(
    (event: SelectionEvents, option: OptionValue) => {
      // if the option is disabled, do nothing
      if (option.disabled) {
        return;
      }

      // for single-select, always return the selected option
      let newSelection = [option.value];

      // toggle selected state of the option for multiselect
      if (multiselect) {
        const selectedIndex = selectedOptions.findIndex(o => o === option.value);
        if (selectedIndex > -1) {
          // deselect option
          newSelection = [...selectedOptions.slice(0, selectedIndex), ...selectedOptions.slice(selectedIndex + 1)];
        } else {
          // select option
          newSelection = [...selectedOptions, option.value];
        }
      }

      setSelectedOptions(newSelection);
      onOptionSelect?.(event, { optionValue: option.value, optionText: option.text, selectedOptions: newSelection });
    },
    [onOptionSelect, multiselect, selectedOptions, setSelectedOptions],
  );

  const clearSelection = (event: SelectionEvents) => {
    setSelectedOptions([]);
    onOptionSelect?.(event, { optionValue: undefined, optionText: undefined, selectedOptions: [] });
  };

  return { clearSelection, selectOption, selectedOptions };
};

'use client';

import * as React from 'react';
import { useSetKeyboardNavigation } from '@fluentui/react-tabster';
import type { ActiveDescendantImperativeRef } from '@fluentui/react-aria';
import { mergeCallbacks, slot, useEventCallback, useMergedRefs } from '@fluentui/react-utilities';
import type { ExtractSlotProps, Slot, SlotComponentType } from '@fluentui/react-utilities';
import { getDropdownActionFromKey } from '../utils/dropdownKeyActions';
import type { ComboboxBaseState } from './ComboboxBase.types';
import type { OptionValue } from './OptionCollection.types';

export type UseTriggerSlotState = Pick<
  ComboboxBaseState,
  'open' | 'getOptionById' | 'selectOption' | 'setOpen' | 'multiselect' | 'setHasFocus'
>;

export type UseTriggerSlotOptions = {
  state: UseTriggerSlotState;
  defaultProps: unknown;
  activeDescendantController: ActiveDescendantImperativeRef;
  shouldCloseOnBlur?: (event: React.FocusEvent<HTMLButtonElement> & React.FocusEvent<HTMLInputElement>) => boolean;
};

export function useTriggerSlot(
  triggerSlotFromProp: NonNullable<Slot<'button'>>,
  ref: React.Ref<HTMLButtonElement>,
  options: UseTriggerSlotOptions & { elementType: 'button' },
): SlotComponentType<ExtractSlotProps<Slot<'button'>>>;

export function useTriggerSlot(
  triggerSlotFromProp: NonNullable<Slot<'input'>>,
  ref: React.Ref<HTMLInputElement>,
  options: UseTriggerSlotOptions & { elementType: 'input' },
): SlotComponentType<ExtractSlotProps<Slot<'input'>>>;

/**
 * Shared trigger behaviour for combobox and dropdown
 * @returns trigger slot with desired behaviour and props
 */
export function useTriggerSlot(
  triggerSlotFromProp: NonNullable<Slot<'input'>> | NonNullable<Slot<'button'>>,
  ref: React.Ref<HTMLButtonElement> | React.Ref<HTMLInputElement>,
  options: UseTriggerSlotOptions & { elementType: 'input' | 'button' },
): SlotComponentType<ExtractSlotProps<Slot<'button'>>> | SlotComponentType<ExtractSlotProps<Slot<'input'>>> {
  const {
    state: { open, setOpen, setHasFocus },
    defaultProps,
    elementType,
    activeDescendantController,
    shouldCloseOnBlur,
  } = options;

  const trigger = slot.always(triggerSlotFromProp, {
    defaultProps: {
      type: 'text',
      'aria-expanded': open,
      role: 'combobox',
      ...(typeof defaultProps === 'object' && defaultProps),
    },
    elementType,
  });

  // handle trigger focus/blur
  const triggerRef = React.useRef<HTMLButtonElement | HTMLInputElement>(null);
  trigger.ref = useMergedRefs(triggerRef, trigger.ref, ref) as React.Ref<HTMLButtonElement & HTMLInputElement>;

  // the trigger should open/close the popup on click or blur
  trigger.onBlur = mergeCallbacks((event: React.FocusEvent<HTMLButtonElement> & React.FocusEvent<HTMLInputElement>) => {
    if (shouldCloseOnBlur?.(event) ?? true) {
      setOpen(event, false);
      setHasFocus(false);
    }
  }, trigger.onBlur);

  trigger.onFocus = mergeCallbacks(
    (event: React.FocusEvent<HTMLButtonElement> & React.FocusEvent<HTMLInputElement>) => {
      if (event.target === event.currentTarget) {
        setHasFocus(true);
      }
    },
    trigger.onFocus,
  );
  trigger.onClick = mergeCallbacks(
    (event: React.MouseEvent<HTMLButtonElement> & React.MouseEvent<HTMLInputElement>) => {
      setOpen(event, !open);
    },
    trigger.onClick,
  );

  // handle combobox keyboard interaction
  trigger.onKeyDown = mergeCallbacks(
    useTriggerKeydown({ activeDescendantController, ...options.state }),
    trigger.onKeyDown,
  );

  return trigger as SlotComponentType<ExtractSlotProps<Slot<'input'>>>;
}

function useTriggerKeydown(
  options: {
    activeDescendantController: ActiveDescendantImperativeRef;
  } & Pick<UseTriggerSlotState, 'setOpen' | 'selectOption' | 'getOptionById' | 'multiselect' | 'open'>,
) {
  const { activeDescendantController, getOptionById, setOpen, selectOption, multiselect, open } = options;

  const getActiveOption = React.useCallback(() => {
    const activeOptionId = activeDescendantController.active();
    return activeOptionId ? getOptionById(activeOptionId) : undefined;
  }, [activeDescendantController, getOptionById]);

  const first = () => {
    activeDescendantController.first();
  };

  const last = () => {
    activeDescendantController.last();
  };

  const next = (activeOption: OptionValue | undefined) => {
    if (activeOption) {
      activeDescendantController.next();
    } else {
      activeDescendantController.first();
    }
  };

  const previous = (activeOption: OptionValue | undefined) => {
    if (activeOption) {
      activeDescendantController.prev();
    } else {
      activeDescendantController.first();
    }
  };

  const pageUp = () => {
    for (let i = 0; i < 10; i++) {
      activeDescendantController.prev();
    }
  };

  const pageDown = () => {
    for (let i = 0; i < 10; i++) {
      activeDescendantController.next();
    }
  };

  const setKeyboardNavigation = useSetKeyboardNavigation();
  return useEventCallback((e: React.KeyboardEvent<HTMLInputElement> & React.KeyboardEvent<HTMLButtonElement>) => {
    const action = getDropdownActionFromKey(e, { open, multiselect });
    const activeOption = getActiveOption();

    switch (action) {
      case 'First':
      case 'Last':
      case 'Next':
      case 'Previous':
      case 'PageDown':
      case 'PageUp':
      case 'Open':
      case 'Close':
      case 'CloseSelect':
      case 'Select':
        e.preventDefault();
        break;
    }

    setKeyboardNavigation(true);

    switch (action) {
      case 'First':
        first();
        break;
      case 'Last':
        last();
        break;
      case 'Next':
        next(activeOption);
        break;
      case 'Previous':
        previous(activeOption);
        break;
      case 'PageDown':
        pageDown();
        break;
      case 'PageUp':
        pageUp();
        break;
      case 'Open':
        setOpen(e, true);
        break;
      case 'Close':
        // stop propagation for escape key to avoid dismissing any parent popups
        e.stopPropagation();
        setOpen(e, false);
        break;
      case 'CloseSelect':
        !multiselect && !activeOption?.disabled && setOpen(e, false);
      // fallthrough
      case 'Select':
        activeOption && selectOption(e, activeOption);
        break;
      case 'Tab':
        !multiselect && activeOption && selectOption(e, activeOption);
        break;
    }
  });
}

