import * as React from 'react';
import { useDialog_unstable } from './useDialog';
import { renderDialog_unstable } from './renderDialog';
import type { DialogProps } from './Dialog.types';
import { useDialogContextValues_unstable } from './useDialogContextValues';

/**
 * The `Dialog` root level component serves as an interface for interaction with all possible behaviors exposed.
 * It provides context down the hierarchy to `children` compound components to allow functionality.
 * This component expects to receive as children either a `DialogSurface` or a `DialogTrigger`
 * and a `DialogSurface` (or some component that will eventually render one of those compound components)
 * in this specific order
 */
export const Dialog: React.FC<DialogProps> = React.memo(props => {
  const state = useDialog_unstable(props);
  const contextValues = useDialogContextValues_unstable(state);

  return renderDialog_unstable(state, contextValues);
});

Dialog.displayName = 'Dialog';

import type * as React from 'react';
import type { PresenceMotionSlotProps } from '@fluentui/react-motion';
import type { ScaleParams } from '@fluentui/react-motion-components-preview';
import type { ComponentProps, ComponentState, JSXElement, Slot } from '@fluentui/react-utilities';

import type { DialogContextValue, DialogSurfaceContextValue } from '../../contexts';
import type { DialogSurfaceElement } from '../DialogSurface/DialogSurface.types';

export type DialogSlots = {
  /**
   * For more information refer to the [Motion docs page](https://react.fluentui.dev/?path=/docs/motion-motion-slot--docs).
   *
   */
  surfaceMotion: Slot<PresenceMotionSlotProps<ScaleParams>>;
};

export type InternalDialogSlots = {
  surfaceMotion: NonNullable<Slot<PresenceMotionSlotProps<ScaleParams>>>;
};

export type DialogOpenChangeEvent = DialogOpenChangeData['event'];

export type DialogOpenChangeData =
  | {
      type: 'escapeKeyDown';
      open: boolean;
      event: React.KeyboardEvent<DialogSurfaceElement>;
    }
  | {
      type: 'backdropClick';
      open: boolean;
      event: React.MouseEvent<DialogSurfaceElement>;
    }
  | {
      type: 'triggerClick';
      open: boolean;
      event: React.MouseEvent<DialogSurfaceElement>;
    };

export type DialogModalType = 'modal' | 'non-modal' | 'alert';

/**
 * Callback fired when the component changes value from open state.
 *
 * @param event - a React's Synthetic event or a KeyboardEvent in case of `documentEscapeKeyDown`
 * @param data - A data object with relevant information,
 * such as open value and type of interaction that created the event
 */
export type DialogOpenChangeEventHandler = (event: DialogOpenChangeEvent, data: DialogOpenChangeData) => void;

export type DialogContextValues = {
  dialog: DialogContextValue;
  /**
   * dialogSurface context is provided by Dialog as false
   * to ensure components inside Dialog but outside DialogSurface will consume this as false
   */
  dialogSurface: DialogSurfaceContextValue;
};

export type DialogProps = ComponentProps<Partial<DialogSlots>> & {
  /**
   * Dialog variations.
   *
   * `modal`: When this type of dialog is open, the rest of the page is dimmed out and cannot be interacted with.
   * The tab sequence is kept within the dialog and moving the focus outside
   * the dialog will imply closing it. This is the default type of the component.
   *
   * `non-modal`: When a non-modal dialog is open, the rest of the page is not dimmed out
   * and users can interact with the rest of the page.
   * This also implies that the tab focus can move outside the dialog when it reaches the last focusable element.
   *
   * `alert`: is a special type of modal dialogs that interrupts the user's workflow
   * to communicate an important message or ask for a decision.
   * Unlike a typical modal dialog, the user must take an action through the options given to dismiss the dialog,
   * and it cannot be dismissed through the dimmed background.
   *
   * @default modal
   */
  modalType?: DialogModalType;
  /**
   * Controls the open state of the dialog
   * @default false
   */
  open?: boolean;
  /**
   * Default value for the uncontrolled open state of the dialog.
   * @default false
   */
  defaultOpen?: boolean;
  /**
   * Callback fired when the component changes value from open state.
   *
   * @param event - a React's Synthetic event or a KeyboardEvent in case of `documentEscapeKeyDown`
   * @param data - A data object with relevant information,
   * such as open value and type of interaction that created the event
   */
  // eslint-disable-next-line @nx/workspace-consistent-callback-type -- can't change type of existing callback
  onOpenChange?: DialogOpenChangeEventHandler;
  /**
   * Can contain two children including `DialogTrigger` and `DialogSurface`.
   * Alternatively can only contain `DialogSurface` if using trigger outside dialog, or controlling state.
   */
  children: [JSXElement, JSXElement] | JSXElement;
  /**
   * Enables standard behavior according to the [HTML dialog spec](https://developer.mozilla.org/en-US/docs/Web/API/HTMLDialogElement/showModal)
   * where the focus trap involves setting outside elements inert.
   *
   * @default false
   */
  inertTrapFocus?: boolean;
  /**
   * Decides whether the dialog should be removed from the DOM tree when it is closed.
   * This can be useful when dealing with components that may contain state that should not
   * be reset when the dialog is closed.
   *
   * @default true
   */
  unmountOnClose?: boolean;
};

export type DialogState = ComponentState<InternalDialogSlots> &
  DialogContextValue & {
    content: React.ReactNode;
    trigger: React.ReactNode;
  };

export { Dialog } from './Dialog';
export type {
  DialogContextValues,
  DialogModalType,
  DialogOpenChangeData,
  DialogOpenChangeEvent,
  DialogOpenChangeEventHandler,
  DialogProps,
  DialogSlots,
  DialogState,
  InternalDialogSlots,
} from './Dialog.types';
export { renderDialog_unstable } from './renderDialog';
export { useDialog_unstable } from './useDialog';
export { useDialogContextValues_unstable } from './useDialogContextValues';

/** @jsxRuntime automatic */
/** @jsxImportSource @fluentui/react-jsx-runtime */

import { assertSlots } from '@fluentui/react-utilities';
import type { JSXElement } from '@fluentui/react-utilities';
import * as React from 'react';

import { MotionRefForwarder } from '@fluentui/react-motion';
import { DialogProvider, DialogSurfaceProvider } from '../../contexts';
import type { DialogState, DialogContextValues, InternalDialogSlots } from './Dialog.types';

/**
 * Render the final JSX of Dialog
 */
export const renderDialog_unstable = (state: DialogState, contextValues: DialogContextValues): JSXElement => {
  assertSlots<InternalDialogSlots>(state);

  return (
    <DialogProvider value={contextValues.dialog}>
      <DialogSurfaceProvider value={contextValues.dialogSurface}>
        {state.trigger}
        {state.content && (
          <state.surfaceMotion>
            <MotionRefForwarder>
              {/* Casting here as content should be equivalent to <DialogSurface/> */}
              {/* FIXME: content should not be ReactNode it should be ReactElement instead. */}
              {state.content as React.ReactElement}
            </MotionRefForwarder>
          </state.surfaceMotion>
        )}
      </DialogSurfaceProvider>
    </DialogProvider>
  );
};

'use client';

import * as React from 'react';

import { useHasParentContext } from '@fluentui/react-context-selector';
import { useModalAttributes } from '@fluentui/react-tabster';
import { presenceMotionSlot } from '@fluentui/react-motion';
import { useControllableState, useEventCallback, useId } from '@fluentui/react-utilities';

import { useFocusFirstElement } from '../../utils';
import { DialogContext } from '../../contexts';
import { DialogSurfaceMotion } from '../DialogSurfaceMotion';
import type { DialogOpenChangeData, DialogProps, DialogState } from './Dialog.types';

/**
 * Create the state required to render Dialog.
 *
 * The returned state can be modified with hooks such as useDialogStyles_unstable,
 * before being passed to renderDialog_unstable.
 *
 * @param props - props from this instance of Dialog
 */
export const useDialog_unstable = (props: DialogProps): DialogState => {
  const { children, modalType = 'modal', onOpenChange, inertTrapFocus = false, unmountOnClose = true } = props;

  const dialogTitleId = useId('dialog-title-');

  const [trigger, content] = childrenToTriggerAndContent(children);

  const [open, setOpen] = useControllableState({
    state: props.open,
    defaultState: props.defaultOpen,
    initialState: false,
  });

  const requestOpenChange = useEventCallback((data: DialogOpenChangeData) => {
    onOpenChange?.(data.event, data);

    // if user prevents default then do not change state value
    // otherwise updates state value and trigger reference to the element that caused the opening
    if (!data.event.isDefaultPrevented()) {
      setOpen(data.open);
    }
  });

  const dialogRef = useFocusFirstElement(open, modalType);

  const { modalAttributes, triggerAttributes } = useModalAttributes({
    trapFocus: modalType !== 'non-modal',
    legacyTrapFocus: !inertTrapFocus,
  });

  const isNestedDialog = useHasParentContext(DialogContext);

  return {
    components: {
      surfaceMotion: DialogSurfaceMotion,
    },
    inertTrapFocus,
    open,
    modalType,
    content,
    trigger,
    requestOpenChange,
    dialogTitleId,
    isNestedDialog,
    unmountOnClose,
    dialogRef,
    modalAttributes,
    triggerAttributes,
    surfaceMotion: presenceMotionSlot(props.surfaceMotion, {
      elementType: DialogSurfaceMotion,
