      return;
    }

    if (isNestedDialog || modalType === 'non-modal') {
      return;
    }

    disableBodyScroll();

    return () => enableBodyScroll();
  }, [open, modalType, isNestedDialog, disableBodyScroll, enableBodyScroll]);

  return {
    components: {
      backdrop: 'div',
      root: 'div',
      backdropMotion: DialogBackdropMotion,
    },
    open,
    backdrop,
    isNestedDialog,
    treatBackdropAsNested,
    backdropAppearance,
    unmountOnClose,
