const group = '[role="group"]';
const groupLabel = '[role="presentation"]';

// ---- Fixtures ----

const BasicCombobox = (props: Partial<ComboboxProps>) => (
  <Combobox
    id="combobox"
    placeholder="Select an animal"
    expandIcon={{ id: 'expand-icon', children: 'Open' }}
    {...props}
  >
    <Option>Cat</Option>
    <Option>Dog</Option>
    <Option disabled>Ferret</Option>
    <Option>Fish</Option>
    <Option>Hamster</Option>
  </Combobox>
);

// ---- Tests ----

describe('Combobox', () => {
  describe('listbox visibility', () => {
    it('is closed by default', () => {
      mount(<BasicCombobox />);
      cy.get(listbox).should('not.exist');
    });

    it('opens on trigger click', () => {
      mount(<BasicCombobox />);
      cy.get(trigger).realClick();
      cy.get(listbox).should('exist');
    });

    it('toggles on click-only expand icon activation', () => {
      mount(<BasicCombobox />);

      cy.get(expandIcon).trigger('click');
      cy.get('[data-open]').should('exist');
      cy.get(expandIcon).trigger('click');
      cy.get('[data-open]').should('not.exist');
    });

    it('toggles on expand icon keyboard activation', () => {
      mount(<BasicCombobox />);

      cy.get(expandIcon).focus().realPress('Enter');
      cy.get('[data-open]').should('exist');
      cy.get(expandIcon).focus().realPress('Space');
      cy.get('[data-open]').should('not.exist');
      cy.get(trigger).should('be.focused');
    });

    it('closes on Escape from the expand icon without bubbling to a parent dialog', () => {
      const onDialogKeyDown = cy.stub().as('onDialogKeyDown');
      mount(
        <div role="dialog" onKeyDown={onDialogKeyDown}>
          <BasicCombobox defaultOpen />
        </div>,
      );

      cy.get(expandIcon).focus().realPress('Escape');
      cy.get(listbox).should('not.exist');
      cy.get(trigger).should('be.focused');
      cy.get('@onDialogKeyDown').should('not.have.been.called');
    });

    it('clears focus state when focus leaves from the expand icon', () => {
      mount(<BasicCombobox />);

      cy.get(trigger).realClick();
      cy.get(listbox).should('exist');
      cy.get(expandIcon).focus();
      cy.get(listbox).should('exist');
      cy.realPress('Tab');
      cy.get(listbox).should('not.exist');
    });

    (['auto', 'manual'] as const).forEach(popover => {
      it(`does not suppress click-only activation after a canceled pointer gesture for ${popover} popovers`, () => {
        const onOpenChange = cy.stub().as('onOpenChange');
        mount(<BasicCombobox listbox={{ popover }} onOpenChange={onOpenChange} />);

        cy.get(expandIcon).realMouseDown();
        cy.get('body').realMouseMove(0, 0, { position: 'bottomRight' }).realMouseUp({ position: 'bottomRight' });
        cy.get('@onOpenChange').should('not.have.been.called');

        cy.get(trigger).realClick();
        cy.get(listbox).should('be.visible');
        cy.get(trigger).should('have.attr', 'aria-expanded', 'true');
        cy.get('@onOpenChange').should('have.been.calledOnce');

        cy.get(expandIcon).then($icon => $icon[0].click());
        cy.get(listbox).should('not.exist');
        cy.get(trigger).should('have.attr', 'aria-expanded', 'false').and('be.focused');
        cy.get('@onOpenChange').should('have.been.calledTwice');

        cy.get(expandIcon).realClick();
        cy.get(listbox).should('be.visible');
        cy.get('@onOpenChange').should('have.been.calledThrice');
        cy.get(expandIcon).realClick();
        cy.get(listbox).should('not.exist');
        cy.get('@onOpenChange').should('have.callCount', 4);
      });

      it(`toggles the ${popover} popover on pointer activation with one notification per change`, () => {
        const onOpenChange = cy.stub().as('onOpenChange');
        mount(<BasicCombobox listbox={{ popover }} onOpenChange={onOpenChange} />);

        cy.get(expandIcon).realClick();
        cy.get(listbox).should('be.visible');
        cy.get(trigger).should('have.attr', 'aria-expanded', 'true').and('be.focused');
        cy.get('@onOpenChange').should('have.been.calledOnce');
        cy.get(expandIcon).realClick();
        cy.get(listbox).should('not.exist');
        cy.get(trigger).should('have.attr', 'aria-expanded', 'false').and('be.focused');
        cy.get('[data-open]').should('not.exist');
        cy.get('@onOpenChange').should('have.been.calledTwice');
        cy.get(expandIcon).realClick();
        cy.get(listbox).should('be.visible');
        cy.get(trigger).should('have.attr', 'aria-expanded', 'true');
        cy.get('@onOpenChange').should('have.been.calledThrice');
      });
    });

    it('closes on input blur with a null relatedTarget when the expand icon is absent', () => {
      const onOpenChange = cy.stub().as('onOpenChange');
      mount(<BasicCombobox defaultOpen expandIcon={null} onOpenChange={onOpenChange} />);

      cy.get(expandIcon).should('not.exist');
      cy.get(listbox).should('be.visible');
      cy.get(trigger).focus().should('be.focused').blur();
      cy.get(listbox).should('not.exist');
      cy.get(trigger).should('have.attr', 'aria-expanded', 'false');
      cy.get('[data-open]').should('not.exist');
      cy.get('@onOpenChange').should('have.been.calledOnce');
    });

    it('notifies of an input blur close only once', () => {
      const onOpenChange = cy.stub().as('onOpenChange');
      mount(<BasicCombobox defaultOpen onOpenChange={onOpenChange} />);

      cy.get(trigger).focus().blur();
      cy.get('[data-open]').should('not.exist');
      cy.get('@onOpenChange').should('have.been.calledOnce');
    });

    it('removes the visually hidden expand icon from the tab order', () => {
      mount(<BasicCombobox clearable defaultSelectedOptions={['Cat']} defaultValue="Cat" />);

      cy.get(expandIcon).should('have.attr', 'tabindex', '-1');
    });

    it('opens on ArrowDown key', () => {
      mount(<BasicCombobox />);
      cy.get(trigger).focus().realPress('ArrowDown');
      cy.get(listbox).should('exist');
    });

    it('closes on Escape key', () => {
      mount(<BasicCombobox />);
      cy.get(trigger).realClick();
      cy.get(listbox).should('exist');
      cy.realPress('Escape');
      cy.get(listbox).should('not.exist');
    });

    it('closes on click outside', () => {
      mount(<BasicCombobox />);
      cy.get(trigger).realClick();
      cy.get(listbox).should('exist');
      cy.get('body').realClick({ position: 'bottomRight' });
      cy.get(listbox).should('not.exist');
    });
  });

  describe('option selection', () => {
    it('closes listbox and shows selected value in trigger after option click', () => {
      mount(<BasicCombobox />);
      cy.get(trigger).realClick();
      cy.contains(option, 'Cat').realClick();
      cy.get(listbox).should('not.exist');
      cy.get(trigger).should('have.value', 'Cat');
    });

    it('cannot select a disabled option', () => {
      mount(<BasicCombobox />);
      cy.get(trigger).realClick();
      cy.contains(option, 'Ferret').realClick();
      cy.get(trigger).should('not.have.value', 'Ferret');
    });

    it('returns focus to trigger after selection', () => {
      mount(<BasicCombobox />);
      cy.get(trigger).realClick();
      cy.contains(option, 'Cat').realClick();
      cy.get(trigger).should('be.focused');
    });
  });

  describe('keyboard navigation', () => {
    it('selects first option with ArrowDown then Enter', () => {
      mount(<BasicCombobox />);
      cy.get(trigger).focus().realPress('ArrowDown');
      cy.realPress('Enter');
      cy.get(trigger).should('have.value', 'Cat');
    });

    it('navigates to subsequent options with repeated ArrowDown', () => {
      mount(<BasicCombobox />);
      cy.get(trigger).focus().realPress('ArrowDown'); // Cat
      cy.realPress('ArrowDown'); // Dog
      cy.realPress('Enter');
      cy.get(trigger).should('have.value', 'Dog');
    });

    it('navigates back with ArrowUp', () => {
      mount(<BasicCombobox />);
      cy.get(trigger).focus().realPress('ArrowDown'); // Cat
      cy.realPress('ArrowDown'); // Dog
      cy.realPress('ArrowUp'); // back to Cat
      cy.realPress('Enter');
      cy.get(trigger).should('have.value', 'Cat');
    });

    it('Home key jumps to first option', () => {
      mount(<BasicCombobox />);
      cy.get(trigger).focus().realPress('ArrowDown');
      cy.realPress('ArrowDown'); // Dog
      cy.realPress('Home');
      cy.realPress('Enter');
      cy.get(trigger).should('have.value', 'Cat');
    });

    it('End key jumps to last option', () => {
      mount(<BasicCombobox />);
      cy.get(trigger).focus().realPress('ArrowDown');
      cy.realPress('End');
      cy.realPress('Enter');
      cy.get(trigger).should('have.value', 'Hamster');
    });

    it('Escape closes without changing selection', () => {
      mount(<BasicCombobox />);
      cy.get(trigger).realClick();
      cy.contains(option, 'Cat').realClick();
      cy.get(trigger).realClick();
      cy.realPress('ArrowDown');
      cy.realPress('Escape');
      cy.get(trigger).should('have.value', 'Cat');
    });
  });

  describe('clearable', () => {
    const ClearableCombobox = () => (
      <Combobox id="combobox" placeholder="Select an animal" clearable clearIcon={{ id: 'clear-icon', children: 'X' }}>
        <Option>Cat</Option>
        <Option>Dog</Option>
      </Combobox>
    );

    it('clears selection when clear icon is clicked', () => {
      mount(<ClearableCombobox />);
      cy.get(trigger).realClick();
      cy.contains(option, 'Cat').realClick();
      cy.get(trigger).should('have.value', 'Cat');
      cy.get('#clear-icon').realClick();
      cy.get(trigger).should('have.value', '');
    });

    it('returns focus to trigger after clearing', () => {
      mount(<ClearableCombobox />);
      cy.get(trigger).realClick();
      cy.contains(option, 'Cat').realClick();
      cy.get('#clear-icon').realClick();
      cy.get(trigger).should('be.focused');
    });
  });

  describe('controlled open state', () => {
    const ControlledCombobox = () => {
      const [open, setOpen] = React.useState(false);
      return (
        <>
          <button id="toggle" onClick={() => setOpen(o => !o)}>
            Toggle
          </button>
          <Combobox id="combobox" placeholder="Select" open={open} onOpenChange={(_, data) => setOpen(data.open)}>
            <Option>Cat</Option>
            <Option>Dog</Option>
          </Combobox>
        </>
      );
    };

    it('opens via external state', () => {
      mount(<ControlledCombobox />);
      cy.get(listbox).should('not.exist');
      cy.get('#toggle').realClick();
      cy.get(listbox).should('exist');
    });

    it('closes via external state', () => {
      mount(<ControlledCombobox />);
      cy.get('#toggle').realClick();
      cy.get(listbox).should('exist');
      cy.get('#toggle').realClick();
      cy.get(listbox).should('not.exist');
    });

    it('syncs open state with onOpenChange when Escape is pressed', () => {
      mount(<ControlledCombobox />);
      cy.get('#toggle').realClick();
      cy.get(listbox).should('exist');
      cy.get(trigger).focus().realPress('Escape');
      cy.get(listbox).should('not.exist');
    });
  });

  describe('freeform', () => {
    it('preserves typed value that does not match any option', () => {
      mount(
        <Combobox id="combobox" placeholder="Type anything…" freeform>
          <Option>Cat</Option>
          <Option>Dog</Option>
        </Combobox>,
      );
      cy.get(trigger).realClick().realType('Unicorn');
      cy.realPress('Escape');
      cy.get(trigger).should('have.value', 'Unicorn');
    });

    it('selects a matching option from typed input', () => {
      mount(
        <Combobox id="combobox" placeholder="Type anything…" freeform>
          <Option>Cat</Option>
          <Option>Dog</Option>
        </Combobox>,
      );
      cy.get(trigger).realClick().realType('Cat');
      cy.contains(option, 'Cat').realClick();
      cy.get(trigger).should('have.value', 'Cat');
    });
  });

  describe('multiselect', () => {
    it('keeps listbox open after selecting an option', () => {
      mount(
        <Combobox id="combobox" multiselect placeholder="Select animals">
          <Option>Cat</Option>
          <Option>Dog</Option>
        </Combobox>,
      );
      cy.get(trigger).realClick();
      cy.contains(multiselectOption, 'Cat').realClick();
      cy.get(multiselectPopup).should('exist');
    });

    it('shows comma-separated values in trigger for multiple selections', () => {
      mount(
        <Combobox id="combobox" multiselect placeholder="Select animals">
          <Option>Cat</Option>
          <Option>Dog</Option>
          <Option>Fish</Option>
        </Combobox>,
      );
      cy.get(trigger).realClick();
      cy.contains(multiselectOption, 'Cat').realClick();
      cy.contains(multiselectOption, 'Dog').realClick();
      cy.get(trigger).invoke('val').should('include', 'Cat');
      cy.get(trigger).invoke('val').should('include', 'Dog');
    });

    it('deselects an already-selected option on second click', () => {
      mount(
        <Combobox id="combobox" multiselect placeholder="Select animals">
          <Option>Cat</Option>
          <Option>Dog</Option>
        </Combobox>,
      );
      cy.get(trigger).realClick();
      cy.contains(multiselectOption, 'Cat').realClick();
      cy.contains(multiselectOption, 'Cat').realClick(); // deselect
      cy.get(trigger).should('have.value', '');
    });
  });

  describe('disabled', () => {
    it('does not open when the trigger is disabled', () => {
      mount(<BasicCombobox disabled />);
      cy.get(trigger).should('be.disabled');
      cy.get(listbox).should('not.exist');
    });
  });

  describe('option groups', () => {
    beforeEach(() => {
      mount(
        <Combobox id="combobox" placeholder="Select">
          <OptionGroup label="Land">
            <Option>Cat</Option>
            <Option>Dog</Option>
          </OptionGroup>
          <OptionGroup label="Sea">
            <Option>Fish</Option>
          </OptionGroup>
        </Combobox>,
      );
      cy.get(trigger).realClick();
    });

    it('renders the correct number of groups', () => {
      cy.get(group).should('have.length', 2);
    });

    it('renders group labels', () => {
      cy.get(groupLabel).first().should('contain.text', 'Land');
      cy.get(groupLabel).last().should('contain.text', 'Sea');
    });

    it('options inside groups are selectable', () => {
      cy.contains(option, 'Fish').realClick();
      cy.get(trigger).should('have.value', 'Fish');
    });
  });
});

'use client';

import * as React from 'react';
import type { ForwardRefComponent } from '@fluentui/react-utilities';
import { useCombobox } from './useCombobox';
import { renderCombobox } from './renderCombobox';
import type { ComboboxProps } from './Combobox.types';
import { useComboboxContextValues } from './useComboboxContextValues';

export const Combobox: ForwardRefComponent<ComboboxProps> = React.forwardRef((props, ref) => {
  const state = useCombobox(props, ref as React.Ref<HTMLInputElement>);
  const contextValues = useComboboxContextValues(state);

  return renderCombobox(state, contextValues);
});

Combobox.displayName = 'Combobox';

import type { BaseComboboxState, BaseComboboxProps } from '@fluentui/react-combobox';
import type { PositioningShorthand } from '../../positioning';

export type {
  ComboboxSlots,
  ComboboxContextValues,
  ComboboxOpenChangeData,
  ComboboxOpenEvents,
} from '@fluentui/react-combobox';

export type ComboboxProps = Omit<BaseComboboxProps, 'inlinePopup' | 'mountNode' | 'positioning'> & {
  positioning?: PositioningShorthand;
};

export type ComboboxState = BaseComboboxState & {
  root: {
    /**
     * Whether the dropdown is currently open.
     */
    'data-open'?: string;
    /**
     * Whether the trigger element is currently disabled.
     */
    'data-disabled'?: string;
    /**
     * Whether the trigger element is currently displaying a placeholder.
     */
    'data-placeholder'?: string;
    /**
     * Whether the trigger element is currently invalid.
     */
    'data-invalid'?: string;
    /**
     * Wether the clear icon is visible.
     */
    'data-clearable'?: string;
  };
};

export { Combobox } from './Combobox';
export type { ComboboxSlots, ComboboxProps, ComboboxState } from './Combobox.types';
export { renderCombobox } from './renderCombobox';
export { useCombobox } from './useCombobox';
export { useComboboxContextValues } from './useComboboxContextValues';
export { useComboboxFilter } from './useComboboxFilter';

export { Listbox, renderListbox, useListbox, useListboxContextValues } from '../Dropdown/Listbox';
export type { ListboxSlots, ListboxProps, ListboxState, ListboxContextValues } from '../Dropdown/Listbox';

export type { OptionSlots, OptionProps, OptionState } from '../Dropdown/Option';
export { Option, renderOption, useOption } from '../Dropdown/Option';

export type { OptionGroupSlots, OptionGroupProps, OptionGroupState } from '../Dropdown/OptionGroup';
export { OptionGroup, renderOptionGroup, useOptionGroup } from '../Dropdown/OptionGroup';

/** @jsxRuntime automatic */
/** @jsxImportSource @fluentui/react-jsx-runtime */

import { assertSlots } from '@fluentui/react-utilities';
import type { JSXElement } from '@fluentui/react-utilities';
import { ActiveDescendantContextProvider } from '@fluentui/react-aria';
import { ListboxProvider } from '@fluentui/react-combobox';
import type { ComboboxContextValues, ComboboxSlots, ComboboxState } from './Combobox.types';

export const renderCombobox = (state: ComboboxState, contextValues: ComboboxContextValues): JSXElement => {
  assertSlots<ComboboxSlots>(state);

  return (
    <state.root>
      <ActiveDescendantContextProvider value={contextValues.activeDescendant}>
        <ListboxProvider value={contextValues.listbox}>
          <state.input />
          {state.clearIcon && <state.clearIcon />}
          {state.expandIcon && <state.expandIcon />}
          {state.open && state.listbox && <state.listbox />}
        </ListboxProvider>
      </ActiveDescendantContextProvider>
    </state.root>
  );
};

'use client';

import * as React from 'react';
import { mergeCallbacks, useEventCallback, useMergedRefs, slot } from '@fluentui/react-utilities';
import { useComboboxExpandIconSlot, useInputTriggerSlot } from '@fluentui/react-combobox';
import type { ComboboxProps, ComboboxState } from './Combobox.types';
import { Listbox } from '../Dropdown/Listbox';
import { toDataAttributeValue } from '../../utils';
import { useListboxPopupState } from '../Dropdown/useListboxPopupState';

export const useCombobox = (props: ComboboxProps, ref: React.Ref<HTMLInputElement>): ComboboxState => {
  const { freeform } = props;

  const {
    props: mergedProps,
    triggerRef,
    activeParentRef,
    activeDescendantController,
    triggerNativeProps,
    internalState,
    listbox,
    rootSlot,
  } = useListboxPopupState<ComboboxProps, HTMLInputElement>(props, {
    primarySlotTagName: 'input',
    fieldControlOptions: { supportsLabelFor: true, supportsRequired: true },
    // For multiselect, editable should be false to display comma-separated values in the trigger
    // For single-select, editable is true to allow filtering
    baseStateExtras: p => ({ editable: !p.multiselect }),
  });

  const { appearance: _appearance, size: _size, ...baseState } = internalState;
  const { clearable, clearSelection, disabled, hasFocus, multiselect, open, selectedOptions } = baseState;
  const expandIconRef = React.useRef<HTMLSpanElement>(null);

  const triggerSlot = useInputTriggerSlot(mergedProps.input ?? {}, useMergedRefs(triggerRef, activeParentRef, ref), {
    state: internalState,
    freeform,
    defaultProps: {
      type: 'text',
      value: baseState.value ?? '',
      'aria-controls': open ? listbox?.id : undefined,
      ...triggerNativeProps,
    },
    activeDescendantController,
    shouldCloseOnBlur: event => !expandIconRef.current || event.relatedTarget !== expandIconRef.current,
  });

  const showClearIcon = selectedOptions.length > 0 && !disabled && clearable && !multiselect;
  const placeholderVisible = !baseState.value && !!mergedProps.placeholder;

  const state: ComboboxState = {
    ...baseState,
    components: { root: 'div', input: 'input', expandIcon: 'span', clearIcon: 'span', listbox: Listbox },
    root: {
      ...rootSlot,
      'data-open': toDataAttributeValue(open),
      'data-disabled': toDataAttributeValue(triggerSlot.disabled),
      'data-placeholder': toDataAttributeValue(placeholderVisible),
      'data-invalid': toDataAttributeValue(triggerSlot['aria-invalid']),
      'data-clearable': toDataAttributeValue(showClearIcon),
    },
    input: triggerSlot,
    listbox: open || hasFocus ? listbox : undefined,
    clearIcon: slot.optional(mergedProps.clearIcon, {
      defaultProps: { 'aria-hidden': 'true' },
      elementType: 'span',
      renderByDefault: true,
    }),
    expandIcon: useComboboxExpandIconSlot(mergedProps.expandIcon, {
      disabled,
      hideFromTabOrder: showClearIcon,
      open,
      'aria-label': mergedProps['aria-label'],
      'aria-labelledby': mergedProps['aria-labelledby'],
      triggerLabelledBy: triggerSlot['aria-labelledby'],
    }),
    showClearIcon,
    activeDescendantController,
  };

  const openOnPointerDownRef = React.useRef<boolean | undefined>(undefined);

  const onExpandIconMouseDown = useEventCallback(
    // eslint-disable-next-line react-hooks/refs
    mergeCallbacks(state.expandIcon?.onMouseDown, (event: React.MouseEvent<HTMLSpanElement>) => {
      event.preventDefault();
      openOnPointerDownRef.current = open;
    }),
  );

  const onExpandIconClick = useEventCallback(
    // eslint-disable-next-line react-hooks/refs
    mergeCallbacks(state.expandIcon?.onClick, (event: React.MouseEvent<HTMLSpanElement>) => {
      event.preventDefault();
      // Click-only activation must not consume a canceled pointer gesture.
      const wasOpenOnPointerDown = event.detail > 0 ? openOnPointerDownRef.current : undefined;
      const nextOpen = !(wasOpenOnPointerDown ?? open);
      openOnPointerDownRef.current = undefined;
      // A pointer interaction that starts while open light-dismisses an auto popover on pointerup.
      // Let the popover's toggle event issue the close notification so onOpenChange fires only once.
      if (!disabled && (!wasOpenOnPointerDown || listbox?.popover === 'manual')) {
        internalState.setOpen(event, nextOpen);
      }
      triggerRef.current?.focus();
    }),
  );

  const onExpandIconKeyDown = useEventCallback(
    // eslint-disable-next-line react-hooks/refs
    mergeCallbacks(state.expandIcon?.onKeyDown, event => {
      if (open && event.key === 'Escape') {
        event.preventDefault();
        event.stopPropagation();
        internalState.setOpen(event, false);
        triggerRef.current?.focus();
        return;
      }

      if (!disabled && (event.key === 'Enter' || event.key === ' ')) {
        event.preventDefault();
        const nextOpen = !open;
        internalState.setOpen(event, nextOpen);
        triggerRef.current?.focus();
      }
    }),
  );
  const expandIconSlotRef = useMergedRefs(state.expandIcon?.ref, expandIconRef);

  if (state.expandIcon) {
    state.expandIcon.ref = expandIconSlotRef;
    state.expandIcon.onMouseDown = onExpandIconMouseDown;
    state.expandIcon.onClick = onExpandIconClick;
    state.expandIcon.onKeyDown = onExpandIconKeyDown;
  }

  state.root.onBlur = mergeCallbacks(state.root.onBlur, event => {
    if (!event.relatedTarget || !event.currentTarget.contains(event.relatedTarget)) {
      if (event.target !== event.currentTarget.querySelector('input')) {
        internalState.setOpen(event as unknown as React.FocusEvent<HTMLInputElement>, false);
      }
      internalState.setHasFocus(false);
    }
  });

  const onClearIconMouseDown = useEventCallback(
    mergeCallbacks(state.clearIcon?.onMouseDown, (ev: React.MouseEvent<HTMLSpanElement>) => {
      ev.preventDefault();
    }),
  );
  const onClearIconClick = useEventCallback(
    // eslint-disable-next-line react-hooks/refs
    mergeCallbacks(state.clearIcon?.onClick, (ev: React.MouseEvent<HTMLSpanElement>) => {
      clearSelection(ev);
      triggerRef.current?.focus();
    }),
  );

  if (state.clearIcon) {
    state.clearIcon.onMouseDown = onClearIconMouseDown;
    state.clearIcon.onClick = onClearIconClick;
  }

  // Heads up! We don't support "clearable" in multiselect mode, so we should never display a slot
  if (multiselect) {
    state.clearIcon = undefined;
  }

  return state;
};

'use client';

import { useComboboxContextValues as useComboboxContextValuesBase } from '@fluentui/react-combobox';
import type { ComboboxState, ComboboxContextValues } from './Combobox.types';

export const useComboboxContextValues = useComboboxContextValuesBase as unknown as (
  state: ComboboxState,
) => ComboboxContextValues;

'use client';

import * as React from 'react';
import type { JSXElement } from '@fluentui/react-utilities';

type UseComboboxFilterConfig = {
  /**
   * The current query string used to filter the options.
   */
  query: string;
  /**
   * The list of options to filter.
   */
  options: string[];
  /**
   * Optional filter function to override the default filtering behavior.
   */
  filter?: (option: string, index: number) => boolean;
  /**
   * Element to render when there are no options to display.
   */
  noOptionsElement: JSXElement;
  /**
   * A function that renders an option element for a given option.
   * Use it to customize how options are displayed in the listbox.
   */
  renderOption: (option: string) => JSXElement;
};

/**
 * A hook that filters a list of options based on a query string and returns the filtered options as JSX elements.
 *
 * @param config - The configuration object for the hook.
 * @returns An array of JSX elements representing the filtered options.
 */
export function useComboboxFilter({
  filter: filterOverride,
  noOptionsElement,
  renderOption,
  query,
  options,
}: UseComboboxFilterConfig): JSXElement[] {
  const defaultFilter = React.useCallback(
    (option: string) => {
      const trimmedQuery = query.trim();
      return trimmedQuery === '' || option.toLowerCase().includes(trimmedQuery.toLowerCase());
    },
    [query],
  );
  const filter = filterOverride ?? defaultFilter;
  const filteredOptions = React.useMemo(
    () =>
      options.reduce<JSXElement[]>((accumulator, option, index) => {
        if (filter(option, index)) {
          accumulator.push(renderOption(option));
        }
        return accumulator;
      }, []),
    [options, renderOption, filter],
  );

  return filteredOptions.length === 0
    ? [noOptionsElement.key ? noOptionsElement : React.cloneElement(noOptionsElement, { key: 'no-options' })]
    : filteredOptions;
}

