/**
 * A button with primary and secondary content. Concise primary and secondary text form its accessible name.
 */
export const CompoundButton: ForwardRefComponent<CompoundButtonProps> = React.forwardRef((props, ref) => {
  const state = useCompoundButton(props, ref);

  return renderCompoundButton(state);
});

CompoundButton.displayName = 'CompoundButton';

import type { CompoundButtonBaseState } from '@fluentui/react-button';

export type { CompoundButtonBaseProps as CompoundButtonProps, CompoundButtonSlots } from '@fluentui/react-button';

/**
 * CompoundButton component state.
 */
export type CompoundButtonState = CompoundButtonBaseState & {
  root: {
    /**
     * Data attribute set when the button is disabled.
     */
    'data-disabled'?: string;

    /**
     * Data attribute set when the button is disabled but still focusable.
     */
    'data-disabled-focusable'?: string;

    /**
     * Data attribute set when the button renders only an icon.
     */
    'data-icon-only'?: string;

    /**
     * Data attribute reflecting the icon position when an icon slot is present.
     */
    'data-icon-position'?: CompoundButtonBaseState['iconPosition'];

    /**
     * Data attribute set when secondary content is rendered.
     */
    'data-has-secondary-content'?: string;
  };
};

export { CompoundButton } from './CompoundButton';
export type { CompoundButtonProps, CompoundButtonSlots, CompoundButtonState } from './CompoundButton.types';
export { renderCompoundButton } from './renderCompoundButton';
export { useCompoundButton } from './useCompoundButton';

'use client';

import type * as React from 'react';
import { useCompoundButtonBase_unstable } from '@fluentui/react-button';

import { toDataAttributeValue } from '../../utils';
import type { CompoundButtonProps, CompoundButtonState } from './CompoundButton.types';

/**
 * Returns the state for a CompoundButton component, given its props and ref.
 */
export const useCompoundButton = (
  props: CompoundButtonProps,
  ref: React.Ref<HTMLButtonElement | HTMLAnchorElement>,
): CompoundButtonState => {
  const state: CompoundButtonState = useCompoundButtonBase_unstable(props, ref);
  const hasSecondaryContent = Boolean(!state.iconOnly && state.secondaryContent);

  // eslint-disable-next-line react-hooks/immutability
  state.root['data-disabled'] = toDataAttributeValue(state.disabled);
  // eslint-disable-next-line react-hooks/immutability
  state.root['data-disabled-focusable'] = toDataAttributeValue(state.disabledFocusable);
  // eslint-disable-next-line react-hooks/immutability
  state.root['data-icon-only'] = toDataAttributeValue(state.iconOnly);
  // eslint-disable-next-line react-hooks/immutability
  state.root['data-icon-position'] = state.icon ? state.iconPosition : undefined;
  // eslint-disable-next-line react-hooks/immutability
  state.root['data-has-secondary-content'] = toDataAttributeValue(hasSecondaryContent);

  return state;
};

