'use client';

import * as React from 'react';
import { useDialog } from './useDialog';
import { useDialogContextValues } from './useDialogContextValues';
import { renderDialog } from './renderDialog';
import type { DialogProps } from './Dialog.types';

/**
 * The `Dialog` root component serves as an interface for all Dialog behaviors.
 * It provides context to compound sub-components: `DialogTrigger`, `DialogSurface`,
 * `DialogHeader`, `DialogTitle`, `DialogBody`, and `DialogActions`.
 *
 * This component uses the native HTML `<dialog>` element (via `DialogSurface`) for
 * built-in focus trapping, backdrop, and accessibility semantics.
 */
export const Dialog: React.FC<DialogProps> = React.memo(props => {
  const state = useDialog(props);
  const contextValues = useDialogContextValues(state);
  return renderDialog(state, contextValues);
});

Dialog.displayName = 'Dialog';

import type * as React from 'react';
import type { JSXElement, EventHandler } from '@fluentui/react-utilities';
import type {
  DialogContextValue,
  DialogModalType,
  DialogOpenChangeData,
  DialogSurfaceContextValue,
} from './dialogContext';

export type { DialogModalType, DialogOpenChangeData };

export type DialogOpenChangeEvent = DialogOpenChangeData['event'];

/**
 * Callback fired when the component changes value from open state.
 *
 * @param event - a React's Synthetic event
 * @param data - A data object with relevant information,
 * such as open value and type of interaction that created the event
 */
export type DialogOpenChangeEventHandler = EventHandler<DialogOpenChangeData>;

export type DialogContextValues = {
  dialog: DialogContextValue;
  /**
   * dialogSurface context is provided by Dialog as false
   * to ensure components inside Dialog but outside DialogSurface consume this as false
   */
  dialogSurface: DialogSurfaceContextValue;
};

export type DialogProps = {
  /**
   * Dialog variations.
   *
   * `modal`: When this type of dialog is open, the rest of the page is dimmed out and cannot be interacted with.
   * The tab sequence is kept within the dialog. This is the default type of the component.
   *
   * `non-modal`: When a non-modal dialog is open, the rest of the page is not dimmed out
   * and users can interact with the rest of the page.
