      cy.get('[data-testid=trigger]').focus().trigger('mouseenter');
      cy.get('[data-testid=surface]').should('be.visible');
      cy.get('[data-testid=trigger]').trigger('mouseleave');
      cy.get('[data-testid=surface]').should('not.exist');
