import type { MenuProps } from './Menu.types';

/**
 * Wrapper component that manages state for a popup MenuList and a MenuTrigger
 */
export const Menu: React.FC<MenuProps> = props => {
  const state = useMenu_unstable(props);
  const contextValues = useMenuContextValues_unstable(state);

  return renderMenu_unstable(state, contextValues);
};

Menu.displayName = 'Menu';

import type * as React from 'react';
import type { PresenceMotionSlotProps } from '@fluentui/react-motion';
import type { PositioningVirtualElement, SetVirtualMouseTarget } from '@fluentui/react-positioning';
import type { PositioningShorthand } from '@fluentui/react-positioning';
import type { PortalProps } from '@fluentui/react-portal';
import type { ComponentProps, ComponentState, JSXElement, Slot } from '@fluentui/react-utilities';
import type { MenuContextValue } from '../../contexts/menuContext';
import type { MenuListProps } from '../MenuList/MenuList.types';

export type MenuSlots = {
  /**
   * Slot for the surface motion animation.
   * For more information refer to the [Motion docs page](https://react.fluentui.dev/?path=/docs/motion-motion-slot--docs).
   */
  surfaceMotion: Slot<PresenceMotionSlotProps>;
};

export type InternalMenuSlots = {
  surfaceMotion: NonNullable<Slot<PresenceMotionSlotProps>>;
};

/**
 * Extends and drills down Menulist props to simplify API
 */
export type MenuProps = ComponentProps<Partial<MenuSlots>> &
  Pick<PortalProps, 'mountNode'> &
  Pick<
    MenuListProps,
    'checkedValues' | 'defaultCheckedValues' | 'hasCheckmarks' | 'hasIcons' | 'onCheckedValueChange'
  > & {
    /**
     * Can contain two children including `MenuTrigger` and `MenuPopover`.
     * Alternatively can only contain `MenuPopover` if using a custom `target`.
     */
    children: [JSXElement, JSXElement] | JSXElement;

    /**
     * Sets the delay for mouse open/close for the popover one mouse enter/leave
     */
    hoverDelay?: number;

    /**
     * Root menus are rendered out of DOM order on `document.body`, use this to render the menu in DOM order
     * This option is disregarded for submenus
     *
     * @default false
     */
    inline?: boolean;

    /**
     * Call back when the component requests to change value
     * The `open` value is used as a hint when directly controlling the component
     */
    // eslint-disable-next-line @nx/workspace-consistent-callback-type -- can't change type of existing callback
    onOpenChange?: (e: MenuOpenEvent, data: MenuOpenChangeData) => void;

    /**
     * Whether the popup is open
     *
     * @default false
     */
    open?: boolean;

    /**
     * Whether the popup is open by default
     *
     * @default false
     */
    defaultOpen?: boolean;

    /**
     * Opens the menu on right click (context menu), removes all other menu open interactions
     *
     * @default false
     */
    openOnContext?: boolean;

    /**
     * Opens the menu on hover
     *
     * @default false
     */
    openOnHover?: boolean;

    /**
     * Do not dismiss the menu when a menu item is clicked
     *
     * @default false
     */
    persistOnItemClick?: boolean;

    /**
     * Configures the positioned menu
     */
    positioning?: PositioningShorthand;

    /**
     * Close when scroll outside of it
     *
     * @default false
     */
    closeOnScroll?: boolean;
  };

export type MenuState = ComponentState<InternalMenuSlots> &
  Required<
    Pick<
      MenuProps,
      | 'hasCheckmarks'
      | 'hasIcons'
      | 'mountNode'
      | 'inline'
      | 'checkedValues'
      | 'onCheckedValueChange'
      | 'open'
      | 'openOnHover'
      | 'closeOnScroll'
      | 'hoverDelay'
      | 'openOnContext'
      | 'persistOnItemClick'
    >
  > & {
    /**
     * Anchors the popper to the mouse click for context events
     */
    contextTarget?: PositioningVirtualElement;

    /**
     * Whether this menu is a submenu
     */
    isSubmenu: boolean;

    /**
     * Internal react node that just simplifies handling children
     */
    menuPopover: React.ReactNode;

    /**
     * The ref for the popup
     */
    // eslint-disable-next-line @typescript-eslint/no-deprecated
    menuPopoverRef: React.MutableRefObject<HTMLElement | null>;

    /**
     * Internal react node that just simplifies handling children
     */
    menuTrigger: React.ReactNode;

    /**
     * A callback to set the target of the popper to the mouse click for context events
     */
    setContextTarget: SetVirtualMouseTarget;

    /**
     * Callback to open/close the popup
     */
    setOpen: (e: MenuOpenEvent, data: MenuOpenChangeData & { ignoreHoverDelay?: boolean }) => void;

    /**
     * Id for the MenuTrigger element for aria relationship
     */
    triggerId: string;

    /**
     * The ref for the MenuTrigger, used for popup positioning
     */
    // eslint-disable-next-line @typescript-eslint/no-deprecated
    triggerRef: React.MutableRefObject<HTMLElement | null>;

    /**
     * Call back when the component requests to change value
     * The `open` value is used as a hint when directly controlling the component
     * @deprecated this property is not used internally anymore,
     * the signature remains just to avoid breaking changes
     */
    onOpenChange?: (e: MenuOpenEvent, data: MenuOpenChangeData) => void;
    /**
     * Default values to be checked on mount
     @deprecated this property is not used internally anymore,
     * the signature remains just to avoid breaking changes
     */
    defaultCheckedValues?: Record<string, string[]>;

    /**
     * An optional safe zone area to be rendered around the menu
     */
    safeZone?: React.ReactElement | null;
  };

export type MenuBaseProps = Omit<MenuProps, 'surfaceMotion'>;

export type MenuBaseState = Omit<MenuState, 'surfaceMotion' | 'components'>;

export type MenuContextValues = {
  menu: MenuContextValue;
};

/**
 * The supported events that will trigger open/close of the menu
 */
export type MenuOpenEvent = MenuOpenChangeData['event'];
/**
 * @deprecated use MenuOpenEvent instead
 */
export type MenuOpenEvents = MenuOpenEvent;

/**
 * Data attached to open/close events
 */
export type MenuOpenChangeData = {
  /**
   * indicates whether the request for the open state was bubbled from a nested menu
   */
  bubble?: boolean;
  /**
   * Indicates whether the change of state was a keyboard interaction
   * @deprecated
   * This should not be used, since `Enter`, `Space` and click should be interpreted as the same thing as a click
   */
  keyboard?: boolean;
  open: boolean;
} & (
  | {
      type: 'menuTriggerContextMenu';
      event: React.MouseEvent<HTMLElement>;
    }
  | {
      type: 'menuTriggerClick';
      event: React.MouseEvent<HTMLElement>;
    }
  | {
      type: 'menuTriggerMouseEnter';
      event: React.MouseEvent<HTMLElement>;
    }
  | {
      type: 'menuSafeZoneMouseEnter';
      event: React.MouseEvent;
    }
  | {
      type: 'menuSafeZoneTimeout';
      event: Event;
    }
  | {
      type: 'menuTriggerMouseLeave';
      event: React.MouseEvent<HTMLElement>;
    }
  | {
      type: 'menuTriggerMouseMove';
      event: React.MouseEvent<HTMLElement>;
    }
  | {
      type: 'menuTriggerKeyDown';
      event: React.KeyboardEvent<HTMLElement>;
    }
  | {
      type: 'menuItemClick';
      event: React.MouseEvent<HTMLElement>;
    }
  | {
      type: 'menuPopoverMouseEnter';
      event: React.MouseEvent<HTMLElement>;
    }
  | {
      type: 'menuPopoverKeyDown';
      event: React.KeyboardEvent<HTMLElement>;
    }
  | {
      type: 'clickOutside';
      event: MouseEvent | TouchEvent;
    }
  | {
      type: 'scrollOutside';
      event: MouseEvent | TouchEvent;
    }
  | {
      type: 'menuMouseEnter';
      event: MouseEvent | TouchEvent;
    }
);

import { createPresenceComponent, motionTokens } from '@fluentui/react-motion';
import { fadeAtom, slideAtom } from '@fluentui/react-motion-components-preview';
import {
  POSITIONING_SLIDE_DIRECTION_VAR_X as slideDirectionVarX,
  POSITIONING_SLIDE_DIRECTION_VAR_Y as slideDirectionVarY,
} from '@fluentui/react-positioning';

// Shared timing constants for the enter animation.
const duration = motionTokens.durationSlower;
const easing = motionTokens.curveDecelerateMid;

/**
 * Default `surfaceMotion` slot for `<Menu>`.
 *
 * Enter-only animation combining a fade and a direction-aware slide.
 * The slide reads CSS variables set by `usePositioningSlideDirection` and scales
 * them by `distance` pixels. There is no exit animation; the surface unmounts immediately.
 *
 * @param distance - Travel distance (px) for the enter slide. Defaults to `10`.
 */
export const MenuSurfaceMotion = createPresenceComponent(({ distance = 10 }: { distance?: number }) => ({
  enter: [
    fadeAtom({ duration, easing, direction: 'enter' }),
    {
      // slideAtom produces translate keyframes from `outX`/`outY` → `0px`.
      // The `outX`/`outY` values read the positioning-provided CSS variables and scale
      // them by `distance` so the surface slides in from the correct direction.
      ...slideAtom({
        duration,
        easing,
        direction: 'enter',
        outX: `calc(var(${slideDirectionVarX}, 0px) * ${distance})`,
        outY: `calc(var(${slideDirectionVarY}, 0px) * ${distance})`,
      }),
      // 'accumulate' compositing adds this effect's transform on top of the element's
      // existing transform, preserving any transform applied by the positioning engine.
      composite: 'accumulate',
    },
  ],
  // No exit animation — the surface unmounts immediately on close.
  exit: [],
}));

export { Menu } from './Menu';
export type {
  MenuBaseProps,
  MenuBaseState,
  MenuContextValues,
  MenuOpenChangeData,
  MenuOpenEvent,
  // eslint-disable-next-line @typescript-eslint/no-deprecated
  MenuOpenEvents,
  MenuProps,
  MenuSlots,
  MenuState,
} from './Menu.types';
export { renderMenu_unstable } from './renderMenu';
export { useMenu_unstable, useMenuBase_unstable } from './useMenu';
export { useMenuContextValues_unstable } from './useMenuContextValues';

/** @jsxRuntime automatic */
/** @jsxImportSource @fluentui/react-jsx-runtime */

import * as React from 'react';
import { MotionRefForwarder } from '@fluentui/react-motion';
import { assertSlots } from '@fluentui/react-utilities';
import type { JSXElement } from '@fluentui/react-utilities';
import { MenuProvider } from '../../contexts/menuContext';
import type { InternalMenuSlots, MenuContextValues, MenuState } from './Menu.types';

/**
 * Render the final JSX of Menu
 */
export const renderMenu_unstable = (state: MenuState, contextValues: MenuContextValues): JSXElement => {
  assertSlots<InternalMenuSlots>(state);

  return (
    <MenuProvider value={contextValues.menu}>
      {state.menuTrigger}
      {state.menuPopover && (
        <state.surfaceMotion>
          <MotionRefForwarder>
            {/* Casting here as content should be equivalent to <MenuPopover /> */}
            {/* FIXME: content should not be ReactNode it should be ReactElement instead. */}
            {state.menuPopover as React.ReactElement}
          </MotionRefForwarder>
        </state.surfaceMotion>
      )}
    </MenuProvider>
  );
};

'use client';

import * as React from 'react';
import {
  resolvePositioningShorthand,
  usePositioningMouseTarget,
  usePositioning,
  useSafeZoneArea,
  usePositioningSlideDirection,
  type PositioningShorthandValue,
} from '@fluentui/react-positioning';
import { presenceMotionSlot } from '@fluentui/react-motion';
import {
  useControllableState,
  useId,
  useOnClickOutside,
  useEventCallback,
  useOnScrollOutside,
  elementContains,
  useTimeout,
  useFirstMount,
  useMergedRefs,
} from '@fluentui/react-utilities';
import { useFluent_unstable as useFluent } from '@fluentui/react-shared-contexts';
import { useFocusFinders } from '@fluentui/react-tabster';

import { useMenuContext_unstable } from '../../contexts/menuContext';
import { MENU_SAFEZONE_TIMEOUT_EVENT, MENU_ENTER_EVENT, useOnMenuMouseEnter, useIsSubmenu } from '../../utils';
import { menuItemClassNames } from '../MenuItem/useMenuItemStyles.styles';
import type {
  MenuBaseProps,
  MenuBaseState,
  MenuOpenChangeData,
  MenuOpenEvent,
  MenuProps,
  MenuState,
} from './Menu.types';
import { MenuSurfaceMotion } from './MenuSurfaceMotion';

// If it's not possible to position the submenu in smaller viewports, try
// and fallback to this order of positions
const submenuFallbackPositions: PositioningShorthandValue[] = [
  'after',
  'after-bottom',
  'before-top',
  'before',
  'before-bottom',
  'above',
];

/**
 * Create the state required to render Menu.
 *
 * The returned state can be modified with hooks such as useMenuStyles,
 * before being passed to renderMenu_unstable.
 *
 * @param props - props from this instance of Menu
 */
export const useMenu_unstable = (props: MenuProps & { safeZone?: boolean | { timeout?: number } }): MenuState => {
  const { surfaceMotion, ...baseProps } = props;
  const baseState = useMenuBase_unstable(baseProps);

  return {
    ...baseState,
    components: {
      surfaceMotion: MenuSurfaceMotion,
    },
    surfaceMotion: presenceMotionSlot(surfaceMotion, {
      elementType: MenuSurfaceMotion,
      defaultProps: {
        visible: baseState.open,
        appear: true,
        unmountOnExit: true,
      },
    }),
  };
};

/**
 * Base hook for Menu component, produces state required to render the component.
 * It doesn't set any design-related slots specific to Menu such as `surfaceMotion`.
 *
 * @param props - props from this instance of Menu
 */
export const useMenuBase_unstable = (
  props: MenuBaseProps & { safeZone?: boolean | { timeout?: number } },
): MenuBaseState => {
  const isSubmenu = useIsSubmenu();
  const {
    hoverDelay = 500,
    inline = false,
    hasCheckmarks = false,
    hasIcons = false,
    closeOnScroll = false,
    openOnContext = false,
    persistOnItemClick = false,
    openOnHover = isSubmenu,
    defaultCheckedValues,
    mountNode = null,
    safeZone,
  } = props;

  const { targetDocument } = useFluent();
  const triggerId = useId('menu');
  const [contextTarget, setContextTarget] = usePositioningMouseTarget();

  const resolvedPositioning = resolvePositioningShorthand(props.positioning);
  const handlePositionEnd = usePositioningSlideDirection({
    targetDocument,
    onPositioningEnd: resolvedPositioning.onPositioningEnd,
  });

  const positioningOptions = {
    position: isSubmenu ? 'after' : 'below',
    align: isSubmenu ? 'top' : 'start',
    target: props.openOnContext ? contextTarget : undefined,
    fallbackPositions: isSubmenu ? submenuFallbackPositions : undefined,
    ...resolvedPositioning,
    onPositioningEnd: handlePositionEnd,
  } as const;

  const children = React.Children.toArray(props.children) as React.ReactElement[];

  if (process.env.NODE_ENV !== 'production') {
    if (children.length === 0) {
      // eslint-disable-next-line no-console
      console.warn('Menu must contain at least one child');
    }

    if (children.length > 2) {
      // eslint-disable-next-line no-console
      console.warn('Menu must contain at most two children');
    }
  }

  let menuTrigger: React.ReactElement | undefined = undefined;
  let menuPopover: React.ReactElement | undefined = undefined;
  if (children.length === 2) {
    menuTrigger = children[0];
    menuPopover = children[1];
  } else if (children.length === 1) {
    menuPopover = children[0];
  }

  const { targetRef, containerRef } = usePositioning(positioningOptions);

  const enableSafeZone = safeZone && openOnHover;
  const safeZoneDescriptorRef = React.useRef({
    isInside: false,
    mouseCoordinates: { x: 0, y: 0 },
  });

  const safeZoneHandle = useSafeZoneArea({
    disabled: !enableSafeZone,
    timeout: typeof safeZone === 'object' ? safeZone.timeout : 300,

    onSafeZoneEnter: e => {
      setOpen(e, { open: true, keyboard: false, type: 'menuSafeZoneMouseEnter', event: e });
      safeZoneDescriptorRef.current.isInside = true;
    },
    onSafeZoneLeave: () => {
      safeZoneDescriptorRef.current.isInside = false;
    },
    onSafeZoneMove: e => {
      safeZoneDescriptorRef.current.mouseCoordinates = {
        x: e.clientX,
        y: e.clientY,
      };
    },
    onSafeZoneTimeout: () => {
      const event = new CustomEvent(MENU_SAFEZONE_TIMEOUT_EVENT);

      setOpen(event, { open: false, keyboard: false, type: 'menuSafeZoneTimeout', event });

      if (safeZoneDescriptorRef.current.isInside && targetDocument) {
        const elementsInPoint = targetDocument.elementsFromPoint(
          safeZoneDescriptorRef.current.mouseCoordinates.x,
          safeZoneDescriptorRef.current.mouseCoordinates.y,
        );
        const menuItemEl = elementsInPoint.find(el => {
          return el.classList.contains(menuItemClassNames.root);
        }) as HTMLElement | null;

        menuItemEl?.dispatchEvent(event);
      }
    },
  });

  const triggerRef = useMergedRefs(targetRef, safeZoneHandle.targetRef);
  const menuPopoverRef = useMergedRefs(containerRef, safeZoneHandle.containerRef);

  // TODO Better way to narrow types ?
  const [open, setOpen] = useMenuOpenState({
    hoverDelay,
    isSubmenu,
    setContextTarget,
    closeOnScroll,
    menuPopoverRef,
    triggerRef,
    open: props.open,
    defaultOpen: props.defaultOpen,
    onOpenChange: props.onOpenChange,
    openOnContext,
  });

  const [checkedValues, onCheckedValueChange] = useMenuSelectableState({
    checkedValues: props.checkedValues,
    defaultCheckedValues,
    onCheckedValueChange: props.onCheckedValueChange,
  });

  return {
    inline,
    hoverDelay,
    triggerId,
    isSubmenu,
    openOnHover,
    contextTarget,
    setContextTarget,
    hasCheckmarks,
    hasIcons,
    closeOnScroll,
    menuTrigger,
    menuPopover,
    mountNode,
    triggerRef,
    menuPopoverRef,
    openOnContext,
    open,
    setOpen,
    checkedValues,
    onCheckedValueChange,
    persistOnItemClick,
    safeZone: safeZoneHandle.elementToRender,
  };
};

/**
 * Adds appropriate state values and handlers for selectable items
 * i.e checkboxes and radios
 */
const useMenuSelectableState = (
  props: Pick<MenuProps, 'checkedValues' | 'defaultCheckedValues' | 'onCheckedValueChange'>,
) => {
  const [checkedValues, setCheckedValues] = useControllableState({
    state: props.checkedValues,
    defaultState: props.defaultCheckedValues,
    initialState: {},
  });
  const onCheckedValueChange: MenuState['onCheckedValueChange'] = useEventCallback((e, { name, checkedItems }) => {
    props.onCheckedValueChange?.(e, { name, checkedItems });

    setCheckedValues(currentValue => ({
      ...currentValue,
      [name]: checkedItems,
    }));
  });

  return [checkedValues, onCheckedValueChange] as const;
};

const useMenuOpenState = (
  state: Pick<
    MenuState,
    | 'isSubmenu'
    | 'menuPopoverRef'
    | 'setContextTarget'
    | 'triggerRef'
    | 'openOnContext'
    | 'closeOnScroll'
    | 'hoverDelay'
  > &
    Pick<MenuProps, 'open' | 'defaultOpen' | 'onOpenChange'>,
) => {
  const { targetDocument } = useFluent();
  const parentSetOpen = useMenuContext_unstable(context => context.setOpen);
