  const selection = useListSelection({
    onSelectionChange: onChange,
    selectionMode,
    selectedItems: selectionState,
    defaultSelectedItems,
  });

  return {
    components: {
      root: DEFAULT_ROOT_EL_TYPE,
    },
    root: slot.always(
      getIntrinsicElementProps(DEFAULT_ROOT_EL_TYPE, {
        ref,
        ...(navigable && { role: 'menu' }),
