import { mergeClasses } from '@griffel/react';
import { classNamesFunction } from '@fluentui/react';
import type { IStackProps, IStackTokens, IStackItemProps } from '@fluentui/react';
import * as React from 'react';

import { getChildrenGapStyles } from './stackUtils';
import type { StackShimStyles } from './stackUtils';
import type { JSXElement } from '@fluentui/react-utilities';
import {
  useFlexAlignItemsStyles,
  useFlexGrowStyles,
  useFlexJustifyContentStyles,
  useStackStyles,
} from './StackShim.styles';

const stackClassNames = {
  root: 'ms-Stack',
  inner: 'ms-Stack-inner',
};

const getClassNames = classNamesFunction<IStackProps, StackShimStyles>();
export const StackShim = (props: IStackProps): JSXElement => {
  const styles = useStackStyles();
  const alignItemsFlexStyles = useFlexAlignItemsStyles();
  const justifyContentFlexStyles = useFlexJustifyContentStyles();
  const growFlexStyles: Record<string, string> = useFlexGrowStyles();

  const {
    as: RootType = 'div',
    verticalFill,
    horizontal,
    reversed,
    grow,
    wrap,
    horizontalAlign,
    verticalAlign,
    disableShrink,
    className,
  } = props;

  const tokens: IStackTokens = { ...props.tokens };

  let tokensRootStyles = {};
  let tokensInnerStyles = {};
  let childrenGapClassName;

  if (tokens) {
    tokensRootStyles = {
      padding: !wrap ? tokens.padding : undefined,
      maxHeight: tokens.maxHeight,
      maxWidth: tokens.maxWidth,
    };

    tokensInnerStyles = {
      padding: wrap ? tokens.padding : undefined,
    };

    if (tokens.childrenGap) {
      childrenGapClassName = getClassNames(getChildrenGapStyles, {
        horizontal,
        reversed,
        tokens,
      });
    }
  }

  const stackStyles = [
    wrap ? styles.wrap : styles.root,
    horizontal && styles.horizontal,
    verticalFill && styles.verticalFill,
  ];

  const stackInnerStyles = [
    styles.inner,
    horizontal && styles.horizontal,
    (!tokens || !tokens.childrenGap) && styles.innerWidth,
  ];

  type StackChildren = Exclude<React.ReactNode, boolean | string | number | bigint | null | undefined>;

  let stackChildren = React.Children.toArray(props.children) as StackChildren[];
  if (
    stackChildren.length === 1 &&
    React.isValidElement(stackChildren[0]) &&
    stackChildren[0].type === React.Fragment
  ) {
    stackChildren = (stackChildren[0].props as React.FragmentProps).children as StackChildren[];
  }

  stackChildren = React.Children.map(stackChildren, child => {
    if (!child) {
      return null;
    }

    const _child = child as React.ReactElement<{}, React.ComponentType>;

    if (_child.type && _child.type.name === 'StackItemShim') {
      const defaultItemProps: IStackItemProps = {
        shrink: !disableShrink,
      };

      return React.cloneElement(_child, {
        ...defaultItemProps,
        ..._child.props,
      });
    }

    return child;
  });

  if (reversed) {
    if (horizontal) {
      stackStyles.push(styles.reversedHorizontal);
      stackInnerStyles.push(styles.reversedHorizontal);
    } else {
      stackStyles.push(styles.reversedVertical);
      stackInnerStyles.push(styles.reversedVertical);
    }
  }

  if (grow) {
    const flexGrow = grow === true ? growFlexStyles[1] : growFlexStyles[grow];
    stackStyles.push(flexGrow);
  }

  if (disableShrink) {
    stackStyles.push(styles.disableShrink);
  }

  if (horizontalAlign) {
    if (horizontal) {
      stackStyles.push(justifyContentFlexStyles[horizontalAlign]);
      stackInnerStyles.push(justifyContentFlexStyles[horizontalAlign]);
    } else {
      stackStyles.push(alignItemsFlexStyles[horizontalAlign]);
      stackInnerStyles.push(alignItemsFlexStyles[horizontalAlign]);
    }
  }

  if (verticalAlign) {
    if (horizontal) {
      stackStyles.push(alignItemsFlexStyles[verticalAlign]);
      stackInnerStyles.push(alignItemsFlexStyles[verticalAlign]);
    } else {
      stackStyles.push(justifyContentFlexStyles[verticalAlign]);
      stackInnerStyles.push(justifyContentFlexStyles[verticalAlign]);
    }
  }

  const rootClass = mergeClasses(
    stackClassNames.root,
    ...stackStyles,
    childrenGapClassName && !wrap && childrenGapClassName.root,
    className,
  );

  const innerClass = mergeClasses(
    stackClassNames.inner,
    ...stackInnerStyles,
    childrenGapClassName && wrap && childrenGapClassName.inner,
  );

  return wrap ? (
    <RootType className={rootClass} style={tokensRootStyles}>
      <div className={innerClass} style={tokensInnerStyles}>
        {stackChildren}
      </div>
    </RootType>
  ) : (
    <RootType className={rootClass} style={tokensRootStyles}>
      {stackChildren}
    </RootType>
  );
};

import type { IStackProps, IStackTokens, IStyle, ITheme } from '@fluentui/react';
import { getTheme } from '@fluentui/react';

// Helper function that converts a themed spacing key (if given) to the corresponding themed spacing value.
const getThemedSpacing = (space: string, theme: ITheme): string => {
  if (theme.spacing.hasOwnProperty(space)) {
    return theme.spacing[space as keyof typeof theme.spacing];
  }
  return space;
};

// Helper function that takes a gap as a string and converts it into a { value, unit } representation.
const getValueUnitGap = (gap: string): { value: number; unit: string } => {
  const numericalPart = parseFloat(gap);
  const numericalValue = isNaN(numericalPart) ? 0 : numericalPart;
  const numericalString = isNaN(numericalPart) ? '' : numericalPart.toString();

  const unitPart = gap.substring(numericalString.toString().length);

  return {
    value: numericalValue,
    unit: unitPart || 'px',
  };
};

/**
 * Takes in a gap size in either a CSS-style format (e.g. 10 or "10px")
 *  or a key of a themed spacing value (e.g. "s1").
 * Returns the separate numerical value of the padding (e.g. 10)
 *  and the CSS unit (e.g. "px").
 */
export const parseGap = (
  gap: IStackProps['gap'],
  theme: ITheme,
): { rowGap: { value: number; unit: string }; columnGap: { value: number; unit: string } } => {
  if (gap === undefined || gap === '') {
    return {
      rowGap: {
        value: 0,
        unit: 'px',
      },
      columnGap: {
        value: 0,
        unit: 'px',
      },
    };
  }

  if (typeof gap === 'number') {
    return {
      rowGap: {
        value: gap,
        unit: 'px',
      },
      columnGap: {
        value: gap,
        unit: 'px',
      },
    };
  }

  const splitGap = gap.split(' ');

  // If the array has more than two values, then return 0px.
  if (splitGap.length > 2) {
    return {
      rowGap: {
        value: 0,
        unit: 'px',
      },
      columnGap: {
        value: 0,
        unit: 'px',
      },
    };
  }

  // If the array has two values, then parse each one.
  if (splitGap.length === 2) {
    return {
      rowGap: getValueUnitGap(getThemedSpacing(splitGap[0], theme)),
      columnGap: getValueUnitGap(getThemedSpacing(splitGap[1], theme)),
    };
  }

  // Else, parse the numerical value and pass it as both the vertical and horizontal gap.
  const calculatedGap = getValueUnitGap(getThemedSpacing(gap, theme));

  return {
    rowGap: calculatedGap,
    columnGap: calculatedGap,
  };
};

/**
 * Takes in a padding in a CSS-style format (e.g. 10, "10px", "10px 10px", etc.)
 *  where the separate padding values can also be the key of a themed spacing value
 *  (e.g. "s1 m", "10px l1 20px l2", etc.).
 * Returns a CSS-style padding.
 */
export const parsePadding = (padding: number | string | undefined, theme: ITheme): number | string | undefined => {
  if (padding === undefined || typeof padding === 'number' || padding === '') {
    return padding;
  }

  const paddingValues = padding.split(' ');
  if (paddingValues.length < 2) {
    return getThemedSpacing(padding, theme);
  }

  return paddingValues.reduce((padding1: string, padding2: string) => {
    return getThemedSpacing(padding1, theme) + ' ' + getThemedSpacing(padding2, theme);
  });
};

export interface StackShimStyles {
  root?: IStyle;
  inner?: IStyle;
}
/**
 *
 * getStyles function for Stack.tokens.childrenGap prop styling
 */
export const getChildrenGapStyles = (props: IStackProps): StackShimStyles => {
  const theme = getTheme();

  const { horizontal, reversed } = props;
  const tokens: IStackTokens = { ...props.tokens };

  const { rowGap, columnGap } = parseGap(tokens.childrenGap, theme);
  const horizontalMargin = `${-0.5 * columnGap.value}${columnGap.unit}`;
  const verticalMargin = `${-0.5 * rowGap.value}${rowGap.unit}`;

  return {
    root: [
      reversed &&
        horizontal && {
          '> *:not(:last-child)': {
            marginLeft: `${columnGap.value}${columnGap.unit}`,
          },
        },
      reversed &&
        !horizontal && {
          '> *:not(:last-child)': {
            marginTop: `${rowGap.value}${rowGap.unit}`,
          },
        },
      !reversed &&
        horizontal && {
          '> *:not(:first-child)': {
            marginLeft: `${columnGap.value}${columnGap.unit}`,
          },
        },
      !reversed &&
        !horizontal && {
          '> *:not(:first-child)': {
            marginTop: `${rowGap.value}${rowGap.unit}`,
          },
        },
    ],
    inner: [
      {
        marginLeft: horizontalMargin,
        marginRight: horizontalMargin,
        marginTop: verticalMargin,
        marginBottom: verticalMargin,
        width: columnGap.value === 0 ? '100%' : `calc(100% + ${columnGap.value}${columnGap.unit})`,
        '> *': {
          margin: `${0.5 * rowGap.value}${rowGap.unit} ${0.5 * columnGap.value}${columnGap.unit}`,
        },
      },
      horizontal && {
        height: rowGap.value === 0 ? '100%' : `calc(100% + ${rowGap.value}${rowGap.unit})`,
        '> *': {
          maxWidth: columnGap.value === 0 ? '100%' : `calc(100% - ${columnGap.value}${columnGap.unit})`,
        },
      },
      !horizontal && {
        height: `calc(100% + ${rowGap.value}${rowGap.unit})`,
        '> *': {
          maxHeight: rowGap.value === 0 ? '100%' : `calc(100% - ${rowGap.value}${rowGap.unit})`,
        },
      },
    ],
  };
};

