   *
   * A motion definition can contain multiple animations and therefore multiple "cancel" events. The callback is
   * triggered once all animations have been cancelled with "null" instead of an event object to avoid ambiguity.
   */
  // eslint-disable-next-line @nx/workspace-consistent-callback-type -- EventHandler<T> does not support "null"
  onMotionCancel?: (ev: null) => void;

  /**
   * Callback that is called when the whole motion starts.
   *
   * A motion definition can contain multiple animations and therefore multiple "start" events. The callback is
   * triggered when the first animation is started. There is no official "start" event with the Web Animations API.
   * so the callback is triggered with "null".
   */
  // eslint-disable-next-line @nx/workspace-consistent-callback-type -- EventHandler<T> does not support "null"
  onMotionStart?: (ev: null) => void;

  /**
   * When this value changes, the animation replays from the start on the same DOM element,
   * cancelling any in-progress animation, without remounting the component or its children.
   *
   * **Why not just use a React `key`?** Changing a React `key` forces a full unmount and
   * remount of the subtree: DOM nodes are destroyed and recreated, focus is lost, and any
   * child state is reset. `replayKey` avoids all of that — only the animation effect reruns
   * while the DOM and component state remain intact.
   *
   * Use this when you want to retrigger a motion in response to a state change (e.g. a user
   * action or a data update) while preserving DOM continuity. It is the declarative equivalent
   * of calling `imperativeRef.current.play()` but driven by a prop rather than a ref call.
   *
   * @example
   * ```tsx
   * // Replay a Fade.In each time the user clicks "Refresh"
   * const [replayKey, setReplayKey] = React.useState(0);
   * <Fade.In replayKey={replayKey}>
   *   <div>Content</div>
   * </Fade.In>
   * <button onClick={() => setReplayKey(k => k + 1)}>Refresh</button>
   * ```
   */
  replayKey?: string | number;
};

export type MotionComponent<MotionParams extends Record<string, MotionParam> = {}> = React.FC<
  MotionComponentProps & MotionParams
> & {
  [MOTION_DEFINITION]: AtomMotionFn<MotionParams>;
};

/**
 * Creates a component that will animate the children using the provided motion.
 *
 * @param value - A motion definition.
 */
export function createMotionComponent<MotionParams extends Record<string, MotionParam> = {}>(
  value: AtomMotion | AtomMotion[] | AtomMotionFn<MotionParams>,
): MotionComponent<MotionParams> {
  const Atom: React.FC<MotionComponentProps & MotionParams> = props => {
    const {
      children,
      imperativeRef,
      onMotionFinish: onMotionFinishProp,
      onMotionStart: onMotionStartProp,
      onMotionCancel: onMotionCancelProp,
      replayKey,
      ..._rest
    } = props;
    const params = _rest as Exclude<typeof props, MotionComponentProps>;
    const [child, childRef] = useChildElement(children);

    const handleRef = useMotionImperativeRef(imperativeRef);
    const isInitialRender = React.useRef(true);
    const skipMotions = useMotionBehaviourContext() === 'skip';
    const optionsRef = React.useRef<{ skipMotions: boolean; params: MotionParams }>({
      skipMotions,
      params,
    });

    const animateAtoms = useAnimateAtoms();
    const isReducedMotion = useIsReducedMotion();

    const onMotionStart = useEventCallback(() => {
      onMotionStartProp?.(null);
    });

    const onMotionFinish = useEventCallback(() => {
      onMotionFinishProp?.(null);
    });

    const onMotionCancel = useEventCallback(() => {
      onMotionCancelProp?.(null);
    });

    // Stable callback (all deps are refs or useEventCallback) that activates a handle for a new playback cycle.
    //
    // TODO: consider moving the cancel+play+rewire sequence into a handle.replay() method on AnimationHandle,
    // keeping pure animation sequencing on the handle and React callbacks here in the component.
    const activateAnimationHandle = React.useCallback(
      (handle: AnimationHandle) => {
        onMotionStart();
        handle.setMotionEndCallbacks(onMotionFinish, onMotionCancel);
        if (optionsRef.current.skipMotions) {
          handle.finish();
        }
      },
      [onMotionStart, onMotionFinish, onMotionCancel],
    );

    useIsomorphicLayoutEffect(() => {
      // Heads up!
      // We store the params in a ref to avoid re-rendering the component when the params change.
      optionsRef.current = { skipMotions, params };
    });

    useIsomorphicLayoutEffect(() => {
      const element = childRef.current;

      if (element) {
        const atoms = typeof value === 'function' ? value({ element, ...optionsRef.current.params }) : value;

        const handle = animateAtoms(element, atoms, { isReducedMotion: isReducedMotion() });
        handleRef.current = handle;
        activateAnimationHandle(handle);

        return () => {
          handle.cancel();
        };
      }
    }, [animateAtoms, childRef, handleRef, isReducedMotion, activateAnimationHandle]);

    // Skips initial mount; on replayKey changes, reuses existing Animation objects via cancel+play
    // rather than recreating them, preserving DOM continuity.
    useIsomorphicLayoutEffect(() => {
      if (isInitialRender.current) {
        return;
      }

      const handle = handleRef.current;
      if (handle) {
        handle.cancel();
        handle.play();
        activateAnimationHandle(handle);
      }
      // eslint-disable-next-line react-hooks/exhaustive-deps -- replayKey is intentionally the only trigger; other deps are stable refs/callbacks
    }, [replayKey]);

    useIsomorphicLayoutEffect(() => {
      isInitialRender.current = false;

      return () => {
        isInitialRender.current = true;
      };
    }, []);

    return child;
  };

  return Object.assign(Atom, {
    // Heads up!
    // Always normalize it to a function to simplify types
    [MOTION_DEFINITION]: typeof value === 'function' ? value : () => value,
  });
}

import type { MotionParam, AtomMotionFn } from '../types';
import type { MotionComponent } from './createMotionComponent';
import { MOTION_DEFINITION, createMotionComponent } from './createMotionComponent';

/**
 * Create a variant function that wraps a motion function to customize it.
 * The new motion function has the supplied variant params as defaults,
 * but these can still be overridden by runtime params when the new function is called.
 *
 * @internal
 */
export function createMotionFnVariant<MotionParams extends Record<string, MotionParam> = {}>(
  motionFn: AtomMotionFn<MotionParams>,
  variantParams: Partial<MotionParams>,
): typeof motionFn {
  const variantFn: typeof motionFn = runtimeParams => motionFn({ ...variantParams, ...runtimeParams });
  return variantFn;
}

/**
 * Create a new motion component based on another motion component,
 * using the provided variant parameters as defaults.
 *
 * @param component - A component created by `createMotionComponent`.
 * @param variantParams - An object containing the variant parameters to be used as defaults.
 * The variant parameters should match the type of the component's motion parameters.
 * @returns A new motion component that uses the provided variant parameters as defaults.
 * The new component can still accept runtime parameters that override the defaults.
 */
export function createMotionComponentVariant<MotionParams extends Record<string, MotionParam> = {}>(
  component: MotionComponent<MotionParams>,
  variantParams: Partial<MotionParams>,
): MotionComponent<MotionParams> {
  const originalFn = component[MOTION_DEFINITION];
  // The variant params become new defaults, but they can still be overridden by runtime params.
  const variantFn = createMotionFnVariant(originalFn, variantParams);
  return createMotionComponent(variantFn);
}

import * as React from 'react';
import { mount } from '@fluentui/scripts-cypress';
import { createPresenceComponent } from './createPresenceComponent';
import { MotionBehaviourProvider } from '../contexts/MotionBehaviourContext';

describe('createPresenceComponent', () => {
  const noop = () => {
    return;
  };
  // Ensure reduced-motion is disabled for deterministic animation behavior
  beforeEach(() => {
    cy.window().then(win => {
      const orig = win.matchMedia;
      // Redefine matchMedia so that prefers-reduced-motion never matches
      Object.defineProperty(win, 'matchMedia', {
        configurable: true,
        value: (query: string) => {
          if (query.includes('prefers-reduced-motion')) {
            return {
              matches: false,
              media: query,
              onchange: null,
              addListener: noop, // deprecated API still sometimes read
              removeListener: noop,
              addEventListener: noop,
              removeEventListener: noop,
              dispatchEvent: () => false,
            };
          }
          return orig.call(win, query);
        },
      });
    });
  });

  it('should call onMotionCancel', () => {
    const TestMotion = createPresenceComponent({
      enter: { keyframes: [{ opacity: 0 }, { opacity: 1 }], duration: 4000 },
      exit: { keyframes: [{ opacity: 1 }, { opacity: 0 }], duration: 4000 },
    });

    const TestComponent = () => {
      const [visible, setVisible] = React.useState(true);
      const [cancel, setCancel] = React.useState(0);

      return (
        <>
          <button id="toggle" onClick={() => setVisible(!visible)}>
            Toggle
          </button>
          <TestMotion
            visible={visible}
            onMotionCancel={(ev, data) => {
              setCancel(s => s + 1);
            }}
          >
            <div />
          </TestMotion>

          <div id="cancel">{cancel}</div>
        </>
      );
    };

    mount(<TestComponent />);

    // First toggle: start exit motion
    cy.get('#toggle').click();

    // Give React effect a couple of frames to start the animation rather than an arbitrary ms wait
    cy.window().then(
      win =>
        new Cypress.Promise<void>(resolve => {
          requestAnimationFrame(() => {
            win.requestAnimationFrame(() => resolve());
          });
        }),
    );

    // Second toggle: should cancel the in-flight exit animation and trigger onMotionCancel
    cy.get('#toggle').click();

    cy.get('#cancel').should('have.text', '1');
  });

  it('should disable motion with motion disable provider', () => {
    const TestMotion = createPresenceComponent({
      enter: { keyframes: [{ opacity: 0 }, { opacity: 0, offset: 0.9 }], duration: 60000 },
      exit: { keyframes: [{ opacity: 1 }, { opacity: 0 }], duration: 60000 },
    });

    const TestComponent = () => {
      const [visible, setVisible] = React.useState(true);

      return (
        <>
          <button id="toggle" onClick={() => setVisible(!visible)}>
            Toggle
          </button>
          <MotionBehaviourProvider value="skip">
            <TestMotion appear visible={visible}>
              <div>Hello World</div>
            </TestMotion>
          </MotionBehaviourProvider>
        </>
      );
    };

    mount(<TestComponent />);
    cy.contains('Hello World', { timeout: 100 }).should('be.visible');
  });
});

'use client';

import { useEventCallback, useFirstMount, useIsomorphicLayoutEffect } from '@fluentui/react-utilities';
import type { JSXElement } from '@fluentui/react-utilities';
import * as React from 'react';

import { PresenceGroupChildContext } from '../contexts/PresenceGroupChildContext';
import { useAnimateAtoms } from '../hooks/useAnimateAtoms';
import { useMotionImperativeRef } from '../hooks/useMotionImperativeRef';
import { useMountedState } from '../hooks/useMountedState';
import { useIsReducedMotion } from '../hooks/useIsReducedMotion';
import { useChildElement } from '../utils/useChildElement';
import type {
  MotionParam,
  PresenceMotion,
  MotionImperativeRef,
  PresenceMotionFn,
  PresenceDirection,
  AnimationHandle,
} from '../types';
import { useMotionBehaviourContext } from '../contexts/MotionBehaviourContext';
import type { MotionComponent } from './createMotionComponent';
import { createMotionComponent } from './createMotionComponent';

/**
 * A private symbol to store the motion definition on the component for variants.
 *
 * @internal
 */
export const PRESENCE_MOTION_DEFINITION = Symbol('PRESENCE_MOTION_DEFINITION');

export type PresenceComponentProps = {
  /**
   * By default, the child component won't execute the "enter" motion when it initially mounts, regardless of the value
   * of "visible". If you desire this behavior, ensure both "appear" and "visible" are set to "true".
   */
  appear?: boolean;

  /** A React element that will be cloned and will have motion effects applied to it. */
  children: JSXElement;

  /** Provides imperative controls for the animation. */
  imperativeRef?: React.Ref<MotionImperativeRef | undefined>;

  /**
   * Callback that is called when the whole motion finishes.
   *
   * A motion definition can contain multiple animations and therefore multiple "finish" events. The callback is
   * triggered once all animations have finished with "null" instead of an event object to avoid ambiguity.
   */
  // eslint-disable-next-line @nx/workspace-consistent-callback-type -- EventHandler<T> does not support "null"
  onMotionFinish?: (ev: null, data: { direction: PresenceDirection }) => void;

  /**
   * Callback that is called when the whole motion is cancelled. When a motion is cancelled it does not
   * emit a finish event but a specific cancel event
   *
   * A motion definition can contain multiple animations and therefore multiple "finish" events. The callback is
   * triggered once all animations have finished with "null" instead of an event object to avoid ambiguity.
   */
  // eslint-disable-next-line @nx/workspace-consistent-callback-type -- EventHandler<T> does not support "null"
  onMotionCancel?: (ev: null, data: { direction: PresenceDirection }) => void;

  /**
   * Callback that is called when the whole motion starts.
   *
   * A motion definition can contain multiple animations and therefore multiple "start" events. The callback is
   * triggered when the first animation is started. There is no official "start" event with the Web Animations API.
   * so the callback is triggered with "null".
   */
  // eslint-disable-next-line @nx/workspace-consistent-callback-type -- EventHandler<T> does not support "null"
  onMotionStart?: (ev: null, data: { direction: PresenceDirection }) => void;

  /** Defines whether a component is visible; triggers the "enter" or "exit" motions. */
  visible?: boolean;

  /**
   * By default, the child component remains mounted after it reaches the "finished" state. Set "unmountOnExit" if
   * you prefer to unmount the component after it finishes exiting.
   */
  unmountOnExit?: boolean;
};

export type PresenceComponent<MotionParams extends Record<string, MotionParam> = {}> = React.FC<
  PresenceComponentProps & MotionParams
> & {
  (props: PresenceComponentProps & MotionParams): JSXElement | null;
  [PRESENCE_MOTION_DEFINITION]: PresenceMotionFn<MotionParams>;
  In: MotionComponent<MotionParams>;
  Out: MotionComponent<MotionParams>;
};

const INTERRUPTABLE_MOTION_SYMBOL = Symbol.for('interruptablePresence');

export function createPresenceComponent<MotionParams extends Record<string, MotionParam> = {}>(
  value: PresenceMotion | PresenceMotionFn<MotionParams>,
): PresenceComponent<MotionParams> {
  return Object.assign(
    (props: PresenceComponentProps & MotionParams) => {
      const itemContext = React.useContext(PresenceGroupChildContext);
      const merged = { ...itemContext, ...props };
      const skipMotions = useMotionBehaviourContext() === 'skip';

      const {
        appear,
        children,
        imperativeRef,
        onExit,
        onMotionFinish,
        onMotionStart,
        onMotionCancel,
        visible,
        unmountOnExit,
        ..._rest
      } = merged;
      const params = _rest as Exclude<typeof merged, PresenceComponentProps | typeof itemContext>;

      const [mounted, setMounted] = useMountedState(visible, unmountOnExit);
      const [child, childRef] = useChildElement(children, mounted);

      const handleRef = useMotionImperativeRef(imperativeRef);
      const optionsRef = React.useRef<{ appear?: boolean; params: MotionParams; skipMotions: boolean }>({
        appear,
        params,
        skipMotions,
      });

      const animateAtoms = useAnimateAtoms();
      const isFirstMount = useFirstMount();
      const isReducedMotion = useIsReducedMotion();

      const handleMotionStart = useEventCallback((direction: PresenceDirection) => {
        onMotionStart?.(null, { direction });
      });
      const handleMotionFinish = useEventCallback((direction: PresenceDirection) => {
        onMotionFinish?.(null, { direction });

        if (direction === 'exit' && unmountOnExit) {
          setMounted(false);
          onExit?.();
        }
      });

      const handleMotionCancel = useEventCallback((direction: PresenceDirection) => {
        onMotionCancel?.(null, { direction });
      });

      useIsomorphicLayoutEffect(() => {
        // Heads up!
        // We store the params in a ref to avoid re-rendering the component when the params change.
        optionsRef.current = { appear, params, skipMotions };
      });

      useIsomorphicLayoutEffect(
        () => {
          const element = childRef.current;

          if (!element) {
            return;
          }

          let handle: AnimationHandle | undefined;

          function cleanup() {
            if (!handle) {
              return;
            }

            // Heads up!
            //
            // If the animation is interruptible & is running, we don't want to cancel it as it will be reversed in
            // the next effect.
            if (IS_EXPERIMENTAL_INTERRUPTIBLE_MOTION && handle.isRunning()) {
              return;
            }

            handle.cancel();
            handleRef.current = undefined;
          }

          const presenceMotion =
            typeof value === 'function' ? value({ element, ...optionsRef.current.params }) : (value as PresenceMotion);
          const IS_EXPERIMENTAL_INTERRUPTIBLE_MOTION = (
            presenceMotion as PresenceMotion & { [INTERRUPTABLE_MOTION_SYMBOL]?: boolean }
          )[INTERRUPTABLE_MOTION_SYMBOL];

          if (IS_EXPERIMENTAL_INTERRUPTIBLE_MOTION) {
            handle = handleRef.current;

            if (handle && handle.isRunning()) {
              handle.reverse();

              return cleanup;
            }
          }

          const atoms = visible ? presenceMotion.enter : presenceMotion.exit;
          const direction: PresenceDirection = visible ? 'enter' : 'exit';

          // Heads up!
          // Initial styles are applied when the component is mounted for the first time and "appear" is set to "false" (otherwise animations are triggered)
          const applyInitialStyles = !optionsRef.current.appear && isFirstMount;
          const skipAnimationByConfig = optionsRef.current.skipMotions;

          if (!applyInitialStyles) {
            handleMotionStart(direction);
          }

          handle = animateAtoms(element, atoms, { isReducedMotion: isReducedMotion() });

          if (applyInitialStyles) {
            // Heads up!
            // .finish() is used in this case to skip animation and apply animation styles immediately
            handle.finish();

            return cleanup;
          }

          handleRef.current = handle;
          handle.setMotionEndCallbacks(
            () => handleMotionFinish(direction),
            () => handleMotionCancel(direction),
          );

          if (skipAnimationByConfig) {
            handle.finish();
          }

          return cleanup;
        },
        // Excluding `isFirstMount` from deps to prevent re-triggering the animation on subsequent renders
        // eslint-disable-next-line react-hooks/exhaustive-deps
        [
          animateAtoms,
          childRef,
          handleRef,
          isReducedMotion,
          handleMotionFinish,
          handleMotionStart,
          handleMotionCancel,
          visible,
        ],
      );

      React.useEffect(() => {
        // Heads up!
        //
        // Dispose the handle when unmounting the component to clean up retained references. Doing it in a separate
        // effect to ensure that the component is unmounted.

        if (unmountOnExit && !mounted) {
          handleRef.current?.dispose();
        }
      }, [handleRef, unmountOnExit, mounted]);

      if (mounted) {
        return child;
      }

      return null;
    },
    {
      // Heads up!
      // Always normalize it to a function to simplify types
      [PRESENCE_MOTION_DEFINITION]: typeof value === 'function' ? value : () => value,
    },
    {
      // Wrap `enter` in its own motion component as a static method, e.g. <Fade.In>
      In: createMotionComponent(
        // If we have a motion function, wrap it to forward the runtime params and pick `enter`.
        // Otherwise, pass the `enter` motion object directly.
        typeof value === 'function' ? (...args: Parameters<typeof value>) => value(...args).enter : value.enter,
      ),

      // Wrap `exit` in its own motion component as a static method, e.g. <Fade.Out>
      Out: createMotionComponent(
        // If we have a motion function, wrap it to forward the runtime params and pick `exit`.
        // Otherwise, pass the `exit` motion object directly.
        typeof value === 'function' ? (...args: Parameters<typeof value>) => value(...args).exit : value.exit,
      ),
    },
  );
}

import type { MotionParam, PresenceMotionFn } from '../types';
import type { PresenceComponent } from './createPresenceComponent';
import { PRESENCE_MOTION_DEFINITION, createPresenceComponent } from './createPresenceComponent';

/**
 * Create a variant function that wraps a presence function to customize it.
 * The new presence function has the supplied variant params as defaults,
 * but these can still be overridden by runtime params when the new function is called.
 *
 * @internal
 */
export function createPresenceFnVariant<MotionParams extends Record<string, MotionParam> = {}>(
  presenceFn: PresenceMotionFn<MotionParams>,
  variantParams: Partial<MotionParams>,
): typeof presenceFn {
  const variantFn: typeof presenceFn = runtimeParams => presenceFn({ ...variantParams, ...runtimeParams });
  return variantFn;
}

/**
 * Create a new presence component based on another presence component,
 * using the provided variant parameters as defaults.
 *
 * @param component - A component created by `createPresenceComponent`.
 * @param variantParams - An object containing the variant parameters to be used as defaults.
 * The variant parameters should match the type of the component's motion parameters.
 * @returns A new presence component that uses the provided variant parameters as defaults.
 * The new component can still accept runtime parameters that override the defaults.
 */
export function createPresenceComponentVariant<MotionParams extends Record<string, MotionParam> = {}>(
  component: PresenceComponent<MotionParams>,
  variantParams: Partial<MotionParams>,
): PresenceComponent<MotionParams> {
  const originalFn = component[PRESENCE_MOTION_DEFINITION];
  // The variant params become new defaults, but they can still be overridden by runtime params.
  const variantFn = createPresenceFnVariant(originalFn, variantParams);
  return createPresenceComponent(variantFn);
}

'use client';

import * as React from 'react';

import { isAnimationRunning } from '../utils/isAnimationRunning';
import type { AnimationHandle, AtomMotion } from '../types';

export const DEFAULT_ANIMATION_OPTIONS: KeyframeEffectOptions = {
  fill: 'forwards',
};

// A motion atom's default reduced motion is a simple 1 ms duration.
// But an atom can define a custom reduced motion, overriding keyframes and/or params like duration, easing, iterations, etc.
const DEFAULT_REDUCED_MOTION_ATOM: NonNullable<AtomMotion['reducedMotion']> = {
  duration: 1,
};

/**
 * Creates an animation handle that controls multiple animations.
 * Is used to avoid leaking "element" references from the hook.
 *
 * @param animations
 */
function createHandle(animations: Animation[]): AnimationHandle {
  return {
    set playbackRate(rate: number) {
      animations.forEach(animation => {
        animation.playbackRate = rate;
      });
    },
    setMotionEndCallbacks(onfinish: () => void, oncancel: () => void) {
      // Heads up!
      // This could use "Animation:finished", but it's causing a memory leak in Chromium.
      // See: https://issues.chromium.org/u/2/issues/383016426
      const promises = animations.map(animation => {
        return new Promise<void>((resolve, reject) => {
          animation.onfinish = () => resolve();
          animation.oncancel = () => reject();
        });
      });

      Promise.all(promises)
        .then(() => {
          onfinish();
        })
        .catch(() => {
          oncancel();
        });
    },
    isRunning() {
      return animations.some(animation => isAnimationRunning(animation));
    },

    dispose: () => {
      animations.length = 0;
    },

    cancel: () => {
      animations.forEach(animation => {
        animation.cancel();
      });
    },
    pause: () => {
      animations.forEach(animation => {
        animation.pause();
      });
    },
    play: () => {
      animations.forEach(animation => {
        animation.play();
      });
    },
    finish: () => {
      animations.forEach(animation => {
        animation.finish();
      });
    },
    reverse: () => {
      // Heads up!
      //
      // This is used for the interruptible motion. If the animation is running, we need to reverse it.
      //
      // TODO: what do with animations that have "delay"?
      // TODO: what do with animations that have different "durations"?

      animations.forEach(animation => {
        animation.reverse();
      });
    },
  };
}

function useAnimateAtomsInSupportedEnvironment() {
  // eslint-disable-next-line @nx/workspace-no-restricted-globals
  const SUPPORTS_PERSIST = typeof window !== 'undefined' && typeof window.Animation?.prototype.persist === 'function';

  return React.useCallback(
    (
      element: HTMLElement,
      value: AtomMotion | AtomMotion[],
      options: {
        isReducedMotion: boolean;
      },
    ): AnimationHandle => {
      const atoms = Array.isArray(value) ? value : [value];
      const { isReducedMotion } = options;

      const animations = atoms
        .map(motion => {
          // Grab the custom reduced motion definition if it exists, or fall back to the default reduced motion.
          const { keyframes: motionKeyframes, reducedMotion = DEFAULT_REDUCED_MOTION_ATOM, ...params } = motion;
          // Grab the reduced motion keyframes if they exist, or fall back to the regular keyframes.
          const { keyframes: reducedMotionKeyframes = motionKeyframes, ...reducedMotionParams } = reducedMotion;

          const animationKeyframes: Keyframe[] = isReducedMotion ? reducedMotionKeyframes : motionKeyframes;
          const animationParams: KeyframeEffectOptions = {
            ...DEFAULT_ANIMATION_OPTIONS,
            ...params,

            // Use reduced motion overrides (e.g. duration, easing) when reduced motion is enabled
            ...(isReducedMotion && reducedMotionParams),
          };

          try {
            // Firefox can throw an error when calling `element.animate()`.
            // See: https://github.com/microsoft/fluentui/issues/33902
            const animation = element.animate(animationKeyframes, animationParams);

            if (SUPPORTS_PERSIST) {
              // Chromium browsers can return null when calling `element.animate()`.
              // See: https://github.com/microsoft/fluentui/issues/33902
              animation?.persist();
            } else {
              const resultKeyframe = animationKeyframes[animationKeyframes.length - 1];
              Object.assign(element.style ?? {}, resultKeyframe);
            }

            return animation;
          } catch (e) {
            return null;
          }
        })
        .filter(animation => !!animation) as Animation[];

      return createHandle(animations);
    },
    [SUPPORTS_PERSIST],
  );
}

/**
 * In test environments, this hook is used to delay the execution of a callback until the next render. This is necessary
 * to ensure that the callback is not executed synchronously, which would cause the test to fail.
 *
 * @see https://github.com/microsoft/fluentui/issues/31701
 */
function useAnimateAtomsInTestEnvironment() {
  const [count, setCount] = React.useState(0);
  const callbackRef = React.useRef<() => void>(undefined);

  const realAnimateAtoms = useAnimateAtomsInSupportedEnvironment();

  React.useEffect(() => {
    if (count > 0) {
      callbackRef.current?.();
    }
  }, [count]);

  return React.useCallback(
    (
      element: HTMLElement,
      value: AtomMotion | AtomMotion[],
      options: {
        isReducedMotion: boolean;
      },
    ): AnimationHandle => {
      const ELEMENT_SUPPORTS_WEB_ANIMATIONS = typeof element.animate === 'function';

      // Heads up!
      // If the environment supports Web Animations API, we can use the native implementation.
      if (ELEMENT_SUPPORTS_WEB_ANIMATIONS) {
        return realAnimateAtoms(element, value, options);
      }

      return {
        setMotionEndCallbacks(onfinish: () => void) {
          callbackRef.current = onfinish;
          setCount(v => v + 1);
        },

        set playbackRate(rate: number) {
          /* no-op */
        },
        isRunning() {
          return false;
        },

        dispose() {
          /* no-op */
        },

        cancel() {
          /* no-op */
        },
        pause() {
          /* no-op */
        },
        play() {
          /* no-op */
        },
        finish() {
          /* no-op */
        },
        reverse() {
          /* no-op */
        },
      };
    },
    [realAnimateAtoms],
  );
}

/**
 * @internal
 */
export function useAnimateAtoms(): (
  element: HTMLElement,
  value: AtomMotion | AtomMotion[],
  options: { isReducedMotion: boolean },
) => AnimationHandle {
  if (process.env.NODE_ENV === 'test') {
    // eslint-disable-next-line react-hooks/rules-of-hooks
    return useAnimateAtomsInTestEnvironment();
  }

  // eslint-disable-next-line react-hooks/rules-of-hooks
  return useAnimateAtomsInSupportedEnvironment();
}

