export type PopoverSlots = {
  /**
   * Slot for the surface motion animation.
   * For more information refer to the [Motion docs page](https://react.fluentui.dev/?path=/docs/motion-motion-slot--docs).
   */
  surfaceMotion: Slot<PresenceMotionSlotProps>;
};

export type InternalPopoverSlots = {
  surfaceMotion: NonNullable<Slot<PresenceMotionSlotProps>>;
};

/**
 * Determines popover padding and arrow size
 */
export type PopoverSize = 'small' | 'medium' | 'large';

/**
 * Popover Props
 */
export type PopoverProps = ComponentProps<Partial<PopoverSlots>> &
  Pick<PortalProps, 'mountNode'> & {
    /**
     * A popover can appear styled with brand or inverted.
     * When not specified, the default style is used.
     */
    appearance?: 'brand' | 'inverted';

    /**
     * Can contain two children including `PopoverTrigger` and `PopoverSurface`.
     * Alternatively can only contain `PopoverSurface` if using a custom `target`.
     */
    children: [JSXElement, JSXElement] | JSXElement;

    /**
     * Close when scroll outside of it
     *
     * @default false
     */
    closeOnScroll?: boolean;

    /**
     * Used to set the initial open state of the Popover in uncontrolled mode
     *
     * @default false
     */
    defaultOpen?: boolean;

    /**
     * Popovers are rendered out of DOM order on `document.body` by default, use this to render the popover in DOM order
     *
     * @default false
     */
    inline?: boolean;

    /**
     * Sets the delay for closing popover on mouse leave
     */
    mouseLeaveDelay?: number;

    /**
     * Display an arrow pointing to the target.
     *
     * @default false
     */
    withArrow?: boolean;

    /**
     * Call back when the component requests to change value
     * The `open` value is used as a hint when directly controlling the component
     */
    // eslint-disable-next-line @nx/workspace-consistent-callback-type -- can't change type of existing callback
    onOpenChange?: (e: OpenPopoverEvents, data: OnOpenChangeData) => void;

    /**
     * Controls the opening of the Popover
     *
     * @default false
     */
    open?: boolean;

    /**
     * Flag to open the Popover as a context menu. Disables all other interactions
     *
     * @default false
     */
    openOnContext?: boolean;

    /**
     * Flag to open the Popover by hovering the trigger
     *
     * @default false
     */
    openOnHover?: boolean;

    /**
     * Flag to close the Popover when an iframe outside a PopoverSurface is focused
     *
     * @default true
     */
    closeOnIframeFocus?: boolean;

    /**
     * Configures the position of the Popover.
     * Explore [Positioning docs](https://react.fluentui.dev/?path=/docs/concepts-developer-positioning-components--docs) for more options.
     */
    positioning?: PositioningShorthand;

    /**
     * Determines popover padding and arrow size
     *
     * @default medium
     */
    size?: PopoverSize;

    /**
     * Should trap focus
     *
     * @default false
     */
    trapFocus?: boolean;

    /**
     * Must be used with the `trapFocus` prop
     * Enables older Fluent UI focus trap behavior where the user
     * cannot tab into the window outside of the document. This is now
     * non-standard behavior according to the [HTML dialog spec](https://developer.mozilla.org/en-US/docs/Web/API/HTMLDialogElement/showModal)
     * where the focus trap involves setting outside elements inert.
     *
     * @deprecated this behavior is default provided now, to opt-out of it in favor of standard behavior use the `inertTrapFocus` property
     */
    legacyTrapFocus?: boolean;
    /**
     * Enables standard behavior according to the [HTML dialog spec](https://developer.mozilla.org/en-US/docs/Web/API/HTMLDialogElement/showModal)
     * where the focus trap involves setting outside elements inert,
     * making navigation leak from the trapped area back to the browser toolbar and vice-versa.
     *
     * @default false
     */
    inertTrapFocus?: boolean;

    /**
     * By default Popover focuses the first focusable element in PopoverSurface on open.
     * Specify `disableAutoFocus` to prevent this behavior.
     *
     * @default false
     */
    // eslint-disable-next-line @typescript-eslint/naming-convention
    unstable_disableAutoFocus?: boolean;
  };

/**
 * Popover State
 */
export type PopoverState = ComponentState<InternalPopoverSlots> &
  Pick<
    PopoverProps,
    | 'appearance'
    | 'mountNode'
    | 'onOpenChange'
    | 'openOnContext'
    | 'openOnHover'
    | 'trapFocus'
    | 'withArrow'
    | 'inertTrapFocus'
  > &
  Required<Pick<PopoverProps, 'inline' | 'open'>> &
  Pick<PopoverProps, 'children'> & {
    /**
     * Ref of the pointing arrow
     */
    // eslint-disable-next-line @typescript-eslint/no-deprecated
    arrowRef: React.MutableRefObject<HTMLDivElement | null>;

    /**
     * Ref of the PopoverSurface
     */
    // eslint-disable-next-line @typescript-eslint/no-deprecated
    contentRef: React.MutableRefObject<HTMLElement | null>;

    /**
     * Anchors the popper to the mouse click for context events
     */
    contextTarget: PositioningVirtualElement | undefined;

    popoverSurface: React.ReactElement | undefined;

    popoverTrigger: React.ReactElement | undefined;

    /**
     * A callback to set the target of the popper to the mouse click for context events
     */
    setContextTarget: SetVirtualMouseTarget;

    /**
     * Callback to open/close the Popover
     */
    setOpen: (e: OpenPopoverEvents, open: boolean) => void;

    size: NonNullable<PopoverProps['size']>;

    /**
     * Callback to toggle the open state of the Popover
     */
    toggleOpen: (e: OpenPopoverEvents) => void;

    /**
     * Ref of the PopoverTrigger
     */
    // eslint-disable-next-line @typescript-eslint/no-deprecated
    triggerRef: React.MutableRefObject<HTMLElement | null>;
  };

/**
 * Data attached to open/close events
 */
export type OnOpenChangeData = { open: boolean };

/**
 * The supported events that will trigger open/close of the menu
 */
export type OpenPopoverEvents =
  | MouseEvent
  | TouchEvent
  | FocusEvent
  | React.FocusEvent<HTMLElement>
  | React.KeyboardEvent<HTMLElement>
  | React.MouseEvent<HTMLElement>;

import { createPresenceComponent, motionTokens } from '@fluentui/react-motion';
import { fadeAtom, slideAtom } from '@fluentui/react-motion-components-preview';
import {
  POSITIONING_SLIDE_DIRECTION_VAR_X as slideDirectionVarX,
  POSITIONING_SLIDE_DIRECTION_VAR_Y as slideDirectionVarY,
} from '@fluentui/react-positioning';

// Shared timing constants for the enter animation.
const duration = motionTokens.durationSlower;
const easing = motionTokens.curveDecelerateMid;

/**
 * Default `surfaceMotion` slot for `<Popover>`.
 *
 * Enter-only animation combining a fade and a direction-aware slide.
 * The slide reads CSS variables set by `usePositioningSlideDirection` and scales
 * them by `distance` pixels. There is no exit animation; the surface unmounts immediately.
 *
 * @param distance - Travel distance (px) for the enter slide. Defaults to `10`.
 */
export const PopoverSurfaceMotion = createPresenceComponent(({ distance = 10 }: { distance?: number }) => ({
  enter: [
    fadeAtom({ duration, easing, direction: 'enter' }),
    {
      // slideAtom produces translate keyframes from `outX`/`outY` → `0px`.
      // The `outX`/`outY` values read the positioning-provided CSS variables and scale
      // them by `distance` so the surface slides in from the correct direction.
      ...slideAtom({
        duration,
        easing,
        direction: 'enter',
        outX: `calc(var(${slideDirectionVarX}, 0px) * ${distance})`,
        outY: `calc(var(${slideDirectionVarY}, 0px) * ${distance})`,
      }),
      // 'accumulate' compositing adds this effect's transform on top of the element's
      // existing transform, preserving any transform applied by the positioning engine.
      composite: 'accumulate',
    },
  ],
  // No exit animation — the surface unmounts immediately on close.
  exit: [],
}));

export { Popover } from './Popover';
export type { OnOpenChangeData, OpenPopoverEvents, PopoverProps, PopoverSize, PopoverState } from './Popover.types';
export { renderPopover_unstable } from './renderPopover';
export { usePopover_unstable } from './usePopover';
export { usePopoverContextValues_unstable } from './usePopoverContextValues';
export type { PopoverContextValues } from './usePopoverContextValues';

/** @jsxRuntime automatic */
/** @jsxImportSource @fluentui/react-jsx-runtime */

import * as React from 'react';
import { assertSlots, type JSXElement } from '@fluentui/react-utilities';
import { MotionRefForwarder } from '@fluentui/react-motion';
import { PopoverContext, popoverContextDefaultValue } from '../../popoverContext';
import type { InternalPopoverSlots, PopoverState } from './Popover.types';
import type { PopoverContextValues } from './usePopoverContextValues';

/**
 * Render the final JSX of Popover
 */
export const renderPopover_unstable = (state: PopoverState, contextValues?: PopoverContextValues): JSXElement => {
  assertSlots<InternalPopoverSlots>(state);

  return (
    <PopoverContext.Provider value={contextValues?.popover ?? popoverContextDefaultValue}>
      {state.popoverTrigger}
      {state.popoverSurface && (
        <state.surfaceMotion>
          <MotionRefForwarder>
            {/* Casting here as content should be equivalent to <PopoverSurface /> */}
            {/* FIXME: content should not be ReactNode it should be ReactElement instead. */}
            {state.popoverSurface as React.ReactElement}
          </MotionRefForwarder>
        </state.surfaceMotion>
      )}
    </PopoverContext.Provider>
  );
};

'use client';

import * as React from 'react';
import {
  useControllableState,
  useEventCallback,
  useOnClickOutside,
  useOnScrollOutside,
  elementContains,
  useTimeout,
} from '@fluentui/react-utilities';
import { useFluent_unstable as useFluent } from '@fluentui/react-shared-contexts';
import {
  usePositioning,
  resolvePositioningShorthand,
  mergeArrowOffset,
  usePositioningMouseTarget,
  usePositioningSlideDirection,
} from '@fluentui/react-positioning';
import { useFocusFinders, useActivateModal } from '@fluentui/react-tabster';
import { arrowHeights } from '../PopoverSurface/index';
import type { OpenPopoverEvents, PopoverProps, PopoverState } from './Popover.types';
import { popoverSurfaceBorderRadius } from './constants';
import { presenceMotionSlot } from '@fluentui/react-motion';
import { PopoverSurfaceMotion } from './PopoverSurfaceMotion';

/**
 * Create the state required to render Popover.
 *
 * The returned state can be modified with hooks such as usePopoverStyles,
 * before being passed to renderPopover_unstable.
 *
 * @param props - props from this instance of Popover
 */
export const usePopover_unstable = (props: PopoverProps): PopoverState => {
  const [contextTarget, setContextTarget] = usePositioningMouseTarget();
  const { targetDocument } = useFluent();

  const positioning = resolvePositioningShorthand(props.positioning);
  const handlePositionEnd = usePositioningSlideDirection({
    targetDocument,
    onPositioningEnd: positioning.onPositioningEnd,
  });

  const initialState = {
    size: 'medium',
    contextTarget,
    setContextTarget,
    ...props,
    positioning: {
      ...positioning,
      onPositioningEnd: handlePositionEnd,
    },
  } as const;

  const children = React.Children.toArray(props.children) as React.ReactElement[];

  if (process.env.NODE_ENV !== 'production') {
    if (children.length === 0) {
      // eslint-disable-next-line no-console
      console.warn('Popover must contain at least one child');
    }

    if (children.length > 2) {
      // eslint-disable-next-line no-console
      console.warn('Popover must contain at most two children');
    }
  }

  let popoverTrigger: React.ReactElement | undefined = undefined;
  let popoverSurface: React.ReactElement | undefined = undefined;
  if (children.length === 2) {
    popoverTrigger = children[0];
    popoverSurface = children[1];
  } else if (children.length === 1) {
    popoverSurface = children[0];
  }

  const [open, setOpenState] = useOpenState(initialState);

  const [setOpenTimeout, clearOpenTimeout] = useTimeout();
  const setOpen = useEventCallback((e: OpenPopoverEvents, shouldOpen: boolean) => {
    clearOpenTimeout();
    if (!(e instanceof Event) && e.persist) {
      // < React 17 still uses pooled synthetic events
      e.persist();
    }

    if (e.type === 'mouseleave') {
      // FIXME leaking Node timeout type
      // eslint-disable-next-line @typescript-eslint/ban-ts-comment
      // @ts-ignore
      setOpenTimeout(() => {
        setOpenState(e, shouldOpen);
      }, props.mouseLeaveDelay ?? 500);
    } else {
      setOpenState(e, shouldOpen);
    }
  });

  const toggleOpen = React.useCallback<PopoverState['toggleOpen']>(
    (e: OpenPopoverEvents) => {
      setOpen(e, !open);
    },
    [setOpen, open],
  );

  const positioningRefs = usePopoverRefs(initialState);

  useOnClickOutside({
    contains: elementContains,
    element: targetDocument,
    callback: ev => setOpen(ev, false),
    refs: [positioningRefs.triggerRef, positioningRefs.contentRef],
    disabled: !open,
    disabledFocusOnIframe: !(props.closeOnIframeFocus ?? true),
  });

  // only close on scroll for context, or when closeOnScroll is specified
  const closeOnScroll = initialState.openOnContext || initialState.closeOnScroll;
  useOnScrollOutside({
    contains: elementContains,
    element: targetDocument,
    callback: ev => setOpen(ev, false),
    refs: [positioningRefs.triggerRef, positioningRefs.contentRef],
    disabled: !open || !closeOnScroll,
  });

  // When trapFocus is enabled, dismiss the popover only on a genuine inside -> outside focus
  // transition. Focus that was never inside - e.g. a consumer keeping focus on an external element
  // via `unstable_disableAutoFocus` - must not dismiss it on an outside -> outside focus change.
  // Internal `closeOnFocusOutside` prop allows consumers to opt out during gradual rollout.
  const closeOnFocusOutside = (props as PopoverProps & { closeOnFocusOutside?: boolean }).closeOnFocusOutside ?? true;

  const focusWasInsideRef = React.useRef(false);

  const closeOnFocusOutCallback = useEventCallback((ev: FocusEvent) => {
    const target = (ev.composedPath()[0] ?? ev.target) as HTMLElement | null;
    const contentElement = positioningRefs.contentRef.current;
    const triggerElement = positioningRefs.triggerRef.current ?? null;

    if (!contentElement) {
      return;
    }

    const isInside = elementContains(contentElement, target) || elementContains(triggerElement, target);

    if (isInside) {
      focusWasInsideRef.current = true;
      return;
    }

    // Only dismiss if focus previously lived inside the popover.
    if (focusWasInsideRef.current) {
      focusWasInsideRef.current = false;
      setOpen(ev, false);
    }
  });

  React.useEffect(() => {
    if (!open || !props.trapFocus || !closeOnFocusOutside) {
      return;
    }

    focusWasInsideRef.current = false;
    targetDocument?.addEventListener('focusin', closeOnFocusOutCallback, true);
    return () => {
      targetDocument?.removeEventListener('focusin', closeOnFocusOutCallback, true);
    };
  }, [open, props.trapFocus, closeOnFocusOutside, targetDocument, closeOnFocusOutCallback]);

  const { findFirstFocusable } = useFocusFinders();
  const activateModal = useActivateModal();

  React.useEffect(() => {
    if (props.unstable_disableAutoFocus) {
      return;
    }

    const contentElement = positioningRefs.contentRef.current;

    if (open && contentElement) {
      const shouldFocusContainer = !isNaN(contentElement.getAttribute('tabIndex') ?? undefined);
      const firstFocusable = shouldFocusContainer ? contentElement : findFirstFocusable(contentElement);

      firstFocusable?.focus();

      if (shouldFocusContainer) {
        // Modal activation happens automatically when something inside the modal is focused programmatically.
        // When the container is focused, we need to activate the modal manually.
        activateModal(contentElement);
      }
    }
  }, [findFirstFocusable, activateModal, open, positioningRefs.contentRef, props.unstable_disableAutoFocus]);

  return {
    components: {
      surfaceMotion: PopoverSurfaceMotion,
    },
    ...initialState,
    ...positioningRefs,
    // eslint-disable-next-line @typescript-eslint/no-deprecated
    inertTrapFocus: props.inertTrapFocus ?? (props.legacyTrapFocus === undefined ? false : !props.legacyTrapFocus),
    popoverTrigger,
    popoverSurface,
    open,
    setOpen,
    toggleOpen,
    setContextTarget,
    contextTarget,
    inline: props.inline ?? false,
    surfaceMotion: presenceMotionSlot(props.surfaceMotion, {
      elementType: PopoverSurfaceMotion,
      defaultProps: {
        visible: open,
        appear: true,
        unmountOnExit: true,
      },
    }),
  };
};

/**
 * Creates and manages the Popover open state
 */
function useOpenState(
  state: Pick<PopoverState, 'setContextTarget' | 'onOpenChange'> & Pick<PopoverProps, 'open' | 'defaultOpen'>,
) {
  const onOpenChange: PopoverState['onOpenChange'] = useEventCallback((e, data) => state.onOpenChange?.(e, data));

  const [open, setOpenState] = useControllableState({
    state: state.open,
    defaultState: state.defaultOpen,
    initialState: false,
  });
  // eslint-disable-next-line react-hooks/immutability
  state.open = open !== undefined ? open : state.open;
  const setContextTarget = state.setContextTarget;

  const setOpen = React.useCallback(
    (e: OpenPopoverEvents, shouldOpen: boolean) => {
      if (shouldOpen && e.type === 'contextmenu') {
        setContextTarget(e as React.MouseEvent);
      }

      if (!shouldOpen) {
        setContextTarget(undefined);
      }

      setOpenState(shouldOpen);
      onOpenChange?.(e, { open: shouldOpen });
    },
    [setOpenState, onOpenChange, setContextTarget],
  );

  return [open, setOpen] as const;
}

/**
 * Creates and sets the necessary trigger, target and content refs used by Popover
 */
function usePopoverRefs(
  state: Pick<PopoverState, 'size' | 'contextTarget'> &
    Pick<PopoverProps, 'positioning' | 'openOnContext' | 'withArrow'>,
