  if (state.withArrow) {
    positioningOptions.offset = mergeArrowOffset(positioningOptions.offset, arrowHeights[state.size]);
  }

  const { targetRef: triggerRef, containerRef: contentRef, arrowRef } = usePositioning(positioningOptions);

  return {
    triggerRef,
    contentRef,
    arrowRef,
  } as const;
}

