'use client';

import { mergeClasses } from '@griffel/react';
import { useId } from '@fluentui/react-utilities';
import type { JSXElement } from '@fluentui/react-utilities';
import * as React from 'react';
import { useSyncExternalStore } from 'use-sync-external-store/shim';

import type { createSafeZoneAreaStateStore } from './createSafeZoneAreaStateStore';
import { getRectCorners } from './getRectCorners';
import { getMouseAnchor } from './getMouseAnchor';
import { pointsToSvgPath } from './pointsToSvgPath';
import { useStyles } from './SafeZoneArea.styles';
import type { Point } from './types';
import { computeOutsideClipPath } from './computeOutsideClipPath';
import { getSafeZonePoints } from './getSafeZonePoints';

export type SafeZoneAreaImperativeHandle = {
  updateSVG: (options: { containerRect: DOMRect; targetRect: DOMRect; mouseCoordinates: Point }) => void;
};

export type SafeZoneAreaProps = {
  /** Enables debug mode: makes drawn shapes visible. */
  debug: boolean;

  /** A reference to the SafeZoneArea imperative handle. */
  imperativeRef: React.Ref<SafeZoneAreaImperativeHandle>;

  // eslint-disable-next-line @nx/workspace-consistent-callback-type
  onMouseEnter: (e: React.MouseEvent) => void;
  // eslint-disable-next-line @nx/workspace-consistent-callback-type
  onMouseMove: (e: React.MouseEvent) => void;
  // eslint-disable-next-line @nx/workspace-consistent-callback-type
  onMouseLeave: (e: React.MouseEvent) => void;

  stateStore: ReturnType<typeof createSafeZoneAreaStateStore>;
};

// ---

/**
 * A component that renders a safe zone area with SVG shapes. Uses `useSyncExternalStore` to manage its active state
 * to avoid causing re-renders in `useSafeZoneArea()` as the hook might be used in host components like `Menu`.
 *
 * Draws a polygon from the mouse to the facing edges of the container and clips out the target element.
 *
 * @internal
 */
export const SafeZoneArea = React.memo((props: SafeZoneAreaProps): JSXElement => {
  const { debug, onMouseEnter, onMouseMove, onMouseLeave, stateStore } = props;

  const clipPathId = useId();
  const styles = useStyles();

  const active = useSyncExternalStore(stateStore.subscribe, stateStore.isActive);
  const svgRef = React.useRef<SVGSVGElement>(null);
  const safeZoneRef = React.useRef<SVGPathElement>(null);
  const clipPathRef = React.useRef<SVGPathElement>(null);
  const rectDebugRef = React.useRef<SVGPathElement>(null);

  React.useImperativeHandle(
    props.imperativeRef,
    () => ({
      updateSVG({ containerRect, targetRect, mouseCoordinates }) {
        const topOffset = Math.min(targetRect.top, containerRect.top);
        const leftOffset = Math.min(targetRect.left, containerRect.left);
        const bottomOffset = Math.max(targetRect.bottom, containerRect.bottom);
        const rightOffset = Math.max(targetRect.right, containerRect.right);

        const containerCorners = getRectCorners(containerRect, [leftOffset, topOffset]);
        const targetCorners = getRectCorners(targetRect, [leftOffset, topOffset]);

        // SVG coordinates are relative to its top-left corner.
        const relativeMouseCoordinates: Point = [mouseCoordinates[0] - leftOffset, mouseCoordinates[1] - topOffset];
        const mouseAnchor = getMouseAnchor(
          containerCorners.topLeft,
          containerCorners.bottomRight,
          relativeMouseCoordinates,
        );

        const svgWidth = rightOffset - leftOffset;
        const svgHeight = bottomOffset - topOffset;
        const clipPath = computeOutsideClipPath(svgWidth, svgHeight, {
          x: targetCorners.topLeft[0],
          y: targetCorners.topLeft[1],
          width: targetRect.width,
          height: targetRect.height,
        });

        if (svgRef.current) {
          svgRef.current.style.width = `${svgWidth}px`;
          svgRef.current.style.height = `${svgHeight}px`;
          svgRef.current.style.transform = `translate(${leftOffset}px, ${topOffset}px)`;
        }

        const safeZonePoints = getSafeZonePoints(mouseAnchor, containerCorners);
        safeZoneRef.current?.setAttribute('d', safeZonePoints.length > 0 ? pointsToSvgPath(safeZonePoints) : '');
        clipPathRef.current?.setAttribute('d', clipPath);
        rectDebugRef.current?.setAttribute('d', clipPath);
      },
    }),
    [],
  );

  return (
    <div className={mergeClasses(styles.wrapper, active && styles.wrapperActive)} data-safe-zone="">
      <svg
        aria-hidden
        className={styles.svg}
        xmlns="http://www.w3.org/2000/svg"
        ref={svgRef}
        style={{ width: 0, height: 0, transform: 'translate(0px, 0px)' }}
      >
        <g
          className={mergeClasses(styles.safeZone, debug && styles.safeZoneDebug)}
          clipPath={`url(#${clipPathId})`}
          onMouseEnter={onMouseEnter}
          onMouseMove={onMouseMove}
          onMouseLeave={onMouseLeave}
        >
          <path ref={safeZoneRef} />
        </g>

        <clipPath id={clipPathId}>
          <path ref={clipPathRef} />
        </clipPath>

        {debug && <path ref={rectDebugRef} className={styles.rectDebug} />}
      </svg>
    </div>
  );
});

function drawRectangle(rect: { x: number; y: number; width: number; height: number }): string {
  if (rect.width <= 0 || rect.height <= 0) {
    return '';
  }

  let pathData = '';

  // Creates a subpath moving in counterclockwise direction to create a hole

  pathData += `M ${rect.x},${rect.y} `;
  pathData += `V ${rect.y + rect.height} `; // Down to bottom-left
  pathData += `H ${rect.x + rect.width} `; // Right to bottom-right
  pathData += `V ${rect.y} `; // Up to top-right
  pathData += `H ${rect.x} `; // Left to top-left (closing)
  pathData += `Z `; // Close path

  return pathData;
}

/**
 * Computes a clip path that covers the area outside a rectangle.
 *
 * @internal
 */
export function computeOutsideClipPath(
  svgWidth: number,
  svgHeight: number,
  targetRect: { x: number; y: number; width: number; height: number },
): string {
  let pathData = `M 0,0 H ${svgWidth} V ${svgHeight} H 0 Z `;

  // Draw the rectangle counterclockwise to create a hole in the main path.

  pathData += drawRectangle(targetRect);

  return pathData;
}

export function createSafeZoneAreaStateStore(): {
  isActive: () => boolean;
  toggleActive: (newIsActive: boolean) => void;
  subscribe: (listener: (value: boolean) => void) => () => void;
} {
  let isActive = false;
  const listeners: ((value: boolean) => void)[] = [];

  return {
    isActive() {
      return isActive;
    },
    toggleActive(newIsActive: boolean) {
      if (isActive === newIsActive) {
        return;
      }

      isActive = newIsActive;
      listeners.forEach(listener => listener(isActive));
    },

    subscribe(listener: (value: boolean) => void) {
      listeners.push(listener);

      return () => {
        const index = listeners.indexOf(listener);

        if (index > -1) {
          listeners.splice(index, 1);
        }
      };
    },
  };
}

import type { Point } from './types';

const OFFSET_DISTANCE = 20;

/**
 * Measures the distance between two points in a 2D space.
 */
export function measureDistance(a: Point, b: Point): number {
  return Math.sqrt((a[0] - b[0]) ** 2 + (a[1] - b[1]) ** 2);
}

/**
 * Returns a unit vector pointing from point `b` to point `a`.
 * If the distance is zero, returns a zero vector.
 */
export function getUnitVector(a: Point, b: Point): Point {
  const distance = measureDistance(a, b);

  if (distance === 0) {
    return [0, 0];
  }

  return [(a[0] - b[0]) / distance, (a[1] - b[1]) / distance];
}

/**
 * Calculates the anchor point for a mouse position within a container defined by its top-left and bottom-right corners.
 * The anchor point is calculated as an offset from the center of the container in the direction of the mouse position.
 *
 * @internal
 */
export function getMouseAnchor(topLeftCorner: Point, bottomRightCorner: Point, mouseCoordinates: Point): Point {
  const containerCenter: Point = [
    (topLeftCorner[0] + bottomRightCorner[0]) / 2,
    (topLeftCorner[1] + bottomRightCorner[1]) / 2,
  ];

  const unitVector = getUnitVector(
    [mouseCoordinates[0], mouseCoordinates[1]],
    [containerCenter[0], containerCenter[1]],
  );
  const distance = measureDistance(
    [containerCenter[0], containerCenter[1]],
    [mouseCoordinates[0], mouseCoordinates[1]],
  );

  return [
    containerCenter[0] + unitVector[0] * (distance + OFFSET_DISTANCE),
    containerCenter[1] + unitVector[1] * (distance + OFFSET_DISTANCE),
  ];
}

import type { Point } from './types';

/**
 * Calculates the corners of a rectangle based on its DOMRect and an offset.
 *
 * @internal
 */
export function getRectCorners(
  rect: DOMRect,
  offset: Point,
): Record<'topLeft' | 'topRight' | 'bottomRight' | 'bottomLeft', Point> {
  return {
    topLeft: [rect.left - offset[0], rect.top - offset[1]],
    topRight: [rect.right - offset[0], rect.top - offset[1]],
    bottomRight: [rect.right - offset[0], rect.bottom - offset[1]],
    bottomLeft: [rect.left - offset[0], rect.bottom - offset[1]],
  };
}

import type { Point } from './types';

type RectCorners = Record<'topLeft' | 'topRight' | 'bottomRight' | 'bottomLeft', Point>;

/**
 * Returns the mouse anchor and the container corners facing it.
 *
 * @internal
 */
export function getSafeZonePoints(mouseAnchor: Point, containerCorners: RectCorners): Point[] {
  const { topLeft, topRight, bottomRight, bottomLeft } = containerCorners;
  const isAbove = mouseAnchor[1] < topLeft[1];
  const isBelow = mouseAnchor[1] > bottomLeft[1];
  const isLeft = mouseAnchor[0] < topLeft[0];
  const isRight = mouseAnchor[0] > topRight[0];

  if (isAbove) {
    if (isLeft) {
      return [mouseAnchor, bottomLeft, topLeft, topRight];
    }

    if (isRight) {
      return [mouseAnchor, topLeft, topRight, bottomRight];
    }

    return [mouseAnchor, topLeft, topRight];
  }

  if (isBelow) {
    if (isLeft) {
      return [mouseAnchor, topLeft, bottomLeft, bottomRight];
    }

    if (isRight) {
      return [mouseAnchor, topRight, bottomRight, bottomLeft];
    }

    return [mouseAnchor, bottomRight, bottomLeft];
  }

  if (isLeft) {
    return [mouseAnchor, bottomLeft, topLeft];
  }

  if (isRight) {
    return [mouseAnchor, topRight, bottomRight];
  }

  return [];
}

import type { Point } from './types';

/**
 * Calculates the corners of a rectangle based on its DOMRect and an offset.
 *
 * @internal
 */
export function pointsToSvgPath(points: Point[]): string {
  return `M ${points} z`;
}

/**
 * A type representing a point in a 2D space as an array of two numbers (x & y coordinates).
 *
 * @internal
 */
export type Point = [number, number];

