/**
 * Cypress doesn't display the cursor position in the viewport, this component shows a red dot at the mouse position.
 */
const DebugPointer: React.FC = () => {
  const pointerRef = React.useRef<HTMLDivElement>(null);

  React.useEffect(() => {
    function onMouseMove(event: MouseEvent) {
      if (pointerRef.current) {
        pointerRef.current.style.left = `${event.x - 2}px`;
        pointerRef.current.style.top = `${event.y - 2}px`;
      }
    }

    window.addEventListener('mousemove', onMouseMove);

    return () => {
      window.removeEventListener('mousemove', onMouseMove);
    };
  }, []);

  return (
    <Portal>
      <div
        style={{
          borderRadius: '4px',
          pointerEvents: 'none',
          background: 'red',
          height: '4px',
          width: '4px',
          position: 'fixed',
        }}
        ref={pointerRef}
      />
    </Portal>
  );
};

const Example = ({
  containerHeight = 400,

  popoverWidth = 150,
  popoverHeight = 300,

  onSafeZoneLeave,
  onSafeZoneEnter,
  onSafeZoneTimeout,
  timeout = 100000,

  positioning,
  triggerStyle,
}: {
  containerHeight?: number;

  popoverHeight?: number;
  popoverWidth?: number;

  positioning: Pick<PositioningProps, 'align' | 'position' | 'offset'>;
  triggerStyle?: React.CSSProperties;
} & Pick<UseSafeZoneOptions, 'onSafeZoneEnter' | 'onSafeZoneLeave' | 'onSafeZoneTimeout' | 'timeout'>) => {
  const safeZoneArea = useSafeZoneArea({
    debug: true,
    timeout,
    onSafeZoneLeave,
    onSafeZoneEnter,
    onSafeZoneTimeout,
  });
  const { containerRef, targetRef } = usePositioning(positioning);

  return (
    <div
      style={{
        position: 'relative',
        width: '400px',
        height: containerHeight,
        background: 'lightgray',
        border: '2px dashed black',
      }}
    >
      <DebugPointer />

      <button
        ref={useMergedRefs(targetRef, safeZoneArea.targetRef)}
        className="trigger"
        style={{
          left: 50,
          top: 150,
          width: 100,
          height: 80,
          ...triggerStyle,
          cursor: 'pointer',
          position: 'absolute',
        }}
      >
        TRIGGER
      </button>

      <Portal>
        <div
          data-popper-placement="right-top"
          className="popover"
          ref={useMergedRefs(containerRef, safeZoneArea.containerRef)}
          style={{
            backgroundColor: 'orange',
            border: '2px solid black',
            position: 'absolute',
            padding: '20px',
            width: popoverWidth,
            height: popoverHeight,
          }}
        >
          POPOVER
        </div>
        {safeZoneArea.elementToRender}
      </Portal>
    </div>
  );
};

describe('useSafeZoneArea', () => {
  it('SVG is visible on hover', () => {
    mount(<Example positioning={{ align: 'center', position: 'after', offset: { mainAxis: 20 } }} />);

    cy.get('.trigger').realHover({ position: 'center' });
    cy.get('[data-safe-zone]').should('have.css', 'display', 'block');
    cy.get('[data-safe-zone] svg').should('have.css', 'width', '314px');
    cy.get('[data-safe-zone] svg').should('have.css', 'height', '344px');
  });

  ['small-trigger', 'small-container'].forEach(layout => {
    it(`onSafeZoneEnter and onSafeZoneLeave are called (${layout})`, () => {
      const onSafeZoneEnter = cy.stub().as('onSafeZoneEnter');
      const onSafeZoneLeave = cy.stub().as('onSafeZoneLeave');

      mount(
        <Example
          positioning={{ align: 'center', position: 'after', offset: { mainAxis: 20 } }}
          onSafeZoneLeave={onSafeZoneLeave}
          onSafeZoneEnter={onSafeZoneEnter}
          {...(layout === 'small-container' && {
            positioning: { align: 'end', position: 'above' },
            popoverHeight: 30,
            popoverWidth: 100,
            triggerStyle: { width: 300, height: 100 },
          })}
        />,
      );

      if (layout === 'small-container') {
        cy.get('.trigger').realHover({ position: 'left' });
        cy.get('.trigger').realMouseMove(100, -10, { position: 'topLeft' });
      } else {
        cy.get('.trigger').realHover({ position: 'center' });
        cy.get('.trigger').realMouseMove(10, 10, { position: 'topRight' });
      }

      cy.get('@onSafeZoneEnter').should('be.called');

      // ---

      if (layout === 'small-container') {
        cy.get('.trigger').realMouseMove(10, -10, { position: 'topLeft' });
        cy.get('.trigger').should('be.visible');
      } else {
        cy.get('.trigger').realMouseMove(-50, -10, { position: 'topRight' });
        cy.get('.trigger').should('be.visible');
      }

      cy.get('@onSafeZoneLeave').should('be.called');
    });
  });

  it('safe zone is hidden once mouse is over the popover', () => {
    mount(
      <Example popoverHeight={300} positioning={{ align: 'center', position: 'after', offset: { mainAxis: 20 } }} />,
    );

    cy.get('.trigger').realHover({ position: 'center' });
    cy.get('[data-safe-zone]').should('have.css', 'display', 'block');

    cy.get('.popover').realHover({ position: 'center' });
    cy.get('[data-safe-zone]').should('have.css', 'display', 'none');
  });

  it('safe zone is stays open as long as mouse keeps moving inside it', () => {
    const onSafeZoneTimeout = cy.stub().as('onSafeZoneTimeout');

    mount(
      <Example
        popoverHeight={300}
        onSafeZoneTimeout={onSafeZoneTimeout}
        positioning={{ align: 'center', position: 'after', offset: { mainAxis: 20 } }}
        timeout={300}
      />,
    );

    cy.get('.trigger').realHover({ position: 'right' });
    cy.get('[data-safe-zone]').should('have.css', 'display', 'block');

    cy.clock(0).then(() => {
      // Move the mouse inside the safe zone area, it should stay visible

      for (let startX = 10, startY = 10; startX < 15; startX++, startY++) {
        cy.get('.trigger').realMouseMove(startX, startY, { position: 'topRight' });
        cy.tick(299);

        cy.get('[data-safe-zone]').should('have.css', 'display', 'block');
      }

      // After 300ms of no movement, the safe zone should be hidden
      cy.tick(301);

      cy.get('@onSafeZoneTimeout').should('be.called');
      cy.get('[data-safe-zone]').should('have.css', 'display', 'none');
    });
  });

  it('safe zone is hidden after timeout if mouse is not moving', () => {
    const onSafeZoneTimeout = cy.stub().as('onSafeZoneTimeout');

    mount(
      <Example
        popoverHeight={300}
        onSafeZoneTimeout={onSafeZoneTimeout}
        positioning={{ align: 'center', position: 'after', offset: { mainAxis: 20 } }}
        timeout={200}
      />,
    );

    cy.get('.trigger').realHover({ position: 'center' });
    cy.get('[data-safe-zone]').should('have.css', 'display', 'block');

    // Wait for the timeout to finish, safe zone should be hidden

    cy.get('[data-safe-zone]').should('have.css', 'display', 'none');

    // Move again, safe zone should be shown again

    cy.get('.trigger').realHover({ position: 'right' });
    cy.get('[data-safe-zone]').should('have.css', 'display', 'block');

    // "onSafeZoneTimeout" is not called again since the mouse is still over the target element

    cy.get('@onSafeZoneTimeout').should('not.be.called');
  });

  it('onSafeZoneTimeout is called after timeout on safe zone enter', () => {
    const onSafeZoneEnter = cy.stub().as('onSafeZoneEnter');
    const onSafeZoneTimeout = cy.stub().as('onSafeZoneTimeout');

    mount(
      <Example
        positioning={{ align: 'center', position: 'after', offset: { mainAxis: 20 } }}
        onSafeZoneEnter={onSafeZoneEnter}
        onSafeZoneTimeout={onSafeZoneTimeout}
        timeout={200}
      />,
    );

    // Activate the safe zone

    cy.get('.trigger').realHover({ position: 'center' });
    cy.get('[data-safe-zone]').should('have.css', 'display', 'block');

    // Move over the safe zone to start the timeout

    cy.get('.trigger').realMouseMove(10, 10, { position: 'topRight' });
    cy.get('@onSafeZoneEnter').should('be.called');

    // Wait for the timeout to finish

    cy.get('@onSafeZoneTimeout').should('be.called');
    cy.get('[data-safe-zone]').should('have.css', 'display', 'none');
  });
});

'use client';

import { useAnimationFrame, useEventCallback, useMergedRefs, useTimeout } from '@fluentui/react-utilities';
import type { JSXElement, RefObjectFunction } from '@fluentui/react-utilities';
import * as React from 'react';

import { createSafeZoneAreaStateStore } from './createSafeZoneAreaStateStore';
import { type SafeZoneAreaImperativeHandle, SafeZoneArea } from './SafeZoneArea';

export type UseSafeZoneOptions = {
  /** Enables debug mode: makes drawn shapes visible. */
  debug?: boolean;

  /** Disables the safe zone area. */
  disabled?: boolean;

  /** The time in milliseconds to wait before clearing the safe zone. */
  timeout?: number;

  /** Called when the mouse enters the safe zone. */
  onSafeZoneEnter?: (e: React.MouseEvent) => void;

  /** Called when the mouse moves within the safe zone. */
  onSafeZoneMove?: (e: React.MouseEvent) => void;

  /** Called when the mouse leaves the safe zone. */
  onSafeZoneLeave?: (e: React.MouseEvent) => void;

  /** Called when the safe zone times out, even if a cursor is still over a safe zone. */
  onSafeZoneTimeout?: () => void;
};

/**
 * Time in milliseconds after which the safe zone area will be cleared if no mouse movement is detected.
 *
 * Only affects the target element, not the safe zone area itself.
 */
const MOUSE_MOVE_TARGET_POLLING_TIMEOUT = 2000;

// ---

export function useSafeZoneArea({
  debug = false,
  disabled = false,

  onSafeZoneEnter,
  onSafeZoneMove,
  onSafeZoneLeave,
  onSafeZoneTimeout,

  timeout = 1500,
}: UseSafeZoneOptions = {}): {
  containerRef: RefObjectFunction<HTMLElement>;
  targetRef: RefObjectFunction<HTMLElement>;
  elementToRender: JSXElement | null;
} {
  const [stateStore] = React.useState(createSafeZoneAreaStateStore);

  const safeZoneAreaRef = React.useRef<SafeZoneAreaImperativeHandle>(null);
  const containerRef = React.useRef<HTMLElement>(null);
  const targetRef = React.useRef<HTMLElement>(null);

  const [setSafeZoneCloseTimeout, clearSafeZoneCloseTimeout] = useTimeout();
  const [requestUpdateFrame, clearUpdateFrame] = useAnimationFrame();

  const mouseCoordinatesRef = React.useRef<{ x: number; y: number }>({ x: 0, y: 0 });

  // eslint-disable-next-line react-hooks/preserve-manual-memoization
  const containerListenerRef = React.useMemo(() => {
    if (disabled) {
      return () => {
        // do nothing
      };
    }

    let containerEl: HTMLElement | null = null;

    function onContainerMouseEnter() {
      clearSafeZoneCloseTimeout();
      stateStore.toggleActive(false);
    }

    return (el: HTMLElement | null) => {
      if (el === null) {
        containerEl?.removeEventListener('mouseenter', onContainerMouseEnter);
      }

      containerEl = el;
      el?.addEventListener('mouseenter', onContainerMouseEnter);
    };
  }, [clearSafeZoneCloseTimeout, disabled, stateStore]);

  // eslint-disable-next-line react-hooks/preserve-manual-memoization
  const targetListenerRef = React.useMemo(() => {
    if (disabled) {
      return () => {
        // do nothing
      };
    }

    let targetEl: HTMLElement | null = null;

    function onTargetMouseMove(e: MouseEvent) {
      mouseCoordinatesRef.current = { x: e.clientX, y: e.clientY };

      if (!stateStore.isActive()) {
        stateStore.toggleActive(true);
      }

      setSafeZoneCloseTimeout(() => {
        stateStore.toggleActive(false);
      }, MOUSE_MOVE_TARGET_POLLING_TIMEOUT);
    }

    return (el: HTMLElement | null) => {
      if (el === null) {
        clearUpdateFrame();
        clearSafeZoneCloseTimeout();

        targetEl?.removeEventListener('mousemove', onTargetMouseMove);
      }

      targetEl = el;
      el?.addEventListener('mousemove', onTargetMouseMove);
    };
  }, [clearUpdateFrame, clearSafeZoneCloseTimeout, disabled, stateStore, setSafeZoneCloseTimeout]);

  const onSvgMouseEnter = useEventCallback((e: React.MouseEvent) => {
    onSafeZoneEnter?.(e);

    setSafeZoneCloseTimeout(() => {
      stateStore.toggleActive(false);
      onSafeZoneTimeout?.();
    }, timeout);
  });

  const onSvgMouseMove = useEventCallback((e: React.MouseEvent) => {
    setSafeZoneCloseTimeout(() => {
      stateStore.toggleActive(false);
      onSafeZoneTimeout?.();
    }, timeout);
    onSafeZoneMove?.(e);
  });

  const onSvgMouseLeave = useEventCallback((e: React.MouseEvent) => {
    onSafeZoneLeave?.(e);
  });

  React.useEffect(() => {
    return stateStore.subscribe(isActive => {
      if (isActive) {
        function updateSVGs() {
          const containerEl = containerRef.current;
          const targetEl = targetRef.current;

          if (containerEl && targetEl) {
            safeZoneAreaRef.current?.updateSVG({
              containerRect: containerEl.getBoundingClientRect(),
              mouseCoordinates: [mouseCoordinatesRef.current.x, mouseCoordinatesRef.current.y],
              targetRect: targetEl.getBoundingClientRect(),
            });
          }

          requestUpdateFrame(updateSVGs);
        }

        updateSVGs();
        return;
      }

      clearUpdateFrame();
    });
  }, [clearUpdateFrame, requestUpdateFrame, stateStore]);

  return {
    containerRef: useMergedRefs(containerRef, containerListenerRef),
    targetRef: useMergedRefs(targetRef, targetListenerRef),

    elementToRender: React.useMemo(
      () =>
        disabled ? null : (
          <SafeZoneArea
            debug={debug}
            onMouseEnter={onSvgMouseEnter}
            onMouseMove={onSvgMouseMove}
            onMouseLeave={onSvgMouseLeave}
            imperativeRef={safeZoneAreaRef}
            stateStore={stateStore}
          />
        ),
      [disabled, debug, onSvgMouseEnter, onSvgMouseMove, onSvgMouseLeave, stateStore],
    ),
  };
}

