import type { Middleware } from '@floating-ui/dom';
import { detectOverflow } from '@floating-ui/dom';

export function intersecting(): Middleware {
  return {
    name: 'intersectionObserver',
    fn: async middlewareArguments => {
      const floatingRect = middlewareArguments.rects.floating;
      const altOverflow = await detectOverflow(middlewareArguments, { altBoundary: true });

      const isIntersectingTop = altOverflow.top < floatingRect.height && altOverflow.top > 0;
      const isIntersectingBottom = altOverflow.bottom < floatingRect.height && altOverflow.bottom > 0;

      const isIntersecting = isIntersectingTop || isIntersectingBottom;

      return {
        data: {
          intersecting: isIntersecting,
        },
      };
    },
  };
}

import type { Middleware } from '@floating-ui/dom';

export const matchTargetSizeCssVar = '--fui-match-target-size';

export function matchTargetSize(): Middleware {
  return {
    name: 'matchTargetSize',
    fn: async middlewareArguments => {
      const {
        rects: { reference: referenceRect, floating: floatingRect },
        elements: { floating: floatingElement },
        middlewareData: { matchTargetSize: { matchTargetSizeAttempt = false } = {} },
      } = middlewareArguments;

      if (referenceRect.width === floatingRect.width || matchTargetSizeAttempt) {
        return {};
      }

      const { width } = referenceRect;
      floatingElement.style.setProperty(matchTargetSizeCssVar, `${width}px`);
      if (!floatingElement.style.width) {
        floatingElement.style.width = `var(${matchTargetSizeCssVar})`;
      }

      return {
        data: { matchTargetSizeAttempt: true },
        reset: {
          rects: true,
        },
      };
    },
  };
}

import { size } from '@floating-ui/dom';
import type { Middleware } from '@floating-ui/dom';
import type { NormalizedAutoSize, PositioningOptions } from '../types';
import { getBoundary } from '../utils/getBoundary';
import { toFloatingUIPadding } from '../utils';
export interface MaxSizeMiddlewareOptions
  extends Pick<PositioningOptions, 'overflowBoundary' | 'overflowBoundaryPadding'> {
  container: HTMLElement | null;
  isRtl: boolean;
}

/**
 * floating-ui `size` middleware uses floating element's height/width to calculate available height/width.
 * This middleware only runs once per lifecycle, resetting styles applied by maxSize from previous lifecycle.
 * Then floating element's original size is restored and `size` middleware can calculate available height/width correctly.
 */
export const resetMaxSize = (autoSize: NormalizedAutoSize): Middleware => ({
  name: 'resetMaxSize',
  fn({ middlewareData, elements }) {
    if (middlewareData.resetMaxSize?.maxSizeAlreadyReset) {
      return {};
    }

    const { applyMaxWidth, applyMaxHeight } = autoSize;
    if (applyMaxWidth) {
      elements.floating.style.removeProperty('box-sizing');
      elements.floating.style.removeProperty('max-width');
      elements.floating.style.removeProperty('width');
    }
    if (applyMaxHeight) {
      elements.floating.style.removeProperty('box-sizing');
      elements.floating.style.removeProperty('max-height');
      elements.floating.style.removeProperty('height');
    }

    return {
      data: { maxSizeAlreadyReset: true },
      reset: { rects: true },
    };
  },
});

export function maxSize(autoSize: NormalizedAutoSize, options: MaxSizeMiddlewareOptions): Middleware {
  const { container, overflowBoundary, overflowBoundaryPadding, isRtl } = options;
  return size({
    ...(overflowBoundaryPadding && { padding: toFloatingUIPadding(overflowBoundaryPadding, isRtl) }),
    ...(overflowBoundary && { altBoundary: true, boundary: getBoundary(container, overflowBoundary) }),
    apply({ availableHeight, availableWidth, elements, rects }) {
      const applyMaxSizeStyles = (apply: boolean, dimension: 'width' | 'height', availableSize: number) => {
        if (!apply) {
          return;
        }

        elements.floating.style.setProperty('box-sizing', 'border-box');
        elements.floating.style.setProperty(`max-${dimension}`, `${availableSize}px`);

        if (rects.floating[dimension] > availableSize) {
          elements.floating.style.setProperty(dimension, `${availableSize}px`);

          const axis = dimension === 'width' ? 'x' : 'y';
          if (!elements.floating.style.getPropertyValue(`overflow-${axis}`)) {
            elements.floating.style.setProperty(`overflow-${axis}`, 'auto');
          }
        }
      };

      const { applyMaxWidth, applyMaxHeight } = autoSize;
      applyMaxSizeStyles(applyMaxWidth, 'width', availableWidth);
      applyMaxSizeStyles(applyMaxHeight, 'height', availableHeight);
    },
  });
}

import type { Middleware } from '@floating-ui/dom';
import { offset as baseOffset } from '@floating-ui/dom';
import type { PositioningOptions } from '../types';
import { getFloatingUIOffset } from '../utils/getFloatingUIOffset';

/**
 * Wraps floating UI offset middleware to transform offset value.
 */
export function offset(offsetValue: PositioningOptions['offset']): Middleware {
  const floatingUIOffset = getFloatingUIOffset(offsetValue);
  return baseOffset(floatingUIOffset);
}

import type { Middleware } from '@floating-ui/dom';
import { shift as baseShift, limitShift } from '@floating-ui/dom';
import type { PositioningOptions } from '../types';
import { getBoundary, toFloatingUIPadding } from '../utils/index';

export interface ShiftMiddlewareOptions
  extends Pick<PositioningOptions, 'overflowBoundary' | 'overflowBoundaryPadding' | 'shiftToCoverTarget'> {
  hasScrollableElement?: boolean;
  disableTether?: PositioningOptions['unstable_disableTether'];
  container: HTMLElement | null;
  isRtl: boolean;
}

/**
 * Wraps the floating UI shift middleware for easier usage of our options
 */
export function shift(options: ShiftMiddlewareOptions): Middleware {
  const {
    hasScrollableElement,
    shiftToCoverTarget,
    disableTether,
    overflowBoundary,
    container,
    overflowBoundaryPadding,
    isRtl,
  } = options;

  return baseShift({
    ...(hasScrollableElement && { boundary: 'clippingAncestors' }),
    ...(shiftToCoverTarget && {
      crossAxis: true,
      limiter: limitShift({ crossAxis: true, mainAxis: false }),
    }),
    ...(disableTether && {
      crossAxis: disableTether === 'all',
      limiter: limitShift({ crossAxis: disableTether !== 'all', mainAxis: false }),
    }),
    ...(overflowBoundaryPadding && { padding: toFloatingUIPadding(overflowBoundaryPadding, isRtl) }),
    ...(overflowBoundary && { altBoundary: true, boundary: getBoundary(container, overflowBoundary) }),
  });
}

import type * as React from 'react';

/**
 * Physical placement of a positioned element relative to its target, as computed by Floating UI.
 * This is a Fluent-owned equivalent of Floating UI's `Placement` type, avoiding a transitive
 * dependency on `@floating-ui/dom` in the public API surface.
 */
export type PositioningPlacement =
  | 'top'
  | 'top-start'
  | 'top-end'
  | 'right'
  | 'right-start'
  | 'right-end'
  | 'bottom'
  | 'bottom-start'
  | 'bottom-end'
  | 'left'
  | 'left-start'
  | 'left-end';

/**
 * Detail payload of the positioning end event, providing the final computed placement
 * after all middleware (flip, shift, etc.) have run.
 */
export type OnPositioningEndEventDetail = {
  /**
   * The computed placement of the positioned element. May differ from the requested
   * placement if flip or other middleware adjusted it.
   */
  placement: PositioningPlacement;

  /**
   * True when the floating element has escaped its clipping boundary,
   * as reported by Floating UI's hide middleware.
   */
  escaped: boolean;

  /**
   * True when the reference element is clipped or out of view,
   * as reported by Floating UI's hide middleware.
   */
  referenceHidden: boolean;
};

/**
 * Custom DOM event dispatched on the positioned container element when a
 * positioning update completes. Carries placement information in `event.detail`.
 */
export type OnPositioningEndEvent = CustomEvent<OnPositioningEndEventDetail>;

export type PositioningRect = {
  width: number;
  height: number;
  x: number;
  y: number;
};

export type OffsetFunctionParam = {
  positionedRect: PositioningRect;
  targetRect: PositioningRect;
  position: Position;
  alignment?: Alignment;
};

export type TargetElement = HTMLElement | PositioningVirtualElement;

/**
 * @internal
 */
export interface PositionManager {
  updatePosition: () => void;
  dispose: () => void;
}

export interface UsePositioningReturn {
  // React refs are supposed to be contravariant
  // (allows a more general type to be passed rather than a more specific one)
  // However, Typescript currently can't infer that fact for refs
  // See https://github.com/microsoft/TypeScript/issues/30748 for more information
  // eslint-disable-next-line @typescript-eslint/no-explicit-any, @typescript-eslint/no-deprecated
  targetRef: React.MutableRefObject<any>;
  // eslint-disable-next-line @typescript-eslint/no-explicit-any, @typescript-eslint/no-deprecated
  containerRef: React.MutableRefObject<any>;
  // eslint-disable-next-line @typescript-eslint/no-explicit-any, @typescript-eslint/no-deprecated
  arrowRef: React.MutableRefObject<any>;
}

export type OffsetObject = { crossAxis?: number; mainAxis: number };

export type OffsetShorthand = number;

export type OffsetFunction = (param: OffsetFunctionParam) => OffsetObject | OffsetShorthand;

export type Offset = OffsetFunction | OffsetObject | OffsetShorthand;

export type Position = 'above' | 'below' | 'before' | 'after';
export type Alignment = 'top' | 'bottom' | 'start' | 'end' | 'center';

export type AutoSize = 'height' | 'height-always' | 'width' | 'width-always' | 'always' | boolean;
export type NormalizedAutoSize = { applyMaxWidth: boolean; applyMaxHeight: boolean };

export type PositioningBoundary =
  | PositioningRect
  | HTMLElement
  | Array<HTMLElement>
  | 'clippingParents'
  | 'scrollParent'
  | 'window';
/**
 * @deprecated use PositioningBoundary instead
 */
export type Boundary = PositioningBoundary;

export type PositioningImperativeRef = {
  /**
   * Updates the position imperatively.
   * Useful when the position of the target changes from other factors than scrolling of window resize.
   */
  updatePosition: () => void;

  /**
   * Sets the target and updates positioning imperatively.
   * Useful for avoiding double renders with the target option.
   */
  setTarget: (target: TargetElement | null) => void;
};

export type PositioningVirtualElement = {
  getBoundingClientRect: () => {
    x: number;
    y: number;
    top: number;
    left: number;
    bottom: number;
    right: number;
    width: number;
    height: number;
  };
  contextElement?: Element;
};

export type SetVirtualMouseTarget = (event: React.MouseEvent | MouseEvent | undefined | null) => void;

/**
 * Internal options for positioning
 */
export interface PositioningOptions {
  /** Alignment for the component. Only has an effect if used with the @see position option */
  align?: Alignment;

  /** The element which will define the boundaries of the positioned element for the flip behavior. */
  flipBoundary?: PositioningBoundary | null;

  /** The element which will define the boundaries of the positioned element for the overflow behavior. */
  overflowBoundary?: PositioningBoundary | null;

  /**
   * Applies a padding to the overflow bounadry, so that overflow is detected earlier before the
   * positioned surface hits the overflow boundary.
   */
  overflowBoundaryPadding?: number | Partial<{ top: number; end: number; bottom: number; start: number }>;

  /**
   * Position for the component. Position has higher priority than align. If position is vertical ('above' | 'below')
   * and align is also vertical ('top' | 'bottom') or if both position and align are horizontal ('before' | 'after'
   * and 'start' | 'end' respectively),
   * then provided value for 'align' will be ignored and 'center' will be used instead.
   */
  position?: Position;

  /**
   * Enables the position element to be positioned with 'fixed' (default value is position: 'absolute')
   * @default false
   * @deprecated use `strategy` instead
   */
  positionFixed?: boolean;

  /**
   * Specifies the type of CSS position property to use.
   * @default absolute
   */
  strategy?: 'absolute' | 'fixed';

  /**
   * Lets you displace a positioned element from its reference element.
   * This can be useful if you need to apply some margin between them or if you need to fine tune the
   * position according to some custom logic.
   */
  offset?: Offset;

  /**
   * Defines padding between the corner of the popup element and the arrow.
   * Use to prevent the arrow from overlapping a rounded corner, for example.
   */
  arrowPadding?: number;

  /**
   * Applies styles on the positioned element to fit it within the available space in viewport.
   * - true: set styles for max height/width.
   * - 'height': set styles for max height.
   * - 'width'': set styles for max width.
   * Note that options 'always'/'height-always'/'width-always' are now obsolete, and equivalent to true/'height'/'width'.
   */
  autoSize?: AutoSize;

  /**
   * Modifies position and alignment to cover the target
   */
  coverTarget?: boolean;

  /**
   * Disables automatic repositioning of the component; it will always be placed according to the values of `align` and
   * `position` props, regardless of the size of the component, the reference element or the viewport.
   */
  pinned?: boolean;

  /**
   * When the reference element or the viewport is outside viewport allows a positioned element to be fully in viewport.
   * "all" enables this behavior for all axis.
   */
  // eslint-disable-next-line @typescript-eslint/naming-convention
  unstable_disableTether?: boolean | 'all';

  /**
   * If flip fails to stop the positioned element from overflowing
   * its boundaries, use a specified fallback positions.
   */
  fallbackPositions?: PositioningShorthandValue[];

  /**
   * Modifies whether popover is positioned using transform.
   * @default true
   */
  useTransform?: boolean;

  /**
   * If false, does not position anything
   */
  enabled?: boolean;

  /**
   * When set, the positioned element matches the chosen dimension(s) of the target element
   */
  matchTargetSize?: 'width';

  /**
   * Called when a position update has finished. Multiple position updates can happen in a single render,
   * since positioning happens outside of the React lifecycle.
   * The event's `detail.placement` indicates the final computed placement after middleware adjustments.
   *
   * It's also possible to listen to the custom DOM event `fui-positioningend`
   */
  onPositioningEnd?: (e: OnPositioningEndEvent) => void;

  /**
   * Disables the resize observer that updates position on target or dimension change
   */
  disableUpdateOnResize?: boolean;

  /**
   * When true, the positioned element will shift to cover the target element when there's not enough space.
   * @default false
   */
  shiftToCoverTarget?: boolean;
}

/**
 * Public api that allows components using react-positioning to specify positioning options
 */
export interface PositioningProps
  extends Pick<
    PositioningOptions,
    | 'align'
    | 'arrowPadding'
    | 'autoSize'
    | 'coverTarget'
    | 'fallbackPositions'
    | 'flipBoundary'
    | 'offset'
    | 'overflowBoundary'
    | 'overflowBoundaryPadding'
    | 'pinned'
    | 'position'
    | 'strategy'
    | 'useTransform'
    | 'matchTargetSize'
    | 'onPositioningEnd'
    | 'disableUpdateOnResize'
    | 'shiftToCoverTarget'
  > {
  /** An imperative handle to Popper methods. */
  positioningRef?: React.Ref<PositioningImperativeRef>;

  /**
   * Manual override for the target element. Useful for scenarios where a component accepts user prop to override target
   */
  target?: TargetElement | null;
}

export type PositioningShorthandValue =
  | 'above'
  | 'above-start'
  | 'above-end'
  | 'below'
  | 'below-start'
  | 'below-end'
  | 'before'
  | 'before-top'
  | 'before-bottom'
  | 'after'
  | 'after-top'
  | 'after-bottom';

export type PositioningShorthand = PositioningProps | PositioningShorthandValue;

// ---

export type PositioningConfigurationFnOptions = Omit<
  PositioningOptions,
  // Excluded as the function will never be called if disabled
  | 'enabled'
  // Callback is not subscribed from options
  | 'onPositioningEnd'
  // Is deprecated, no need to bloat the interface
  | 'positionFixed'
>;
export type PositioningConfigurationFn = (params: {
  container: HTMLElement;
  arrow: HTMLElement | null;
  options: PositioningConfigurationFnOptions;
}) => PositioningConfigurationFnOptions;

'use client';

import { canUseDOM, useEventCallback, useIsomorphicLayoutEffect } from '@fluentui/react-utilities';
import * as React from 'react';

import { POSITIONING_END_EVENT } from './constants';
import { createPositionManager } from './createPositionManager';
import type {
  OnPositioningEndEvent,
  PositioningOptions,
  PositioningProps,
  PositionManager,
  TargetElement,
  UsePositioningReturn,
} from './types';
import { usePositioningOptions } from './usePositioningOptions';
import { useCallbackRef, hasAutofocusFilter } from './utils';

/**
 * @internal
 */
export function usePositioning(options: PositioningProps & PositioningOptions): UsePositioningReturn {
  const managerRef = React.useRef<PositionManager | null>(null);
  const targetRef = React.useRef<TargetElement | null>(null);
  const overrideTargetRef = React.useRef<TargetElement | null>(null);
  const containerRef = React.useRef<HTMLElement | null>(null);
  const arrowRef = React.useRef<HTMLElement | null>(null);

  const { enabled = true } = options;
  const resolvePositioningOptions = usePositioningOptions(options);
  const updatePositionManager = React.useCallback(() => {
    if (managerRef.current) {
      managerRef.current.dispose();
    }
    managerRef.current = null;

    const target = overrideTargetRef.current ?? targetRef.current;

    if (enabled && canUseDOM() && target && containerRef.current) {
      managerRef.current = createPositionManager({
        container: containerRef.current,
        target,
        arrow: arrowRef.current,
        ...resolvePositioningOptions(containerRef.current, arrowRef.current),
      });
    }
  }, [enabled, resolvePositioningOptions]);

  const setOverrideTarget = useEventCallback((target: TargetElement | null) => {
    overrideTargetRef.current = target;
    updatePositionManager();
  });

  React.useImperativeHandle(
    options.positioningRef,
    () => ({
      updatePosition: () => managerRef.current?.updatePosition(),
      setTarget: (target: TargetElement | null) => {
        if (options.target && process.env.NODE_ENV !== 'production') {
          const err = new Error();
          // eslint-disable-next-line no-console
          console.warn('Imperative setTarget should not be used at the same time as target option');
          // eslint-disable-next-line no-console
          console.warn(err.stack);
        }

        setOverrideTarget(target);
      },
    }),
    [options.target, setOverrideTarget],
  );

  useIsomorphicLayoutEffect(() => {
    setOverrideTarget(options.target ?? null);
  }, [options.target, setOverrideTarget]);

  useIsomorphicLayoutEffect(() => {
    updatePositionManager();
  }, [updatePositionManager]);

  if (process.env.NODE_ENV !== 'production') {
    // This checked should run only in development mode
    // eslint-disable-next-line react-hooks/rules-of-hooks
    React.useEffect(() => {
      if (containerRef.current) {
        const contentNode = containerRef.current;
        const treeWalker = contentNode.ownerDocument?.createTreeWalker(contentNode, NodeFilter.SHOW_ELEMENT, {
          acceptNode: hasAutofocusFilter,
        });

        while (treeWalker.nextNode()) {
          const node = treeWalker.currentNode;
          // eslint-disable-next-line no-console
          console.warn('usePositioning():', node);
          // eslint-disable-next-line no-console
          console.warn(
            [
              'usePositioning(): ^ this node contains "autoFocus" prop on a React element. This can break the initial',
              'positioning of an element and cause a window jump effect. This issue occurs because React polyfills',
              '"autoFocus" behavior to solve inconsistencies between different browsers:',
              'https://github.com/facebook/react/issues/11851#issuecomment-351787078',
              '\n',
              'However, ".focus()" in this case occurs before any other React effects will be executed',
              '(React.useEffect(), componentDidMount(), etc.) and we can not prevent this behavior. If you really',
              'want to use "autoFocus" please add "position: fixed" to styles of the element that is wrapped by',
              '"Popper".',
              `In general, it's not recommended to use "autoFocus" as it may break accessibility aspects:`,
              'https://github.com/jsx-eslint/eslint-plugin-jsx-a11y/blob/master/docs/rules/no-autofocus.md',
              '\n',
              'We suggest to use the "trapFocus" prop on Fluent components or a catch "ref" and then use',
              '"ref.current.focus" in React.useEffect():',
              'https://reactjs.org/docs/refs-and-the-dom.html#adding-a-ref-to-a-dom-element',
            ].join(' '),
          );
        }
      }
      // We run this check once, no need to add deps here
      // TODO: Should be rework to handle options.enabled and contentRef updates
    }, []);
  }

  const setTarget = useCallbackRef<TargetElement>(null, target => {
    if (targetRef.current !== target) {
      targetRef.current = target;
      updatePositionManager();
    }
  });

  const onPositioningEnd = useEventCallback((e: OnPositioningEndEvent) => options.onPositioningEnd?.(e));
  const setContainer = useCallbackRef<HTMLElement | null>(null, container => {
    if (containerRef.current !== container) {
      // Cast because CustomEvent<OnPositioningEndEventDetail> is not assignable to EventListener
      containerRef.current?.removeEventListener(POSITIONING_END_EVENT, onPositioningEnd as EventListener);
      container?.addEventListener(POSITIONING_END_EVENT, onPositioningEnd as EventListener);
      containerRef.current = container;
      updatePositionManager();
    }
  });

  const setArrow = useCallbackRef<HTMLElement | null>(null, arrow => {
    if (arrowRef.current !== arrow) {
      arrowRef.current = arrow;
      updatePositionManager();
    }
  });

  // Let users use callback refs so they feel like 'normal' DOM refs
  return { targetRef: setTarget, containerRef: setContainer, arrowRef: setArrow };
}

'use client';

import * as React from 'react';
import { createVirtualElementFromClick } from './createVirtualElementFromClick';
import type { PositioningVirtualElement, SetVirtualMouseTarget } from './types';

/**
 * A state hook that manages a popper virtual element from mouseevents.
 * Useful for scenarios where a component needs to be positioned by mouse click (e.g. contextmenu)
 * React synthetic events are not persisted by this hook
 *
 * @internal
 * @param initialState - initializes a user provided state similare to useState
 * @returns state and dispatcher for a Popper virtual element that uses native/synthetic mouse events
 */
export const usePositioningMouseTarget = (
  initialState?: PositioningVirtualElement | (() => PositioningVirtualElement),
): readonly [PositioningVirtualElement | undefined, SetVirtualMouseTarget] => {
  const [virtualElement, setVirtualElement] = React.useState<PositioningVirtualElement | undefined>(initialState);

  const setVirtualMouseTarget: SetVirtualMouseTarget = event => {
    if (event === undefined || event === null) {
      setVirtualElement(undefined);
      return;
    }

    let mouseevent: MouseEvent;
    if (!(event instanceof MouseEvent)) {
      mouseevent = event.nativeEvent;
    } else {
      mouseevent = event;
    }

    if (!(mouseevent instanceof MouseEvent) && process.env.NODE_ENV !== 'production') {
      // eslint-disable-next-line no-console
      console.error('usePositioningMouseTarget should only be used with MouseEvent');
    }

    const contextTarget = createVirtualElementFromClick(mouseevent);
    setVirtualElement(contextTarget);
  };

  return [virtualElement, setVirtualMouseTarget] as const;
};

'use client';

import { devtools } from '@floating-ui/devtools';
import { hide as hideMiddleware, arrow as arrowMiddleware } from '@floating-ui/dom';
import type { Middleware, Placement, Strategy } from '@floating-ui/dom';
import { useFluent_unstable as useFluent } from '@fluentui/react-shared-contexts';
import * as React from 'react';

import {
  shift as shiftMiddleware,
  flip as flipMiddleware,
  coverTarget as coverTargetMiddleware,
  maxSize as maxSizeMiddleware,
  resetMaxSize as resetMaxSizeMiddleware,
  offset as offsetMiddleware,
  intersecting as intersectingMiddleware,
  matchTargetSize as matchTargetSizeMiddleware,
} from './middleware';
import type { PositioningConfigurationFn, PositioningConfigurationFnOptions, PositioningOptions } from './types';
import { toFloatingUIPlacement, hasScrollParent, normalizeAutoSize } from './utils';
import { devtoolsCallback } from './utils/devtools';
import { usePositioningConfiguration } from './PositioningConfigurationContext';

/**
 * This is redundant and exists only to manage React dependencies properly & avoid leaking individual options to the
 * scope of `usePositioningOptions`.
 *
 * @internal
 */
function usePositioningConfigFn(
  configFn: PositioningConfigurationFn,
  options: PositioningOptions,
): (container: HTMLElement, arrow: HTMLElement | null) => PositioningConfigurationFnOptions {
  const {
    align,
    arrowPadding,
    autoSize,
    coverTarget,
    disableUpdateOnResize,
    flipBoundary,
    offset,
    overflowBoundary,
    pinned,
    position,
    // eslint-disable-next-line @typescript-eslint/naming-convention
    unstable_disableTether,
    strategy,
    overflowBoundaryPadding,
    fallbackPositions,
    useTransform,
    matchTargetSize,
    shiftToCoverTarget,
  } = options;

  return React.useCallback(
    (container: HTMLElement, arrow: HTMLElement | null) => {
      return configFn({
        container,
        arrow,
        options: {
          autoSize,
          disableUpdateOnResize,
          matchTargetSize,
          offset,
          strategy,
          coverTarget,
          flipBoundary,
          overflowBoundary,
          useTransform,
          overflowBoundaryPadding,
          pinned,
          arrowPadding,
          align,
          fallbackPositions,
          shiftToCoverTarget,
          position,
          // eslint-disable-next-line @typescript-eslint/naming-convention
          unstable_disableTether,
        },
      });
    },
    [
      autoSize,
      disableUpdateOnResize,
      matchTargetSize,
      offset,
      strategy,
      coverTarget,
      flipBoundary,
      overflowBoundary,
      useTransform,
      overflowBoundaryPadding,
      pinned,
      arrowPadding,
      align,
      fallbackPositions,
      shiftToCoverTarget,
      position,
      unstable_disableTether,
      configFn,
    ],
  );
}

/**
 * @internal
 */
export function usePositioningOptions(options: PositioningOptions): (
  container: HTMLElement,
  arrow: HTMLElement | null,
) => {
  placement: Placement | undefined;
  middleware: Middleware[];
  strategy: Strategy;
  disableUpdateOnResize?: boolean;
  useTransform?: boolean;
} {
  const { dir, targetDocument } = useFluent();
  const isRtl = dir === 'rtl';

  const configFn = usePositioningConfigFn(usePositioningConfiguration(), options);
  const {
    // eslint-disable-next-line @typescript-eslint/no-deprecated
    positionFixed,
  } = options;

  return React.useCallback(
    (container: HTMLElement, arrow: HTMLElement | null) => {
      const hasScrollableElement = hasScrollParent(container);

      const optionsAfterEnhancement = configFn(container, arrow);
      const {
        autoSize,
        disableUpdateOnResize,
        matchTargetSize,
        offset,
        coverTarget,
        flipBoundary,
        overflowBoundary,
        useTransform,
        overflowBoundaryPadding,
        pinned,
        position,
        arrowPadding,
        strategy,
        align,
        fallbackPositions,
        shiftToCoverTarget,
        // eslint-disable-next-line @typescript-eslint/naming-convention
        unstable_disableTether,
      } = optionsAfterEnhancement;
      const normalizedAutoSize = normalizeAutoSize(autoSize);

      const middleware = [
        normalizedAutoSize && resetMaxSizeMiddleware(normalizedAutoSize),
        matchTargetSize && matchTargetSizeMiddleware(),
        offset && offsetMiddleware(offset),
        coverTarget && coverTargetMiddleware(),
        !pinned && flipMiddleware({ container, flipBoundary, hasScrollableElement, isRtl, fallbackPositions }),
        shiftMiddleware({
          container,
          hasScrollableElement,
          overflowBoundary,
          disableTether: unstable_disableTether,
          overflowBoundaryPadding,
          isRtl,
          shiftToCoverTarget,
        }),
        normalizedAutoSize &&
          maxSizeMiddleware(normalizedAutoSize, { container, overflowBoundary, overflowBoundaryPadding, isRtl }),
        intersectingMiddleware(),
        arrow && arrowMiddleware({ element: arrow, padding: arrowPadding }),
        hideMiddleware({ strategy: 'referenceHidden' }),
        hideMiddleware({ strategy: 'escaped' }),
        process.env.NODE_ENV !== 'production' &&
          targetDocument &&
          devtools(targetDocument, devtoolsCallback(optionsAfterEnhancement)),
      ].filter(Boolean) as Middleware[];

      const placement = toFloatingUIPlacement(align, position, isRtl);

      return {
        placement,
        middleware,
        strategy: strategy ?? positionFixed ? ('fixed' as const) : ('absolute' as const),

        disableUpdateOnResize,
        useTransform,
      };
    },
    [configFn, isRtl, targetDocument, positionFixed],
  );
}

'use client';

import * as React from 'react';
import { useEventCallback, isHTMLElement } from '@fluentui/react-utilities';
import type { PositioningProps } from './types';
import { POSITIONING_SLIDE_DIRECTION_VAR_X, POSITIONING_SLIDE_DIRECTION_VAR_Y } from './constants';

const registeredProperties = new WeakMap<Document, Set<string>>();
const slideDirectionProperties = [POSITIONING_SLIDE_DIRECTION_VAR_X, POSITIONING_SLIDE_DIRECTION_VAR_Y];

/**
 * Returns the slide direction unit vectors for a given Floating UI placement.
 * Values are -1, 0, or 1, representing the direction the element slides in from.
 */
export function getPlacementSlideDirections(placement: string): { x: number; y: number } {
  const side = placement.split('-')[0];
  // Default to sliding down from the top side
  let x = 0;
  let y = 1;

  if (side === 'right') {
    x = -1;
    y = 0;
  } else if (side === 'bottom') {
    x = 0;
    y = -1;
  } else if (side === 'left') {
    x = 1;
    y = 0;
  }

  return { x, y };
}

type UsePositioningSlideDirectionOptions = {
  /** The target document for CSS.registerProperty. */
  targetDocument: Document | undefined;
  /** The user's original onPositioningEnd callback, if any. */
  onPositioningEnd?: PositioningProps['onPositioningEnd'];
};

/**
 * A hook that manages CSS custom properties for slide direction based on positioning placement.
 *
 * It wraps the `onPositioningEnd` callback to set `--fui-positioning-slide-direction-x` and
 * `--fui-positioning-slide-direction-y` CSS custom properties on the positioned element,
 * and registers them via `CSS.registerProperty` to avoid properties propagation down to a DOM tree.
 *
 * @returns The wrapped `onPositioningEnd` handler to pass to the positioning config.
 */
export function usePositioningSlideDirection(
  options: UsePositioningSlideDirectionOptions,
): NonNullable<PositioningProps['onPositioningEnd']> {
  const { targetDocument, onPositioningEnd } = options;

  const handlePositionEnd: NonNullable<PositioningProps['onPositioningEnd']> = useEventCallback(e => {
    onPositioningEnd?.(e);

    const element = e.target;
    const placement = e.detail.placement;

    if (!isHTMLElement(element)) {
      return;
    }

    const { x, y } = getPlacementSlideDirections(placement);

    element.style.setProperty(POSITIONING_SLIDE_DIRECTION_VAR_X, `${x}px`);
    element.style.setProperty(POSITIONING_SLIDE_DIRECTION_VAR_Y, `${y}px`);
  });

  React.useEffect(() => {
    const css = targetDocument?.defaultView?.CSS;
    if (!targetDocument || !css?.registerProperty) {
      return;
    }
    let properties = registeredProperties.get(targetDocument);
    if (!properties) {
      properties = new Set<string>();
      registeredProperties.set(targetDocument, properties);
    }
    for (const name of slideDirectionProperties) {
      if (properties.has(name)) {
        continue;
      }
      try {
        css.registerProperty({ name, syntax: '<length>', inherits: false, initialValue: '0px' });
        properties.add(name);
      } catch (error) {
        if (error && typeof error === 'object' && 'name' in error && error.name === 'InvalidModificationError') {
          properties.add(name);
        }
      }
    }
  }, [targetDocument]);

  return handlePositionEnd;
}

export function createResizeObserver(
  targetWindow: Window & typeof globalThis,
  callback: ResizeObserverCallback,
): ResizeObserver {
  // https://github.com/jsdom/jsdom/issues/3368
  // Add the polyfill here so it is not needed for all unit tests that leverage positioning
  if (process.env.NODE_ENV === 'test') {
    targetWindow.ResizeObserver = class ResizeObserver {
      public observe() {
        // do nothing
      }
      public unobserve() {
        // do nothing
      }
      public disconnect() {
        // do nothing
      }
    };
  }

  return new targetWindow.ResizeObserver(callback);
}

/**
 * Promise microtask debouncer used by Popper.js v2
 * This is no longer exported in Floating UI (Popper.js v3)
 * https://github.com/floating-ui/floating-ui/blob/v2.x/src/utils/debounce.js
 * @param fn function that will be debounced
 */
export function debounce<T>(fn: Function): () => Promise<T> {
  let pending: Promise<T> | undefined;
  return () => {
    if (!pending) {
      pending = new Promise<T>(resolve => {
        Promise.resolve().then(() => {
          pending = undefined;
          resolve(fn());
        });
      });
    }

    return pending;
  };
}

