import type { Offset, OffsetObject } from '../types';

/**
 * Generally when adding an arrow to popper, it's necessary to offset the position of the popper by the
 * height of the arrow. A simple utility to merge a provided offset with an arrow height to return the final offset
 *
 * @internal
 * @param userOffset - The offset provided by the user
 * @param arrowHeight - The height of the arrow in px
 * @returns User offset augmented with arrow height
 */
export function mergeArrowOffset(userOffset: Offset | undefined | null, arrowHeight: number): Offset {
  if (typeof userOffset === 'number') {
    return addArrowOffset(userOffset, arrowHeight);
  }

  if (typeof userOffset === 'object' && userOffset !== null) {
    return addArrowOffset(userOffset, arrowHeight);
  }

  if (typeof userOffset === 'function') {
    return offsetParams => {
      const offset = userOffset(offsetParams);
      return addArrowOffset(offset, arrowHeight);
    };
  }

  return { mainAxis: arrowHeight };
}

const addArrowOffset = (offset: OffsetObject | number, arrowHeight: number): OffsetObject => {
  if (typeof offset === 'number') {
    return { mainAxis: offset + arrowHeight };
  }

  return { ...offset, mainAxis: (offset.mainAxis ?? 0) + arrowHeight };
};

import type { NormalizedAutoSize, PositioningOptions } from '../types';

/**
 * AutoSizes contains many options from historic implementation.
 * Now options 'always'/'height-always'/'width-always' are obsolete.
 * This function maps them to true/'height'/'width'
 */
export const normalizeAutoSize = (autoSize?: PositioningOptions['autoSize']): NormalizedAutoSize | false => {
  switch (autoSize) {
    case 'always':
    case true:
      return {
        applyMaxWidth: true,
        applyMaxHeight: true,
      };

    case 'width-always':
    case 'width':
      return {
        applyMaxWidth: true,
        applyMaxHeight: false,
      };

    case 'height-always':
    case 'height':
      return {
        applyMaxWidth: false,
        applyMaxHeight: true,
      };

    default:
      return false;
  }
};

import type { Side, Placement, Alignment } from '@floating-ui/dom';

/**
 * Parses Floating UI placement and returns the different components
 * @param placement - the floating ui placement (i.e. bottom-start)
 *
 * @returns side and alignment components of the placement
 */
export function parseFloatingUIPlacement(placement: Placement): { side: Side; alignment: Alignment } {
  const tokens = placement.split('-');
  return {
    side: tokens[0] as Side,
    alignment: tokens[1] as Alignment,
  };
}

