  const { count, compact = false, icon, max = 5, value } = props;

  const valueTextId = useId('rating-value-');
  const countTextId = useId('rating-count-');

  const state: RatingDisplayBaseState = {
    compact,
    icon,
    max,
    value,
    components: {
      root: 'div',
      valueText: 'span',
      countText: 'span',
