export interface SandboxContext {
  provider: 'codesandbox-cloud' | 'codesandbox-browser' | 'stackblitz-cloud';
  bundler: 'vite' | 'cra';
  storyExportToken: string;
  storyFile: string;
  dependencies: Record<string, string>;
  requiredDependencies: Record<string, string>;
  optionalDependencies: Record<string, string>;
  devDependencies: Record<string, string>;
}

interface ParametersConfig {
  optionalDependencies?: Record<string, string>;
  requiredDependencies?: Record<string, string>;
  devDependencies?: Record<string, string>;
  provider: 'codesandbox-cloud' | 'codesandbox-browser' | 'stackblitz-cloud';
  bundler: 'vite' | 'cra';
  transformFiles?: (files: Record<string, string>, ctx: SandboxContext) => Record<string, string>;
}

export interface ParametersExtension {
  exportToSandbox?: ParametersConfig;
  /**
   * Adds an "Open in new tab" button to each story in the Docs view.
   * Opens the story's iframe URL directly in a new browser tab, outside of the Storybook shell.
   *
   * @default true
   */
  openInNewTab?: boolean;
}

export interface PresetConfig {
  importMappings: import('@fluentui/babel-preset-storybook-full-source').BabelPluginOptions['importMappings'];
  storyGranularity?: import('@fluentui/babel-preset-storybook-full-source').BabelPluginOptions['storyGranularity'];
  webpackRule?: import('webpack').RuleSetRule;
  babelLoaderOptionsUpdater?: (value: import('@babel/core').TransformOptions) => typeof value;
  /**
   * When `true` (or a config object), enables CSS module auto-detection in the babel plugin:
   *  - Preserves `*.module.css` imports (rewriting paths to `./styles/<basename>`)
   *  - Auto-detects CSS module files on disk and injects `Story.parameters.cssModuleSources.cssModules`
   *  - If `tokensFilePath` is provided, reads the file and injects `Story.parameters.cssModuleSources.tokensSource`
   *
   * @default false
   */
  cssModules?: import('@fluentui/babel-preset-storybook-full-source').BabelPluginOptions['cssModules'];
}

import { getParameters } from 'codesandbox-import-utils/lib/api/define';

import { scaffold } from './sandbox-scaffold';
import { addHiddenInput, prepareData, prepareSandboxContainers, type Data } from './sandbox-utils';
import { StoryContext } from './types';

const defaultFileToPreview = encodeURIComponent('src/example.tsx');

// SVG icon: external link (box with arrow pointing upper-right), similar to Storybook's native "open in new tab" icon
const externalLinkIconSvg = `<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 14 14" width="14" height="14" fill="none" stroke="currentColor" stroke-width="1.2" stroke-linecap="round" stroke-linejoin="round" style="vertical-align: middle; margin-right: 4px;"><path d="M11 8.5v3a1 1 0 0 1-1 1H2.5a1 1 0 0 1-1-1V4a1 1 0 0 1 1-1H6"/><path d="M8.5 1.5H13v4.5"/><path d="M13 1.5 6.5 8"/></svg>`;

const actionConfig = {
  'codesandbox-cloud': {
    label: 'CodeSandbox',
    factory: (files: Record<string, string>, config: Data) => openCodeSandbox({ files, ...config }),
  },
  'codesandbox-browser': {
    label: 'CodeSandbox',
    factory: (files: Record<string, string>, config: Data) => openCodeSandbox({ files, ...config }),
  },
  'stackblitz-cloud': {
    label: 'Stackblitz',
    factory: (files: Record<string, string>, config: Data) => openStackblitz({ files, ...config }),
  },
};

export function addDemoActionButtons(context: StoryContext) {
  const config = prepareData(context);
  if (!config) {
    throw new Error('issues with data');
  }

  prepareSandboxContainers(context).forEach(({ container, cssClasses }) => {
    if (context.parameters.openInNewTab !== false) {
      addButton({
        container,
        classList: cssClasses,
        markerClass: 'with-open-in-new-tab-button',
        content: `${externalLinkIconSvg} Open in new tab`,
        onClick: () => {
          window.open(`./iframe.html?id=${encodeURIComponent(context.id)}&viewMode=story`, '_blank');
        },
      });
    }

    if (context.parameters.fullSourceIsRunnable === false || context.parameters.fullSourceUnsupportedImports?.length) {
      return;
    }

    const files = scaffold[config.bundler](config);
    const action = actionConfig[config.provider];

    addButton({
      container,
      classList: cssClasses,
      markerClass: 'with-code-sandbox-button',
      content: `${externalLinkIconSvg} Open in ${action.label}`,
      onClick: () => {
        action.factory(files, config);
      },
    });
  });
}

function addButton(options: {
  container: HTMLElement;
  classList: string[];
  markerClass: string;
  content: string;
  onClick: () => void;
}) {
  const { container, classList, markerClass, content, onClick } = options;
  const buttonClassList = classList.map(cls => (cls === 'with-code-sandbox-button' ? markerClass : cls));

  const button = document.createElement('button');
  button.classList.add(...buttonClassList);
  button.innerHTML = content;

  container.prepend(button);

  button.addEventListener('click', onClick);
}

/**
 *
 * @see https://developer.stackblitz.com/docs/platform/post-api/
 */
function openStackblitz(data: { files: Record<string, string> } & Data) {
  const { files, description, title } = data;
  const form = document.createElement('form');
  form.method = 'post';
  form.target = '_blank';
  form.action = `https://stackblitz.com/run?file=${defaultFileToPreview}`;
  // node template - boots web-container
  addHiddenInput(form, 'project[template]', 'node');
  addHiddenInput(form, 'project[title]', title);
  addHiddenInput(form, 'project[description]', `# ${description}`);

  Object.keys(files).forEach(key => {
    const value = files[key];
    addHiddenInput(form, `project[files][${key}]`, value);
  });

  document.body.appendChild(form);
  form.submit();
  document.body.removeChild(form);
}

/**
 *
 * @see https://codesandbox.io/docs/learn/sandboxes/cli-api#define-api
 */
function openCodeSandbox({ files, provider }: { files: Record<string, string> } & Data) {
  const normalizedFilesApi = Object.entries(files).reduce((acc, current) => {
    acc[current[0]] = { isBinary: false, content: current[1] };
    return acc;
  }, {} as Record<string, { content: string; isBinary: boolean }>);

  const env = provider === 'codesandbox-cloud' ? 'server' : 'browser';
  const parameters = getParameters({ files: normalizedFilesApi });

  const form = document.createElement('form');
  form.method = 'POST';
  form.target = '_blank';
  form.action = `https://codesandbox.io/api/v1/sandboxes/define?environment=${env}`;

  addHiddenInput(form, 'parameters', parameters);
  addHiddenInput(form, 'query', `file=${defaultFileToPreview}`);
  document.body.appendChild(form);
  form.submit();
  document.body.removeChild(form);
}

import dedent from 'dedent';

import type { SandboxContext } from './public-types';
import type { Data } from './sandbox-utils';
import { serializeJson } from './utils';

const commonDevDeps = { '@types/react': '^17', '@types/react-dom': '^17', typescript: '~4.7.0' };

export const scaffold = {
  vite: (data: Data): Record<string, string> => {
    if (data.provider === 'codesandbox-browser') {
      throw new Error('vite is not supported on codesandbox-browser');
    }

    const base: Record<string, string> = {
      'index.html': Vite.getHTML(),
      'src/App.tsx': Vite.getApp(data),
      'src/index.tsx': Vite.getRootIndex(),
      'src/example.tsx': Vite.getExample(data),
      'tsconfig.json': Vite.getTsconfig(),
      'tsconfig.node.json': Vite.getTsconfigNode(),
      'vite.config.ts': Vite.getViteCfg(),
      'package.json': Vite.getPkgJson(data),
    };
    if (data.provider === 'stackblitz-cloud') {
      Object.assign(base, getStackblitzConfig());
    }
    if (data.provider === 'codesandbox-cloud') {
      Object.assign(base, getCodesandboxConfig('vite'));
    }
    return applyTransform(base, data);
  },
  cra: (data: Data): Record<string, string> => {
    const base: Record<string, string> = {
      'public/index.html': CRA.getHTML(),
      'src/App.tsx': CRA.getApp(data),
      'src/index.tsx': CRA.getRootIndex(),
      'src/example.tsx': CRA.getExample(data),
      'tsconfig.json': CRA.getTsconfig(),
      'package.json': CRA.getPkgJson(data),
    };
    if (data.provider === 'stackblitz-cloud') {
      Object.assign(base, getStackblitzConfig());
    }
    if (data.provider === 'codesandbox-cloud') {
      Object.assign(base, getCodesandboxConfig('cra'));
    }

    return applyTransform(base, data);
  },
};

function applyTransform(base: Record<string, string>, data: Data): Record<string, string> {
  let files = base;

  // Auto-inject CSS module files when detected by the babel plugin.
  // This replaces the need for a manual `withCssModuleSource` + `transformFiles`
  // callback in every story meta.
  if (data.cssModuleSources?.cssModules?.length || data.cssModuleSources?.tokensSource) {
    files = applyCssModuleTransform(files, data);
  }

  if (!data.transformFiles) {
    return files;
  }
  const ctx: SandboxContext = {
    provider: data.provider,
    bundler: data.bundler,
    storyExportToken: data.storyExportToken,
    storyFile: data.storyFile,
    dependencies: data.dependencies,
    requiredDependencies: data.requiredDependencies,
    optionalDependencies: data.optionalDependencies,
    devDependencies: data.devDependencies,
  };
  return data.transformFiles(files, ctx);
}

/**
 * Generates sandbox files for auto-detected CSS modules:
 *   1. Places each CSS module (and optional `tokens.css`) under `src/styles/`.
 *   2. Rewrites relative `*.module.css` imports in `src/example.tsx` to `./styles/<basename>`.
 *   3. Prepends `import './styles/tokens.css'` to `src/App.tsx` so design tokens cascade.
 */
function applyCssModuleTransform(files: Record<string, string>, data: Data): Record<string, string> {
  const next = { ...files };
  const { cssModuleSources } = data;

  for (const mod of cssModuleSources?.cssModules ?? []) {
    next[`src/styles/${mod.name}`] = mod.source;
  }

  if (cssModuleSources?.tokensSource) {
    next['src/styles/tokens.css'] = cssModuleSources.tokensSource;
  }

  // Rewrite relative *.module.css imports to ./styles/<basename>
  const example = next['src/example.tsx'];
  if (typeof example === 'string') {
    next['src/example.tsx'] = example.replace(/(['"])\.\.?\/[^'"]+\.module\.css\1/g, match => {
      const quote = match[0];
      const basename = match.slice(1, -1).split('/').pop();
      return `${quote}./styles/${basename}${quote}`;
    });
  }

  // Prepend tokens import to App.tsx
  const app = next['src/App.tsx'];
  if (cssModuleSources?.tokensSource && typeof app === 'string' && !app.includes('./styles/tokens.css')) {
    next['src/App.tsx'] = `import './styles/tokens.css';\n${app}`;
  }

  return next;
}

