import * as React from 'react';
import { mergeClasses, useFluent, useMergedRefs, type ForwardRefComponent } from '@fluentui/react-components';

import type { PlaygroundSetupMetadata } from '../setup';
import type {
  PlaygroundRuntimeErrorKind,
  PlaygroundRuntimeMessage,
  ResolvedPlaygroundRuntimeManifest,
} from './runtime';
import { createSandboxDocument, type PlaygroundConsoleLevel } from './sandbox';
import { usePreviewStyles } from './Preview.styles';

export const PREVIEW_SANDBOX = 'allow-scripts';

export interface PreviewProps {
  code: string | null;
  requiredModules?: string[];
  runId: number;
  restartId?: number;
  preserveState?: boolean;
  paused?: boolean;
  themeId?: string;
  cssModules?: Array<{ name: string; specifier: string; locals: Record<string, string>; cssText: string }>;
  manifest: ResolvedPlaygroundRuntimeManifest;
  onMetadata: (metadata: PlaygroundSetupMetadata) => void;
  /** Called when the sandbox runtime fails to initialize, so it will never become ready. */
  onInitError?: (message: string) => void;
  onSuccess: (runId: number) => void;
  onError: (error: {
    kind: PlaygroundRuntimeErrorKind;
    message: string;
    runId: number;
    previewRetained?: boolean;
  }) => void;
  /** Fixed preview width in CSS pixels, e.g. to emulate a phone. Fills the pane when omitted. */
  frameWidth?: number;
  onConsole?: (entry: { level: PlaygroundConsoleLevel; message: string; runId: number }) => void;
  placeholder?: React.ReactNode;
  className?: string;
  style?: React.CSSProperties;
}

const SandboxFrame: ForwardRefComponent<PreviewProps> = React.forwardRef((props, ref) => {
  const {
    code,
    requiredModules,
    runId,
    preserveState,
    paused,
    themeId,
    cssModules,
    manifest,
    onMetadata,
    onInitError,
    onSuccess,
    onError,
    onConsole,
    className,
    style,
  } = props;
  const { targetDocument } = useFluent();
  const frameRef = React.useRef<HTMLIFrameElement | null>(null);
  const mergedRef = useMergedRefs(ref, frameRef);
  const readyRef = React.useRef(false);
  const postedRunRef = React.useRef<number | undefined>(undefined);
  // Live updates reuse this token; only replacing the iframe resets its environment.
  const [token] = React.useState(() => `${manifest.buildId}:${runId}:${Math.random().toString(36).slice(2)}`);
  const parentOrigin = targetDocument?.defaultView?.location.origin;
  const source = React.useMemo(
    // Opaque parents (e.g. `file:` URLs) report the origin "null", which cannot be targeted.
    () => createSandboxDocument(manifest, token, parentOrigin && parentOrigin !== 'null' ? parentOrigin : '*'),
    [manifest, parentOrigin, token],
  );

  React.useEffect(() => {
    readyRef.current = false;
  }, [token]);

  const postRun = React.useCallback(() => {
    if (!readyRef.current || !frameRef.current?.contentWindow) {
      return;
    }

    if (paused) {
      frameRef.current.contentWindow.postMessage({ source: 'fluentui-playground', token, type: 'invalidate' }, '*');
      return;
    }
    if (code === null || postedRunRef.current === runId) {
      return;
    }
    postedRunRef.current = runId;
    frameRef.current.contentWindow.postMessage(
      {
        source: 'fluentui-playground',
        token,
        type: 'run',
        code,
        requiredModules,
        cssModules,
        themeId,
        runId,
        preserveState,
      },
      '*',
    );
  }, [code, cssModules, paused, preserveState, requiredModules, runId, themeId, token]);

  React.useEffect(() => {
    const targetWindow = targetDocument?.defaultView;
    if (!targetWindow) {
      return;
    }

    const handleMessage = (event: MessageEvent<PlaygroundRuntimeMessage>) => {
      const message = event.data;
      if (
        event.source !== frameRef.current?.contentWindow ||
        message?.source !== 'fluentui-playground' ||
        message.token !== token
      ) {
        return;
      }

      if (message.type === 'ready') {
        readyRef.current = true;
        onMetadata(message.metadata);
        postRun();
      } else if (message.type === 'init-error') {
        onInitError?.(message.message);
      } else if (message.type === 'success' && message.runId === runId && !paused) {
        onSuccess(message.runId);
      } else if (message.type === 'error' && message.runId === runId && !paused) {
        onError(message);
      } else if (message.type === 'console') {
        onConsole?.({ level: message.level, message: message.message, runId: message.runId });
      }
    };

    targetWindow.addEventListener('message', handleMessage);
    return () => targetWindow.removeEventListener('message', handleMessage);
  }, [onConsole, onError, onInitError, onMetadata, onSuccess, paused, postRun, runId, targetDocument, token]);

  // Send the current run once its sandbox is ready.
  React.useEffect(() => {
    postRun();
  }, [postRun]);

  return (
    <iframe
      ref={mergedRef}
      title="Playground preview"
      // User code is evaluated with `new Function` inside this opaque-origin iframe. Do not add `allow-same-origin`.
      sandbox={PREVIEW_SANDBOX}
      srcDoc={source}
      className={className}
      style={style}
    />
  );
});
SandboxFrame.displayName = 'SandboxFrame';

/**
 * Reuse the opaque-origin sandbox and its loaded packages until the runtime build or explicit restart ID changes.
 */
export const Preview = React.forwardRef<HTMLDivElement, PreviewProps>((props, ref) => {
  const styles = usePreviewStyles();

  return (
    <div
      ref={ref}
      className={mergeClasses(styles.root, props.frameWidth !== undefined && styles.rootFixedWidth, props.className)}
    >
      <SandboxFrame
        {...props}
        key={`${props.manifest.buildId}:${props.restartId ?? 0}`}
        className={mergeClasses(styles.frame, props.frameWidth !== undefined && styles.frameFixedWidth)}
        style={props.frameWidth ? { width: `${props.frameWidth}px` } : undefined}
      />
      {props.code === null && props.placeholder ? <div className={styles.placeholder}>{props.placeholder}</div> : null}
    </div>
  );
});

Preview.displayName = 'Preview';

import type * as monacoApi from 'monaco-editor/esm/vs/editor/editor.api';

type Monaco = {
  languages: {
    typescript: {
      getTypeScriptWorker: typeof monacoApi.languages.typescript.getTypeScriptWorker;
      typescriptDefaults: Pick<monacoApi.languages.typescript.LanguageServiceDefaults, 'getDiagnosticsOptions'>;
    };
  };
};
type Diagnostic = monacoApi.languages.typescript.Diagnostic;

export const COMPILER_OPTIONS: monacoApi.languages.typescript.CompilerOptions = {
  // numeric enum values, see `monaco.languages.typescript.{JsxEmit,ModuleKind,ScriptTarget}`
  jsx: 4, // JsxEmit.ReactJSX -> emits `require("react/jsx-runtime")`, so stories don't need to import React for JSX
  module: 1, // ModuleKind.CommonJS -> `require()` calls are resolved against the dependency allowlist
  target: 6, // ScriptTarget.ES2019
  moduleResolution: 2, // ModuleResolutionKind.NodeJs -> resolves `file:///node_modules/**` extra libs, see `typings.ts`
  // ImportsNotUsedAsValues.Preserve -> unused value imports still emit `require()`, so importing a module that isn't
  // allowlisted is reported immediately instead of being silently elided. Its replacement, `verbatimModuleSyntax`,
  // rejects ESM syntax when emitting CommonJS, so keep the deprecated option until the runner consumes ESM.
  importsNotUsedAsValues: 1,
  ignoreDeprecations: '5.0',
  esModuleInterop: true,
  allowSyntheticDefaultImports: true,
  allowNonTsExtensions: true,
  allowJs: true,
  strict: false,
  isolatedModules: true,
  noEmitHelpers: false,
};

export interface CompileDiagnostic {
  message: string;
  line?: number;
  column?: number;
}

export interface CompileResult {
  code: string;
  diagnostics: CompileDiagnostic[];
}

function flattenMessage(messageText: Diagnostic['messageText']): string {
  if (typeof messageText === 'string') {
    return messageText;
  }

  const parts: string[] = [messageText.messageText];
  (messageText.next ?? []).forEach(next => parts.push(flattenMessage(next)));

  return parts.join('\n');
}

function toCompileDiagnostic(model: monacoApi.editor.ITextModel, diagnostic: Diagnostic): CompileDiagnostic {
  const result: CompileDiagnostic = { message: flattenMessage(diagnostic.messageText) };

  if (typeof diagnostic.start === 'number') {
    const position = model.getPositionAt(diagnostic.start);
    result.line = position.lineNumber;
    result.column = position.column;
  }

  return result;
}

/**
 * Transpiles the TSX content of provided model to CommonJS. Work happens inside Monaco's TypeScript web worker.
 */
export async function compile(monaco: Monaco, model: monacoApi.editor.ITextModel): Promise<CompileResult> {
  const defaults = monaco.languages.typescript.typescriptDefaults;
  const diagnosticsOptions = defaults.getDiagnosticsOptions();

  try {
    return await compileModel(monaco, model);
  } catch (error) {
    // Enabling semantic diagnostics when typings arrive disposes Monaco's worker, including pending emits.
    if (diagnosticsOptions === defaults.getDiagnosticsOptions()) {
      throw error;
    }
    return compileModel(monaco, model);
  }
}

async function compileModel(monaco: Monaco, model: monacoApi.editor.ITextModel): Promise<CompileResult> {
  const getWorker = await monaco.languages.typescript.getTypeScriptWorker();
  const worker = await getWorker(model.uri);
  const fileName = model.uri.toString();

  const [syntacticDiagnostics, emitOutput] = await Promise.all([
    worker.getSyntacticDiagnostics(fileName),
    worker.getEmitOutput(fileName),
  ]);

  const diagnostics = syntacticDiagnostics.map(diagnostic => toCompileDiagnostic(model, diagnostic));
  const jsOutput = emitOutput.outputFiles.find(file => file.name.endsWith('.js'));

  return {
    code: jsOutput?.text ?? '',
    diagnostics,
  };
}

export function formatDiagnostics(diagnostics: CompileDiagnostic[]): string {
  return diagnostics
    .map(diagnostic => {
      const location = diagnostic.line ? `(${diagnostic.line},${diagnostic.column}) ` : '';
      return `${location}${diagnostic.message}`;
    })
    .join('\n');
}

import type { PlaygroundConsoleLevel } from './sandbox';

export interface ConsoleEntry {
  id: number;
  level: PlaygroundConsoleLevel;
  message: string;
  /** Number of identical consecutive messages collapsed into this entry. */
  count: number;
}

export const MAX_CONSOLE_ENTRIES = 500;

/**
 * Appends a console message, collapsing it into the previous entry when it repeats and keeping the newest
 * {@link MAX_CONSOLE_ENTRIES} entries.
 */
export function appendConsoleEntry(
  entries: readonly ConsoleEntry[],
  next: { level: PlaygroundConsoleLevel; message: string },
  id: number,
): ConsoleEntry[] {
  const last = entries[entries.length - 1];
  if (last && last.level === next.level && last.message === next.message) {
    return [...entries.slice(0, -1), { ...last, count: last.count + 1 }];
  }

  const appended = [...entries, { id, level: next.level, message: next.message, count: 1 }];
  return appended.length > MAX_CONSOLE_ENTRIES ? appended.slice(appended.length - MAX_CONSOLE_ENTRIES) : appended;
}

export function countConsoleEntries(entries: readonly ConsoleEntry[], level: PlaygroundConsoleLevel): number {
  return entries.reduce((total, entry) => (entry.level === level ? total + entry.count : total), 0);
}

import postcss from 'postcss';

import type { CssModuleSource } from '../url';

export type { CssModuleSource };

export interface CompiledCssModule {
  name: string;
  /** Specifier used in transformed story source (`./styles/<basename>`). */
  specifier: string;
  locals: Record<string, string>;
  cssText: string;
}

export function cssModuleBasename(name: string): string {
  return name.replace(/^.*[/\\]/, '');
}

export function toCssModuleSpecifier(name: string): string {
  return `./styles/${cssModuleBasename(name)}`;
}

const HASH_MULTIPLIER = 31;
const HASH_MODULUS = 1_000_000_003;

function hashString(input: string): string {
  let hash = 0;
  for (let charIndex = 0; charIndex < input.length; charIndex += 1) {
    // Arbitrary non-cryptographic constants; the large prime modulus keeps deterministic class names short.
    // Collisions are possible but unlikely for story-scoped CSS module class names.
    hash = (hash * HASH_MULTIPLIER + input.charCodeAt(charIndex)) % HASH_MODULUS;
  }
  return hash.toString(36);
}

function findClosingParenthesis(selector: string, start: number): number {
  let depth = 1;

  for (let index = start; index < selector.length; index += 1) {
    const character = selector[index];
    if (character === '"' || character === "'") {
      const quote = character;
      index += 1;
      while (index < selector.length && selector[index] !== quote) {
        if (selector[index] === '\\') {
          index += 1;
        }
        index += 1;
      }
    } else if (selector.startsWith('/*', index)) {
      const commentEnd = selector.indexOf('*/', index + 2);
      index = commentEnd === -1 ? selector.length : commentEnd + 1;
    } else if (character === '(') {
      depth += 1;
    } else if (character === ')') {
      depth -= 1;
      if (depth === 0) {
        return index;
      }
    }
  }

  return -1;
}

function transformSelector(selector: string, getLocalClassName: (local: string) => string, localize = true): string {
  let result = '';

  for (let index = 0; index < selector.length; ) {
    const character = selector[index];
    if (character === '"' || character === "'") {
      const quote = character;
      const start = index;
      index += 1;
      while (index < selector.length && selector[index] !== quote) {
        index += selector[index] === '\\' ? 2 : 1;
      }
      index = Math.min(index + 1, selector.length);
      result += selector.slice(start, index);
    } else if (selector.startsWith('/*', index)) {
      const end = selector.indexOf('*/', index + 2);
      const next = end === -1 ? selector.length : end + 2;
      result += selector.slice(index, next);
      index = next;
    } else if (selector.startsWith(':global(', index)) {
      const contentStart = index + ':global('.length;
      const end = findClosingParenthesis(selector, contentStart);
      if (end === -1) {
        result += selector.slice(index);
        break;
      }
      result += transformSelector(selector.slice(contentStart, end), getLocalClassName, false);
      index = end + 1;
    } else if (localize && character === '.' && /[A-Za-z_]/.test(selector[index + 1] ?? '')) {
      let end = index + 2;
      while (/[\w-]/.test(selector[end] ?? '')) {
        end += 1;
      }
      const local = selector.slice(index + 1, end);
      result += `.${getLocalClassName(local)}`;
      index = end;
    } else {
      result += character;
      index += 1;
    }
  }

  return result;
}

/**
 * Compiles a CSS module the way Storybook's css-loader does in spirit: local class names are hashed,
 * `:global(...)` wrappers are stripped so the inner selector is injected as real CSS.
 */
export function compileCssModule(mod: CssModuleSource): CompiledCssModule {
  const basename = cssModuleBasename(mod.name);
  const id = basename.replace(/\.module\.css$/i, '').replace(/[^\w-]+/g, '_') || 'css';
  // File-scoped names survive declaration edits so live CSS updates need not remount React.
  const suffix = hashString(basename);
  // No prototype, so class names like `constructor` or `__proto__` are plain keys.
  const locals: Record<string, string> = Object.create(null);
  const getLocalClassName = (local: string) => {
    if (!Object.prototype.hasOwnProperty.call(locals, local)) {
      locals[local] = `${id}__${local}--${suffix}`;
    }
    return locals[local];
  };
  const root = postcss.parse(mod.source, { from: mod.name });
  root.walkRules(rule => {
    rule.selector = transformSelector(rule.selector, getLocalClassName);
  });

  return {
    name: basename,
    specifier: toCssModuleSpecifier(basename),
    locals,
    cssText: root.toString(),
  };
}

export function compileCssModules(mods: readonly CssModuleSource[]): CompiledCssModule[] {
  return mods.map(compileCssModule);
}

export function updateCssModuleSource(
  modules: readonly CssModuleSource[],
  name: string,
  source: string,
): CssModuleSource[] {
  return modules.map(mod => (mod.name === name ? { ...mod, source } : mod));
}

export function findCompiledCssModule(
  specifier: string,
  modules: readonly CompiledCssModule[],
): CompiledCssModule | undefined {
  const exact = modules.find(mod => mod.specifier === specifier);
  if (exact) {
    return exact;
  }

  const basename = cssModuleBasename(specifier);
  return modules.find(mod => cssModuleBasename(mod.specifier) === basename || mod.name === basename);
}

/**
 * Turns user input into a CSS module file name, e.g. `card` or `card.css` -> `card.module.css`.
 */
export function normalizeCssModuleName(input: string): string {
  const name = cssModuleBasename(input.trim());
  if (/\.module\.css$/i.test(name)) {
    return name;
  }

  return `${name.replace(/\.css$/i, '')}.module.css`;
}

/**
 * Returns why provided (normalized) CSS module name cannot be added, or `undefined` when it is valid.
 */
export function validateCssModuleName(name: string, modules: readonly CssModuleSource[]): string | undefined {
  if (!/^[\w-]+\.module\.css$/i.test(name)) {
    return 'Use letters, digits, "-" or "_", ending with .module.css.';
  }
  if (modules.some(mod => cssModuleBasename(mod.name).toLowerCase() === name.toLowerCase())) {
    return `${name} already exists.`;
  }

  return undefined;
}

export function getUniqueCssModuleName(modules: readonly CssModuleSource[], base = 'styles'): string {
  for (let index = 1; ; index++) {
    const name = `${base}${index === 1 ? '' : index}.module.css`;
    if (!validateCssModuleName(name, modules)) {
      return name;
    }
  }
}

export function createCssModuleSource(name: string): string {
  return `/* import styles from './${name}'; */\n.root {\n}\n`;
}

import type * as monacoApi from 'monaco-editor/esm/vs/editor/editor.api';

import type { ThemeOption } from './themes';

type Monaco = typeof monacoApi;

export const EDITOR_FONT_FAMILY =
  '"Cascadia Code", "JetBrains Mono", "Fira Code", "SF Mono", Menlo, Consolas, "Liberation Mono", monospace';

// Monaco only accepts hex colors; Fluent themes use hex for these tokens but some tokens are keywords ('transparent')
const HEX_COLOR = /^#[0-9a-f]{6}([0-9a-f]{2})?$/i;

interface SyntaxPalette {
  foreground: string;
  comment: string;
  keyword: string;
  stringLiteral: string;
  numberLiteral: string;
  type: string;
  identifier: string;
  delimiter: string;
  regexp: string;
  selection: string;
  lineHighlight: string;
  cursor: string;
  bracket1: string;
  bracket2: string;
  bracket3: string;
}

// Monaco token colors must be hex. Syntax highlighting has no Fluent semantic tokens (keyword / string /
// type), so these stay curated GitHub-inspired palettes. Editor chrome below uses resolved Theme values.
const LIGHT_PALETTE: SyntaxPalette = {
  foreground: '#1f2328',
  comment: '#6e7781',
  keyword: '#cf222e',
  stringLiteral: '#0a3069',
  numberLiteral: '#0550ae',
  type: '#953800',
  identifier: '#1f2328',
  delimiter: '#57606a',
  regexp: '#116329',
  selection: '#b6d6ff80',
  lineHighlight: '#f6f8fa',
  cursor: '#2f80ed',
  bracket1: '#0550ae',
  bracket2: '#8250df',
  bracket3: '#116329',
};

const DARK_PALETTE: SyntaxPalette = {
  foreground: '#e6edf3',
  comment: '#8b949e',
  keyword: '#ff7b72',
  stringLiteral: '#a5d6ff',
  numberLiteral: '#79c0ff',
  type: '#ffa657',
  identifier: '#e6edf3',
  delimiter: '#8b949e',
  regexp: '#7ee787',
  selection: '#3b82f660',
  lineHighlight: '#ffffff0a',
  cursor: '#7ab2ff',
  bracket1: '#79c0ff',
  bracket2: '#d2a8ff',
  bracket3: '#7ee787',
};

/**
 * Defines (or redefines) a Monaco theme for the given Fluent theme: the editor chrome uses the Fluent surface colors so
 * it blends in with the pane it lives in, syntax highlighting uses a curated palette per color scheme.
 *
 * @returns the Monaco theme name to pass to `editor.setTheme()`.
 */
export function defineEditorTheme(monaco: Monaco, option: ThemeOption): string {
  const { theme, dark } = option;
  const palette = dark ? DARK_PALETTE : LIGHT_PALETTE;
  const name = `fluent-${option.id}`;

  const colors: Record<string, string> = {
    'editor.background': theme.colorNeutralBackground1,
    'editor.foreground': palette.foreground,
    'editorGutter.background': theme.colorNeutralBackground1,
    'editorLineNumber.foreground': theme.colorNeutralForeground4,
    'editorLineNumber.activeForeground': theme.colorNeutralForeground2,
    'editor.lineHighlightBackground': palette.lineHighlight,
    'editor.lineHighlightBorder': palette.lineHighlight,
    'editor.selectionBackground': palette.selection,
    'editor.inactiveSelectionBackground': palette.selection,
    'editorCursor.foreground': palette.cursor,
    'editorIndentGuide.background': theme.colorNeutralStroke3,
    'editorIndentGuide.activeBackground': theme.colorNeutralStroke1,
    'editorBracketHighlight.foreground1': palette.bracket1,
    'editorBracketHighlight.foreground2': palette.bracket2,
    'editorBracketHighlight.foreground3': palette.bracket3,
    'editorWidget.background': theme.colorNeutralBackground1,
    'editorWidget.border': theme.colorNeutralStroke1,
    'editorSuggestWidget.background': theme.colorNeutralBackground1,
    'editorSuggestWidget.border': theme.colorNeutralStroke1,
    'editorSuggestWidget.selectedBackground': theme.colorNeutralBackground1Selected,
    'editorHoverWidget.background': theme.colorNeutralBackground1,
    'editorHoverWidget.border': theme.colorNeutralStroke1,
    'scrollbarSlider.background': theme.colorNeutralStroke1,
    'scrollbarSlider.hoverBackground': theme.colorNeutralStroke1Hover,
    'scrollbarSlider.activeBackground': theme.colorNeutralStroke1Pressed,
    focusBorder: theme.colorStrokeFocus2,
  };

  const rules: monacoApi.editor.ITokenThemeRule[] = [
    { token: '', foreground: palette.foreground.slice(1) },
    { token: 'comment', foreground: palette.comment.slice(1), fontStyle: 'italic' },
    { token: 'keyword', foreground: palette.keyword.slice(1) },
    { token: 'string', foreground: palette.stringLiteral.slice(1) },
    { token: 'number', foreground: palette.numberLiteral.slice(1) },
    { token: 'regexp', foreground: palette.regexp.slice(1) },
    { token: 'type.identifier', foreground: palette.type.slice(1) },
    { token: 'identifier', foreground: palette.identifier.slice(1) },
    { token: 'delimiter', foreground: palette.delimiter.slice(1) },
  ];

  monaco.editor.defineTheme(name, {
    base: dark ? 'vs-dark' : 'vs',
    inherit: true,
    rules,
    colors: Object.fromEntries(Object.entries(colors).filter(([, value]) => HEX_COLOR.test(value))),
  });

  return name;
}

export function getNextFileTabIndex(key: string, currentIndex: number, tabCount: number): number | null {
  switch (key) {
    case 'ArrowLeft':
      return (currentIndex - 1 + tabCount) % tabCount;
    case 'ArrowRight':
      return (currentIndex + 1) % tabCount;
    case 'Home':
      return 0;
    case 'End':
      return tabCount - 1;
    default:
      return null;
  }
}

import type * as monacoApi from 'monaco-editor/esm/vs/editor/editor.api';
import type { Options } from 'prettier';

type Monaco = typeof monacoApi;

/** Mirrors the repository `prettier.config.js`. */
export const PRETTIER_OPTIONS: Options = {
  printWidth: 120,
  tabWidth: 2,
  singleQuote: true,
  trailingComma: 'all',
  arrowParens: 'avoid',
};

export type FormatLanguage = 'typescript' | 'css';

/**
 * Formats TSX or CSS source with Prettier. Parsers are loaded on first use (separate chunks).
 */
export async function formatCode(code: string, language: FormatLanguage = 'typescript'): Promise<string> {
  if (language === 'css') {
    const [prettier, { default: postcssParser }] = await Promise.all([
      import(/* webpackChunkName: "prettier" */ 'prettier/standalone'),
      import(/* webpackChunkName: "prettier" */ 'prettier/parser-postcss'),
    ]);

    return prettier.format(code, { ...PRETTIER_OPTIONS, parser: 'css', plugins: [postcssParser] });
  }

  const [prettier, { default: typescriptParser }] = await Promise.all([
    import(/* webpackChunkName: "prettier" */ 'prettier/standalone'),
    import(/* webpackChunkName: "prettier" */ 'prettier/parser-typescript'),
  ]);

  return prettier.format(code, { ...PRETTIER_OPTIONS, parser: 'typescript', plugins: [typescriptParser] });
}

export interface FormatterOptions {
  /** Called when formatting fails, e.g. because of a syntax error. */
  onError?: (error: Error) => void;
}

function registerLanguageFormatter(
  monaco: Monaco,
  language: FormatLanguage,
  options: FormatterOptions,
): monacoApi.IDisposable {
  return monaco.languages.registerDocumentFormattingEditProvider(language, {
    displayName: 'Prettier',
    async provideDocumentFormattingEdits(model) {
      const text = model.getValue();

      try {
        const formatted = await formatCode(text, language);

        return formatted === text ? [] : [{ range: model.getFullModelRange(), text: formatted }];
      } catch (error) {
        options.onError?.(error instanceof Error ? error : new Error(String(error)));
        return [];
      }
    },
  });
}

/**
 * Registers Prettier as the document formatter for TypeScript and CSS (`Shift+Alt+F` / "Format Document").
 */
export function registerFormatter(monaco: Monaco, options: FormatterOptions = {}): monacoApi.IDisposable {
  const typescript = registerLanguageFormatter(monaco, 'typescript', options);
  const css = registerLanguageFormatter(monaco, 'css', options);

  return {
    dispose() {
      typescript.dispose();
      css.dispose();
    },
  };
}

import * as React from 'react';
import { canUseDOM } from '@fluentui/react-utilities';
import { createRoot } from 'react-dom/client';

import { readPlaygroundHash } from '../url';
import { Playground } from './Playground';
import { loadRuntimeManifest, resolveManifestPath } from './runtime';

if (!canUseDOM()) {
  throw new Error('Playground requires a browser environment');
}

const targetDocument = globalThis.document;
const targetWindow = targetDocument.defaultView;
const container = targetDocument.getElementById('root');

if (!container || !targetWindow) {
  throw new Error('Playground browser environment is incomplete');
}

/** Path to the Storybook-emitted runtime, relative to `playground/app/playground.html`. */
const DEFAULT_MANIFEST_PATH = '../runtime/manifest.json';

const manifestPath = resolveManifestPath(
  new URLSearchParams(targetWindow.location.search).get('manifest'),
  targetWindow.location.href,
  DEFAULT_MANIFEST_PATH,
);
const { state: initialState, issues: initialIssues } = readPlaygroundHash(targetWindow.location.hash);

loadRuntimeManifest(targetWindow, manifestPath).then(
  manifest => {
    createRoot(container).render(
      <React.StrictMode>
        <Playground
          initialCode={initialState?.code ?? null}
          initialCssModules={initialState?.cssModules}
          initialIssues={initialIssues}
          initialTitle={initialState?.title}
          manifest={manifest}
        />
      </React.StrictMode>,
    );
  },
  error => {
    container.textContent = error instanceof Error ? error.message : String(error);
  },
);

/**
 * Minimal Monaco setup: TypeScript language service + CSS tokenization.
 * CSS highlighting uses the basic language (no css.worker) so the shell stays small.
 */
import 'monaco-editor/esm/vs/editor/editor.all.js';
import 'monaco-editor/esm/vs/basic-languages/css/css.contribution.js';
import 'monaco-editor/esm/vs/basic-languages/typescript/typescript.contribution.js';
import 'monaco-editor/esm/vs/language/typescript/monaco.contribution.js';

import * as monaco from 'monaco-editor/esm/vs/editor/editor.api';

import { COMPILER_OPTIONS } from './compiler';

type MonacoGlobal = typeof globalThis & { MonacoEnvironment?: monaco.Environment };

const CANCELED = 'Canceled';

/**
 * Monaco cancels in-flight language feature requests (e.g. occurrence highlighting) when the editor switches models,
 * and some of those promises are never awaited. Such rejections are expected, so keep them out of the error console.
 */
export function isMonacoCancellation(reason: unknown): boolean {
  return reason instanceof Error && reason.name === CANCELED && reason.message === CANCELED;
}

globalThis.addEventListener?.('unhandledrejection', event => {
  if (isMonacoCancellation(event.reason)) {
    event.preventDefault();
  }
});

(globalThis as MonacoGlobal).MonacoEnvironment = {
  getWorker(_workerId: string, label: string) {
    // `name` doubles as the webpack chunk name, see `webpack.playground.config.js`
    if (label === 'typescript' || label === 'javascript') {
      return new Worker(new URL('monaco-editor/esm/vs/language/typescript/ts.worker.js', import.meta.url), {
        name: 'ts.worker',
      });
    }

    return new Worker(new URL('monaco-editor/esm/vs/editor/editor.worker.js', import.meta.url), {
      name: 'editor.worker',
    });
  },
};

monaco.languages.typescript.typescriptDefaults.setCompilerOptions(COMPILER_OPTIONS);
monaco.languages.typescript.typescriptDefaults.addExtraLib(
  `declare module '*.module.css' {
  const classes: { readonly [key: string]: string };
  export default classes;
}
`,
  'file:///playground/css-modules.d.ts',
);
// Type declarations of imported modules are loaded on demand by `TypingsLoader` (see `typings.ts`), which enables
// semantic validation once they are available - until then it would only report missing modules.
monaco.languages.typescript.typescriptDefaults.setDiagnosticsOptions({
  noSemanticValidation: true,
  noSyntaxValidation: false,
});
monaco.languages.typescript.typescriptDefaults.setEagerModelSync(true);

export { monaco };

import { getRequireSpecifier, scanTokens } from '../moduleScanner';

export interface PlaygroundErrorDiagnostic {
  message: string;
  line?: number;
  column?: number;
}

export class PlaygroundError extends Error {
  public kind: 'compile' | 'import' | 'runtime' | 'export';
  /** Source locations of compile errors. */
  public diagnostics?: PlaygroundErrorDiagnostic[];

  constructor(kind: PlaygroundError['kind'], message: string, diagnostics?: PlaygroundErrorDiagnostic[]) {
    super(message);
    this.name = 'PlaygroundError';
    this.kind = kind;
    this.diagnostics = diagnostics;
  }
}

/**
 * CSS imports are executed from story CSS modules encoded in the playground URL.
 * Other CSS files cannot be imported.
 */
export function isCssSpecifier(name: string): boolean {
  return /\.css$/i.test(name);
}

/**
 * Collects module specifiers from real `require()` calls in transpiled CommonJS code.
 * Unlike tools/collect-typings.js, this scans executable JavaScript instead of declarations, so it skips strings,
 * comments, and regex literals before preloading modules for the iframe runtime.
 * This is an early preload list; the sandboxed `require` shim also enforces the allowlist at execution time.
 */
export function getRequiredModules(code: string): string[] {
  const tokens = scanTokens(code);
  const modules = new Set<string>();
  for (let index = 0; index < tokens.length; index += 1) {
    const specifier = getRequireSpecifier(tokens, index);
    if (specifier !== undefined) {
      modules.add(specifier);
    }
  }

  return Array.from(modules);
}

/**
 * Throws when code imports anything that isn't part of the allowlist.
 */
export function assertAllowedModules(requested: string[], allowed: string[]): void {
  const notAllowed = requested.filter(name => !allowed.includes(name) && !isCssSpecifier(name));

  if (notAllowed.length === 0) {
    return;
  }

  const list = notAllowed.map(name => `"${name}"`).join(', ');
  throw new PlaygroundError(
    'import',
    `Cannot import ${list}. Only pre-installed dependencies are available in the playground:\n${allowed
      .map(name => `  - ${name}`)
      .join('\n')}`,
  );
}

import type { PlaygroundRuntimeManifest, PlaygroundSetupMetadata } from '../setup';
import type { PlaygroundConsoleLevel } from './sandbox';

export interface ResolvedPlaygroundRuntimeManifest extends PlaygroundRuntimeManifest {
  baseUrl: string;
  scripts: string[];
  styles: string[];
  typings: string;
}

export type PlaygroundRuntimeErrorKind = 'import' | 'runtime' | 'export';

export type PlaygroundRuntimeMessage =
  | {
      source: 'fluentui-playground';
      token: string;
      type: 'ready';
      metadata: PlaygroundSetupMetadata;
    }
  | {
      source: 'fluentui-playground';
      token: string;
      /** The runtime failed before registering, e.g. a setup module threw or a runtime script did not load. */
      type: 'init-error';
      message: string;
    }
  | {
      source: 'fluentui-playground';
      token: string;
      type: 'success';
      runId: number;
    }
  | {
      source: 'fluentui-playground';
      token: string;
      type: 'error';
      runId: number;
      kind: PlaygroundRuntimeErrorKind;
      message: string;
      previewRetained?: boolean;
    }
  | {
      source: 'fluentui-playground';
      token: string;
      type: 'console';
      level: PlaygroundConsoleLevel;
      /** Run that was active when the message was logged, `0` before the first run. */
      runId: number;
      message: string;
    };

/**
 * Resolves the `?manifest=` override (used to point a standalone shell at a Storybook runtime). Only same-origin
 * manifests are accepted, so a crafted link cannot load scripts and typings from another site.
 */
export function resolveManifestPath(requested: string | null, pageUrl: string, fallback: string): string {
  if (!requested) {
    return fallback;
  }

  try {
    const page = new URL(pageUrl);
    const resolved = new URL(requested, page);

    return resolved.origin === page.origin ? resolved.href : fallback;
  } catch {
    return fallback;
  }
}

/**
 * Fetches the Storybook-emitted playground runtime manifest and resolves asset URLs against the Storybook root.
 */
export async function loadRuntimeManifest(
  targetWindow: Window,
  manifestPath: string,
): Promise<ResolvedPlaygroundRuntimeManifest> {
  const manifestUrl = new URL(manifestPath, targetWindow.location.href);
  const response = await targetWindow.fetch(manifestUrl);

  if (!response.ok) {
    throw new Error(`Failed to load playground runtime (${response.status} ${response.statusText})`);
  }

  const manifest = (await response.json()) as PlaygroundRuntimeManifest;
  // `playground/app/playground.html` and `playground/runtime/manifest.json` are both two levels below Storybook root.
  const storybookRoot = new URL('../../', manifestUrl);

  return {
    ...manifest,
    baseUrl: storybookRoot.href,
    scripts: manifest.scripts.map(script => new URL(script, storybookRoot).href),
    styles: manifest.styles.map(style => new URL(style, storybookRoot).href),
    typings: new URL(manifest.typings, storybookRoot).href,
    moduleTypings: manifest.moduleTypings
      ? Object.fromEntries(
          Object.entries(manifest.moduleTypings).map(([moduleName, urls]) => [
            moduleName,
            urls.map(url => new URL(url, storybookRoot).href),
          ]),
        )
      : undefined,
  };
}

import type { ResolvedPlaygroundRuntimeManifest } from './runtime';

export const PLAYGROUND_REGISTER_CALLBACK = '__FLUENTUI_PLAYGROUND_REGISTER_V1__';

function escapeInlineJson(value: unknown): string {
  return JSON.stringify(value).replace(/</g, '\\u003c');
}

/** Maximum console messages forwarded per second; the rest are summarized so a logging loop cannot flood the shell. */
export const CONSOLE_MESSAGES_PER_SECOND = 100;
const CONSOLE_LEVELS = ['log', 'info', 'warn', 'error', 'debug'] as const;
export type PlaygroundConsoleLevel = (typeof CONSOLE_LEVELS)[number];

function getOrigin(url: string): string | undefined {
  try {
    const { origin } = new URL(url);
    return origin && origin !== 'null' ? origin : undefined;
  } catch {
    return undefined;
  }
}

/**
 * Content Security Policy for the preview document. The iframe origin is opaque, so `'self'` would match nothing:
 * trusted sources are the explicit origins that serve the Storybook runtime (scripts, lazy chunks, styles, fonts).
 * Inline and eval are required because the bootstrap is inline and user code runs through `new Function`. Network
 * access (`fetch`, XHR, WebSocket), nested frames, and form submissions to other origins are blocked. Images and media
 * may load from any HTTPS URL so examples can show avatars and pictures.
 */
export function createSandboxContentSecurityPolicy(manifest: ResolvedPlaygroundRuntimeManifest): string {
  const origins = Array.from(
    new Set(
      [manifest.baseUrl, manifest.typings, ...manifest.scripts, ...manifest.styles]
        .map(getOrigin)
        .filter((origin): origin is string => Boolean(origin)),
    ),
  ).join(' ');

  return [
    `default-src 'none'`,
    `script-src 'unsafe-inline' 'unsafe-eval' ${origins}`,
    `style-src 'unsafe-inline' ${origins}`,
    `font-src data: ${origins}`,
    `img-src data: blob: https: ${origins}`,
    `media-src data: blob: https: ${origins}`,
    `connect-src ${origins}`,
    `worker-src blob: ${origins}`,
    `base-uri ${origins}`,
    `form-action 'none'`,
    `frame-src 'none'`,
    `object-src 'none'`,
  ].join('; ');
}

function escapeHtmlAttribute(value: string): string {
  return value.replace(/&/g, '&amp;').replace(/"/g, '&quot;').replace(/</g, '&lt;');
}

/**
 * Builds the `srcDoc` for the sandboxed preview iframe. The bootstrap script registers a callback that the consumer
 * runtime entry invokes once React + module loaders + setup are available, then evaluates user code on `run` messages.
 *
 * @param parentOrigin - origin of the playground shell; messages to the parent are only delivered to this origin.
 */
export function createSandboxDocument(
  manifest: ResolvedPlaygroundRuntimeManifest,
  token: string,
  parentOrigin = '*',
): string {
  const bootstrap = `
(() => {
  const token = ${escapeInlineJson(token)};
  const callbackName = ${escapeInlineJson(PLAYGROUND_REGISTER_CALLBACK)};
  const parentOrigin = ${escapeInlineJson(parentOrigin)};
  let runtime;
  let root;
  let RenderBoundary;
  let activeRunId = 0;
  // Unlike activeRunId, this is not reset while the shell invalidates a run, so logs keep their version.
  let latestRunId = 0;
  let successfulRun;
  let moduleEffects = [];
  const nativeSetTimeout = window.setTimeout.bind(window);

  const send = message => parent.postMessage({
    source: 'fluentui-playground',
    token,
    ...message,
  }, parentOrigin);

  const formatValue = (value, depth, seen) => {
    if (typeof value === 'string') {
      return depth === 0 ? value : JSON.stringify(value);
    }
    if (typeof value === 'function') {
      return '[Function ' + (value.name || 'anonymous') + ']';
    }
    if (typeof value === 'bigint') {
      return value + 'n';
    }
    if (value === null || typeof value !== 'object') {
      return String(value);
    }
    if (value instanceof Error) {
      return value.name + ': ' + value.message;
    }
    if (typeof Node !== 'undefined' && value instanceof Node) {
      return value.nodeType === 1 ? '<' + value.nodeName.toLowerCase() + '>' : '[' + value.nodeName + ']';
    }
    if (seen.has(value)) {
      return '[Circular]';
    }
    if (depth >= 3) {
      return Array.isArray(value) ? '[Array]' : '[Object]';
    }
    seen.add(value);
    try {
      if (Array.isArray(value)) {
        const items = value.slice(0, 50).map(item => formatValue(item, depth + 1, seen));
        if (value.length > 50) {
          items.push('… ' + (value.length - 50) + ' more');
        }
        return '[' + items.join(', ') + ']';
      }
      const keys = Object.keys(value);
      const entries = keys.slice(0, 50).map(key => {
        let item;
        try {
          item = formatValue(value[key], depth + 1, seen);
        } catch (error) {
          item = '[Thrown: ' + formatValue(error, depth + 1, seen) + ']';
        }
        return key + ': ' + item;
      });
      if (keys.length > 50) {
        entries.push('… ' + (keys.length - 50) + ' more');
      }
      const name = value.constructor && value.constructor !== Object ? value.constructor.name + ' ' : '';
      return name + (entries.length ? '{ ' + entries.join(', ') + ' }' : '{}');
    } finally {
      seen.delete(value);
    }
  };

  const formatConsoleArgs = args => {
    const rest = Array.from(args);
    let text = '';
    if (typeof rest[0] === 'string' && /%[sdifoOc%]/.test(rest[0])) {
      const template = rest.shift();
      text = template.replace(/%([sdifoOc%])/g, (match, directive) => {
        if (directive === '%') {
          return '%';
        }
        if (rest.length === 0) {
          return match;
        }
        const value = rest.shift();
        if (directive === 'c') {
          return '';
        }
        if (directive === 'd' || directive === 'i') {
          return String(parseInt(value, 10));
        }
        if (directive === 'f') {
          return String(parseFloat(value));
        }
        return directive === 's' && typeof value === 'string' ? value : formatValue(value, 0, new Set());
      });
    }
    const parts = rest.map(value => formatValue(value, 0, new Set()));
    const message = (text ? [text, ...parts] : parts).join(' ');
    return message.length > 10000 ? message.slice(0, 10000) + '… (truncated)' : message;
  };

  let consoleWindowStart = 0;
  let consoleCount = 0;
  let suppressedConsole = 0;
  const flushSuppressedConsole = () => {
    if (suppressedConsole > 0) {
      send({
        type: 'console',
        level: 'warn',
        runId: latestRunId,
        message: suppressedConsole + ' console messages were not shown because the preview logged too quickly.',
      });
      suppressedConsole = 0;
    }
  };
  ${escapeInlineJson(CONSOLE_LEVELS)}.forEach(level => {
    const original = console[level];
    console[level] = function (...args) {
      original.apply(console, args);
      const now = Date.now();
      if (now - consoleWindowStart >= 1000) {
        consoleWindowStart = now;
        consoleCount = 0;
        flushSuppressedConsole();
      }
      if (++consoleCount > ${CONSOLE_MESSAGES_PER_SECOND}) {
        if (suppressedConsole++ === 0) {
          nativeSetTimeout(flushSuppressedConsole, 1000);
        }
        return;
      }
      try {
        send({ type: 'console', level, runId: latestRunId, message: formatConsoleArgs(args) });
      } catch (error) {
        // Formatting user values must never break the code that logged them.
      }
    };
  });

  // Timers and global listeners created while a module is evaluated belong to that module version. They are
  // disposed when a newer version replaces it, so live edits do not stack intervals or listeners.
  const collectModuleEffects = evaluate => {
    const effects = [];
    const patches = [
      [window, 'setTimeout', id => () => window.clearTimeout(id)],
      [window, 'setInterval', id => () => window.clearInterval(id)],
      [window, 'requestAnimationFrame', id => () => window.cancelAnimationFrame(id)],
    ].map(([target, name, dispose]) => {
      const original = target[name];
      target[name] = function (...args) {
        const id = original.apply(target, args);
        effects.push(dispose(id));
        return id;
      };
      return () => {
        target[name] = original;
      };
    });
    [window, document].forEach(target => {
      const original = target.addEventListener;
      target.addEventListener = function (type, listener, options) {
        original.call(target, type, listener, options);
        effects.push(() => target.removeEventListener(type, listener, options));
      };
      patches.push(() => {
        target.addEventListener = original;
      });
    });
    try {
      evaluate();
    } catch (error) {
      effects.forEach(dispose => dispose());
      throw error;
    } finally {
      patches.forEach(restore => restore());
    }
    return effects;
  };

  const formatError = error => (error instanceof Error ? error.name + ': ' + error.message : String(error));

  const sendError = (error, runId, previewRetained = false) => {
    if (runId !== activeRunId) {
      return;
    }
    send({
      type: 'error',
      runId,
      previewRetained,
      kind: error && error.kind ? error.kind : 'runtime',
      message: formatError(error),
    });
  };

  // Failures before the runtime registers (a setup module throwing, a runtime script failing to load) cannot be
  // attributed to a run; report the first one so the shell can stop waiting for "ready".
  let initFailed = false;
  const sendInitError = message => {
    if (runtime || initFailed) {
      return;
    }
    initFailed = true;
    send({ type: 'init-error', message });
  };

  const reportAsyncError = event => {
    const error = 'reason' in event ? event.reason : event.error || event.message;
    if (!runtime) {
      sendInitError(formatError(error));
      return;
    }
    if (!activeRunId) {
      return;
    }

    successfulRun = undefined;
    sendError(error, activeRunId);
  };

  window.addEventListener('error', reportAsyncError);
  window.addEventListener('unhandledrejection', reportAsyncError);
  // Resource load errors do not bubble, so listen in the capture phase.
  window.addEventListener(
    'error',
    event => {
      const target = event.target;
      if (target && target !== window && target.tagName === 'SCRIPT') {
        sendInitError('Failed to load the playground runtime script "' + target.src + '".');
      }
    },
    true,
  );

  const isComponentLike = value =>
    typeof value === 'function' ||
    (typeof value === 'object' && value !== null && '$$typeof' in value);

  const pickComponent = exports => {
    if (isComponentLike(exports.default)) {
      return exports.default;
    }
    if (isComponentLike(exports.Default)) {
      return exports.Default;
    }
    for (const [name, value] of Object.entries(exports)) {
      if (name !== '__esModule' && isComponentLike(value)) {
        return value;
      }
    }
    const error = new Error('Nothing to render. Export a component as default, Default, or another named export.');
    error.kind = 'export';
    throw error;
  };

  window[callbackName] = nextRuntime => {
    try {
      registerRuntime(nextRuntime);
    } catch (error) {
      runtime = undefined;
      sendInitError(formatError(error));
    }
  };

  const registerRuntime = nextRuntime => {
    runtime = nextRuntime;
    RenderBoundary = class extends runtime.React.Component {
      constructor(props) {
        super(props);
        this.state = { error: null };
      }

      static getDerivedStateFromError(error) {
        return { error };
      }

      componentDidCatch(error) {
        successfulRun = undefined;
        sendError(error, this.props.runId);
      }

      componentDidMount() {
        this.reportSuccess();
      }

      componentDidUpdate() {
        this.reportSuccess();
      }

      reportSuccess() {
        if (!this.state.error && this.props.runId === activeRunId) {
          successfulRun = this.props.run;
          send({ type: 'success', runId: this.props.runId });
        }
      }

      render() {
        return this.state.error ? null : this.props.children;
      }
    };
    const setup = runtime.setup || {};
    const metadata = {
      title: setup.title,
      subtitle: setup.subtitle,
      defaultCode: setup.defaultCode,
      themes: (setup.themes || []).map(theme => ({
        id: theme.id,
        label: theme.label,
        dark: theme.dark,
      })),
    };
    delete window[callbackName];
    send({ type: 'ready', metadata });
  };

  window.addEventListener('message', async event => {
    const message = event.data;
    if (
      event.source !== parent ||
      !message ||
      message.source !== 'fluentui-playground' ||
      message.token !== token ||
      !runtime
    ) {
      return;
    }

    if (message.type === 'invalidate') {
      activeRunId = 0;
      return;
    }
    if (message.type !== 'run') {
      return;
    }

    // Effects of a newly evaluated module version until they replace the current ones.
    let pendingModuleEffects;
    try {
      activeRunId = message.runId;
      latestRunId = message.runId;
      const previous = successfulRun;
      const cssLocals = JSON.stringify((message.cssModules || []).map(mod => [mod.specifier, mod.locals]));
      const reuseComponent = message.preserveState && previous &&
        previous.code === message.code && previous.cssLocals === cssLocals;
      const isCssSpecifier = name => /\\.css$/i.test(name);
      const cssModules = new Map((message.cssModules || []).map(mod => [mod.specifier, mod]));
      const findCssModule = name => {
        if (cssModules.has(name)) {
          return cssModules.get(name);
        }
        const basename = name.split('/').pop();
        for (const mod of cssModules.values()) {
          if (mod.name === basename || (mod.specifier && mod.specifier.split('/').pop() === basename)) {
            return mod;
          }
        }
        return undefined;
      };
      const requested = message.requiredModules || [];
      const allowedModules = runtime.allowedModules || Object.keys(runtime.moduleLoaders);
      const isAllowedModule = name =>
        allowedModules.includes(name) && Object.prototype.hasOwnProperty.call(runtime.moduleLoaders, name);
      const unavailable = requested.filter(name => !isAllowedModule(name) && !findCssModule(name));
      if (unavailable.length > 0) {
        const error = new Error('Cannot import ' + unavailable.map(name => '"' + name + '"').join(', ') + '.');
        error.kind = 'import';
        throw error;
      }

      const loaded = reuseComponent ? [] : await Promise.all(
        requested.filter(name => !findCssModule(name)).map(async name => [name, await runtime.moduleLoaders[name]()])
      );
      // A later edit can supersede a slow lazy import in the same iframe.
      if (message.runId !== activeRunId) {
        return;
      }
      const modules = new Map(loaded);

      const sandboxRequire = name => {
        if (typeof name !== 'string') {
          const error = new Error('Module specifier must be a string.');
          error.kind = 'import';
          throw error;
        }
        const cssModule = findCssModule(name);
        if (cssModule) {
          return Object.assign(Object.create(null), {
            __esModule: true,
            // Structured cloning restores Object.prototype; class names like "constructor" must not inherit.
            default: Object.assign(Object.create(null), cssModule.locals),
          }, cssModule.locals);
        }
        if (isCssSpecifier(name)) {
          const error = new Error('CSS module "' + name + '" is not available in this playground session.');
          error.kind = 'import';
          throw error;
        }
        if (!isAllowedModule(name) || !modules.has(name)) {
          const error = new Error('Module "' + name + '" is not available.');
          error.kind = 'import';
          throw error;
        }
        return modules.get(name);
      };
      let Component;
      if (reuseComponent) {
        Component = previous.Component;
      } else {
        const sandboxModule = { exports: Object.create(null) };
        // User code runs with sandbox-global access; isolation depends on Preview's opaque-origin iframe sandbox.
        const evaluate = new Function('require', 'exports', 'module', message.code);
        pendingModuleEffects = collectModuleEffects(() =>
          evaluate(sandboxRequire, sandboxModule.exports, sandboxModule),
        );
        Component = pickComponent(sandboxModule.exports);
      }

      const setup = runtime.setup || {};
      const selectedTheme = (setup.themes || []).find(theme => theme.id === message.themeId);
      const element = setup.render
        ? setup.render({ Component, theme: selectedTheme && selectedTheme.value })
        : runtime.React.createElement(Component);
      const nextRun = {
        Component,
        code: message.code,
        cssLocals,
        componentKey: reuseComponent ? previous.componentKey : message.runId,
      };
      const guardedElement = runtime.React.createElement(
        RenderBoundary,
        { key: nextRun.componentKey, runId: message.runId, run: nextRun },
        element,
      );

      // Evaluation/import errors leave the last successful DOM and styles untouched.
      document.querySelectorAll('style[data-playground-css]').forEach(node => node.remove());
      (message.cssModules || []).forEach(mod => {
        const style = document.createElement('style');
        style.setAttribute('data-playground-css', mod.specifier);
        style.textContent = mod.cssText;
        document.head.appendChild(style);
      });
      root = root || runtime.createRoot(document.getElementById('root'));
      root.render(guardedElement);
      if (pendingModuleEffects) {
        moduleEffects.forEach(dispose => dispose());
        moduleEffects = pendingModuleEffects;
        pendingModuleEffects = undefined;
      }
    } catch (error) {
      // A version that failed to render must not leave its timers and listeners running.
      if (pendingModuleEffects) {
        pendingModuleEffects.forEach(dispose => dispose());
      }
      sendError(error, message.runId, Boolean(successfulRun));
    }
  });
})();
`;
  const styles = manifest.styles.map(style => `<link rel="stylesheet" href=${escapeInlineJson(style)} />`).join('');
  const scripts = manifest.scripts.map(script => `<script src=${escapeInlineJson(script)}></script>`).join('');

  return `<!DOCTYPE html>
<html>
  <head>
    <meta charset="utf-8" />
    <meta http-equiv="Content-Security-Policy" content="${escapeHtmlAttribute(
      createSandboxContentSecurityPolicy(manifest),
    )}" />
    <meta name="viewport" content="width=device-width, initial-scale=1" />
    <base href=${escapeInlineJson(manifest.baseUrl)} />
    ${styles}
    <style>
      html, body, #root { min-height: 100%; margin: 0; }
      body { padding: 24px; box-sizing: border-box; }
    </style>
  </head>
  <body>
    <div id="root"></div>
    <script>${bootstrap}</script>
    ${scripts}
  </body>
</html>`;
}

/** `true` for macOS / iOS user agents, where Monaco binds `Cmd`/`Option` instead of `Ctrl`/`Alt`. */
export function isAppleDevice(userAgent: string): boolean {
  return /macintosh|mac os|iphone|ipad/i.test(userAgent);
}

/**
 * Keyboard shortcut of Monaco's built-in "Format Document" action for the current platform
 * (`editor.action.formatDocument`: Shift+Alt+F, but Ctrl+Shift+I on Linux).
 */
export function getFormatShortcutLabel(userAgent: string): string {
  if (isAppleDevice(userAgent)) {
    return 'Shift+Option+F';
  }
  if (/linux/i.test(userAgent) && !/android/i.test(userAgent)) {
    return 'Ctrl+Shift+I';
  }
  return 'Shift+Alt+F';
}

/** Keyboard shortcut of the playground "Run" action (`CtrlCmd+Enter`). */
export function getRunShortcutLabel(userAgent: string): string {
  return isAppleDevice(userAgent) ? 'Cmd+Enter' : 'Ctrl+Enter';
}

/** Keyboard shortcut of the playground "Save" action (`CtrlCmd+S`), which formats the code and updates the link. */
export function getSaveShortcutLabel(userAgent: string): string {
  return isAppleDevice(userAgent) ? 'Cmd+S' : 'Ctrl+S';
}

/** `true` for `Cmd+S` on Apple devices and `Ctrl+S` elsewhere, without other modifiers. */
export function isSaveShortcut(
  event: Pick<KeyboardEvent, 'key' | 'ctrlKey' | 'metaKey' | 'altKey' | 'shiftKey'>,
  userAgent: string,
): boolean {
  const primary = isAppleDevice(userAgent) ? event.metaKey && !event.ctrlKey : event.ctrlKey && !event.metaKey;

  return primary && !event.altKey && !event.shiftKey && event.key.toLowerCase() === 's';
}

