import type * as monacoApi from 'monaco-editor/esm/vs/editor/editor.api';

type Monaco = typeof monacoApi;

// `import … from '…'`, `export … from '…'`, `import '…'`, `import('…')` and `require('…')`
const MODULE_SPECIFIER_REGEX = /(?:\bfrom\s*|\bimport\s*\(\s*|\bimport\s+|\brequire\s*\(\s*)["']([^"'\n]+)["']/g;

/**
 * Module specifiers referenced by source code. A fast approximation (it also matches text in comments), which is
 * fine for deciding which declarations to prefetch.
 */
export function getImportedModules(source: string): string[] {
  const modules = new Set<string>();
  for (const match of source.matchAll(MODULE_SPECIFIER_REGEX)) {
    modules.add(match[1]);
  }

  return Array.from(modules);
}

/**
 * Fetches a typings file (URL from the Storybook-emitted runtime manifest).
 */
export async function fetchTypings(targetWindow: Window, typingsUrl: string): Promise<Record<string, string>> {
  const response = await targetWindow.fetch(typingsUrl);

  if (!response.ok) {
    throw new Error(`Failed to load type declarations (${response.status} ${response.statusText})`);
  }

  return response.json();
}

/**
 * Adds declaration files to Monaco's TypeScript worker. Adding libraries updates the running worker; files that are
 * already registered with the same content are skipped by Monaco.
 *
 * @returns number of registered declaration files
 */
export function addTypings(monaco: Monaco, typings: Record<string, string>): number {
  const entries = Object.entries(typings);
  const { typescriptDefaults } = monaco.languages.typescript;

  // `addExtraLib` notifies the worker asynchronously & debounced, so adding many files in a row syncs them only once
  entries.forEach(([filePath, content]) => {
    typescriptDefaults.addExtraLib(content, filePath);
  });

  return entries.length;
}

/**
 * Types are available, so type errors become meaningful. Changing diagnostics options restarts the worker, so this
 * runs once.
 */
export function enableSemanticValidation(monaco: Monaco): void {
  const { typescriptDefaults } = monaco.languages.typescript;
  if (typescriptDefaults.getDiagnosticsOptions().noSemanticValidation === false) {
    return;
  }

  typescriptDefaults.setDiagnosticsOptions({
    ...typescriptDefaults.getDiagnosticsOptions(),
    noSemanticValidation: false,
  });
}

export type TypingsStatus = 'loading' | 'ready' | 'error';

/**
 * Fetches each typings file at most once (including concurrent requests) and exposes the aggregate status as an
 * external store for `useSyncExternalStore`.
 */
export class TypingsLoader {
  private readonly requests = new Map<string, Promise<void>>();
  private readonly failed = new Set<string>();
  private readonly listeners = new Set<() => void>();
  private pending = 0;
  private status: TypingsStatus = 'loading';

  public constructor(private readonly monaco: Monaco, private readonly targetWindow: Window) {}

  public load(typingsUrl: string): Promise<void> {
    const existing = this.requests.get(typingsUrl);
    if (existing) {
      return existing;
    }

    this.pending++;
    this.failed.delete(typingsUrl);
    this._update();
    const request = fetchTypings(this.targetWindow, typingsUrl).then(
      typings => {
        addTypings(this.monaco, typings);
        this._settle();
      },
      (error: unknown) => {
        // a later request for the same file retries it (for example after a network hiccup)
        this.requests.delete(typingsUrl);
        this.failed.add(typingsUrl);
        this._settle();
        throw error;
      },
    );
    this.requests.set(typingsUrl, request);

    return request;
  }

  public subscribe = (listener: () => void): (() => void) => {
    this.listeners.add(listener);
    return () => this.listeners.delete(listener);
  };

  public getStatus = (): TypingsStatus => this.status;

  private _settle(): void {
    this.pending--;
    this._update();
  }

  private _update(): void {
    const status: TypingsStatus = this.pending > 0 ? 'loading' : this.failed.size > 0 ? 'error' : 'ready';
    if (status !== this.status) {
      this.status = status;
      this.listeners.forEach(listener => listener());
    }
  }
}

import * as React from 'react';
import { useFluent } from '@fluentui/react-components';

/** Tracks a CSS media query against the window that hosts the playground. */
export function useMediaQuery(query: string): boolean {
  const { targetDocument } = useFluent();
  const targetWindow = targetDocument?.defaultView;
  const [matches, setMatches] = React.useState(() => targetWindow?.matchMedia(query).matches ?? false);

  React.useEffect(() => {
    if (!targetWindow) {
      return;
    }

    const mediaQueryList = targetWindow.matchMedia(query);
    const update = () => setMatches(mediaQueryList.matches);
    update();
    mediaQueryList.addEventListener('change', update);

    return () => mediaQueryList.removeEventListener('change', update);
  }, [query, targetWindow]);

  return matches;
}

import * as React from 'react';
import type * as monacoApi from 'monaco-editor/esm/vs/editor/editor.api';

type MonacoMarkers = {
  editor?: Pick<typeof monacoApi.editor, 'getModelMarkers' | 'onDidChangeMarkers'>;
  MarkerSeverity?: Pick<typeof monacoApi.MarkerSeverity, 'Error'>;
};

const noop = () => undefined;
const getServerSnapshot = () => 0;

/**
 * Number of error markers (syntax and type errors) Monaco currently reports for provided model.
 */
export function useModelErrorCount(monaco: MonacoMarkers, model: monacoApi.editor.ITextModel | null): number {
  const { editor, MarkerSeverity } = monaco;

  const subscribe = React.useCallback(
    (onChange: () => void) => {
      if (!model || !editor) {
        return noop;
      }

      const uri = model.uri.toString();
      const subscription = editor.onDidChangeMarkers(uris => {
        if (uris.some(changed => changed.toString() === uri)) {
          onChange();
        }
      });
      return () => subscription.dispose();
    },
    [editor, model],
  );

  const getSnapshot = React.useCallback(
    () =>
      model && editor && MarkerSeverity
        ? editor.getModelMarkers({ resource: model.uri }).filter(marker => marker.severity === MarkerSeverity.Error)
            .length
        : 0,
    [MarkerSeverity, editor, model],
  );

  return React.useSyncExternalStore(subscribe, getSnapshot, getServerSnapshot);
}

import * as React from 'react';

export const SPLIT_MIN_PERCENT = 20;
export const SPLIT_MAX_PERCENT = 80;
export const SPLIT_DEFAULT_PERCENT = 50;
const SPLIT_KEYBOARD_STEP = 5;

export interface SplitPaneSeparatorProps {
  role: 'separator';
  'aria-orientation': 'vertical';
  'aria-valuemin': number;
  'aria-valuemax': number;
  'aria-valuenow': number;
  tabIndex: 0;
  onPointerDown: React.PointerEventHandler<HTMLElement>;
  onKeyDown: React.KeyboardEventHandler<HTMLElement>;
  onDoubleClick: React.MouseEventHandler<HTMLElement>;
}

export interface SplitPaneState {
  /** Width of the first pane in percent of the container. */
  percent: number;
  /** `true` while the separator is being dragged. */
  dragging: boolean;
  separatorProps: SplitPaneSeparatorProps;
}

function clamp(value: number): number {
  return Math.min(SPLIT_MAX_PERCENT, Math.max(SPLIT_MIN_PERCENT, value));
}

/**
 * Horizontal split between two panes, resizable by dragging the separator (pointer capture, so no document listeners
 * are needed) or with the keyboard (arrow keys, Home/End, Enter resets). Double-click resets the split as well.
 */
export function useSplitPane(containerRef: React.RefObject<HTMLElement | null>): SplitPaneState {
  const [percent, setPercent] = React.useState(SPLIT_DEFAULT_PERCENT);
  const [dragging, setDragging] = React.useState(false);

  const onPointerDown = React.useCallback(
    (event: React.PointerEvent<HTMLElement>) => {
      const container = containerRef.current;
      if (!container || event.button !== 0) {
        return;
      }

      event.preventDefault();
      const separator = event.currentTarget;
      const { left, width } = container.getBoundingClientRect();
      separator.setPointerCapture(event.pointerId);
      setDragging(true);

      const onMove = (moveEvent: PointerEvent) => {
        setPercent(clamp(((moveEvent.clientX - left) / width) * 100));
      };
      const onEnd = () => {
        separator.removeEventListener('pointermove', onMove);
        separator.removeEventListener('pointerup', onEnd);
        separator.removeEventListener('pointercancel', onEnd);
        setDragging(false);
      };

      separator.addEventListener('pointermove', onMove);
      separator.addEventListener('pointerup', onEnd);
      separator.addEventListener('pointercancel', onEnd);
    },
    [containerRef],
  );

  const onKeyDown = React.useCallback((event: React.KeyboardEvent<HTMLElement>) => {
    switch (event.key) {
      case 'ArrowLeft':
        setPercent(current => clamp(current - SPLIT_KEYBOARD_STEP));
        break;
      case 'ArrowRight':
        setPercent(current => clamp(current + SPLIT_KEYBOARD_STEP));
        break;
      case 'Home':
        setPercent(SPLIT_MIN_PERCENT);
        break;
      case 'End':
        setPercent(SPLIT_MAX_PERCENT);
        break;
      case 'Enter':
        setPercent(SPLIT_DEFAULT_PERCENT);
        break;
      default:
        return;
    }
    event.preventDefault();
  }, []);

  const onDoubleClick = React.useCallback(() => setPercent(SPLIT_DEFAULT_PERCENT), []);

  return {
    percent,
    dragging,
    separatorProps: {
      role: 'separator',
      'aria-orientation': 'vertical',
      'aria-valuemin': SPLIT_MIN_PERCENT,
      'aria-valuemax': SPLIT_MAX_PERCENT,
      'aria-valuenow': Math.round(percent),
      tabIndex: 0,
      onPointerDown,
      onKeyDown,
      onDoubleClick,
    },
  };
}

