export type { ParametersExtension };

import { compressToEncodedURIComponent } from 'lz-string';
import { type BoundedDecompressResult, decompressFromEncodedURIComponentBounded } from './lzString';

export const CODE_HASH_PARAM = 'code';
export const CSS_HASH_PARAM = 'css';
export const VERSION_HASH_PARAM = 'v';
export const TITLE_HASH_PARAM = 'title';
/**
 * Version of the hash payload format. Links without `v` predate versioning and are read as version 1. Bump it only for
 * changes that older playgrounds cannot read, and keep decoding every earlier version.
 */
export const PLAYGROUND_HASH_VERSION = 1;
/** Links longer than this may be truncated by chat apps, email clients, or browsers. */
export const RECOMMENDED_MAX_URL_LENGTH = 8000;
/**
 * Compressed payloads longer than this are rejected before decoding. It is far above
 * {@link RECOMMENDED_MAX_URL_LENGTH}, which links should stay under anyway.
 */
export const MAX_ENCODED_PAYLOAD_LENGTH = 200_000;
/**
 * Decoding stops once the decompressed code or styles would exceed this many characters. LZ payloads can expand
 * quadratically, so this, not {@link MAX_ENCODED_PAYLOAD_LENGTH}, bounds the work a crafted link can cause.
 */
export const MAX_DECODED_PAYLOAD_LENGTH = 1_000_000;
/** Longer titles are truncated. */
export const MAX_TITLE_LENGTH = 120;
/** Relative to Storybook's `iframe.html`: shell under `/playground/app`, runtime under `/playground/runtime`. */
export const PLAYGROUND_PATH = 'playground/app/playground.html';

export interface CssModuleSource {
  name: string;
  source: string;
}

export interface PlaygroundUrlState {
  code: string;
  cssModules: CssModuleSource[];
  /** Optional name of the example, e.g. the story it was opened from. */
  title?: string;
}

export interface PlaygroundHashIssue {
  kind: 'invalid-code' | 'invalid-css' | 'payload-too-large' | 'unsupported-version';
  message: string;
  version?: string;
}

export interface PlaygroundHashReadResult {
  /** `null` when the hash has no readable code. */
  state: PlaygroundUrlState | null;
  /** Payload problems users should know about, e.g. a truncated link. */
  issues: PlaygroundHashIssue[];
}

/**
 * Compresses source code into a URL safe string.
 */
export function encodeCode(code: string): string {
  return compressToEncodedURIComponent(code);
}

/**
 * Inverse of {@link encodeCode}. Returns `null` when the payload is missing or cannot be decoded.
 */
export function decodeCode(encoded: string): string | null {
  const decoded = decompressFromEncodedURIComponentBounded(encoded, MAX_DECODED_PAYLOAD_LENGTH);

  return decoded.ok ? decoded.value : null;
}

function parseCssModulesPayload(encoded: string): CssModuleSource[] | null | 'too-large' {
  const decoded = decompressFromEncodedURIComponentBounded(encoded, MAX_DECODED_PAYLOAD_LENGTH);
  if (!decoded.ok) {
    return decoded.reason === 'too-large' ? 'too-large' : null;
  }
  const json = decoded.value;
  if (!json) {
    return null;
  }

  try {
    const parsed: unknown = JSON.parse(json);
    if (!Array.isArray(parsed)) {
      return null;
    }

    return parsed.filter(
      (entry): entry is CssModuleSource =>
        Boolean(entry) && typeof entry.name === 'string' && typeof entry.source === 'string',
    );
  } catch {
    return null;
  }
}

/**
 * Reads the playground payload from a `location.hash` value (`#code=...&css=...&v=1`) and reports payload problems,
 * such as a truncated link, instead of silently dropping data.
 */
export function readPlaygroundHash(hash: string): PlaygroundHashReadResult {
  const params = new URLSearchParams(hash.replace(/^#/, ''));
  const issues: PlaygroundHashIssue[] = [];
  const version = params.get(VERSION_HASH_PARAM);
  if (version !== null && !(Number.isInteger(Number(version)) && Number(version) >= 1)) {
    issues.push({ kind: 'unsupported-version', version, message: `Unknown link format version "${version}".` });
  } else if (version !== null && Number(version) > PLAYGROUND_HASH_VERSION) {
    issues.push({
      kind: 'unsupported-version',
      version,
      message: `This link was created by a newer playground (format version ${version}) and may not open correctly.`,
    });
  }

  const encoded = params.get(CODE_HASH_PARAM);
  if (encoded === null) {
    return { state: null, issues };
  }

  if (encoded.length > MAX_ENCODED_PAYLOAD_LENGTH) {
    issues.push({ kind: 'payload-too-large', message: 'The code in this link is too large to open.' });
    return { state: null, issues };
  }

  const decodedCode: BoundedDecompressResult =
    encoded === ''
      ? { ok: true, value: '' }
      : decompressFromEncodedURIComponentBounded(encoded, MAX_DECODED_PAYLOAD_LENGTH);
  if (!decodedCode.ok && decodedCode.reason === 'too-large') {
    issues.push({ kind: 'payload-too-large', message: 'The code in this link is too large to open.' });
    return { state: null, issues };
  }
  const code = decodedCode.ok ? decodedCode.value : null;
  if (code === null) {
    issues.push({ kind: 'invalid-code', message: 'The code in this link could not be read. It may be truncated.' });
    return { state: null, issues };
  }

  const encodedCss = params.get(CSS_HASH_PARAM);
  let cssModules: CssModuleSource[] = [];
  if (encodedCss && encodedCss.length > MAX_ENCODED_PAYLOAD_LENGTH) {
    issues.push({ kind: 'payload-too-large', message: 'The styles in this link are too large to open.' });
  } else if (encodedCss) {
    const parsed = parseCssModulesPayload(encodedCss);
    if (parsed === 'too-large') {
      issues.push({ kind: 'payload-too-large', message: 'The styles in this link are too large to open.' });
    } else if (parsed === null) {
      issues.push({ kind: 'invalid-css', message: 'The styles in this link could not be read. It may be truncated.' });
    } else {
      cssModules = parsed;
    }
  }

  const title = normalizeTitle(params.get(TITLE_HASH_PARAM));

  return { state: title ? { code, cssModules, title } : { code, cssModules }, issues };
}

function normalizeTitle(title: string | null | undefined): string | undefined {
  // Strip control characters from untrusted link data.
  const normalized = title?.replace(/[\u0000-\u001f\u007f]+/g, ' ').trim();

  return normalized ? normalized.slice(0, MAX_TITLE_LENGTH) : undefined;
}

/**
 * Reads the playground payload from a `location.hash` value (`#code=...&css=...`).
 */
export function decodePlaygroundStateFromHash(hash: string): PlaygroundUrlState | null {
  return readPlaygroundHash(hash).state;
}

/**
 * Reads the code payload from a `location.hash` value (`#code=...`).
 */
export function decodeCodeFromHash(hash: string): string | null {
  return decodePlaygroundStateFromHash(hash)?.code ?? null;
}

/**
 * Creates a `location.hash` value for provided playground state.
 */
export function createPlaygroundHash(state: {
  code: string;
  cssModules?: readonly CssModuleSource[];
  title?: string;
}): string {
  let hash = `#${CODE_HASH_PARAM}=${encodeCode(state.code)}`;

  if (state.cssModules && state.cssModules.length > 0) {
    hash += `&${CSS_HASH_PARAM}=${encodeCode(JSON.stringify(state.cssModules))}`;
  }

  const title = normalizeTitle(state.title);
  if (title) {
    hash += `&${TITLE_HASH_PARAM}=${encodeURIComponent(title)}`;
  }

  return `${hash}&${VERSION_HASH_PARAM}=${PLAYGROUND_HASH_VERSION}`;
}

/**
 * Creates a `location.hash` value for provided code.
 */
export function createCodeHash(code: string): string {
  return createPlaygroundHash({ code });
}

/**
 * Creates the playground URL for provided code (and optional CSS modules from the story).
 *
 * The URL is relative to the Storybook preview (`iframe.html`), which lives next to the playground static dirs in the
 * Storybook root, so it also works when Storybook is deployed under a sub path.
 */
export function createPlaygroundUrl(
  code: string,
  baseUrl = `./${PLAYGROUND_PATH}`,
  cssModules?: readonly CssModuleSource[],
  title?: string,
): string {
  return `${baseUrl}${createPlaygroundHash({ code, cssModules, title })}`;
}

import * as crypto from 'node:crypto';
import * as fs from 'node:fs';
import * as path from 'node:path';

import type { PresetConfig } from './public-types';

type WebpackFinalFn = NonNullable<import('@storybook/react-webpack5').StorybookConfig['webpackFinal']>;
type WebpackFinalConfig = Parameters<WebpackFinalFn>[0];
type WebpackFinalOptions = Parameters<WebpackFinalFn>[1];
type CollectTypingsResult = {
  files: Record<string, string>;
  sources: string[];
  missing: string[];
};
type HtmlAssetsData = {
  assets: {
    js: string[];
    css: string[];
  };
};
type EntrypointFiles = {
  getFiles(): string[];
};
export type HtmlWebpackPluginConstructor = {
  getHooks(compilation: import('webpack').Compilation): {
    beforeAssetTagGeneration: {
      tap(name: string, callback: (data: HtmlAssetsData) => HtmlAssetsData): void;
    };
  };
};

export const ENTRY_NAME = 'playground-runtime';
export const REGISTER_CALLBACK = '__FLUENTUI_PLAYGROUND_REGISTER_V1__';
/** Global replaced at build time with the modules playground code can import, see `withOpenInPlaygroundButton`. */
export const ALLOWED_MODULES_DEFINE = '__FLUENTUI_PLAYGROUND_ALLOWED_MODULES__';
export const BUILT_IN_MODULES = ['react', 'react/jsx-runtime', 'react-dom', 'react-dom/client'];
const STALE_RUNTIME_ENTRY_MS = 24 * 60 * 60 * 1000;

const addonFilePattern = /react-storybook-addon-playground[\\/][a-z\\/]+\.[jt]s$/;
const defaultOptions: PresetConfig = {
  modules: {},
};

const { collectTypings, getMonacoTypeScriptVersion: readMonacoTypeScriptVersion } =
  require('../tools/collect-typings') as {
    collectTypings(options: {
      packageRoot: string;
      entries: string[];
      typescriptVersion: string;
    }): CollectTypingsResult;
    getMonacoTypeScriptVersion(): string;
  };

/**
 * Storybook preset hook: emits a separate Webpack entry for the playground runtime (configured modules + setup),
 * collects Monaco typings for those modules, and writes `playground/runtime/manifest.json`.
 */
export function webpackFinal(config: WebpackFinalConfig, options: WebpackFinalOptions): WebpackFinalConfig {
  const addonOptions = getAddonOptions(options);
  const runtimeEntry = writeRuntimeEntry(
    addonOptions,
    options.configDir ?? process.cwd(),
    options.configType === 'PRODUCTION',
  );
  const originalEntry = config.entry;

  config.entry = async (): Promise<import('webpack').EntryObject> => {
    const entry = typeof originalEntry === 'function' ? await originalEntry() : originalEntry;
    const normalizedEntry: import('webpack').EntryObject =
      !entry || typeof entry === 'string' || Array.isArray(entry) ? { main: entry ?? [] } : entry;

    return {
      ...normalizedEntry,
      [ENTRY_NAME]: runtimeEntry,
    };
  };

  config.plugins = config.plugins ?? [];
  config.plugins.push(new ExcludeRuntimeEntryFromHtmlPlugin());
  config.plugins.push(
    new PlaygroundRuntimeManifestPlugin(addonOptions, () => collectConfiguredTypings(addonOptions, options)),
  );
  config.plugins.push(new AllowedModulesDefinePlugin(getAllowedModules(addonOptions)));

  return config;
}

export function getModuleRequests(modules: PresetConfig['modules']): Record<string, string> {
  return Array.isArray(modules) ? Object.fromEntries(modules.map(name => [name, name])) : modules;
}

export function getAllowedModules(options: PresetConfig): string[] {
  return [...BUILT_IN_MODULES, ...Object.keys(getModuleRequests(options.modules))];
}

/**
 * Exposes the allowed modules to the Storybook preview, so the "Open in Playground" button is only shown for stories
 * that the playground can run.
 */
class AllowedModulesDefinePlugin {
  private readonly _allowedModules: string[];

  constructor(allowedModules: string[]) {
    this._allowedModules = allowedModules;
  }

  public apply(compiler: import('webpack').Compiler): void {
    new compiler.webpack.DefinePlugin({ [ALLOWED_MODULES_DEFINE]: JSON.stringify(this._allowedModules) }).apply(
      compiler,
    );
  }
}

/**
 * Storybook injects every Webpack entry into `iframe.html` by default. The playground runtime must only load inside
 * the sandboxed preview iframe.
 */
class ExcludeRuntimeEntryFromHtmlPlugin {
  public apply(compiler: import('webpack').Compiler): void {
    const pluginName = 'ExcludePlaygroundRuntimeFromHtmlPlugin';
    const htmlPluginConstructors = findHtmlWebpackPluginConstructors(compiler.options.plugins);

    compiler.hooks.compilation.tap(pluginName, compilation => {
      if (htmlPluginConstructors.length === 0) {
        compilation.warnings.push(
          new compiler.webpack.WebpackError(
            'Playground: HtmlWebpackPlugin was not found, so the playground runtime entry may be injected into ' +
              'Storybook pages. Please report this with your Storybook and html-webpack-plugin versions.',
          ),
        );
        return;
      }

      htmlPluginConstructors.forEach(htmlPluginConstructor => {
        htmlPluginConstructor.getHooks(compilation).beforeAssetTagGeneration.tap(pluginName, data => {
          return filterRuntimeEntryAssets(compilation.entrypoints, data);
        });
      });
    });
  }
}

/**
 * Finds the constructors of HtmlWebpackPlugin instances by their static `getHooks` API rather than only by class name,
 * which can differ when the plugin is bundled, subclassed or wrapped.
 */
export function findHtmlWebpackPluginConstructors(plugins: ReadonlyArray<unknown>): HtmlWebpackPluginConstructor[] {
  const constructors = new Set<HtmlWebpackPluginConstructor>();
  for (const plugin of plugins) {
    const constructor = (plugin as { constructor?: Partial<HtmlWebpackPluginConstructor> & { name?: string } } | null)
      ?.constructor;
    if (
      typeof constructor?.getHooks === 'function' &&
      (/HtmlWebpackPlugin/.test(constructor.name ?? '') || 'userOptions' in (plugin as object))
    ) {
      constructors.add(constructor as HtmlWebpackPluginConstructor);
    }
  }

  return Array.from(constructors);
}

export function filterRuntimeEntryAssets(
  entrypoints: ReadonlyMap<string, EntrypointFiles>,
  data: HtmlAssetsData,
): HtmlAssetsData {
  const runtimeFiles = new Set(entrypoints.get(ENTRY_NAME)?.getFiles() ?? []);
  const otherEntryFiles = new Set(
    Array.from(entrypoints.entries()).flatMap(([name, entrypoint]) =>
      name === ENTRY_NAME ? [] : entrypoint.getFiles(),
    ),
  );
  const exclusiveRuntimeFiles = Array.from(runtimeFiles).filter(file => !otherEntryFiles.has(file));

  data.assets.js = data.assets.js.filter(asset => !matchesAnyAsset(asset, exclusiveRuntimeFiles));
  data.assets.css = data.assets.css.filter(asset => !matchesAnyAsset(asset, exclusiveRuntimeFiles));

  return data;
}

function matchesAnyAsset(assetUrl: string, assetFiles: string[]): boolean {
  const normalizedUrl = assetUrl.split(/[?#]/, 1)[0].replace(/\\/g, '/');

  return assetFiles.some(file => {
    const normalizedFile = file.replace(/\\/g, '/');
    return normalizedUrl === normalizedFile || normalizedUrl.endsWith(`/${normalizedFile}`);
  });
}

/**
 * Storybook merges an addon's registration options into the options of its preset hooks. Older Storybook versions
 * only expose them through `presetsList`, which is used as a fallback.
 */
export function getAddonOptions(
  options: Pick<WebpackFinalOptions, 'presetsList'> & Partial<PresetConfig>,
): PresetConfig {
  if (options.modules && typeof options.modules === 'object') {
    return { ...defaultOptions, modules: options.modules, setup: options.setup, typings: options.typings };
  }

  const presetRegistration = options.presetsList?.find(preset => isPlaygroundAddonFile(preset.name));
  const addonOptions = presetRegistration?.options ?? {};

  return { ...defaultOptions, ...addonOptions };
}

export function isPlaygroundAddonFile(filePath: string): boolean {
  return addonFilePattern.test(filePath);
}

function getDefaultSetupPath(): string {
  // Compiled next to this file (`lib-commonjs/webpack.js` → `lib-commonjs/defaultSetup.js`)
  return require.resolve('./defaultSetup');
}

const unsafeScriptCharacters: Record<string, string> = {
  '<': '\\u003C',
  '>': '\\u003E',
  '/': '\\u002F',
  '\u2028': '\\u2028',
  '\u2029': '\\u2029',
};

/**
 * Serializes a string as a JavaScript string literal for generated source. On top of `JSON.stringify`, escapes
 * characters that could end a comment or script block, or a line in older engines.
 */
function toJsStringLiteral(value: string): string {
  return JSON.stringify(value).replace(/[<>/\u2028\u2029]/g, character => unsafeScriptCharacters[character]);
}

/**
 * Builds the playground runtime entry source.
 *
 * Production loads configured modules on demand so large packages (such as icons) do not execute on every run.
 * Development uses eager import() chunks: evaluation is still deferred until requested, but Webpack does not
 * create lazy-compilation proxies that need the separate-origin development server.
 */
export function buildRuntimeEntrySource(options: PresetConfig, lazyModules = false): string {
  const modules = Object.entries(getModuleRequests(options.modules));
  const setupPath = options.setup ?? getDefaultSetupPath();
  const moduleLoaders = modules
    .map(
      ([publicName, request], index) =>
        `${toJsStringLiteral(publicName)}: () => ${
          lazyModules
            ? `import(/* webpackChunkName: "playground-module-${index}" */ ${toJsStringLiteral(request)})`
            : `import(/* webpackMode: "eager" */ ${toJsStringLiteral(request)})`
        }`,
    )
    .join(',\n  ');

  return `
import * as React from 'react';
import * as ReactDOM from 'react-dom';
import * as ReactDOMClient from 'react-dom/client';
import * as ReactJsxRuntime from 'react/jsx-runtime';
import * as setupModule from ${toJsStringLiteral(setupPath)};
// This entry is \`.mjs\`: a default import of a CommonJS setup (such as the compiled default setup) would yield
// \`module.exports\` rather than its \`default\` export.
const setupExports = setupModule.default;
const setup = setupExports && setupExports.__esModule ? setupExports.default : setupExports;
const moduleLoaders = {
  react: () => Promise.resolve(React),
  'react/jsx-runtime': () => Promise.resolve(ReactJsxRuntime),
  'react-dom': () => Promise.resolve(ReactDOM),
  'react-dom/client': () => Promise.resolve(ReactDOMClient),
  ${moduleLoaders}
};
const allowedModules = Object.freeze(Object.keys(moduleLoaders));

const register = globalThis[${toJsStringLiteral(REGISTER_CALLBACK)}];
if (typeof register === 'function') {
  register({
    React,
    allowedModules,
    createRoot: ReactDOMClient.createRoot,
    moduleLoaders,
    setup,
  });
}
`.trimStart();
}

/**
 * Directory for the generated runtime entry: `node_modules/.cache` next to the Storybook config (like other build
 * caches), scoped by config directory so several Storybooks can share one `node_modules`.
 */
export function getRuntimeEntryDirectory(configDir: string): string {
  const scope = crypto.createHash('sha256').update(path.resolve(configDir)).digest('hex').slice(0, 8);
  for (let directory = path.resolve(configDir); ; directory = path.dirname(directory)) {
    const nodeModules = path.join(directory, 'node_modules');
    if (fs.existsSync(nodeModules)) {
      return path.join(nodeModules, '.cache', 'fluentui-playground-runtime', scope);
    }
    if (path.dirname(directory) === directory) {
      return path.join(configDir, '.cache', 'fluentui-playground-runtime');
    }
  }
}

function writeRuntimeEntry(options: PresetConfig, configDir: string, lazyModules: boolean): string {
  const source = buildRuntimeEntrySource(options, lazyModules);
  const hash = crypto.createHash('sha256').update(source).digest('hex').slice(0, 12);
  const directory = getRuntimeEntryDirectory(configDir);
  const fileName = `runtime-${hash}.mjs`;
  const filePath = path.join(directory, fileName);

  fs.mkdirSync(directory, { recursive: true });
  fs.writeFileSync(filePath, source, 'utf8');
  // Entries left by earlier option sets. Only old files are removed: a concurrent dev server or build of the same
  // Storybook may still reference its own recent entry.
  const staleBefore = Date.now() - STALE_RUNTIME_ENTRY_MS;
  for (const staleFile of fs.readdirSync(directory)) {
    const stalePath = path.join(directory, staleFile);
    if (/^runtime-[\da-f]+\.mjs$/.test(staleFile) && staleFile !== fileName) {
      try {
        if (fs.statSync(stalePath).mtimeMs < staleBefore) {
          fs.rmSync(stalePath, { force: true });
        }
      } catch {
        // Another process removed it first.
      }
    }
  }

  return filePath;
}

export type ConfiguredTypings = {
  /** React typings plus `typings` addon option entries: always loaded. */
  base: Record<string, string>;
  /** Declarations needed by several configured modules, loaded with any of them. */
  shared: Record<string, string>;
  /** Per configured module (public name), its declarations beyond `base` and `shared`: loaded when code imports it. */
  modules: Record<string, { files: Record<string, string>; usesShared: boolean }>;
  sources: string[];
  missing: string[];
};

export function collectConfiguredTypings(
  options: PresetConfig,
  storybookOptions: Pick<WebpackFinalOptions, 'configDir'>,
  typescriptVersion = getMonacoTypeScriptVersion(),
): ConfiguredTypings {
  const packageRoot = storybookOptions.configDir ?? process.cwd();
  const base = collectTypings({
    packageRoot,
    entries: [...BUILT_IN_MODULES, ...(options.typings ?? [])],
    typescriptVersion,
  });
  const sources = new Set(base.sources);
  const missing = new Set(base.missing);
  const collected: Record<string, Record<string, string>> = {};
  const usage = new Map<string, number>();

  for (const [publicName, request] of Object.entries(getModuleRequests(options.modules))) {
    const result = collectTypings({ packageRoot, entries: [request], typescriptVersion });
    const files: Record<string, string> = {};
    result.sources.forEach(source => sources.add(source));
    result.missing.forEach(value => missing.add(value));
    for (const [filePath, content] of Object.entries(result.files)) {
      if (!(filePath in base.files)) {
        files[filePath] = content;
        usage.set(filePath, (usage.get(filePath) ?? 0) + 1);
      }
    }

    if (publicName !== request) {
      files[`file:///node_modules/${publicName}/index.d.ts`] = `export * from ${JSON.stringify(
        request,
      )};\nexport { default } from ${JSON.stringify(request)};`;
      files[`file:///node_modules/${publicName}/package.json`] = JSON.stringify({
        name: publicName,
        types: './index.d.ts',
      });
    }

    collected[publicName] = files;
  }

  const shared: Record<string, string> = {};
  const modules: ConfiguredTypings['modules'] = {};
  for (const [publicName, files] of Object.entries(collected)) {
    const own: Record<string, string> = {};
    let usesShared = false;
    for (const [filePath, content] of Object.entries(files)) {
      if ((usage.get(filePath) ?? 0) > 1) {
        shared[filePath] = content;
        usesShared = true;
      } else {
        own[filePath] = content;
      }
    }
    modules[publicName] = { files: own, usesShared };
  }

  return { base: base.files, shared, modules, sources: Array.from(sources), missing: Array.from(missing) };
}

/**
 * The playground shell build records the TypeScript version of its bundled Monaco, so published installs do not need
 * `monaco-editor`. Monorepo development falls back to reading the installed `monaco-editor`.
 */
export function getMonacoTypeScriptVersion(
  metadataPath = path.join(__dirname, '..', 'dist', 'playground', 'playground-shell.json'),
): string {
  try {
    const { typescriptVersion } = JSON.parse(fs.readFileSync(metadataPath, 'utf8')) as { typescriptVersion?: unknown };
    if (typeof typescriptVersion === 'string' && /^\d+\.\d+\.\d+$/.test(typescriptVersion)) {
      return typescriptVersion;
    }
  } catch {
    // Not built yet: fall through.
  }

  return readMonacoTypeScriptVersion();
}

/**
 * Emits the runtime manifest and Monaco typings. Typings are collected on the first compilation and recollected when a
 * watch rebuild reports one of their source declaration files as modified or removed.
 */
export class PlaygroundRuntimeManifestPlugin {
  private _typings: ConfiguredTypings | undefined;
  private _typingsSources = new Set<string>();

  public constructor(
    private readonly options: PresetConfig,
    private readonly _collectTypings: () => ConfiguredTypings,
  ) {}

  public apply(compiler: import('webpack').Compiler): void {
    const pluginName = 'PlaygroundRuntimeManifestPlugin';
    const { Compilation, sources } = compiler.webpack;

    compiler.hooks.thisCompilation.tap(pluginName, compilation => {
      const changedFiles = [compiler.modifiedFiles, compiler.removedFiles];
      if (!this._typings || changedFiles.some(files => files && hasAny(files, this._typingsSources))) {
        this._typings = this._collectTypings();
        this._typingsSources = new Set(this._typings.sources);
      }
      const typings = this._typings;
      typings.sources.forEach(source => compilation.fileDependencies.add(source));

      compilation.hooks.processAssets.tap(
        {
          name: pluginName,
          stage: Compilation.PROCESS_ASSETS_STAGE_SUMMARIZE,
        },
        () => {
          if (typings.missing.length > 0) {
            // Missing declarations only limit editor IntelliSense; the runtime works without them.
            compilation.warnings.push(
              new Error(
                `Playground typings could not resolve: ${typings.missing
                  .map(value => JSON.stringify(value))
                  .join(', ')}. Install their declarations for full editor IntelliSense.`,
              ),
            );
          }

          const entrypoint = compilation.entrypoints.get(ENTRY_NAME);
          if (!entrypoint) {
            compilation.errors.push(new Error(`Playground runtime entry "${ENTRY_NAME}" was not emitted.`));
            return;
          }

          const files = entrypoint.getFiles();
          const scripts = files.filter(file => /\.m?js($|\?)/.test(file) && !file.includes('.hot-update.'));
          const styles = files.filter(file => /\.css($|\?)/.test(file) && !file.includes('.hot-update.'));
          const emitTypings = (declarations: Record<string, string>) => {
            const json = JSON.stringify(declarations);
            const hash = crypto.createHash('sha256').update(json).digest('hex').slice(0, 12);
            const file = `playground/runtime/typings.${hash}.json`;
            compilation.emitAsset(file, new sources.RawSource(json));
            return file;
          };
          const typingsFile = emitTypings(typings.base);
          const sharedFile = Object.keys(typings.shared).length > 0 ? emitTypings(typings.shared) : null;
          const moduleTypings = Object.fromEntries(
            Object.entries(typings.modules).map(([publicName, { files: declarations, usesShared }]) => [
              publicName,
              [
                ...(usesShared && sharedFile ? [sharedFile] : []),
                // Modules whose declarations are all shared (e.g. packages re-exported by a suite) need no own file
                ...(Object.keys(declarations).length > 0 ? [emitTypings(declarations)] : []),
              ],
            ]),
          );
          const buildId = crypto
            .createHash('sha256')
            .update(
              JSON.stringify({
                scripts,
                styles,
                modules: getModuleRequests(this.options.modules),
                typingsFile,
                moduleTypings,
              }),
            )
            .digest('hex')
            .slice(0, 12);

          compilation.emitAsset(
            'playground/runtime/manifest.json',
            new sources.RawSource(
              JSON.stringify(
                {
                  scripts,
                  styles,
                  typings: typingsFile,
                  moduleTypings,
                  allowedModules: getAllowedModules(this.options),
                  buildId,
                },
                null,
                2,
              ),
            ),
          );
        },
      );
    });
  }
}

function hasAny(files: ReadonlySet<string>, candidates: ReadonlySet<string>): boolean {
  const [smaller, larger] = files.size <= candidates.size ? [files, candidates] : [candidates, files];
  for (const file of smaller) {
    if (larger.has(file)) {
      return true;
    }
  }
  return false;
}

// @ts-check

const fs = require('fs');
const path = require('path');
const semver = require('semver');

/**
 * @typedef {{ kind: 'module' | 'path' | 'types', value: string }} Specifier
 * @typedef {{ files: Record<string, string>, sources: string[], missing: string[] }} CollectResult
 */

const VIRTUAL_ROOT = 'file:///node_modules';

// `import x from '…'`, `export … from '…'`, `import('…')`, `import x = require('…')`, `/// <reference path|types="…" />`
const SPECIFIER_REGEX =
  /(?:\bfrom\s*|\bimport\s*\(\s*|\bimport\s+|\brequire\s*\(\s*)["']([^"'\n]+)["']|\/\/\/\s*<reference\s+(path|types)\s*=\s*["']([^"'\n]+)["']/g;

// bare package specifier, optionally scoped and with a sub path
const PACKAGE_SPECIFIER_REGEX = /^(@[\w.-]+\/)?[\w.-]+(\/[\w.-]+)*$/;

/** @type {typeof import('typescript') | null | undefined} */
let typescriptModule;

/**
 * TypeScript is an optional peer: Storybook projects almost always have it, but typings collection must not fail
 * without it.
 *
 * @returns {typeof import('typescript') | null}
 */
function getTypeScript() {
  if (typescriptModule === undefined) {
    try {
      typescriptModule = require('typescript');
    } catch {
      typescriptModule = null;
    }
  }

  return typescriptModule ?? null;
}

/**
 * Extracts module specifiers and triple-slash references from a `.d.ts` file. Uses the TypeScript scanner when it
 * is available (it ignores specifier-like text in comments and strings, such as JSDoc examples) and falls back to a
 * regular expression.
 *
 * @param {string} content
 * @param {typeof import('typescript') | null} [ts]
 * @returns {Specifier[]}
 */
function getSpecifiers(content, ts = getTypeScript()) {
  if (ts) {
    const info = ts.preProcessFile(content, true, true);
    return [
      ...info.importedFiles.map(file => ({ kind: /** @type {const} */ ('module'), value: file.fileName })),
      ...info.referencedFiles.map(file => ({ kind: /** @type {const} */ ('path'), value: file.fileName })),
      ...info.typeReferenceDirectives.map(file => ({ kind: /** @type {const} */ ('types'), value: file.fileName })),
    ];
  }

  return getSpecifiersWithRegex(content);
}

/**
 * @param {string} content
 * @returns {Specifier[]}
 */
function getSpecifiersWithRegex(content) {
  /** @type {Specifier[]} */
  const result = [];

  for (const match of content.matchAll(SPECIFIER_REGEX)) {
    if (match[1] !== undefined) {
      result.push({ kind: 'module', value: match[1] });
    } else {
      result.push({ kind: /** @type {'path' | 'types'} */ (match[2]), value: match[3] });
    }
  }

  return result;
}

/**
 * Detects how a declaration file exposes a default export, so classic-resolution shims can forward it:
 * `'equals'` for `export =`, `'default'` for ES default exports, `null` when there is none.
 *
 * @param {string} content
 * @param {typeof import('typescript') | null} [ts]
 * @returns {'equals' | 'default' | null}
 */
function getDefaultExportKind(content, ts = getTypeScript()) {
  if (ts) {
    const sourceFile = ts.createSourceFile('entry.d.ts', content, ts.ScriptTarget.Latest, false, ts.ScriptKind.TS);
    /** @type {'equals' | 'default' | null} */
    let kind = null;
    for (const statement of sourceFile.statements) {
      if (ts.isExportAssignment(statement)) {
        if (statement.isExportEquals) {
          return 'equals';
        }
        kind = 'default';
      } else if (ts.isExportDeclaration(statement)) {
        const clause = statement.exportClause;
        if (clause && ts.isNamedExports(clause) && clause.elements.some(element => element.name.text === 'default')) {
          kind = 'default';
        }
      } else {
        // `getModifiers` was added in TypeScript 4.8, older versions expose `modifiers` directly.
        /** @type {readonly import('typescript').ModifierLike[] | undefined} */
        const modifiers = ts.getModifiers
          ? ts.canHaveModifiers(statement)
            ? ts.getModifiers(statement)
            : undefined
          : /** @type {any} */ (statement).modifiers;
        const kinds = (modifiers ?? []).map(modifier => modifier.kind);
        if (kinds.includes(ts.SyntaxKind.ExportKeyword) && kinds.includes(ts.SyntaxKind.DefaultKeyword)) {
          kind = 'default';
        }
      }
    }
    return kind;
  }

  const code = content.replace(/\/\*[\s\S]*?\*\/|\/\/[^\n]*/g, '');
  if (/\bexport\s*=/.test(code)) {
    return 'equals';
  }
  if (/\bexport\s+default\b/.test(code)) {
    return 'default';
  }
  for (const [, clause] of code.matchAll(/\bexport\s*\{([^}]*)\}/g)) {
    // `default` or `local as default`; the exported name is the last word
    if (clause.split(',').some(element => element.trim().split(/\s+/).pop() === 'default')) {
      return 'default';
    }
  }
  return null;
}

/**
 * Splits a module specifier into package name and sub path.
 *
 * @param {string} specifier
 */
function parseSpecifier(specifier) {
  const segments = specifier.split('/');
  const name = specifier.startsWith('@') ? segments.slice(0, 2).join('/') : segments[0];

  return { name, subpath: specifier.slice(name.length + 1) };
}

/**
 * `@scope/name` -> `@types/scope__name`
 *
 * @param {string} name
 */
function getTypesPackageName(name) {
  return `@types/${name.replace(/^@/, '').replace('/', '__')}`;
}

/**
 * Picks a types path from a package.json `exports` entry (string, conditions, or fallback list).
 *
 * @param {unknown} entry
 * @returns {string | null}
 */
function getTypesFromExportEntry(entry) {
  if (typeof entry === 'string') {
    return entry;
  }

  if (Array.isArray(entry)) {
    for (const candidate of entry) {
      const resolved = getTypesFromExportEntry(candidate);
      if (resolved) {
        return resolved;
      }
    }
    return null;
  }

  if (!entry || typeof entry !== 'object') {
    return null;
  }

  const conditions = /** @type {Record<string, unknown>} */ (entry);
  for (const condition of ['types', 'import', 'require', 'default']) {
    const resolved = getTypesFromExportEntry(conditions[condition]);
    if (resolved) {
      return resolved;
    }
  }

  return null;
}

/**
 * Resolves a types path from `package.json#exports` for `subpath` (`''` is `'.'`).
 *
 * @param {Record<string, any>} packageJson
 * @param {string} subpath
 * @returns {string | null}
 */
function getExportTypesPath(packageJson, subpath) {
  const exportsField = packageJson.exports;
  if (!exportsField) {
    return null;
  }

  if (typeof exportsField === 'string') {
    return subpath ? null : exportsField;
  }

  const key = subpath ? `./${subpath}` : '.';
  const typesPath = getTypesFromExportEntry(
    exportsField[key] ??
      (!subpath && !Object.keys(exportsField).some(exportKey => exportKey.startsWith('.')) ? exportsField : null),
  );
  return typesPath ? typesPath.replace(/^\.\//, '') : null;
}

/**
 * Resolves declarations only, never JavaScript implementations from runtime exports.
 *
 * @param {string} packageDir
 * @param {string} typesPath
 * @returns {string | null}
 */
function resolveTypesFile(packageDir, typesPath) {
  if (/\.d\.[cm]?ts$/.test(typesPath)) {
    return existingFile(path.join(packageDir, typesPath));
  }

  const withoutExt = typesPath.replace(/\.(d\.)?[cm]?[jt]sx?$/, '');
  const declarationExt = typesPath.endsWith('.mjs') ? '.d.mts' : typesPath.endsWith('.cjs') ? '.d.cts' : '.d.ts';

  return (
    existingFile(path.join(packageDir, `${withoutExt}${declarationExt}`)) ||
    existingFile(path.join(packageDir, `${withoutExt}.d.ts`)) ||
    existingFile(path.join(packageDir, `${withoutExt}.d.cts`)) ||
    existingFile(path.join(packageDir, `${withoutExt}.d.mts`)) ||
    existingFile(path.join(packageDir, withoutExt, 'index.d.ts'))
  );
}

/**
 * Applies `typesVersions` from package.json the same way TypeScript does (only `*` wildcards are supported).
 *
 * @param {{ typesVersions?: Record<string, Record<string, string[]>> }} packageJson
 * @param {string} relativePath
 * @param {string} typescriptVersion
 */
function applyTypesVersions(packageJson, relativePath, typescriptVersion) {
  const typesVersions = packageJson.typesVersions;
  if (!typesVersions) {
    return relativePath;
  }

  const matchingRange = Object.keys(typesVersions).find(range => semver.satisfies(typescriptVersion, range));
  if (!matchingRange) {
    return relativePath;
  }

  for (const [pattern, targets] of Object.entries(typesVersions[matchingRange])) {
    const star = pattern.indexOf('*');
    if (star === -1) {
      if (pattern === relativePath) {
        return targets[0];
      }
      continue;
    }

    const prefix = pattern.slice(0, star);
    const suffix = pattern.slice(star + 1);
    if (relativePath.startsWith(prefix) && relativePath.endsWith(suffix)) {
      const matched = relativePath.slice(prefix.length, relativePath.length - suffix.length);
      return targets[0].replaceAll('*', matched);
    }
  }

  return relativePath;
}

/**
 * @param {string} filePath
 * @returns {string | null}
 */
function existingFile(filePath) {
  try {
    return fs.statSync(filePath).isFile() ? filePath : null;
  } catch {
    return null;
  }
}

/**
 * @param {string} filePath
 * @returns {Record<string, any>}
 */
function readJson(filePath) {
  return JSON.parse(fs.readFileSync(filePath, 'utf8'));
}

/**
 * Collects the transitive closure of type declaration files needed to type-check code importing `entries`.
 *
 * Every file gets a virtual path `file:///node_modules/<package>/<relative path>` so that TypeScript's node module
 * resolution works when the files are registered as Monaco extra libs.
 *
 * @param {{ packageRoot: string, entries: string[], typescriptVersion: string }} options
 * @returns {CollectResult}
 */
function collectTypings(options) {
  const { entries, typescriptVersion } = options;
  const packageRoot = path.resolve(options.packageRoot);

  /** @type {Record<string, string>} */
  const files = {};
  /** @type {Set<string>} */
  const sources = new Set();
  /** @type {Set<string>} */
  const missing = new Set();
  /** @type {Map<string, { dir: string, name: string, packageJson: Record<string, any> } | null>} */
  const packages = new Map();

  /**
   * @param {string} name
   * @param {string} fromDir
   */
  function findPackageDir(name, fromDir) {
    let dir = fromDir;
    while (true) {
      const candidate = path.join(dir, 'node_modules', name);
      if (existingFile(path.join(candidate, 'package.json'))) {
        return fs.realpathSync(candidate);
      }
      const parent = path.dirname(dir);
      if (parent === dir) {
        return null;
      }
      dir = parent;
    }
  }

  /**
   * Resolves the package providing types for `name` (and `subpath`): the package itself when it ships types for the
   * root or the requested subpath, `@types/*` otherwise.
   *
   * @param {string} name
   * @param {string} fromDir
   * @param {string} [subpath]
   */
  function getPackage(name, fromDir, subpath = '') {
    const cacheKey = `${name}\0${subpath}`;
    const cached = packages.get(cacheKey);
    if (cached !== undefined) {
      return cached;
    }

    /** @param {string} dir */
    const load = dir => {
      const packageJson = readJson(path.join(dir, 'package.json'));
      return { dir, name: packageJson.name, packageJson };
    };

    const ownDir = findPackageDir(name, fromDir);
    const own = ownDir ? load(ownDir) : null;
    const hasOwnTypes =
      own &&
      (own.packageJson.types ||
        own.packageJson.typings ||
        existingFile(path.join(own.dir, 'index.d.ts')) ||
        resolveEntryFile(own, '') ||
        (subpath && resolveEntryFile(own, subpath)));

    let result = hasOwnTypes ? own : null;
    if (!result && !name.startsWith('@types/')) {
      const typesDir = findPackageDir(getTypesPackageName(name), fromDir);
      result = typesDir ? load(typesDir) : null;
    }

    packages.set(cacheKey, result);
    return result;
  }

  /**
   * @param {{ dir: string, name: string }} pkg
   * @param {string} realFile
   */
  function toVirtualPath(pkg, realFile) {
    return `${VIRTUAL_ROOT}/${pkg.name}/${path.relative(pkg.dir, realFile).split(path.sep).join('/')}`;
  }

  /**
   * Registers a trimmed package.json so TypeScript can read `types`/`typesVersions`.
   *
   * @param {{ dir: string, name: string, packageJson: Record<string, any> }} pkg
   * @param {string} packageJsonPath
   */
  function addPackageJson(pkg, packageJsonPath) {
    const virtualPath = toVirtualPath(pkg, packageJsonPath);
    if (files[virtualPath]) {
      return;
    }

    const json = packageJsonPath === path.join(pkg.dir, 'package.json') ? pkg.packageJson : readJson(packageJsonPath);
    files[virtualPath] = JSON.stringify({
      name: json.name,
      types: json.types || json.typings,
      typesVersions: json.typesVersions,
    });
    sources.add(packageJsonPath);
  }

  /**
   * Resolves a types path, preferring the `typesVersions` mapping for Monaco's bundled TypeScript
   * (`@types/react` 19 ships current types plus a `ts5.0/` tree for TS <= 5.0).
   *
   * @param {{ dir: string, packageJson: Record<string, any> }} pkg
   * @param {string} relativePath
   * @returns {string | null}
   */
  function resolveVersionedTypesFile(pkg, relativePath) {
    const normalized = relativePath.replace(/^\.\//, '');
    const mapped = applyTypesVersions(pkg.packageJson, normalized, typescriptVersion);

    return resolveTypesFile(pkg.dir, mapped) || (mapped !== normalized ? resolveTypesFile(pkg.dir, normalized) : null);
  }

  /**
   * @param {{ dir: string, name: string, packageJson: Record<string, any> }} pkg
   * @param {string} subpath
   */
  function resolveEntryFile(pkg, subpath) {
    const exportTypesPath = getExportTypesPath(pkg.packageJson, subpath);
    if (exportTypesPath) {
      const fromExports = resolveVersionedTypesFile(pkg, exportTypesPath);
      if (fromExports) {
        return fromExports;
      }
    }

    if (!subpath) {
      const entry = (pkg.packageJson.types || pkg.packageJson.typings || 'index.d.ts').replace(/^\.\//, '');
      return resolveVersionedTypesFile(pkg, entry);
    }

    const mapped = applyTypesVersions(pkg.packageJson, subpath, typescriptVersion);
    const direct = resolveVersionedTypesFile(pkg, subpath);
    if (direct) {
      return direct;
    }

    // sub path package (e.g. `@fluentui/react-components/unstable/package.json`)
    const subPackageJsonPath = path.join(pkg.dir, mapped, 'package.json');
    if (existingFile(subPackageJsonPath)) {
      const subPackageJson = readJson(subPackageJsonPath);
      const entry = subPackageJson.types || subPackageJson.typings;
      if (entry) {
        addPackageJson(pkg, subPackageJsonPath);
        return resolveTypesFile(path.join(pkg.dir, mapped), entry);
      }
    }

    return null;
  }

  /**
   * Monaco's TypeScript uses classic node resolution (`pkg/button` -> `pkg/button.d.ts`).
   * When types actually live at an `exports` path like `dist/button.d.ts`, add a shim at the classic location.
   *
   * @param {{ dir: string, name: string }} pkg
   * @param {string} subpath
   * @param {string} entryFile
   */
  function addSubpathShim(pkg, subpath, entryFile) {
    const relativeEntry = path.relative(pkg.dir, entryFile).split(path.sep).join('/');
    const shimRelativePath = subpath ? `${subpath}.d.ts` : 'index.d.ts';
    if (relativeEntry === shimRelativePath || relativeEntry === `${subpath}/index.d.ts`) {
      return;
    }

    const virtualPath = `${VIRTUAL_ROOT}/${pkg.name}/${shimRelativePath}`;
    if (files[virtualPath]) {
      return;
    }

    const importPath = relativeEntry.replace(/\.d\.[cm]?ts$/, '');
    const fromDir = path.posix.dirname(shimRelativePath);
    let relImport = path.posix.relative(fromDir, importPath);
    if (!relImport.startsWith('.')) {
      relImport = `./${relImport}`;
    }

    const target = JSON.stringify(relImport);
    // `export *` never re-exports a default export, forward it explicitly.
    switch (getDefaultExportKind(files[toVirtualPath(pkg, entryFile)] ?? fs.readFileSync(entryFile, 'utf8'))) {
      case 'equals':
        files[virtualPath] = `import entry = require(${target});\nexport = entry;\n`;
        break;
      case 'default':
        files[virtualPath] = `export * from ${target};\nexport { default } from ${target};\n`;
        break;
      default:
        files[virtualPath] = `export * from ${target};\n`;
    }
  }

  /**
   * @param {string} specifier
   * @param {string} fromDir
   */
  function addModule(specifier, fromDir) {
    if (!PACKAGE_SPECIFIER_REGEX.test(specifier)) {
      // regex false positive (e.g. `from '…'` inside a doc comment)
      return;
    }

    const { name, subpath } = parseSpecifier(specifier);
    const pkg = getPackage(name, fromDir, subpath);
    if (!pkg) {
      missing.add(specifier);
      return;
    }

    addPackageJson(pkg, path.join(pkg.dir, 'package.json'));

    const entryFile = resolveEntryFile(pkg, subpath);
    if (entryFile) {
      addFile(pkg, entryFile);
      if (subpath || (!pkg.packageJson.types && !pkg.packageJson.typings)) {
        addSubpathShim(pkg, subpath, entryFile);
      }
    } else {
      missing.add(specifier);
    }
  }

  /**
   * @param {{ dir: string, name: string, packageJson: Record<string, any> }} pkg
   * @param {string} realFile
   */
  function addFile(pkg, realFile) {
    const virtualPath = toVirtualPath(pkg, realFile);
    if (files[virtualPath] !== undefined) {
      return;
    }

    const content = fs.readFileSync(realFile, 'utf8');
    files[virtualPath] = content;
    sources.add(realFile);

    const dir = path.dirname(realFile);
    for (const specifier of getSpecifiers(content)) {
      if (specifier.kind === 'types') {
        addModule(specifier.value, dir);
      } else if (specifier.kind === 'path' || specifier.value.startsWith('.')) {
        const target = resolveTypesFile(dir, specifier.value);

        if (target) {
          addFile(pkg, target);
        }
        // unresolved relative specifiers are almost always regex false positives inside doc comments
      } else {
        addModule(specifier.value, dir);
      }
    }
  }

  entries.forEach(entry => addModule(entry, packageRoot));

  return { files, sources: Array.from(sources), missing: Array.from(missing) };
}

/**
 * Reads the TypeScript version bundled with `monaco-editor`, which decides the `typesVersions` branch to collect.
 *
 * @param {string} [contributionPath]
 * @returns {string}
 */
function getMonacoTypeScriptVersion(
  contributionPath = require.resolve('monaco-editor/esm/vs/language/typescript/monaco.contribution.js'),
) {
  const match = fs.readFileSync(contributionPath, 'utf8').match(/typescriptVersion\s*=\s*["'](\d+\.\d+\.\d+)["']/);
  if (!match) {
    throw new Error('Unable to detect the TypeScript version bundled with monaco-editor');
  }

  return match[1];
}

module.exports = {
  collectTypings,
  getMonacoTypeScriptVersion,
  getSpecifiers,
  getSpecifiersWithRegex,
  getDefaultExportKind,
  parseSpecifier,
  applyTypesVersions,
  getExportTypesPath,
  VIRTUAL_ROOT,
};

