import { useCustomStyleHook_unstable } from '@fluentui/react-shared-contexts';

/**
 * SwatchPicker component - TODO: add more docs
 */
export const SwatchPicker: ForwardRefComponent<SwatchPickerProps> = React.forwardRef((props, ref) => {
  const state = useSwatchPicker_unstable(props, ref);
  const contextValues = useSwatchPickerContextValues(state);

  useSwatchPickerStyles_unstable(state);
  useCustomStyleHook_unstable('useSwatchPickerStyles_unstable')(state);

  return renderSwatchPicker_unstable(state, contextValues);
});

SwatchPicker.displayName = 'SwatchPicker';

import type * as React from 'react';
import type { ComponentProps, ComponentState, Slot, EventHandler, EventData } from '@fluentui/react-utilities';
import type { SwatchPickerContextValue } from '../../contexts/swatchPicker';

export type SwatchPickerSlots = {
  root: Slot<'div'>;
};

export type SwatchPickerOnSelectEventHandler = EventHandler<SwatchPickerOnSelectionChangeData>;

export type SwatchPickerOnSelectionChangeData = EventData<'click', React.MouseEvent<HTMLButtonElement>> & {
  selectedValue: string;
  selectedSwatch: string;
};

/**
 * SwatchPicker Props
 */
export type SwatchPickerProps = ComponentProps<SwatchPickerSlots> & {
  /**
   * Default selected value
   */
  defaultSelectedValue?: string;

  /**
   * Sets the focus behavior for the SwatchPicker.
   *
   * `arrow`
   * This behavior will cycle through all elements inside of the SwatchPicker when pressing the Arrow key.
   *
   * `tab`
   * This behavior will cycle through all elements inside of the SwatchPicker when pressing the Tab key.
   *
   * @default 'arrow'
   */
  focusMode?: 'arrow' | 'tab';

  /**
   * Whether SwatchPicker is row or grid
   */
  layout?: 'row' | 'grid';

  /**
   * Triggers a callback when the value has been changed
   */
  onSelectionChange?: EventHandler<SwatchPickerOnSelectionChangeData>;

  /**
   * Controlled selected value
   */
  selectedValue?: string;

  /**
   * Swatch size
   * @defaultvalue 'medium'
   */
  size?: 'extra-small' | 'small' | 'medium' | 'large';

  /**
   * Swatch shape
   * @defaultvalue 'square'
   */
  shape?: 'rounded' | 'square' | 'circular';

  /**
   * Spacing between swatches
   * @defaultvalue 'medium'
   */
  spacing?: 'small' | 'medium';
};

export type SwatchPickerBaseProps = Omit<SwatchPickerProps, 'size' | 'shape' | 'spacing'>;

/**
 * State used in rendering SwatchPicker
 */
export type SwatchPickerState = ComponentState<SwatchPickerSlots> &
  SwatchPickerContextValue &
  Pick<SwatchPickerProps, 'layout' | 'size' | 'shape' | 'spacing'> & {
    isGrid: boolean;
  };

export type SwatchPickerBaseState = Omit<SwatchPickerState, 'size' | 'shape' | 'spacing'>;

export { SwatchPicker } from './SwatchPicker';
export type {
  SwatchPickerBaseProps,
  SwatchPickerBaseState,
  SwatchPickerOnSelectEventHandler,
  SwatchPickerOnSelectionChangeData,
  SwatchPickerProps,
  SwatchPickerSlots,
  SwatchPickerState,
} from './SwatchPicker.types';
export { renderSwatchPicker_unstable } from './renderSwatchPicker';
export { useSwatchPicker_unstable, useSwatchPickerBase_unstable } from './useSwatchPicker';
export { swatchPickerClassNames, useSwatchPickerStyles_unstable } from './useSwatchPickerStyles.styles';

