    defaultProps: {
      checked,
      defaultChecked,
      id,
      ref,
      role: 'switch',
      type: 'checkbox',
      ...nativeProps.primary,
      disabled: disabled && !disabledFocusable,
      ...(disabledFocusable && { 'aria-disabled': true }),
