describe('DataGrid', () => {
  const Example = () => (
    <DataGrid items={testItems} columns={testColumns}>
      <DataGridHeader>
        <DataGridRow<Item>>{({ renderHeaderCell }) => <DataGridCell>{renderHeaderCell()}</DataGridCell>}</DataGridRow>
