  const registeredTabs = React.useRef<Record<string, TabRegisterData>>({});

  const onRegister = useEventCallback((data: TabRegisterData) => {
    const key = JSON.stringify(data.value);

    if (!key && process.env.NODE_ENV !== 'production') {
