import { defaultOptions, FOCUS_VISIBLE_ATTR, FOCUS_WITHIN_ATTR } from './constants';
import type { makeResetStyles } from '@griffel/react';
import type { GriffelStyle } from '@griffel/react';

// TODO: Use the type directly from @griffel/react
// https://github.com/microsoft/griffel/pull/278
type GriffelResetStyle = Parameters<typeof makeResetStyles>[0];

export interface CreateCustomFocusIndicatorStyleOptions {
  /**
   * Control if the indicator appears when the corresponding element is focused,
   * or any child is focused within the corresponding element.
   * @default 'focus'
   * @alias selectorType
   */
  selector?: 'focus' | 'focus-within';
  /**
   * Customizes the selector provided based on the selector type.
   */
  customizeSelector?: (selector: string) => string;
  /**
   * Enables the browser default outline style
   * @deprecated The custom focus indicator no longer affects outline styles. Outline is overridden
   * in the default focus indicator function, `createFocusOutlineStyle`.
   */
  enableOutline?: boolean;
}

/**
 * Creates a style for @see makeStyles that includes the necessary selectors for focus.
 * Should be used only when @see createFocusOutlineStyle does not fit requirements
 *
 * If you're using `createCustomFocusIndicatorStyle` instead of `createFocusOutlineStyle`
 * keep in mind that the default outline style is not going to be removed
 * (as it is in `createFocusOutlineStyle`),
 * and is your responsibility to manually remove it from your styles.
 *
 * @example
 * ```ts
 * // Link styles
 * const useStyles = makeStyles({
  focusIndicator: createCustomFocusIndicatorStyle({
    textDecorationColor: tokens.colorStrokeFocus2,
    textDecorationLine: 'underline',
    textDecorationStyle: 'double',
    outlineStyle: 'none',
  }),
  // Common styles.
  root: {
    // ❗️ DO NOT FORGET TO REMOVE THE DEFAULT OUTLINE STYLE
    ':focus-visible': {
      outlineStyle: 'none',
    },
 * ```
 *
 * @param style - styling applied on focus, defaults to @see getDefaultFocusOutlineStyles
 * @param options - Configure the style of the focus outline
 */
export function createCustomFocusIndicatorStyle<TStyle extends GriffelStyle | GriffelResetStyle>(
  style: TStyle,
  {
    selector: selectorType = defaultOptions.selector,
    customizeSelector = defaultOptions.customizeSelector,
  }: CreateCustomFocusIndicatorStyleOptions = defaultOptions,
): TStyle extends GriffelStyle ? GriffelStyle : GriffelResetStyle {
  return { [customizeSelector(createBaseSelector(selectorType))]: style };
}

function createBaseSelector(selectorType: 'focus' | 'focus-within'): string {
  switch (selectorType) {
    case 'focus':
      return `&[${FOCUS_VISIBLE_ATTR}]`;
    case 'focus-within':
      return `&[${FOCUS_WITHIN_ATTR}]:focus-within`;
  }
}

import { tokens } from '@fluentui/react-theme';
import { shorthands } from '@griffel/react';
import type { GriffelStyle } from '@griffel/react';
import type { CreateCustomFocusIndicatorStyleOptions } from './createCustomFocusIndicatorStyle';
import { createCustomFocusIndicatorStyle } from './createCustomFocusIndicatorStyle';
import { defaultOptions } from './constants';

export type FocusOutlineOffset = Record<'top' | 'bottom' | 'left' | 'right', string>;
export type FocusOutlineStyleOptions = {
  /**
   * Only property not supported by the native CSS `outline`, if this is no longer needed
   * we can just go native instead
   */
  outlineRadius: string;
  outlineColor: string;
  outlineWidth: string;
  outlineOffset?: string | FocusOutlineOffset;
};
export interface CreateFocusOutlineStyleOptions extends Omit<CreateCustomFocusIndicatorStyleOptions, 'enableOutline'> {
  style?: Partial<FocusOutlineStyleOptions>;

  /**
   * Enables the browser default outline style
   */
  enableOutline?: boolean;
}

/**
 * Get the position of the focus outline
 *
 * @param options - Configures the style of the focus outline
 * @param position - The position of the focus outline
 * @returns CSS value for the position of the focus outline
 */
function getOutlinePosition(
  { outlineWidth, outlineOffset }: FocusOutlineStyleOptions,
  position: 'top' | 'bottom' | 'left' | 'right',
) {
  const offsetValue = (outlineOffset as FocusOutlineOffset)?.[position] || outlineOffset;

  if (!outlineOffset) {
    return `calc(${outlineWidth} * -1)`;
  }

  return `calc(0px - ${outlineWidth} - ${offsetValue})`;
}

/**
 * NOTE: the element with the focus outline needs to have `position: relative` so that the
 * pseudo element can be properly positioned.
 *
 * @param options - Configures the style of the focus outline
 * @returns focus outline styles object
 */
const getFocusOutlineStyles = (options: FocusOutlineStyleOptions): GriffelStyle => {
  const { outlineRadius, outlineColor, outlineWidth } = options;

  return {
    ...shorthands.borderColor('transparent'),
    '@media (forced-colors: active)': {
      '::after': {
        ...shorthands.borderColor('Highlight'),
      },
    },
    '::after': {
      content: '""',
      position: 'absolute',
      pointerEvents: 'none',
      zIndex: 1,

      border: `${outlineWidth} solid ${outlineColor}`,
      borderRadius: outlineRadius,

      top: getOutlinePosition(options, 'top'),
      right: getOutlinePosition(options, 'right'),
      bottom: getOutlinePosition(options, 'bottom'),
      left: getOutlinePosition(options, 'left'),
    },
  };
};

/**
 * NOTE: The element with the focus outline needs to have `position: relative` so that the
 * pseudo element can be properly positioned.
 *
 * @param options - Configure the style of the focus outline
 * @returns focus outline styles object for @see makeStyles
 */
export const createFocusOutlineStyle = ({
  enableOutline = false,
  selector = defaultOptions.selector,
  customizeSelector,
  style = defaultOptions.style,
}: CreateFocusOutlineStyleOptions = defaultOptions): GriffelStyle => ({
  ':focus': {
    outlineStyle: enableOutline ? undefined : 'none',
  },
  ':focus-visible': {
    outlineStyle: enableOutline ? undefined : 'none',
  },

  ...createCustomFocusIndicatorStyle(
    getFocusOutlineStyles({
      outlineColor: tokens.colorStrokeFocus2,
      outlineRadius: tokens.borderRadiusMedium,
      // FIXME: tokens.strokeWidthThick causes some weird bugs
      outlineWidth: '2px',
      ...style,
    }),
    { selector, customizeSelector },
  ),
});

import { isHTMLElement } from '@fluentui/react-utilities';
import type { KeyborgFocusInEvent } from 'keyborg';
import { KEYBORG_FOCUSIN, createKeyborg, disposeKeyborg } from 'keyborg';

import { FOCUS_VISIBLE_ATTR } from './constants';

/**
 * Because `addEventListener` type override falls back to 2nd definition (evt name is unknown string literal)
 * evt is being typed as a base class of MouseEvent -> `Event`.
 * This type is used to override `listener` calls to make TS happy
 */
type ListenerOverride = (evt: Event) => void;

type FocusVisibleState = {
  /**
   * Current element with focus visible in state
   */
  current: HTMLElement | undefined;
};

type HTMLElementWithFocusVisibleScope = {
  focusVisible: boolean | undefined;
} & HTMLElement;

/**
 * @internal
 * @param scope - Applies the ponyfill to all DOM children
 * @param targetWindow - window
 */
export function applyFocusVisiblePolyfill(scope: HTMLElement, targetWindow: Window): () => void {
  if (alreadyInScope(scope)) {
    // Focus visible polyfill already applied at this scope
    return () => undefined;
  }

  const state: FocusVisibleState = {
    current: undefined,
  };

  const keyborg = createKeyborg(targetWindow);

  function registerElementIfNavigating(el: EventTarget | HTMLElement | null) {
    if (keyborg.isNavigatingWithKeyboard() && isHTMLElement(el)) {
      state.current = el;
      el.setAttribute(FOCUS_VISIBLE_ATTR, '');
    }
  }

  function disposeCurrentElement() {
    if (state.current) {
      state.current.removeAttribute(FOCUS_VISIBLE_ATTR);
      state.current = undefined;
    }
  }

  // When navigation mode changes remove the focus-visible selector
  keyborg.subscribe(isNavigatingWithKeyboard => {
    if (!isNavigatingWithKeyboard) {
      disposeCurrentElement();
    } else {
      registerElementIfNavigating(targetWindow.document.activeElement);
    }
  });

  // Keyborg's focusin event is delegated so it's only registered once on the window
  // and contains metadata about the focus event
  const keyborgListener = (e: KeyborgFocusInEvent) => {
    disposeCurrentElement();
    const target = e.composedPath()[0];
    registerElementIfNavigating(target);
  };

  // Make sure that when focus leaves the scope, the focus visible class is removed
  const blurListener = (e: FocusEvent) => {
    if (!e.relatedTarget || (isHTMLElement(e.relatedTarget) && !scope.contains(e.relatedTarget))) {
      disposeCurrentElement();
    }
  };

  scope.addEventListener(KEYBORG_FOCUSIN, keyborgListener as ListenerOverride);
  scope.addEventListener('focusout', blurListener);
  (scope as HTMLElementWithFocusVisibleScope).focusVisible = true;

  if (scope.contains(targetWindow.document.activeElement)) {
    registerElementIfNavigating(targetWindow.document.activeElement);
  }

  // Return disposer
  return () => {
    disposeCurrentElement();

    scope.removeEventListener(KEYBORG_FOCUSIN, keyborgListener as ListenerOverride);
    scope.removeEventListener('focusout', blurListener);
    (scope as HTMLElementWithFocusVisibleScope).focusVisible = undefined;

    disposeKeyborg(keyborg);
  };
}

function alreadyInScope(el: HTMLElement | null | undefined): boolean {
  if (!el) {
    return false;
  }

  if ((el as HTMLElementWithFocusVisibleScope).focusVisible) {
    return true;
  }

  return alreadyInScope(el?.parentElement);
}

import type { KeyborgFocusInEvent } from 'keyborg';
import { KEYBORG_FOCUSIN, createKeyborg, disposeKeyborg } from 'keyborg';
import { FOCUS_WITHIN_ATTR } from './constants';

/**
 * Because `addEventListener` type override falls back to 2nd definition (evt name is unknown string literal)
 * evt is being typed as a base class of MouseEvent -> `Event`.
 * This type is used to override `listener` calls to make TS happy
 */
type ListenerOverride = (evt: Event) => void;

/**
 * A ponyfill that allows `:focus-within` to support visibility based on keyboard/mouse navigation
 * like `:focus-visible` https://github.com/WICG/focus-visible/issues/151
 * @returns ref to the element that uses `:focus-within` styles
 */
export function applyFocusWithinPolyfill(element: HTMLElement, win: Window): () => void {
  const keyborg = createKeyborg(win);

  // When navigation mode changes to mouse, remove the focus-within selector
  keyborg.subscribe(isNavigatingWithKeyboard => {
    if (!isNavigatingWithKeyboard) {
      removeFocusWithinClass(element);
    }
  });

  // Keyborg's focusin event is delegated so it's only registered once on the window
  // and contains metadata about the focus event
  const keyborgListener = (e: KeyborgFocusInEvent) => {
    if (keyborg.isNavigatingWithKeyboard() && isHTMLElement(e.target)) {
      // Griffel can't create chained global styles so use the parent element for now
      applyFocusWithinClass(element);
    }
  };

  // Make sure that when focus leaves the scope, the focus within class is removed
  const blurListener = (e: FocusEvent) => {
    if (!e.relatedTarget || (isHTMLElement(e.relatedTarget) && !element.contains(e.relatedTarget))) {
      removeFocusWithinClass(element);
    }
  };

  element.addEventListener(KEYBORG_FOCUSIN, keyborgListener as ListenerOverride);
  element.addEventListener('focusout', blurListener);

  // Return disposer
  return () => {
    element.removeEventListener(KEYBORG_FOCUSIN, keyborgListener as ListenerOverride);
    element.removeEventListener('focusout', blurListener);
    disposeKeyborg(keyborg);
  };
}

function applyFocusWithinClass(el: HTMLElement) {
  el.setAttribute(FOCUS_WITHIN_ATTR, '');
}

function removeFocusWithinClass(el: HTMLElement) {
  el.removeAttribute(FOCUS_WITHIN_ATTR);
}

function isHTMLElement(target: EventTarget | null): target is HTMLElement {
  if (!target) {
    return false;
  }
  return Boolean(target && typeof target === 'object' && 'classList' in target && 'contains' in target);
}

