const Example = (props: { callback: () => void }) => {
  useFocusedElementChange(props.callback);

  return (
    <>
      <a id="anchor" href="#">
        Anchor
      </a>

      <div tabIndex={0}>before</div>
      <button id="button">Button</button>
      <div tabIndex={0}>after</div>
    </>
  );
