          <button onClick={onClick}>Focus</button>
          {mounted && <button {...attr}>Foo</button>}
        </>
      );
    };

    mount(<Example />);
    cy.contains('Focus').click().get('body').contains('Foo').should('not.be.focused');
  });
});

