  props = useFieldControlProps_unstable(props, { supportsLabelFor: true, supportsRequired: true });

  const { resize = 'none', onChange } = props;

  const [value, setValue] = useControllableState({
    state: props.value,
    defaultState: props.defaultValue,
    initialState: undefined,
  });

  const nativeProps = getPartitionedNativeProps({
    props,
    primarySlotTagName: 'textarea',
    excludedPropNames: ['onChange', 'value', 'defaultValue'],
  });

  const state: TextareaBaseState = {
    resize,
    components: {
      root: 'span',
      textarea: 'textarea',
    },
    textarea: slot.always(props.textarea, {
      defaultProps: {
        ref,
        ...nativeProps.primary,
      },
      elementType: 'textarea',
    }),
    root: slot.always(props.root, {
      defaultProps: nativeProps.root,
      elementType: 'span',
    }),
  };

  state.textarea.value = value;
  state.textarea.onChange = useEventCallback(ev => {
    const newValue = ev.target.value;
    onChange?.(ev, { value: newValue });
    setValue(newValue);
  });

  return state;
};

