import * as React from 'react';
import { useFluent_unstable as useFluent } from '@fluentui/react-shared-contexts';
import {
  dispatchToast as dispatchToastVanilla,
  dismissToast as dismissToastVanilla,
  dismissAllToasts as dismissAllToastsVanilla,
  updateToast as updateToastVanilla,
  playToast as playToastVanilla,
  pauseToast as pauseToastVanilla,
} from './vanilla';
import type { DispatchToastOptions, ToastId, ToasterId, UpdateToastOptions } from './types';

const noop = () => undefined;

/**
 * @param toasterId - If an id is provided all imperative methods control that specific toaster
 * @returns Imperative methods to control toasts
 */
export function useToastController(toasterId?: ToasterId): {
  dispatchToast: (content: React.ReactNode, options?: DispatchToastOptions) => void;
  dismissToast: (toastId: ToastId) => void;
  dismissAllToasts: () => void;
  updateToast: (options: UpdateToastOptions) => void;
  pauseToast: (toastId: ToastId) => void;
  playToast: (toastId: ToastId) => void;
} {
  const { targetDocument } = useFluent();

  return React.useMemo(() => {
    if (!targetDocument) {
      return {
        dispatchToast: noop,
        dismissToast: noop,
        dismissAllToasts: noop,
        updateToast: noop,
        pauseToast: noop,
        playToast: noop,
      };
    }

    return {
      dispatchToast: (content: React.ReactNode, options?: DispatchToastOptions) => {
        dispatchToastVanilla(content, { ...options, toasterId, data: { root: options?.root } }, targetDocument);
      },
      dismissToast: (toastId: ToastId) => {
        dismissToastVanilla(toastId, toasterId, targetDocument);
      },
      dismissAllToasts: () => {
        dismissAllToastsVanilla(toasterId, targetDocument);
      },
      updateToast: (options: UpdateToastOptions) => {
        updateToastVanilla({ ...options, data: { root: options.root }, toasterId }, targetDocument);
      },
      pauseToast: (toastId: ToastId) => {
        pauseToastVanilla(toastId, toasterId, targetDocument);
      },
      playToast: (toastId: ToastId) => {
        playToastVanilla(toastId, toasterId, targetDocument);
      },
    };
  }, [targetDocument, toasterId]);
}

'use client';

import * as React from 'react';
import { isHTMLElement, useEventCallback, useForceUpdate } from '@fluentui/react-utilities';
import { useFluent_unstable as useFluent } from '@fluentui/react-shared-contexts';
import { createToaster } from './vanilla';
import type {
  CommonToastDetail,
  ShowToastEventDetail,
  Toast,
  ToastId,
  ToastListenerMap,
  ToastPosition,
  ToasterId,
  ToasterOptions,
} from './types';
import { EVENTS } from './constants';

export function useToaster<TElement extends HTMLElement = HTMLDivElement>(
  options: Partial<ToasterOptions> = {},
): {
  isToastVisible: (toastId: ToastId) => boolean;
  toastsToRender: Map<ToastPosition, Toast[]>;
  pauseAllToasts: () => void;
  playAllToasts: () => void;
  tryRestoreFocus: () => void;
  closeAllToasts: () => void;
} {
  const forceUpdate = useForceUpdate();
  const { toasterId: userToasterId, shortcuts } = options;
  // Currently the toaster options can never be changed at runtime
  const [toaster] = React.useState(() => createToaster(options));
  const { targetDocument } = useFluent();

  const lastActiveElementRef = React.useRef<HTMLElement | null>(null);

  const isCorrectToaster = useEventCallback((toasterId: ToasterId | undefined) => {
    return toasterId === userToasterId;
  });

  const isFocusShortcut = useEventCallback((e: KeyboardEvent) => {
    if (shortcuts?.focus) {
      return shortcuts.focus(e);
    }
  });

  const pauseAllToasts = React.useCallback(() => {
    toaster.visibleToasts.forEach(toastId => {
      const toast = toaster.toasts.get(toastId);
      toast?.imperativeRef.current?.pause();
    });
  }, [toaster]);

  const playAllToasts = React.useCallback(() => {
    toaster.visibleToasts.forEach(toastId => {
      const toast = toaster.toasts.get(toastId);
      toast?.imperativeRef.current?.play();
    });
  }, [toaster]);

  const getMostRecentVisibleToast = React.useCallback(() => {
    return Array.from(toaster.visibleToasts).reduce((cur, next) => {
      const toast = toaster.toasts.get(next);
      if (!toast) {
        return cur;
      }

      if (!cur) {
        return toast;
      }

      if (cur.order < toast?.order) {
        return toast;
      }

      return cur;
    }, undefined as Toast | undefined);
  }, [toaster]);

  const tryRestoreFocus = React.useCallback(() => {
    const mostRecentToast = getMostRecentVisibleToast();
    if (mostRecentToast?.imperativeRef.current) {
      mostRecentToast.imperativeRef.current.focus();
    } else {
      lastActiveElementRef.current?.focus();
      lastActiveElementRef.current = null;
    }
  }, [getMostRecentVisibleToast]);

  const closeAllToasts = React.useCallback(() => {
    toaster.visibleToasts.forEach(toastId => {
      const toast = toaster.toasts.get(toastId);
      toast?.close();
    });

    tryRestoreFocus();
  }, [toaster, tryRestoreFocus]);

  React.useEffect(() => {
    if (!targetDocument) {
      return;
    }

    const addToastListener = <TType extends keyof ToastListenerMap>(
      eventType: TType,
      callback: ToastListenerMap[TType],
    ) => {
      const listener: ToastListenerMap[TType] = (e: CustomEvent<CommonToastDetail>) => {
        if (!isCorrectToaster(e.detail.toasterId)) {
          return;
        }

        callback(e as CustomEvent<ShowToastEventDetail>);
        forceUpdate();
      };

      targetDocument.addEventListener(eventType, listener as () => void);
      return () => targetDocument.removeEventListener(eventType, listener as () => void);
    };

    const buildToast: ToastListenerMap[typeof EVENTS.show] = e => {
      toaster.buildToast(e.detail, forceUpdate);
    };

    const dismissToast: ToastListenerMap[typeof EVENTS.dismiss] = e => {
      toaster.dismissToast(e.detail.toastId);
    };

    const updateToast: ToastListenerMap[typeof EVENTS.update] = e => {
      toaster.updateToast(e.detail);
    };

    const dismissAllToasts: ToastListenerMap[typeof EVENTS.dismissAll] = e => {
      toaster.dismissAllToasts();
    };

    const pauseToast: ToastListenerMap[typeof EVENTS.pause] = e => {
      const toast = toaster.toasts.get(e.detail.toastId);
      if (toast) {
        toast.imperativeRef.current?.pause();
      }
    };

    const playToast: ToastListenerMap[typeof EVENTS.play] = e => {
      const toast = toaster.toasts.get(e.detail.toastId);
      if (toast) {
        toast.imperativeRef.current?.play();
      }
    };

    const cleanupBuildListener = addToastListener(EVENTS.show, buildToast);
    const cleanupUpdateListener = addToastListener(EVENTS.update, updateToast);
    const cleanupDismissListener = addToastListener(EVENTS.dismiss, dismissToast);
    const cleanupDismissAllListener = addToastListener(EVENTS.dismissAll, dismissAllToasts);
    const cleanupPauseListener = addToastListener(EVENTS.pause, pauseToast);
    const cleanupPlayListener = addToastListener(EVENTS.play, playToast);

    const focusShortcutListener = (e: KeyboardEvent) => {
      if (isFocusShortcut(e)) {
        pauseAllToasts();
        const mostRecentToast = getMostRecentVisibleToast();

        if (mostRecentToast) {
          lastActiveElementRef.current = isHTMLElement(targetDocument.activeElement)
            ? targetDocument.activeElement
            : null;
          mostRecentToast.imperativeRef.current?.focus();
        }
      }
    };

    targetDocument.addEventListener('keydown', focusShortcutListener);

    return () => {
      cleanupBuildListener();
      cleanupDismissAllListener();
      cleanupUpdateListener();
      cleanupDismissListener();
      cleanupPauseListener();
      cleanupPlayListener();

      targetDocument.removeEventListener('keydown', focusShortcutListener);
    };
  }, [
    toaster,
    forceUpdate,
    targetDocument,
    isCorrectToaster,
    pauseAllToasts,
    getMostRecentVisibleToast,
    isFocusShortcut,
  ]);

  const toastsToRender = (() => {
    if (!toaster) {
      return new Map<ToastPosition, Toast[]>();
    }

    const toRender = new Map<ToastPosition, Toast[]>();
    const toasts = Array.from(toaster.toasts.values());

    toasts.forEach(toast => {
      const { position } = toast;
      toRender.has(position) || toRender.set(position, []);
      if (position.startsWith('bottom')) {
        toRender.get(position)!.push(toast);
      } else {
        toRender.get(position)!.unshift(toast);
      }
    });

    return toRender;
  })();

  return {
    isToastVisible: toaster.isToastVisible,
    toastsToRender,
    pauseAllToasts,
    playAllToasts,
    tryRestoreFocus,
    closeAllToasts,
  };
}

import * as React from 'react';
import { createPriorityQueue } from '@fluentui/react-utilities';
import type {
  Toast,
  ToasterOptions,
  ToastId,
  ToastImperativeRef,
  ToastOptions,
  UpdateToastEventDetail,
} from '../types';

function assignDefined<T extends object>(a: Partial<T>, b: Partial<T>) {
  // This cast is required, as Object.entries will return string as key which is not indexable
  for (const [key, prop] of Object.entries(b) as [keyof T, T[keyof T]][]) {
    // eslint-disable-next-line eqeqeq
    if (prop != undefined) {
      a[key] = prop;
    }
  }
}
const defaulToastOptions: Pick<
  ToastOptions,
  'priority' | 'pauseOnHover' | 'pauseOnWindowBlur' | 'position' | 'timeout' | 'politeness' | 'onStatusChange'
> = {
  onStatusChange: undefined,
  priority: 0,
  pauseOnHover: false,
  pauseOnWindowBlur: false,
  position: 'bottom-end',
  timeout: 3000,
};

// Multiple toasts can be dispatched in a single tick, use counter to prevent collisions
let counter = 0;

/**
 * Toast are managed outside of the react lifecycle because they can be
 * dispatched imperatively. Therefore the state of toast visibility can't
 * really be managed properly by a declarative lifecycle.
 */
export function createToaster(options: Partial<ToasterOptions>): {
  buildToast: (toastOptions: Partial<ToastOptions> & { toastId: ToastId }, onUpdate: () => void) => void;
  dismissAllToasts: () => void;
  dismissToast: (toastId: ToastId) => void;
  isToastVisible: (toastId: ToastId) => boolean;
  updateToast: (options: UpdateToastEventDetail) => void;
  visibleToasts: Set<ToastId>;
  toasts: Map<ToastId, Toast>;
} {
  const { limit = Number.POSITIVE_INFINITY } = options;
  const visibleToasts = new Set<ToastId>();
  const toasts = new Map<ToastId, Toast>();

  const queue = createPriorityQueue<ToastId>((ta, tb) => {
    const a = toasts.get(ta);
    const b = toasts.get(tb);
    if (!a || !b) {
      return 0;
    }

    if (a.priority === b.priority) {
      return a.order - b.order;
    }

    return a.priority - b.priority;
  });

  const isToastVisible = (toastId: ToastId) => {
    return visibleToasts.has(toastId);
  };

  /**
   * Updates an existing toast with any available option
   */
  const updateToast = (toastOptions: UpdateToastEventDetail) => {
    const { toastId } = toastOptions;
    const toastToUpdate = toasts.get(toastId);
    if (!toastToUpdate) {
      return;
    }

    Object.assign(toastToUpdate, toastOptions);
    toastToUpdate.updateId++;
  };

  /**
   * Dismisses a toast with a specific id
   */
  const dismissToast = (toastId: ToastId) => {
    visibleToasts.delete(toastId);
  };

  /**
   * Dismisses all toasts and clears the queue
   */
  const dismissAllToasts = () => {
    visibleToasts.clear();
    queue.clear();
  };

  /**
   * @param toastOptions user configured options
   * @param onUpdate Some toast methods can result in UI changes (i.e. close) use this to dispatch callbacks
   */
  const buildToast = (toastOptions: Partial<ToastOptions> & { toastId: ToastId }, onUpdate: () => void) => {
    const { toastId, content, toasterId } = toastOptions;

    if (toasts.has(toastId)) {
      return;
    }

    const close = () => {
      const toast = toasts.get(toastId);
      if (!toast) {
        return;
      }

      visibleToasts.delete(toastId);
      onUpdate();
      toast.onStatusChange?.(null, { status: 'dismissed', ...toast });
    };

    const remove = () => {
      const toast = toasts.get(toastId);
      if (!toast) {
        return;
      }

      toasts.delete(toastId);

      if (visibleToasts.size < limit && queue.peek()) {
        const nextToast = toasts.get(queue.dequeue());
        if (!nextToast) {
          return;
        }

        visibleToasts.add(nextToast.toastId);
      }

      onUpdate();
    };

    const toast: Toast = {
      ...defaulToastOptions,
      close,
      remove,
      toastId,
      content,
      updateId: 0,
      toasterId,
      order: counter++,
      data: {},
      imperativeRef: React.createRef<ToastImperativeRef>(),
    };

    assignDefined(toast, options);
    assignDefined(toast, toastOptions);

    toasts.set(toastId, toast);
    toast.onStatusChange?.(null, { status: 'queued', ...toast });
    if (visibleToasts.size >= limit) {
      queue.enqueue(toastId);
    } else {
      visibleToasts.add(toastId);
    }
  };

  return {
    buildToast,
    dismissAllToasts,
    dismissToast,
    isToastVisible,
    updateToast,
    visibleToasts,
    toasts,
  };
}

