let counter = 0;

export function dispatchToast(content: unknown, options: Partial<ToastOptions> = {}, targetDocument: Document): void {
  const detail: ShowToastEventDetail = {
    ...options,
    content,
    toastId: options.toastId ?? (counter++).toString(),
