      selector: (selectionMode === 'multiselect' ? Checkbox : Radio) as React.ElementType<CheckboxProps | RadioProps>,
    },
    avatarSize: treeAvatarSize[size],
    main: slot.always(main, {
      defaultProps: { children, id: treeItemLayoutState.main.id },
      elementType: 'div',
