  return element.getAttribute(dataTreeItemValueAttrName) as TreeItemValue | null;
};

import type { HTMLElementWalker } from './createHTMLElementWalker';

export function nextTypeAheadElement(treeWalker: HTMLElementWalker, key: string): HTMLElement | null {
  const keyToLowerCase = key.toLowerCase();
  const typeAheadFilter = (element: HTMLElement) => {
    return element.textContent?.trim().charAt(0).toLowerCase() === keyToLowerCase
      ? NodeFilter.FILTER_ACCEPT
      : NodeFilter.FILTER_SKIP;
  };
  let nextElement = treeWalker.nextElement(typeAheadFilter);
  if (!nextElement) {
    treeWalker.currentElement = treeWalker.root;
    nextElement = treeWalker.nextElement(typeAheadFilter);
  }
  return nextElement;
}

export function normalizeOpenItems(
  openSubtrees?: string | string[],
  options?: {
    keepUndefined?: false;
  },
): string[];

export function normalizeOpenItems(
