  describe('iframes', () => {
    beforeEach(() => {
      cy.clock(new Date(), ['setInterval']);
    });

    it('is invoked on a frame focus (disabledFocusOnIframe={false})', () => {
      const onOutsideClick = cy.spy();

      mount(<IFrameExample disabledFocusOnIframe={false} onOutsideClick={onOutsideClick} />);

