  Props extends Pick<React.HTMLAttributes<HTMLElement>, 'style' | 'className'>,
  ExcludedPropKeys extends Extract<keyof Props, string> = never,
>({
  primarySlotTagName,
  props,
  excludedPropNames,
}: {
