/**
 * Measures the width of the scrollbar for the given document.
 *
 * @param targetDocument - Document to measure the scrollbar width
 * @returns The width of the scrollbar in pixels
 */
export function measureScrollbarWidth(targetDocument: Document): number {
  const outer = targetDocument.createElement('div');
  outer.style.visibility = 'hidden';
  outer.style.overflow = 'scroll';

  const inner = targetDocument.createElement('div');
  outer.appendChild(inner);

  targetDocument.body.appendChild(outer);
  const scrollbarWidth = outer.offsetWidth - inner.offsetWidth;
  outer.remove();

  return scrollbarWidth;
}

/**
 * Combine two event callbacks into a single callback function that calls each one in order.
 *
 * Usage example:
 * ```ts
 * state.slot.onChange = mergeCallbacks(state.slot.onChange, ev => {
 *   // Handle onChange
 * });
 * ```
 *
 * The primary use is to avoid the need to capture an existing callback (`state.slot.onChange` in the example) to a
 * local variable before replacing with a new listener that calls the existing one. This helps avoid bugs like:
 * * Infinite recursion by calling the re-assigned state.slot.onChange if it's not captured to a local variable.
 * * Missing a call to the original onChange due to an early return or other conditional.
 *
 * If you need a callback that is stable between renders, wrap the result in {@link useEventCallback}.
 *
 * @internal
 * @param callback1 - The first callback to be called, or undefined
 * @param callback2 - The second callback to be called, or undefined
 *
 * @returns A function that that calls the provided functions in order
 */
export function mergeCallbacks<Args extends unknown[]>(
  callback1: ((...args: Args) => void) | undefined,
  callback2: ((...args: Args) => void) | undefined,
): (...args: Args) => void {
  return (...args: Args) => {
    callback1?.(...args);
    callback2?.(...args);
  };
}

/**
 * Tiny helper to do the minimal amount of work in duplicating an object but omitting some
 * props. This ends up faster than using object ...rest or reduce to filter.
 *
 * This behaves very much like filteredAssign, but does not merge many objects together,
 * uses an exclusion object map, and avoids spreads all for optimal performance.
 *
 * See perf test for background:
 * https://jsperf.com/omit-vs-rest-vs-reduce/1
 *
 * @param obj - The object to clone
 * @param exclusions - The array of keys to exclude
 */
// eslint-disable-next-line @typescript-eslint/no-explicit-any
export function omit<TObj extends Record<string, any>, Exclusions extends (keyof TObj)[]>(
  obj: TObj,
  exclusions: Exclusions,
): Omit<TObj, Exclusions[number]> {
  // eslint-disable-next-line @typescript-eslint/no-explicit-any
  const result: Record<string, any> = {};

  for (const key in obj) {
    if (exclusions.indexOf(key) === -1 && obj.hasOwnProperty(key)) {
      result[key] = obj[key];
    }
  }

  return result as TObj;
}

/**
 * @internal
 */
export type PriorityQueueCompareFn<T> = (a: T, b: T) => number;

/**
 * @internal
 */
export interface PriorityQueue<T> {
  all: () => T[];
  clear: () => void;
  contains: (item: T) => boolean;
  dequeue: () => T;
  enqueue: (item: T) => void;
  peek: () => T | null;
  remove: (item: T) => void;
  size: () => number;
}

/**
 * @internal
 * @param compare - comparison function for items
 * @returns Priority queue implemented with a min heap
 */
export function createPriorityQueue<T>(compare: PriorityQueueCompareFn<T>): PriorityQueue<T> {
  const arr: T[] = [];
  let size = 0;

  const swap = (a: number, b: number) => {
    const tmp = arr[a];
    arr[a] = arr[b];
    arr[b] = tmp;
  };

  const heapify = (i: number) => {
    let smallest = i;
    const l = left(i);
    const r = right(i);

    if (l < size && compare(arr[l], arr[smallest]) < 0) {
      smallest = l;
    }

    if (r < size && compare(arr[r], arr[smallest]) < 0) {
      smallest = r;
    }

    if (smallest !== i) {
      swap(smallest, i);
      heapify(smallest);
    }
  };

  const dequeue = () => {
    if (size === 0) {
      throw new Error('Priority queue empty');
    }

    const res = arr[0];
    arr[0] = arr[--size];
    heapify(0);

    return res;
  };

  const peek = () => {
    if (size === 0) {
      return null;
    }

    return arr[0];
  };

  const enqueue = (item: T) => {
    arr[size++] = item;
    let i = size - 1;
    let p = parent(i);
    while (i > 0 && compare(arr[p], arr[i]) > 0) {
      swap(p, i);
      i = p;
      p = parent(i);
    }
  };

  const contains = (item: T) => {
    const index = arr.indexOf(item);
    return index >= 0 && index < size;
  };

  const remove = (item: T) => {
    const i = arr.indexOf(item);

    if (i === -1 || i >= size) {
      return;
    }

    arr[i] = arr[--size];
    heapify(i);
  };

  const clear = () => {
    size = 0;
  };

  const all = () => {
    return arr.slice(0, size);
  };

  return {
    all,
    clear,
    contains,
    dequeue,
    enqueue,
    peek,
    remove,
    size: () => size,
  };
}

const left = (i: number) => {
  return 2 * i + 1;
};

const right = (i: number) => {
  return 2 * i + 2;
};

const parent = (i: number) => {
  return Math.floor((i - 1) / 2);
};

import type * as React from 'react';

/**
 * Helper type that works similar to Omit,
 * but when modifying an union type it will distribute the omission to all the union members.
 *
 * See [distributive conditional types](https://www.typescriptlang.org/docs/handbook/2/conditional-types.html#distributive-conditional-types) for more information
 */
// Traditional Omit is basically equivalent to => Pick<T, Exclude<keyof T, K>>
//
// let's say we have Omit<{ a: string } | { b: string }, 'a'>
// equivalent to: Pick<{ a: string } | { b: string }, Exclude<keyof ({ a: string } | { b: string }), 'a'>>
// The expected result would be {} | { b: string }, the omission of 'a' from all the union members,
// but keyof ({ a: string } | { b: string }) is never as they don't share common keys
// so  Exclude<never, 'a'> is never,
// and Pick<{ a: string } | { b: string }, never> is {}.
//
// With DistributiveOmit on the other hand it becomes like this:
// DistributiveOmit<{ a: string } | { b: string }, 'a'>
// equivalent to: Omit<{ a: string }, 'a'> | Omit<{ b: string }, 'a'>
// Since every single Omit clause in this case is being applied to a single union member there's no conflicts on keyof evaluation and in the second clause Omit<{ b: string }, 'a'> becomes { b: string },
// so the result is {} | { b: string }, as expected.
// eslint-disable-next-line @typescript-eslint/no-explicit-any
export type DistributiveOmit<T, K extends keyof any> = T extends unknown ? Omit<T, K> : T;

/**
 * Helper type that works similar to Pick,
 * but when modifying an union type it will distribute the picking to all the union members.
 *
 * See {@link https://www.typescriptlang.org/docs/handbook/2/conditional-types.html#distributive-conditional-types} for more information
 *
 * @public
 */
export type DistributivePick<T, K> = T extends unknown ? Pick<T, K & keyof T> : never;

/**
 * Converts a union type (`A | B | C`) to an intersection type (`A & B & C`)
 */
export type UnionToIntersection<U> = (U extends unknown ? (x: U) => U : never) extends (x: infer I) => U ? I : never;

/**
 * If type T includes `null`, remove it and add `undefined` instead.
 *
 * @internal
 */
export type ReplaceNullWithUndefined<T> = T extends null ? Exclude<T, null> | undefined : T;

/**
 * With react 18, our `children` type starts leaking everywhere and that causes conflicts on component declaration, specially in the `propTypes` property of
 * both `ComponentClass` and `FunctionComponent`.
 *
 * This type substitutes `React.ComponentType` only keeping the function signature, it omits `propTypes`, `displayName` and other properties that are not
 * required for the inference.
 *
 * @internal
 */
export type ComponentType<P = {}> = ComponentClass<P> | FunctionComponent<P>;

/**
 * On types/react 18 there are two types being delivered,
 * they rely on the typescript version to decide which will be consumed {@link https://github.com/DefinitelyTyped/DefinitelyTyped/blob/b59dc3ac1e2770fbd6cdbb90ba52abe04c168196/types/react/package.json#L10}
 *
 * If TS is higher than 5.0 then the `FunctionComponent` will be returning ReactNode (which we don't support)
 * If TS is below or equal to 5.0 then the `FunctionComponent` will be returning ReactElement | null (which we support)
 *
 * Since it's not possible to have a single type that works for both cases
 * (as ReactNode is more specific, and this will break while evaluating functions),
 * we need to create our own `FunctionComponent` type
 * that will work for both cases.
 *
 * **THIS TYPE IS INTERNAL AND SHOULD NEVER BE EXPOSED**
 *
 * @internal
 */
export interface FunctionComponent<P> {
  // eslint-disable-next-line @typescript-eslint/no-explicit-any
  (props: P): any;
  displayName?: string;
}

export type FC<P> = FunctionComponent<P>;

export interface ExoticComponent<P> {
  // eslint-disable-next-line @typescript-eslint/no-explicit-any
  (props: P): any;
  $$typeof: symbol;
}

export interface NamedExoticComponent<P> extends ExoticComponent<P> {
  displayName?: string;
}

/**
 * **THIS TYPE IS INTERNAL AND SHOULD NEVER BE EXPOSED**
 *
 * @internal
 */
export interface ComponentClass<P = {}, S = React.ComponentState> extends React.StaticLifecycle<P, S> {
  new (props: P): React.Component<P, S>;
}

/**
 * on types/react 18 ReactNode becomes a more strict type, which is not compatible with our current implementation. to avoid any issues we are creating our own ReactNode type which allows anything.
 *
 * This type should only be used for inference purposes, and should never be exposed.
 *
 * **THIS TYPE IS INTERNAL AND SHOULD NEVER BE EXPOSED**
 *
 * @internal
 */
// eslint-disable-next-line @typescript-eslint/no-explicit-any
export type ReactNode = any;

/**
 * Removes the 'ref' prop from the given Props type, leaving unions intact (such as the discriminated union created by
 * IntrinsicSlotProps). This allows IntrinsicSlotProps to be used with React.forwardRef.
 */
export type PropsWithoutRef<P> = 'ref' extends keyof P ? DistributiveOmit<P, 'ref'> : P;

/**
 * Removes the 'children' prop from the given Props type, leaving unions intact (such as the discriminated union created by
 * IntrinsicSlotProps). This allows IntrinsicSlotProps to be used with React.forwardRef.
 */
export type PropsWithoutChildren<P> = 'children' extends keyof P ? DistributiveOmit<P, 'children'> : P;

/**
 * This type is used to determine if the current version of React is 18+ or not.
 *
 * It checks if the `React.ReactNode` has `{}` it its type.
 * If it is, then it means that the current version of React is lower than 18.
 * If it is not, then it means that the current version of React is 18 or higher.
 * This is useful for ensuring compatibility with different versions of React.
 *
 * **THIS TYPE IS INTERNAL AND SHOULD NEVER BE EXPOSED**
 *
 * @internal
 */
export type ReactVersionDependent<Modern, Legacy> = {} extends React.ReactNode ? Legacy : Modern;

/**
 * Our own alias for `JSX.Element` type that is compatible with both React 17 and React 18+.
 * Use this type when annotating JSX markup in all our code in order to avoid issues between different React versions.
 *
 * Example usage:
 *
 * BAD:
 * ```tsx
 * const renderFoo = (state: FooState) = <div {...props}>Hello World</div>;
 * // infers
 * // R17:  declare const renderFoo: (state: FooState) => JSX.Element;
 * // R18+: declare const renderFoo: (state: FooState) => React.JSX.Element;
 * ```
 *
 * GOOD:
 * ```tsx
 * import type { JSXElement } from '@fluentui/react-utilities';
 * const renderFoo = (state: FooState): JSXElement = <div {...props}>Hello World</div>;
 * ```
 */
export type JSXElement = React.ReactElement<
  /* eslint-disable @typescript-eslint/no-explicit-any */
  any,
  any
  /* eslint-enable @typescript-eslint/no-explicit-any */
>;

/**
 * Type representing all valid JSX intrinsic element names (e.g., 'div', 'button', 'input').
 * It's derived from `React.ElementType` by excluding all custom component types (`React.ComponentType`), ensuring it only includes standard HTML and SVG elements.
 *
 * Use this type when you need to restrict a type to only valid intrinsic element names.
 *
 * @example
 * ```tsx
 * import * as React from 'react';
 * import type { JSXIntrinsicElementKeys } from '@fluentui/react-utilities';
 *
 * const createElement = (tag: JSXIntrinsicElementKeys) => React.createElement(tag, {});
 *
 * createElement('div'); // Valid
 * createElement('span'); // Valid
 * createElement('unknown'); // Error: Argument of type '"unknown"' is not assignable to parameter of type 'JSXIntrinsicElementKeys'.
 * ```
 *
 * This type helps ensure that only valid intrinsic elements are used in scenarios where custom components are not allowed.
 */
export type JSXIntrinsicElementKeys = Exclude<React.ElementType, React.ComponentType>;

/**
 * Our own alias for `JSX.IntrinsicElements` type that is compatible with both React 17 and React 18+.
 * Use this type to get the intrinsic elements from React types in order to avoid issues between different React versions.
 */
export type JSXIntrinsicElement<Element extends JSXIntrinsicElementKeys> = React.ComponentProps<Element>;

import { getParent } from './getParent';

/**
 * Similar functionality to `element.contains` DOM API for use without of order DOM elements that
 * checks the virtual parent hierarchy. If a virtual parents exists, it is chosen over the actual parent
 *
 * @internal
 * @returns true if the child can find the parent in its virtual hierarchy
 */
export function elementContains(parent: Node | null, child: Node | null): boolean {
  if (!parent || !child) {
    return false;
  }

  if (parent === child) {
    return true;
  } else {
    // Tracks references of nodes that have been visited to prevent infinite loops
    const set = new WeakSet<Node>();

    while (child) {
      const nextParent: Node | null = getParent(child, {
        skipVirtual: set.has(child),
      });
      set.add(child);

      if (nextParent === parent) {
        return true;
      }

      child = nextParent;
    }
  }

  return false;
}

import { isVirtualElement } from './isVirtualElement';

type GetParentOptions = {
  /**
   * Indicates if getParent() should ignore a virtual parent.
   * @internal
   */
  skipVirtual?: boolean;
};

/**
 * Gets the virtual parent given the child element, if it exists.
 * @internal
 */
function getVirtualParent(child: Node): Node | null {
  return isVirtualElement(child) ? child._virtual.parent || null : null;
}

/**
 * Gets the element which is the parent of a given element.
 * This method prefers the virtual parent over real DOM parent when present.
 * @internal
 */
export function getParent(child: Node | null, options: GetParentOptions = {}): Node | null {
  if (!child) {
    return null;
  }

  if (!options.skipVirtual) {
    const virtualParent = getVirtualParent(child);

    if (virtualParent) {
      return virtualParent;
    }
  }

  const parent = child.parentNode;

  // Node.DOCUMENT_FRAGMENT_NODE = 11
  if (parent && parent.nodeType === 11) {
    return (parent as ShadowRoot).host;
  }

  return parent;
}

export { elementContains } from './elementContains';
export { setVirtualParent } from './setVirtualParent';
export { getParent } from './getParent';

import type { VirtualElement } from './types';

/**
 * Determines whether or not an element has the virtual hierarchy extension.
 * @internal
 */
export function isVirtualElement(element: Node | VirtualElement): element is VirtualElement {
  return element && !!(element as VirtualElement)._virtual;
}

/**
 * Sets the virtual parent of an element.
 *
 * @internal
 * @param child - Theme element to set the virtual parent
 * @param parent - The virtual parent, use `undefined` to remove a virtual parent relationship
 */
export function setVirtualParent(child: Node, parent?: Node): void {
  if (!child) {
    return;
  }

  Object.assign(child, {
    _virtual: {
      parent,
    },
  });
}

export interface VirtualElement extends Node {
  _virtual: {
    parent?: Node;
  };
}

